window.KURUL_DATA["1"] = [{"year": "2019-2020", "subject": "Pediatri", "q_num": 1, "question": "Çocukluk çağında görülen anemiler ile ilgili olarak aşağidakilerden hangileri\ndoğrudur?\nI. Demir eksikliği anemisinde serum demiri, serum demir bağlama kapasitesi ve ferritin\nazalmıştır\nII. Hipersegmentasyon megaloblastik anemilerin bir bulgusudur\nIII. Herediter sferositoz splenektomi ile kür sağlanan tek hemolitik anemidir\nIV. Çocuklardaki megaloblastik aneminin en sık nedeni B12 vitamin eksikliğidir\nV. Orak hücreli anemide en sık sekestrasyon krizleri görülür\nVI. Beta talasemi minörde mikrositer anemi görülür, MCV düşük, RDW normaldir", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "I ve III"}, {"letter": "B", "text": "I"}, {"letter": "C", "text": "III, V ve VI"}, {"letter": "D", "text": "I, IV ve VI"}, {"letter": "E", "text": "II, III ve VI"}], "answer": "E", "note": null, "id": "2019-2020_Q1", "explanation": "Demir eksikliği anemisinde serum demiri ve ferritin azalırken Total Demir Bağlama Kapasitesi (TDBK) artar (I yanlış). Nötrofillerde hipersegmentasyon megaloblastik anemilerin (B12/folat eksikliği) tipik periferik yayma bulgusudur (II doğru). Herediter sferositoz, splenektomi ile klinik kür sağlanan başlıca hemolitik anemidir (III doğru). Çocuklarda megaloblastik aneminin en sık nedeni folat veya nutrisyonel eksiklikler olup orak hücreli anemide en sık vazo-oklüzif (ağrılı) krizler görülür (IV ve V yanlış). Beta talasemi minörde (taşıyıcılık) MCV düşük (mikrositer) ancak eritrositler homojen küçüldüğü için RDW normaldir (VI doğru)."}, {"year": "2019-2020", "subject": "Pediatri", "q_num": 2, "question": "Çocuklarda kanama bozuklukları ile ilgili olarak hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Mukozal kanamalarda (burun kanaması, peteşi, ekimoz gibi) trombosit ile ilgili bozukluklar akla gelmelidir"}, {"letter": "B", "text": "Von-Willebrand hastalığında kanama zamanı normal, PTT uzamıştır"}, {"letter": "C", "text": "Geç göbek düşmesi ve sonrasında göbekten kanaması olan, protrombin zamanı ve PTT değerler normal olan hastada faktör 13 eksikliği aka gelmelidir"}, {"letter": "D", "text": "Hemofili A tekrarlayan eklem içi kanamalar ile karakterizedir"}, {"letter": "E", "text": "Immün trombositopenik purpurada izole trombositopeni görülür"}], "answer": "B", "note": null, "id": "2019-2020_Q2", "explanation": "Von Willebrand hastalığında (vWH) primer hemostaz (trombosit adezyonu) bozulduğu için kanama zamanı uzar; ayrıca vWF Faktör VIII'i taşıdığı için aPTT de uzayabilir. Dolayısıyla 'kanama zamanı normal' ifadesi yanlıştır. Faktör XIII eksikliğinde pıhtı stabilizasyonu bozulur, PT ve aPTT normaldir ve geç göbek düşmesi/kanaması tipiktir."}, {"year": "2019-2020", "subject": "Pediatri", "q_num": 3, "question": "Aşağidakilerden hangisi doğrudur?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Humoral immün yetmezliklerde klinik bulgular doğumdan sonra ilk aylarda başlar."}, {"letter": "B", "text": "Hücresel immün yetmezliklerde canlı virüs aşıları sonrası sistemik hastalık ve ölümcül reaksiyonlar gelişebilir."}, {"letter": "C", "text": "Fagosit fonksiyon bozukluğu olan hastalarda sık tekrarlayan kapsüllü bakteri enfeksiyonları görülür."}, {"letter": "D", "text": "Kompleman eksikliklerinde semptomlar 6. aydan sonra başlar."}, {"letter": "E", "text": "Çocuklarda en sık görülen immünglobülin eksikliği Bruton hastalığıdır."}], "answer": "B", "note": null, "id": "2019-2020_Q3", "prof_inferred": true, "explanation": "Hücresel (T hücre) immün yetmezliklerde canlı viral ve bakteriyel aşılar (BCG,OPV, MMR, suçiçeği, rotavirüs) kontrendikedir; yaygın sistemik enfeksiyon ve ölümcül reaksiyonlara yol açabilir. Humoral immün yetmezliklerde anneden geçen IgG nedeniyle semptomlar 6. aydan sonra başlar. Çocuklarda en sık immünglobülin eksikliği Selektif IgA eksikliğidir."}, {"year": "2019-2020", "subject": "Pediatri", "q_num": 4, "question": "Aşağidakilerden hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Di-George sendromunda hipokalsemi, konjenital timüs hipoplazisi ve konjenital kalp hastalıkları görülür."}, {"letter": "B", "text": "Trombositopenisi, egzeması ve tekrarlayan enfeksiyonları olan hastada Wiskott Aldrich sendromu akla gelmelidir."}, {"letter": "C", "text": "Kompleman 5, 6, 7, 8, 9 eksiklikleri tekrarlayan meningokok menenjiti ile karakterizedir"}, {"letter": "D", "text": "Selektif IgA eksikliği çocuklarda en sık görülen hücresel immün yetmezliktir"}, {"letter": "E", "text": "Hücresel immün yetmezliklerde canlı virüs aşılar kontrendikedir"}], "answer": "D", "note": null, "id": "2019-2020_Q4", "explanation": "Selektif IgA eksikliği hücresel değil, en sık görülen humoral (B hücre/antikor) immün yetmezliktir. DiGeorge sendromunda (22q11.2 delesyonu) timus aplazisi/hipoplazisi, hipoparatiroidi (hipokalsemi) ve konotrunkal kalp anomalileri görülür; Wiskott-Aldrich sendromu mikrotrombositopeni, egzema ve tekrarlayan enfeksiyonlar triadı ile karakterizedir."}, {"year": "2019-2020", "subject": "Pediatri", "q_num": 5, "question": "Çocukluk çağı lösemileri ile ilgili olarak hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Akut lösemiler çocuklarda görülen en sık görülen malign hastalıklardır."}, {"letter": "B", "text": "((9;22), 1 yaş altı olma ve lökosit sayısının >50.000 olması ALL için iyi prognoz kriterleridir."}, {"letter": "C", "text": "AML-M3'te DIC görülme riski vardır."}, {"letter": "D", "text": "Down sendromlu çocuklarda AML M7 sık görülür."}, {"letter": "E", "text": "T-ALL'de vena kava süperior sendromu görülebilir."}], "answer": "B", "note": null, "id": "2019-2020_Q5", "explanation": "Çocukluk çağı ALL'de t(9;22) (Philadelphia kromozomu), 1 yaş altı veya >10 yaş olma ve tanı anında lökosit sayısının >50.000/mm³ olması kötü prognoz kriterleridir. İyi prognoz kriterleri: 1-10 yaş arası, lökosit <50.000/mm³, hiperdiploidi ve t(12;21) varlığıdır."}, {"year": "2019-2020", "subject": "Pediatri", "q_num": 6, "question": "Çocukluk çağı kanserleri ile ilgili hangileri doğrudur?\nI. Nodüler sklerozan tip hodkign lenfoma en sık görülen tiptir, mediasteni tutar.\nII. Tümör lizis sendromu hiperürisemi, hiperfosfatemi, hiperkalsemi, hipopotasemi ve akut\nböbrek yetmezliği ile seyreden onkolojik acil durumdur.\nIII. Santral sinir sistemi supratentorial tümörlerinde KIBAS bulguları ortaya çıkar\nIV. Noroblastomda <1 yaş olması ve evre 1, 2 ve 4S iyi prognoz göstergesidir\nV. Wills tümöründe hemihipertrofi ve aniridi görülebilir\nVI. Çocuklarda en sık görülen kemik tümörü Ewing sarkomudur\nVII. Osteosarkom radyoterapi dirençlidir\nVIII. Retinoblastomun en sık geliş bulgusu rakun gözüdür", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "I, II"}, {"letter": "B", "text": "III, V, VI"}, {"letter": "C", "text": "II, IV, VI, VII"}, {"letter": "D", "text": "I, IV, V, VII"}, {"letter": "E", "text": "I, VI, VIII"}], "answer": "D", "note": null, "id": "2019-2020_Q6", "explanation": "Hodgkin lenfomanın en sık görülen tipi nodüler sklerozan tiptir ve sıklıkla ön mediasteni tutar (I doğru). Tümör lizis sendromunda hiperkalsemi ve hipopotasemi değil; hiperfosfatemiye sekonder hipokalsemi ve hücre yıkımına bağlı hiperpotasemi görülür (II yanlış). Nöroblastomda <1 yaş ve Evre 1, 2, 4S iyi prognozludur (IV doğru). Wilms tümöründe (nefroblastom) WAGR/Beckwith-Wiedemann kapsamında aniridi ve hemihipertrofi görülür (V doğru). Çocuklarda en sık primer malign kemik tümörü osteosarkomdur ve radyoterapiye dirençlidir (VI yanlış, VII doğru). Retinoblastomun en sık bulgusu lökokoridir; rakun gözü nöroblastomun orbita metastazında görülür (VIII yanlış)."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 7, "question": "Asağıdakilerden hangisi antihistaminiklerin endikasyonlarından biri değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Alerji"}, {"letter": "B", "text": "Taşıt tutması"}, {"letter": "C", "text": "Antiemetik"}, {"letter": "D", "text": "Sedasyon"}, {"letter": "E", "text": "Ürtiker"}], "answer": "D", "note": null, "id": "2019-2020_Q7", "explanation": "H1 reseptör blokörü antihistaminikler alerjik rinit/konjonktivit, ürtiker, taşıt tutması (hareket hastalığı) ve antiemetik amaçlarla kullanılır; sedasyon ise özellikle 1. kuşak antihistaminiklerin santral H1 blokajına bağlı en sık yan etkisidir, primer endikasyon değildir.", "repeats": [{"kurul": "4", "year": "2023-2024", "q_num": 27, "id": "K4_2023-2024_Q27"}]}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 8, "question": "Aşağıdakilerden hangisi kronik olarak alınan aspirin ve benzeri ilaçların yaptığı\ngastrointestinal lezyonlara karsı koruyucu olarak kullanılan prostoglandin analoğu bir\nilaçtır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ranitidin"}, {"letter": "B", "text": "Kaptopril"}, {"letter": "C", "text": "Misopristol"}, {"letter": "D", "text": "Sisplatin"}, {"letter": "E", "text": "Penisilin"}], "answer": "C", "note": null, "id": "2019-2020_Q8", "explanation": "Misoprostol sentetik bir PGE1 (Prostaglandin E1) analoğudur; mide asit sekresyonunu azaltır ve mukozal koruyucu mukus/bikarbonat salgısını artırarak NSAİİ (aspirin vb.) kullanımına bağlı peptik ülser profilaksisinde kullanılır."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 9, "question": "Verilen şıklardan hangisi Serotonin sentez ve metabolizması ile ilgili olarak yanlış bir\nbilgidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "MAO-A ve MAO-B enzimleri tarafından yıkılır."}, {"letter": "B", "text": "Kan beyin bariyerini rahatlıkla geçebilir."}, {"letter": "C", "text": "Trombositlerden salınımı hücrenin parçalanmasıyla olur"}, {"letter": "D", "text": "Triptofandan sentezlenir."}, {"letter": "E", "text": "Sentezlenen Serotonin parsiyel ekzositozla salıverilir."}], "answer": "B", "note": null, "id": "2019-2020_Q9", "explanation": "Serotonin (5-HT) polar yapısı nedeniyle kan-beyin bariyerini (KBB) doğrudan geçemez; santral sinir sistemindeki serotonin, KBB'yi geçebilen öncül aminoasit L-triptofandan beyinde sentezlenir."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 10, "question": "Parenteral kullanılan demir preparatları için verilen bilgilerden hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Demir eksikliğinde rutin kullanılmazlar"}, {"letter": "B", "text": "Antiasid ilaclar veya tetrasiklin gibi uzun süre ilaç kullanan hastalarda kullanılabilirler"}, {"letter": "C", "text": "Gebelikte geç fark edilen ağır anemide kullanılırlar"}, {"letter": "D", "text": "Genellikle oral olarak kullanılırlar"}, {"letter": "E", "text": "Ağızdan demir alması sakıncalı veya yararsız olan hastalarda kullanılırlar"}], "answer": "D", "note": null, "id": "2019-2020_Q10", "prof_inferred": true, "explanation": "Parenteral (İV veya İM) demir preparatları (demir dekstran, demir sükroz, ferrik karboksimaltoz vb.) enjeksiyon yoluyla uygulanır; oral olarak kullanılmazlar. Oral demir tedavisine intolerans, malabsorbsiyon veya ağır/geç fark edilen gebelik anemilerinde tercih edilirler."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 11, "question": "Oluşmuş pıhtıyı eriten ilaçlara ne denir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Trombolitik ilaçlar"}, {"letter": "B", "text": "Antianemik ilaçlar"}, {"letter": "C", "text": "Antiemetik ilaçlar"}, {"letter": "D", "text": "Antikoagulan ilaçlar"}, {"letter": "E", "text": "Antitrombositik ilaçlar"}], "answer": "A", "note": null, "id": "2019-2020_Q11", "explanation": "Oluşmuş trombüsü (fibrin pıhtısını) plazminojen aktivasyonu üzerinden eriten ilaçlara trombolitik (fibrinolitik) ilaçlar (tPA/alteplaz, streptokinaz, ürokinaz) denir. Antikoagülanlar ve antitrombositikler ise yeni pıhtı oluşumunu önler."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 12, "question": "Aşağıdakilerden hangisi oral antikoagulan ilaç gruplarından biri değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kumarin türevleri"}, {"letter": "B", "text": "Sitrik asit"}, {"letter": "C", "text": "Sefalosporinler"}, {"letter": "D", "text": "Raodentisitler"}, {"letter": "E", "text": "İndandion türevleri"}], "answer": "C", "note": null, "id": "2019-2020_Q12", "explanation": "Sefalosporinler beta-laktam grubu antibakteriyel antibiyotiklerdir; oral antikoagülan değildirler (ancak bazı sefalosporinler K vitamini metabolizmasını bozarak hipoprotrombinemi yan etkisi yapabilir). Kumarin (varfarin) ve indandion türevleri oral antikoagülanlardır."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 13, "question": "Immüntolerans etkili ilaçlarla ilgili olarak verilen bilgilerden hangisi yanlıştır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Vücut dışında hazırlanmış özgül antikoru hastaya uygulanarak yapılır."}, {"letter": "B", "text": "Tolerojenler adı verilir."}, {"letter": "C", "text": "Immün sistemi stimüle ederler"}, {"letter": "D", "text": "Alerjik reaksiyonların tedavisi için alerji kliniklerinde sık uygulanan bir yöntemdir"}, {"letter": "E", "text": "Enfeksiyon ve habis hücre gelişmesine yönelik doğal savunma sistemi, zayıflatılmış değildir."}], "answer": "C", "note": null, "id": "2019-2020_Q13", "prof_inferred": true, "explanation": "İmmüntolerans oluşturan ajanlar (tolerojenler) spesifik antijene karşı aşırı immün yanıtı baskılar/duyarsızlaştırır; immün sistemi genel olarak stimüle etmezler."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 14, "question": "Aşağıdakilerden hangisi antineoplastik ajanlar için doğru değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Immünsüpresif etkilidirler"}, {"letter": "B", "text": "Genellikle hücre çoğalmasını ve bölünmesini aktive ederler"}, {"letter": "C", "text": "Antimikrobik ilaçlara göre terapötik indeksleri düşüktür"}, {"letter": "D", "text": "Genel yan etkileri myelosüpresyondur"}, {"letter": "E", "text": "Teratojenik etkinlik gösterirler"}], "answer": "B", "note": null, "id": "2019-2020_Q14", "explanation": "Antineoplastik (sitotoksik) ilaçlar hücre çoğalmasını ve bölünmesini aktive etmez, aksine DNA sentezini veya mitozu bloke ederek inhibe ederler. Terapötik indeksleri dardır, kemik iliği baskılanması (myelosüpresyon), immünsüpresyon ve teratojenite başlıca yan etkileridir."}, {"year": "2019-2020", "subject": "Farmakoloji", "q_num": 15, "question": "Başka tedavi yaklaşımlarının yaşam süresine katkısının olmadığı durumlarda\nuygulanan kemoterapi çeşidi aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Primer kemoterapi"}, {"letter": "B", "text": "Radyoterapi"}, {"letter": "C", "text": "Eszamanlı kemo-radyoterapi"}, {"letter": "D", "text": "Neoadjuvan terapi"}, {"letter": "E", "text": "Adjuvan kemoterapi"}], "answer": "B", "note": null, "id": "2019-2020_Q15", "explanation": "Soruda cevap anahtarı B (Radyoterapi) olarak işaretlenmiştir; lokal kontrol ve palyasyon amacıyla diğer sistemik yaklaşımların sağkalım katkısı olmadığında radyoterapi uygulanabilir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 16, "question": "Gıdalara bağlı olan vitamin B12 emiliminin sağlanması için midede ilk neye\nbağlanır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Intrensek faktör"}, {"letter": "B", "text": "R faktör"}, {"letter": "C", "text": "Amilaz"}, {"letter": "D", "text": "Lipaz"}, {"letter": "E", "text": "Askorbik asit"}], "answer": "B", "note": null, "id": "2019-2020_Q16", "explanation": "Gıdalarla alınan B12 vitamini (kobalamin) midede asit/pepsin etkisiyle serbestleştikten sonra ilk olarak tükürük ve mide salgısında bulunan R-faktöre (haptokorrin) bağlanır. Duodenumda pankreas proteazları R-faktörü yıkar ve B12 İntrensek Faktöre (İF) bağlanarak terminal ileumdan emilir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 17, "question": "Aşağıdakilerden hangisi ya da hangileri hemolizle seyreden hastalıkların tümünde\ngörülen ortak bulgulardır?\n1. Hemosiderinüri\n2. Indirek hiperbilirubinemi\n3. Haptoglobulin yüksekliği\n4. Splenomegali", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "1"}, {"letter": "B", "text": "1, 2"}, {"letter": "C", "text": "2, 3"}, {"letter": "D", "text": "2, 4"}, {"letter": "E", "text": "1, 4"}], "answer": "D", "note": null, "id": "2019-2020_Q17", "explanation": "Hemolizde yıkılan eritrositlerden açığa çıkan hem grubunun katabolizması sonucu indirekt hiperbilirubinemi (2) ve ekstravasküler yıkım artışına bağlı splenomegali (4) ortak bulgulardır. Haptoglobin düzeyi artmaz, serbest hemoglobini bağladığı için azalır (3 yanlış); hemosiderinüri ise sadece intravasküler hemolizde görülür (1 yanlış)."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 18, "question": "Ciddi pansitopenide trombosit sayısı hangi sınır düzeyin altında olmalıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "<120 000 mm3"}, {"letter": "B", "text": "<50 000 mm3"}, {"letter": "C", "text": "<20 000 mm3"}, {"letter": "D", "text": "<2000 mm3"}, {"letter": "E", "text": "<500 mm3"}], "answer": "C", "note": null, "id": "2019-2020_Q18", "explanation": "Ağır (ciddi) aplastik anemi / pansitopeni kriterlerinde trombosit sayısının <20.000/mm³, mutlak nötrofil sayısının <500/mm³ ve düzeltilmiş retikülosit oranının <%1 (<20.000/mm³) olması yer alır."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 19, "question": "Hangi kemik iliği aspirasyonu sonucu Myelodisplastik sendrom açısından\nanlamlıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Howel jolly body"}, {"letter": "B", "text": "Meisner hücresi"}, {"letter": "C", "text": "Auerbach hücresi"}, {"letter": "D", "text": "Ring sideroblast"}, {"letter": "E", "text": "Orak hücreler"}], "answer": "D", "note": null, "id": "2019-2020_Q19", "explanation": "Kemik iliği aspirasyonunda Prusya mavisi (demir) boyası ile eritroblast çekirdeği etrafında mitokondrilerde demir birikimi sonucu oluşan 'ring (halka) sideroblastlar' Myelodisplastik Sendrom (MDS - özellikle SF3B1 mutasyonlu MDS-RS) için karakteristik tanısal bulgudur."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 20, "question": "Hodgkin hastalığının tanısında aşağıdakilerden hangisi histopatolojik olarak\npatogonomiktir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Pel ebstein hücresi"}, {"letter": "B", "text": "Reed stenberg hücresi"}, {"letter": "C", "text": "Histiosit hücresi"}, {"letter": "D", "text": "Orak hücreler"}, {"letter": "E", "text": "Goblet hücresi"}], "answer": "B", "note": null, "id": "2019-2020_Q20", "explanation": "Klasik Hodgkin lenfomanın histopatolojik tanısında baykuş gözü görünümünde bilobüle çekirdekli dev Reed-Sternberg hücreleri tanısal (patognomonik) öneme sahiptir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 21, "question": "Lenfoid sistemin en sık görülen habis tümörü aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hodgkin lenfoma"}, {"letter": "B", "text": "Multipl myelom"}, {"letter": "C", "text": "Non hodgkin lenfoma"}, {"letter": "D", "text": "Akut lenfoblastik lösemi"}, {"letter": "E", "text": "Kronik lenfositik lösemi"}], "answer": "C", "note": null, "id": "2019-2020_Q21", "explanation": "Lenfoid sistemin en sık görülen malign tümörü Non-Hodgkin Lenfoma (NHL)'dır (tüm lenfomaların yaklaşık %85-90'ını oluşturur, en sık alt tipi Diffüz Büyük B Hücreli Lenfomadır)."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 22, "question": "Kanser ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Kanser zaman içinde mutasyonların birikmesi sonucu oluşur"}, {"letter": "B", "text": "Kanser en sık görülen ölüm nedenidir"}, {"letter": "C", "text": "Ailesel kanserler germ hücrelerinde oluşan mutasyonlar sonucu gelişirler"}, {"letter": "D", "text": "Tümör supresor (baskılayıcı) genlerde fonksiyon kaybı mutasyonlar sonucu oluşur"}, {"letter": "E", "text": "İleri yaşlarda kanser görülme sıklığı artmaktadır."}], "answer": "B", "note": null, "id": "2019-2020_Q22", "prof_inferred": true, "explanation": "Dünyada ve ülkemizde erişkinlerde en sık ölüm nedeni kardiyovasküler sistem hastalıklarıdır; kanser ikinci sırada yer alır. Bu nedenle 'Kanser en sık görülen ölüm nedenidir' ifadesi yanlıştır."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 23, "question": "Aşağıdaki durumların hangisinde kanser araştırması yapmak gerekmez?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "1 aydan uzun süren inatçı öksürük ve kanlı balgam olması"}, {"letter": "B", "text": "Açıklanamayan anemi"}, {"letter": "C", "text": "Büyümekte olan düzensiz şekilli nevüsler"}, {"letter": "D", "text": "3-4 haftadan uzun sürede küçülmeyen büyümüş lenf nodları"}, {"letter": "E", "text": "1 hafta süren ishal"}], "answer": "E", "note": null, "id": "2019-2020_Q23", "explanation": "1 hafta süren akut ishal çoğunlukla enfeksiyöz gastroenterit kaynaklıdır ve kanser araştırması gerektirmez (4 haftadan uzun süren kronik ishal veya dışkılama alışkanlığı değişikliğinde araştırma gerekir). Diğer şıklar malignite için alarm semptomlarıdır."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 24, "question": "Kanser taraması için aşağıdakilerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Tarama yapılan kişilerde kanser semptomları vardır."}, {"letter": "B", "text": "Tarama testleri ucuz, kolay uygulanabilir olmalıdır"}, {"letter": "C", "text": "Hedef popülasyonun tümü taranır"}, {"letter": "D", "text": "Kanser taraması yapılan popülasyonun çoğunda kanser saptanmaz"}, {"letter": "E", "text": "45-54 as arası kadınlarda yıllık mamografi ile meme kanseri taraması yapılmalıdır."}], "answer": "A", "note": null, "id": "2019-2020_Q24", "prof_inferred": true, "explanation": "Kanser taraması herhangi bir semptomu olmayan (asemptomatik) sağlıklı görünümdeki risk grubu bireylere erken tanı amacıyla uygulanır. Semptomu olan kişilere yapılan işlem tarama değil tanısal incelemedir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 25, "question": "Aşağıdakilerden hangisi akciğer kanseri için risk faktörlerinden biri değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Radon"}, {"letter": "B", "text": "Hava kirliliği"}, {"letter": "C", "text": "Asbestoz"}, {"letter": "D", "text": "Sigara"}, {"letter": "E", "text": "Diyabetes mellitus"}], "answer": "E", "note": null, "id": "2019-2020_Q25", "prof_inferred": true, "explanation": "Sigara, radon gazı, asbest maruziyeti ve hava kirliliği akciğer kanserinin kanıtlanmış risk faktörleridir; Diabetes mellitus ise akciğer kanseri için bilinen bir risk faktörü değildir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 26, "question": "Aşağidakilerden hangisi immun kaynaklı akkiz hemolitik anemidir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Prostetik kalp kapağına bağlı hemolitik anemi"}, {"letter": "B", "text": "Karaciğerin mahmuz hücreli anemisi"}, {"letter": "C", "text": "Paroksisimal nokturnal hemoglobinüri"}, {"letter": "D", "text": "Uyumsuz kan transfüzyonu"}, {"letter": "E", "text": "Trombotik trombositopenik purpura (TTP)"}], "answer": "D", "note": null, "id": "2019-2020_Q26", "prof_inferred": true, "explanation": "ABO veya Rh uyumsuz kan transfüzyonu, alıcıdaki alloantikorların verici eritrositlerine bağlanarak kompleman aracılı yıkıma yol açtığı immün kaynaklı kazanılmış (akkiz) hemolitik anemidir. Diğer şıklar non-immün (mekanik, membran veya mikroanjiyopatik) hemolitik anemilerdir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 27, "question": "Aşağıdakilerden hangisi multiple myelomda görülmez?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Hiperkalsemi"}, {"letter": "B", "text": "Böbrek yetmezliği"}, {"letter": "C", "text": "Anemi"}, {"letter": "D", "text": "Osteosklerotik kemik lezyonu"}, {"letter": "E", "text": "Kemik iliğindeki plazma hücrelerinde ≥ % 10 artış olması"}], "answer": "D", "note": null, "id": "2019-2020_Q27", "prof_inferred": true, "explanation": "Multiple myelomda osteoklast aktivasyonu (RANKL artışı, OPG azalması) ve osteoblast inhibisyonu (DKK1 artışı) nedeniyle 'zımba ile delinmiş' görünümde osteolitik kemik lezyonları görülür; osteosklerotik lezyon (POEMS sendromu hariç) beklenmez. CRAB bulguları (Hiperkalsemi, Renal yetmezlik, Anemi, Kemik litik lezyonları) ve kemik iliğinde ≥%10 klonal plazma hücresi tipiktir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 21, "id": "2020-2021_Q21"}]}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 28, "question": "Sol supraklavikuler bölgede ağrısız, sert ve fikse lenfadenomegalisi saptanan bir\nhastada;", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ön planda kedi tırmığı hastalığı düşünürüm,"}, {"letter": "B", "text": "Ön planda intratorasik maligniteleri düşünürüm,"}, {"letter": "C", "text": "Tanımlanan lenf bezi Wirchow nodülü olarak adlandırılmakta olup, ön planda gastrointestinal sistem malignitesi düsünürüm,"}, {"letter": "D", "text": "Ön planda lenfoma düşünürüm,"}, {"letter": "E", "text": "Ön planda sarkoidoz düşünürüm."}], "answer": "C", "note": null, "id": "2019-2020_Q28", "explanation": "Sol supraklaviküler bölgede saptanan sert, ağrısız, fikse lenfadenopati 'Virchow nodülü' (Troisier bulgusu) olarak adlandırılır ve duktus torasikus drenajı nedeniyle öncelikle mide/gastrointestinal sistem malignitelerinin metastazını düşündürür."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 29, "question": "Kronik lenfositer lösemi tanısı için aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Periferik kanda ≥5000/μL monoklonal B lenfosit olmalıdır,"}, {"letter": "B", "text": "Akım sitometride CD5, 19, 20 ve 23 pozitif klonal lenfositler olmalıdır,"}, {"letter": "C", "text": "Mevcut anormalliklerin >3 ay süreli olması gerekir,"}, {"letter": "D", "text": "Kemik iliği tutulumuna bağlı sitopeni varlığı durumunda tan için lenfositoz şart değildir."}, {"letter": "E", "text": "Tanı için kemik iliği biyopsisi mutlak şarttır."}], "answer": "E", "note": null, "id": "2019-2020_Q29", "prof_inferred": true, "explanation": "Kronik Lenfositer Lösemi (KLL) tanısı periferik kanda en az 3 ay süren ≥5000/µL monoklonal B lenfositoz ve akım sitometride CD5, CD19, CD20(soluk), CD23 pozitifliği ile konur; tanı için kemik iliği biyopsisi mutlak şart değildir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 30, "question": "Dünya Sağlık Örgütü 2018 sınıflamasına göre aşağıdaki hastalıklardan hangisi\nmiyeloproliferatif hastalıkların içinde sınıflandırılmaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kronik myeloid lösemi"}, {"letter": "B", "text": "Polisitemia vera"}, {"letter": "C", "text": "Esansiyel trombositemi"}, {"letter": "D", "text": "Kronik lenfositik Iösemi"}, {"letter": "E", "text": "Primer miyelofibroz"}], "answer": "D", "note": null, "id": "2019-2020_Q30", "explanation": "DSÖ sınıflamasına göre KML, Polisitemia Vera, Esansiyel Trombositemi ve Primer Miyelofibroz kronik miyeloproliferatif neoplazilerdir. Kronik Lenfositik Lösemi (KLL) ise olgun B hücreli lenfoproliferatif bir neoplazidir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 31, "question": "Deride, bazen palpabl olabilen, 3-5 mm boyutunda kırmızı-mor renkli kanama\nodaklarına ne denir", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Peteşi"}, {"letter": "B", "text": "Purpura"}, {"letter": "C", "text": "Hematom"}, {"letter": "D", "text": "Ekimoz"}, {"letter": "E", "text": "Hemartroz"}], "answer": "B", "note": null, "id": "2019-2020_Q31", "explanation": "Deride ve mukozalarda 2 mm'den küçük noktasal kanamalara peteşi, 3-5 mm (veya 2-10 mm) arasındaki kırmızı-mor kanama odaklarına purpura, >1 cm olan yaygın kanamalara ise ekimoz denir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 32, "question": "Hangisi ekstramedüller hematopoez bölgesi değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Dalak"}, {"letter": "B", "text": "Böbrek"}, {"letter": "C", "text": "Kostalar"}, {"letter": "D", "text": "Karaciğer"}, {"letter": "E", "text": "Lenf ganglionları"}], "answer": "C", "note": null, "id": "2019-2020_Q32", "explanation": "Kostalar erişkinde normal medüller hematopoezin devam ettiği yassı kemiklerdendir (ekstramedüller değildir). Kemik iliği dışında karaciğer, dalak, lenf nodları ve nadiren böbrek/paravertebral alanlarda kan yapımına ekstramedüller hematopoez denir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 33, "question": "Aplastik anemili bir hastanın fizik muayenesinde aşağıdakilerden hangisinin\nbulunması beklenmez?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Peteşi ve purpuralar"}, {"letter": "B", "text": "Splenomegali"}, {"letter": "C", "text": "Boy kısalığı"}, {"letter": "D", "text": "Solukluk"}, {"letter": "E", "text": "İskelet anomalileri"}], "answer": "B", "note": null, "id": "2019-2020_Q33", "prof_inferred": true, "explanation": "Aplastik anemide fizik muayenede pansitopeniye bağlı solukluk, peteşi/purpura ve konjenital formlarda (Fanconi) boy kısalığı/iskelet anomalileri görülebilir; ancak splenomegali ve lenfadenopati beklenmez (varsa lösemi, lenfoma veya miyelofibrozis düşünülmelidir)."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 34, "question": "Çabuk doyma, halsizlik, kilo kaybı yakınması ile hastaneye başvuran bir erkek\nhastanın muayenesinde dalağın alt kosta hattını 15 cm geçtiği saptanıyor. Kan sayımında\nlökosit 450 000 /uL (Normali 4.000-10.500 /uL), trombosit sayısı 550.000/uL (Normali 150-\n450.000 /uL) ve hafif bir anemi tespit ediliyor. Bu hastada olası ön tanınız ve ilk yapacağınız\ntetkik nedir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kronik myelositer lösemi/ Philadelphia kromozomu"}, {"letter": "B", "text": "Esansiyel trombositemi/ Periferik yayma"}, {"letter": "C", "text": "Kronik myelositer lösemi/ BCR-ABL gen mutasyonu analizi"}, {"letter": "D", "text": "Polistemia vera/ Lökosit alkalen fosfataz düzeyi"}, {"letter": "E", "text": "Kronik myelositer lösemi/ Periferik yayma"}], "answer": "E", "note": null, "id": "2019-2020_Q34", "explanation": "Masif splenomegali, çok yüksek lökosit sayısı (450.000/µL), trombositoz ve hafif anemi ile başvuran hastada en olası ön tanı Kronik Miyelositer Lösemi (KML) olup, hematolojik değerlendirmede ilk yapılması gereken temel tetkik periferik yaymadır (miyeloid serinin tüm olgunlaşma basamaklarının görülmesi)."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "Aşağıdakilerden hangisi lenf bezi biyopsisi yapılması gereken durumlardan\ndeğildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Lenfadenomegaliye ilave olarak kilo kaybı, ateş, gece terlemesi gibi sistemik bulgu varlığı,"}, {"letter": "B", "text": "Lenfadenomegaliye ilave olarak başka bir nedene bağlanamayan splenomegali varlığı,"}, {"letter": "C", "text": "Supraklaviküler veya mediastinal 10-15 mm çapında lenfadenopati saptanması,"}, {"letter": "D", "text": "Sert, çevre dokulara veya birbirlerine yapışık lenf bezi/bezleri tespit edilmesi,"}, {"letter": "E", "text": "Kasıkta 10-15 mm çapında ağrılı lenfadenopati saptanması."}], "answer": "E", "note": null, "id": "2019-2020_Q35", "explanation": "Kasıkta (inguinal) 1-1.5 cm çapında ve ağrılı lenfadenopati genellikle alt ekstremite veya genital bölgedeki lokal bir enfeksiyona bağlı reaktif lenfadenittir; biyopsi gerektirmez. B semptomları, splenomegali, supraklaviküler/mediastinal yerleşim ve sert/fikse lenf nodları biyopsi endikasyonudur."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "Aneminin morfolojik değerlendirilmesinde temel belirleyici aşağıdakilerden\nhangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kırmızı küre volüm dağılım"}, {"letter": "B", "text": "Ortalama eritrosit hacmi"}, {"letter": "C", "text": "Retikülosit"}, {"letter": "D", "text": "Ortalama eritrosit hemoglobini"}, {"letter": "E", "text": "Demir"}], "answer": "B", "note": null, "id": "2019-2020_Q36", "explanation": "Anemilerin morfolojik sınıflamasında (mikrositer, normositer, makrositer) temel belirleyici parametre Ortalama Eritrosit Hacmi (MCV - Mean Corpuscular Volume)'dir."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Eritropoez için aşağıdakilerden hangisi gereklidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Eritropoetin"}, {"letter": "B", "text": "Çinko"}, {"letter": "C", "text": "E vitamini"}, {"letter": "D", "text": "Sodyum"}, {"letter": "E", "text": "Trigliserit"}], "answer": "A", "note": null, "id": "2019-2020_Q37", "explanation": "Kemik iliğinde eritroid öncül hücrelerin çoğalması ve olgunlaşması (eritropoez) için böbreklerden hipoksiye yanıt olarak salgılanan Eritropoetin (EPO) hormonu temel uyarandır."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "Hangisi hipokrom mikrositer anemi sebepleri arasında yer almaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Demir eksikliği anemisi"}, {"letter": "B", "text": "Folat eksikliği"}, {"letter": "C", "text": "Talasemi"}, {"letter": "D", "text": "Kronik hastalık anemisi"}, {"letter": "E", "text": "Sideroblastik anemi"}], "answer": "B", "note": null, "id": "2019-2020_Q38", "explanation": "Hipokrom mikrositer anemi nedenleri ('TAŞ Kafa' / 'TICS'): Talasemi, Kronik hastalık anemisi, Sideroblastik anemi, Demir eksikliği anemisi ve Kurşun zehirlenmesidir. Folat eksikliği ise DNA sentezini bozarak megaloblastik (makrositer) anemi yapar."}, {"year": "2019-2020", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Fizik muayene bulgusu olarak perküsyonla traube alanında matite tespit edilen\nhastada aşağıdakilerden hangisi bulunabilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hepatomegali"}, {"letter": "B", "text": "Megakolon"}, {"letter": "C", "text": "Splenomegali"}, {"letter": "D", "text": "Gastroparezi"}, {"letter": "E", "text": "İleus"}], "answer": "C", "note": null, "id": "2019-2020_Q39", "explanation": "Traube alanı sol alt toraksta mide fundus gazına bağlı timpanik ses alınan semilunar alandır; dalak büyüdüğünde (splenomegali) Traube alanı kapanır ve perküsyonda matite alınır."}, {"year": "2019-2020", "subject": "Tıbbi Genetik", "q_num": 40, "question": "Güneş ışınlarına şiddetli hassasiyet, ilerleyici nörolojik hastalık: mikrosefali, derin\ntendon reflekslerinin azalması ya da olmaması, progresif sensorinöral işitme kaybı, kognitif\nbozukluk, cilt / göz kanserlerde 1000 kat artışla karakterize hastalık hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ataxia-telangiektazi"}, {"letter": "B", "text": "Bloom Sendromu"}, {"letter": "C", "text": "Kseroderma pigmentosum"}, {"letter": "D", "text": "Nörofibromatozis"}, {"letter": "E", "text": "Fankoni Anemisi"}], "answer": "C", "note": null, "id": "2019-2020_Q40", "explanation": "Kseroderma pigmentosum, nükleotid eksizyon onarım (NER) mekanizmasındaki genetik defekt sonucu UV (güneş) ışınlarının oluşturduğu pirimidin dimerlerinin onarılamaması, şiddetli fotosensitivite, nörolojik dejenerasyon ve deri/göz kanserlerinde 1000 kat artış ile karakterize otozomal resesif hastalıktır."}, {"year": "2019-2020", "subject": "Tıbbi Genetik", "q_num": 41, "question": "Talasemiler hakkında aşağıda yer alanlardan hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hemoglobin sentezindeki defekt, hipokromik mikrositer bir anemi oluşturur."}, {"letter": "B", "text": "Beta talasemiler postnatal olduğu gibi intrauterin olarak da hastalığa neden olur."}, {"letter": "C", "text": "a- globin zincir yokluğunda, ß- globin zincirleri bir homotetramerik hemoglobin oluşturur."}, {"letter": "D", "text": "ß- zincirlerinin yokluğunda, normal oranda üretilen a-zincirler hemoglobin üretebilmek için bir tetramer oluşturamaz ve presipite olur."}, {"letter": "E", "text": "Her iki ß-globin allelinde de mutasyon taşıyan bireyler (homozigot) şiddetli anemileri nedeniyle yaşam boy tıbbi bakıma ihtiyaç duyup, talasemi major olarak adlandırılır."}], "answer": "B", "note": null, "id": "2019-2020_Q41", "explanation": "Fetal dönemde ana hemoglobin HbF (α2γ2) olduğu ve beta globin zincir sentezi doğumdan sonra (postnatal) belirginleştiği için beta talasemiler intrauterin dönemde hastalık bulgusu vermez; semptomlar postnatal 3-6. aydan sonra ortaya çıkar."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 42, "question": "Aşağıdakilerden hangisi granülasyon dokusunda bulunmaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Tip 1 kollajen"}, {"letter": "B", "text": "Tip 3 kollajen"}, {"letter": "C", "text": "Neovaskülarizasyon"}, {"letter": "D", "text": "Lenfositler"}, {"letter": "E", "text": "Fibroblastlar"}], "answer": "A", "note": null, "id": "2019-2020_Q42", "explanation": "Erken granülasyon dokusunda yeni damarlanma (neovaskülarizasyon), fibroblastlar, mononükleer iltihabi hücreler (makrofaj, lenfosit) ve başlangıçta ince Tip 3 kollajen bulunur; olgun skar dokusunun ana bileşeni olan Tip 1 kollajen ise daha geç evrede (remodeling) baskın hale gelir."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 43, "question": "Aşağıdakilerden hangisi sekonder yara iyileşmesinin bir sonucu değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Daha büyük skar dokusu gelişimi ile sonuçlanması"}, {"letter": "B", "text": "12. saatte epitelizasyonun başlaması"}, {"letter": "C", "text": "Yüksek oranda inflamasyon bulunması"}, {"letter": "D", "text": "Daha uzun sürede iyileşmesi"}, {"letter": "E", "text": "Yara kontraksiyonunun daha yavaş gelişmesi"}], "answer": "B", "note": null, "id": "2019-2020_Q43", "explanation": "12-24. saatte hızlı epitelizasyonun başlaması geniş doku kaybı olmayan 'primer (birincil) yara iyileşmesi'nin özelliğidir. Sekonder yara iyileşmesinde doku kaybı fazladır, inflamasyon yoğundur, iyileşme uzun sürer ve belirgin skar/kontraksiyon gelişir."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 44, "question": "Akut iltihapta, nötrofillerin damar dışına çıkışı süresince ve sonrasında izlenen\ndeğişiklikler, sırasıyla aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Marjinasyon, rolling, adhezyon, transmigrasyon, kemotaksis"}, {"letter": "B", "text": "Transmigrasyon, marjinasyon, rolling, kemotaksis, adhezyon"}, {"letter": "C", "text": "Marjinasyon, adhezyon, transmigrasyon, roling, kemotaksis"}, {"letter": "D", "text": "Rolling, adhezyon, marjinasyon, kemotaksis, transmigrasyon"}, {"letter": "E", "text": "Adhezyon, rolling, marjinasyon,transmigrasvon, emolaksIs"}], "answer": "A", "note": null, "id": "2019-2020_Q44", "explanation": "Akut inflamasyonda lökositlerin damar lümeninden hasar alanına göç sırası: 1. Marjinasyon (duvara yaklaşma), 2. Rolling (selektinlerle yuvarlanma), 3. Adezyon (integrinlerle sıkı yapışma), 4. Transmigrasyon/Diapedez (PECAM-1/CD31 ile endotel arasından geçiş), 5. Kemotaksis (kimyasal uyaranlara doğru göç)."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 45, "question": "Akut iltihapta, nötrofiller için bilinen en kuvvetli eksojen kemotaktik madde\naşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Lökotrien B4"}, {"letter": "B", "text": "Histamin"}, {"letter": "C", "text": "Nitrik oksit"}, {"letter": "D", "text": "PAF"}, {"letter": "E", "text": "Solubl bakteri ürünleri"}], "answer": "E", "note": null, "id": "2019-2020_Q45", "explanation": "Akut iltihapta nötrofiller için en güçlü ekzojen kemotaktik ajanlar solübl bakteriyel ürünlerdir (özellikle N-formil-metiyonil peptidler). LTB4, C5a ve IL-8 ise endojen kemotaktik maddelerdir."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 46, "question": "Filariazis tablosunda geligen ödemin nedeni aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Yüksek kan hidrostatik basıncı"}, {"letter": "B", "text": "Düşük plazma onkotik basıncı"}, {"letter": "C", "text": "Lenfatik obstrüksiyon"}, {"letter": "D", "text": "Sodyum ve su tutulumu"}, {"letter": "E", "text": "Enflamasyon"}], "answer": "C", "note": null, "id": "2019-2020_Q46", "explanation": "Wuchereria bancrofti'nin neden olduğu filariazis tablosunda parazitler lenf damarlarını ve lenf düğümlerini tıkayarak fibrozise ve ağır lenfatik obstrüksiyona (elefantiyazis / fil hastalığı tipinde lenfödem) yol açar."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 47, "question": "Sağ kalp yetmezliğinde gelişen sistemik konjesyon tablosunda, karaciğerde izlenen\ndeğişikliğe ne ad verilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hepatosteatoz"}, {"letter": "B", "text": "Perisantral yağlanma"}, {"letter": "C", "text": "Lannec sirozu"}, {"letter": "D", "text": "Nutmeg karaciğer"}, {"letter": "E", "text": "Kardiyak siroz"}], "answer": "D", "note": null, "id": "2019-2020_Q47", "explanation": "Sağ kalp yetmezliğinde karaciğerde kronik pasif konjesyon gelişir; santral ven çevresindeki hemorajik/konjesyone alanlar ile periferdeki soluk/yağlı parankim bir arada küçük hindistan cevizi ('nutmeg' / muskat karaciğer) görünümü oluşturur."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 48, "question": "Hasta kişinin ikizinden alınan doku transplantasyonuna ne ad verilir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Allograft"}, {"letter": "B", "text": "Ksenograft"}, {"letter": "C", "text": "Otograft"}, {"letter": "D", "text": "İzograft"}, {"letter": "E", "text": "Transgraft"}], "answer": "D", "note": null, "id": "2019-2020_Q48", "prof_inferred": true, "explanation": "Genetik olarak özdeş bireyler (tek yumurta ikizleri veya inbred hayvan suşları) arasında yapılan doku/organ nakline izogreft (singeneik greft) denir. Otogreft kişinin kendisinden, allogreft aynı türün farklı bireyinden, ksenogreft farklı türden yapılan nakildir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 68, "id": "2021-2022_Q68"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 49, "question": "En sık görülen primer immün yetmezlik tipi aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Izole IgA eksikligi"}, {"letter": "B", "text": "Ağır kombine immün yetersizlik hastalığı"}, {"letter": "C", "text": "Bruton'un X'e bağlı agammaglobülinemisi"}, {"letter": "D", "text": "Di George Sendromu"}, {"letter": "E", "text": "Değişken immün yetersizlik"}], "answer": "A", "note": null, "id": "2019-2020_Q49", "explanation": "Toplumda en sık görülen primer immün yetmezlik İzole (Selektif) IgA eksikliğidir (yaklaşık 1/600). Çoğu hasta asemptomatik olmakla birlikte tekrarlayan sinopulmoner ve GİS enfeksiyonları görülebilir."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 50, "question": "Bütün malign tümörler düşünüldüğünde, prognozun belirlenmesi için en iyi veri\naşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Stage (evre)"}, {"letter": "B", "text": "Grade"}, {"letter": "C", "text": "Tümörün yerleşim yeri ve grade’i"}, {"letter": "D", "text": "Tümörün diferansiasyon derecesi ve mitoz sayısı"}, {"letter": "E", "text": "Tümörün çapı"}], "answer": "A", "note": null, "id": "2019-2020_Q50", "explanation": "Malign tümörlerde klinik gidişatı ve sağkalımı (prognozu) belirlemede en önemli faktör tümörün yayılım derecesini gösteren Evre (Stage - TNM)'dir; histolojik derece (Grade) ise evreden sonra gelir."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 51, "question": "Migratuar (gezici) trombofilebit (Trousseau Fenomeni) en sık hangi malign\ntümörlerle bir arada görülür?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Pankreas adenokarsinomu"}, {"letter": "B", "text": "Kolon karsinomları"}, {"letter": "C", "text": "Mide karsinomları"}, {"letter": "D", "text": "Tiroid karsinomları"}, {"letter": "E", "text": "Beyin tümörleri"}], "answer": "A", "note": null, "id": "2019-2020_Q51", "prof_inferred": true, "explanation": "Gezici (migratuar) tromboflebit olarak bilinen Trousseau fenomeni, müsin üreten adenokarsinomlarda (en sık pankreas ve akciğer karsinomları) görülen paraneoplastik bir hiperkoagülabilite tablosudur.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 65, "id": "2021-2022_Q65"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 52, "question": "Aşağıdakilerden hangisi nonspesifik reaktif parakortikal lenfoid hiperplazi\nsebeplerinden değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Postvaksinal LAP"}, {"letter": "B", "text": "Dermatopatik LAP"}, {"letter": "C", "text": "Toxoplazma LAP"}, {"letter": "D", "text": "İlaç hipersensitivite LAP"}, {"letter": "E", "text": "Non-EBV ile ilgili (CMV, HSV) viral LAP"}], "answer": "C", "note": null, "id": "2019-2020_Q52", "prof_inferred": true, "explanation": "Toksoplazma lenfadenopatisi parakortikal hiperplazi değil; belirgin folliküler hiperplazi, marjinal zon monositoid B hücre proliferasyonu ve germinal merkezleri çevreleyen epiteloid histiyosit kümeleri (Piringer-Kuchinka lenfadeniti) ile karakterizedir. Viral enfeksiyonlar, aşı sonrası, ilaç reaksiyonları ve dermatopatik LAP parakortikal (T-zon) hiperplazi yapar."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 53, "question": "Aşağıdakilerden hangisi folliküler paternde lenfoid hiperplazi- folliküler lenfoma\nayırımında, lenfoid hiperplazi lehine bir bulgu değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Foliküllerin subkortikal yerleşimli olması"}, {"letter": "B", "text": "Kapsül ötesine genişleme olmaması"}, {"letter": "C", "text": "Folikül sayısının az olması"}, {"letter": "D", "text": "Farklı şekil ve büyüklükte foliküller olması"}, {"letter": "E", "text": "Foliküllerde Bcl-2 antikoru ile boyanma olması (pozitif immünoreaktivite)"}], "answer": "E", "note": null, "id": "2019-2020_Q53", "prof_inferred": true, "explanation": "Reaktif folliküler hiperplazide germinal merkez hücrelerinde apoptoz aktif olduğu için anti-apoptotik BCL-2 proteini eksprese edilmez (negatiftir). Foliküllerde BCL-2 pozitifliği t(14;18) translokasyonu taşıyan Folliküler Lenfoma lehine en önemli immünohistokimyasal bulgudur.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 66, "id": "2021-2022_Q66"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 54, "question": "Granülom hangi tip immün reaksiyon sonucu meydana gelir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Tip 1 hipersensitivite"}, {"letter": "B", "text": "Antikor aracılı hipersensitivite"}, {"letter": "C", "text": "Hücre aracılı hipersensitivite"}, {"letter": "D", "text": "Immünkompleks aracılı"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "C", "note": null, "id": "2019-2020_Q54", "explanation": "Granülom oluşumu, sindirilemeyen ajanlara karşı CD4+ Th1 lenfositlerin salgıladığı IFN-γ aracılığıyla makrofajların epiteloid histiyositlere ve çok çekirdekli dev hücrelere dönüştüğü Tip IV (hücre aracılı / gecikmiş tip) aşırı duyarlılık reaksiyonudur."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 55, "question": "Arthus reaksiyonu nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Deneysel görülen kütanöz vaskülitdir."}, {"letter": "B", "text": "Hepatit 'de görülen sistemik vaskülitdir"}, {"letter": "C", "text": "SLE 'de görülen sistemik vaskülitdir."}, {"letter": "D", "text": "Poststreptokoksik glomerülonefritdir,"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": null, "id": "2019-2020_Q55", "prof_inferred": true, "explanation": "Arthus reaksiyonu, daha önce duyarlılaştırılmış (dolaşımda presipitan IgG antikoru bulunan) bir bireye antijenin intradermal/subkutan enjeksiyonu sonrası gelişen lokalize immün kompleks (Tip III) aracılı deneysel akut nekrotizan kütanöz vaskülittir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 59, "id": "2021-2022_Q59"}, {"kurul": "1", "year": "2024-2025", "q_num": 65, "id": "2024-2025_Q65"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 56, "question": "Sjögren sendromu için hangisi doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Keratoconjunctivitis sicca vardır,"}, {"letter": "B", "text": "CD8 hücreleri ile İlişkilidir"}, {"letter": "C", "text": "Xerostomia vardır,"}, {"letter": "D", "text": "SS-A (Ro) ve SS-B (La)ya karşı otoantikorlara sahiptir"}, {"letter": "E", "text": "SLE de görülebilir"}], "answer": "B", "note": null, "id": "2019-2020_Q56", "prof_inferred": true, "explanation": "Sjögren sendromu gözyaşı ve tükürük bezlerinin immün aracılı yıkımı (keratokonjonktivitis sikka ve kserostomi) ile seyreden otoimmün bir hastalıktır; patogenezde dokuyu infiltre eden temel hücreler CD8+ değil, CD4+ yardımcı T lenfositler ve B hücreleridir. Anti-SS-A (Ro) ve Anti-SS-B (La) antikorları karakteristiktir.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 79, "id": "2024-2025_Q79"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 57, "question": "Knudson'un gift-darbe hipotezi ilk hangi tümörde öne sürülmüştür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Meme karsinomu"}, {"letter": "B", "text": "Akciğer karsinomu"}, {"letter": "C", "text": "Osteosarkom"}, {"letter": "D", "text": "Nöroblastom"}, {"letter": "E", "text": "Retinoblastom"}], "answer": "E", "note": null, "id": "2019-2020_Q57", "prof_inferred": true, "explanation": "Knudson'un çift vuruş (two-hit) karsinogenez hipotezi ilk kez bir tümör süpresör gen olan RB1 genini ve Retinoblastom gelişimini açıklamak için ileri sürülmüştür (tümör gelişimi için her iki allelin de inaktive olması gerekir).", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 67, "id": "2024-2025_Q67"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 58, "question": "Tümörlerde Warburg elkisini kullanan tanısal yöntem hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Immünhistokimyasal yöntemler"}, {"letter": "B", "text": "Immünfloersan incelemeler"}, {"letter": "C", "text": "Bilgisayarlı tomografi"}, {"letter": "D", "text": "PET-BT"}, {"letter": "E", "text": "Ultrasonografik inceleme"}], "answer": "D", "note": null, "id": "2019-2020_Q58", "prof_inferred": true, "explanation": "Warburg etkisi, tümör hücrelerinin bol oksijen varlığında bile enerji üretimi için oksidatif fosforilasyon yerine aerobik glikolizi tercih ederek yüksek miktarda glukoz tüketmesidir. PET-BT (18F-FDG) tümörlerin bu yüksek glukoz tutulumunu görüntüleyerek tanı ve evrelemede kullanılır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 55, "id": "2021-2022_Q55"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 59, "question": "Hangisi homolog rekombinasyon ile DNA onarımı kusurlarının mevcut olduğu\nhastalıklardan değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Herediter nonpolipöz kolon kanseri sendromu"}, {"letter": "B", "text": "Bloom sendromu"}, {"letter": "C", "text": "Fanconi anemisi"}, {"letter": "D", "text": "Ataksi-telanjiektazi"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": null, "id": "2019-2020_Q59", "prof_inferred": true, "explanation": "Herediter Nonpolipozis Kolon Kanseri (HNPCC - Lynch sendromu) homolog rekombinasyon kusuru değil, DNA yanlış eşleşme onarımı (Mismatch Repair - MMR: MLH1, MSH2, MSH6, PMS2) kusuru sonucu gelişir ve mikrosatellit instabilitesi ile karakterizedir. Bloom, Fanconi anemisi ve Ataksi-telanjiektazi homolog rekombinasyon/DNA kırık onarım bozukluklarıdır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 56, "id": "2021-2022_Q56"}, {"kurul": "1", "year": "2024-2025", "q_num": 60, "id": "2024-2025_Q60"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 60, "question": "Aort anevrizmasi ve disseksiyonu hangi genetik hastalıkta sik görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Ehlers-Danlos sendromu"}, {"letter": "B", "text": "Marfan sendromu"}, {"letter": "C", "text": "Kistik fibrozis"}, {"letter": "D", "text": "Fenilketonüri"}, {"letter": "E", "text": "Tay-Sachs hastalığı"}], "answer": "B", "note": null, "id": "2019-2020_Q60", "prof_inferred": true, "explanation": "Marfan sendromu, 15. kromozomdaki FBN1 (fibrillin-1) gen mutasyonu sonucu elastik liflerin bozulduğu otozomal dominant bir bağ dokusu hastalığıdır; aort kökünde kistik mediyal dejenerasyona bağlı aort anevrizması ve diseksiyonu en önemli ölüm nedenidir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 52, "id": "2021-2022_Q52"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 61, "question": "Sitolojik olarak \"buruşmuş kağıt görüntüsü” hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tay-Sachs hastalığı"}, {"letter": "B", "text": "Niemann-Pick hastalığı"}, {"letter": "C", "text": "Gaucher hastalığı"}, {"letter": "D", "text": "Hurler sendromu"}, {"letter": "E", "text": "Hunter sendromu"}], "answer": "C", "note": null, "id": "2019-2020_Q61", "prof_inferred": true, "explanation": "Gaucher hastalığı glukoserebrozidaz (beta-glukozidaz) enzim eksikliği sonucu makrofajlarda glukoserebrozid birikimiyle karakterizedir; bu makrofajların (Gaucher hücreleri) sitoplazması mikroskopta 'buruşuk kağıt' (crinkled paper) görünümündedir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 53, "id": "2021-2022_Q53"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 62, "question": "Di George sendromu için hangisi doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "22q11.2 delesyonu vardır"}, {"letter": "B", "text": "Timik hipoplazi vardır"}, {"letter": "C", "text": "Hipokalsemi vardır"}, {"letter": "D", "text": "Yele boyun vardır"}, {"letter": "E", "text": "T hücre immün yetmezliği vardır"}], "answer": "D", "note": null, "id": "2019-2020_Q62", "prof_inferred": true, "explanation": "Yele boyun (webbed neck) DiGeorge sendromunda değil, Turner sendromunda (45,X0) ve Noonan sendromunda görülen tipik bir bulgudur. DiGeorge sendromunda 22q11.2 delesyonu, timik hipoplazi (T hücre yetmezliği) ve paratiroid hipoplazisi (hipokalsemi) görülür.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 54, "id": "2021-2022_Q54"}, {"kurul": "1", "year": "2024-2025", "q_num": 72, "id": "2024-2025_Q72"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 63, "question": "Non-immün hidropsta önem kazanan virüs hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Hepatitis B"}, {"letter": "B", "text": "Hepatitis C"}, {"letter": "C", "text": "Rubella"}, {"letter": "D", "text": "Varicella"}, {"letter": "E", "text": "Parvovirus B19"}], "answer": "E", "note": null, "id": "2019-2020_Q63", "prof_inferred": true, "explanation": "Parvovirus B19, eritroid öncül hücrelerdeki P antijenine bağlanarak eritropoezi baskılar; gebelikte fetüse geçtiğinde ağır fetal anemi, yüksek debili kalp yetmezliği ve non-immün hidrops fetalise yol açan en önemli viral etkendir.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 73, "id": "2024-2025_Q73"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 64, "question": "Otosplenektomi hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Herediter sferositoz"}, {"letter": "C", "text": "Alfa talasemi"}, {"letter": "D", "text": "Beta talasemi"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}], "answer": "A", "note": null, "id": "2019-2020_Q64", "prof_inferred": true, "explanation": "Orak hücreli anemide tekrarlayan vazo-oklüzif krizler ve dalak enfarktları sonucunda dalak dokusu zamanla tamamen fibrotik ve kalsifiye hale gelerek işlevini kaybeder; bu tabloya 'otosplenektomi' denir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 49, "id": "2021-2022_Q49"}, {"kurul": "1", "year": "2024-2025", "q_num": 74, "id": "2024-2025_Q74"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 65, "question": "Heinz cisimcikleri hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}, {"letter": "B", "text": "Orak hücreli anemi"}, {"letter": "C", "text": "Herediter stfrositoz"}, {"letter": "D", "text": "Beta talasemi"}, {"letter": "E", "text": "Paroksismal noktürnal hemoglobülinüri"}], "answer": "A", "note": null, "id": "2019-2020_Q65", "prof_inferred": true, "explanation": "Glukoz-6-Fosfat Dehidrogenaz (G6PD) eksikliğinde glutatyon indirgenemediği için eritrositler oksidatif strese maruz kaldığında hemoglobin denatüre olur ve eritrosit membranına çökerek 'Heinz cisimciklerini' oluşturur (dalak makrofajları bunları ısırarak 'bite cell' yapar).", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 50, "id": "2021-2022_Q50"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 66, "question": "Raynaud fenomeni hangi anemi türünde görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Beta talasemi"}, {"letter": "C", "text": "Sick antikorlu immünhemolitik anemiler"}, {"letter": "D", "text": "Soğuk antikorlu immünhemolitik anemiler"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}], "answer": "D", "note": null, "id": "2019-2020_Q66", "prof_inferred": true, "explanation": "Soğuk antikorlu (IgM tipi) otoimmün hemolitik anemilerde, vücudun soğuğa maruz kalan uç kısımlarında (parmak uçları, burun, kulak) IgM antikorları eritrositleri aglütine ederek mikrovasküler tıkanıklığa, akrosiyanoza ve Raynaud fenomenine yol açar.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 51, "id": "2021-2022_Q51"}, {"kurul": "1", "year": "2024-2025", "q_num": 77, "id": "2024-2025_Q77"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 67, "question": "Auer cisimcikleri hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut lenfoblastik Iösemi"}, {"letter": "B", "text": "Akut myeloblastik Iösemi"}, {"letter": "C", "text": "Myelodisplastik sendrom"}, {"letter": "D", "text": "Kronik myelositer lösemi"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "B", "note": null, "id": "2019-2020_Q67", "prof_inferred": true, "explanation": "Auer cisimcikleri (Auer çubukları), miyeloblastların sitoplazmasında azurofilik granüllerin (miyeloperoksidaz pozitif) kaynaşmasıyla oluşan iğne şeklindeki kristaloid yapılardır ve Akut Miyeloblastik Lösemi (AML - özellikle M2 ve M3/APL) için tanısaldır."}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 68, "question": "Hangisi mezenşimal tümör değildir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Anjiosarkom"}, {"letter": "B", "text": "Bazal hücreli karsinom"}, {"letter": "C", "text": "Fibrosarkom"}, {"letter": "D", "text": "Snovyal sarkom"}, {"letter": "E", "text": "Glomus tümörü"}], "answer": "B", "note": null, "id": "2019-2020_Q68", "prof_inferred": true, "explanation": "Bazal hücreli karsinom (BCC) epidermisin bazal tabakasından köken alan malign epitelyal bir tümördür; mezenşimal tümör değildir. Anjiyosarkom, fibrosarkom, sinovyal sarkom ve glomus tümörü mezenşimal kökenlidir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 61, "id": "2020-2021_Q61"}, {"kurul": "1", "year": "2021-2022", "q_num": 79, "id": "2021-2022_Q79"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 69, "question": "Malign tümör derecelendirmesinde hangisi kullanılır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenf düğümü metastazı sayısı"}, {"letter": "B", "text": "Tümör çapı"}, {"letter": "C", "text": "Tümörün çevre dokuya invazyonu"}, {"letter": "D", "text": "Tümörün sitolojik diferansiasyon derecesi"}, {"letter": "E", "text": "Karaciğer metastazının varlığı / yoklugu"}], "answer": "D", "note": null, "id": "2019-2020_Q69", "prof_inferred": true, "explanation": "Malign tümörlerde Derecelendirme (Grading), tümör hücrelerinin normal dokuya ne kadar benzediğini yani sitolojik diferansiasyon derecesini (ve mitoz/nekroz oranını) ifade eder. Tümör çapı, lenf nodu ve uzak organ metastazı ise Evreleme (Staging - TNM) parametreleridir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 60, "id": "2020-2021_Q60"}, {"kurul": "1", "year": "2021-2022", "q_num": 80, "id": "2021-2022_Q80"}, {"kurul": "1", "year": "2022-2023", "q_num": 68, "id": "2022-2023_Q68"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 70, "question": "Infarktüs, nekroz ve şok ile ilgili aşağıda verilen bilgilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Infarktüs bir dokunun vasküler beslenmesinin kesilmesi ile oluşan iskemik nekroz alanıdır ve pulmoner infarktüs sık görülen bir komplikasyondur."}, {"letter": "B", "text": "Infarktüsler renklerine göre ve mikrobiyal infeksiyon varlığı veya yokluğuna göre kırmızı /hemorajik veya beyaz /anemik ve septik veya aseptik olarak sınıflandırılır"}, {"letter": "C", "text": "Kırmızı infarktüsler; Akciğer ve ince barsak gibi çift dolaşımlı dokularda oluşur"}, {"letter": "D", "text": "Beyin bu genellemelerin istisnasını oluşturur: Merkezi sinir sisteminde iskemik doku hasan likefaksiyon nekrozu ile sonuçlanır"}, {"letter": "E", "text": "Şok; kardiyak outputun ve/veya dolaşımdaki etkin kan hacminin azalması sonucu meydana gelen sistemik doku hipoperfüzyonu durumudur"}], "answer": "E", "note": null, "id": "2019-2020_Q70", "prof_inferred": true, "explanation": "Soru kökünde 'Şok; ... sistemik doku hipoperfüzyonu durumudur' cümlesi doğru görünse de diğer yıllardaki aynı soruda E şıkkı 'hiperperfüzyonu' olarak yazıldığı için cevap anahtarında E şıkkı işaretlenmiştir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 55, "id": "2020-2021_Q55"}, {"kurul": "1", "year": "2021-2022", "q_num": 71, "id": "2021-2022_Q71"}, {"kurul": "1", "year": "2022-2023", "q_num": 61, "id": "2022-2023_Q61"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 71, "question": "Inflamasyon mediyatörleri ile ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Kronik iltihabin mediatörleri; lanfosit, makrofaj, plazma hücresi, eozinofil, mast hücreleridir"}, {"letter": "B", "text": "Kanda monositlerin yarılanma ömrü 1 gündür, doku makrofajları ise aylarca yaşayabilirler."}, {"letter": "C", "text": "Asit ve nötral proteazlar; doku hasarı, kompleman komponentleri ve koagülasyon faktörlerinin lokal miktarı artar, reaktif oksijen ürünleri ve NO doku hasarı yapar"}, {"letter": "D", "text": "IL-1, IFN-y dev hücre oluşumunu sağlar, özellikle IFN-y makrofajların epiteloid histiositlere ve dev hücrelere dönüşümünde önemlidir"}, {"letter": "E", "text": "T lenfositlerden ; IL1, TNF ve kemokinler salgılanır ve Makrofajları uyarır, Makrofajlardan IFN gama salgılanır ve T lenfositleri uyarır"}], "answer": "E", "note": null, "id": "2019-2020_Q71", "prof_inferred": true, "explanation": "Kronik inflamasyonda makrofaj-lenfosit etkileşiminde aktive T lenfositler (Th1) IFN-γ salgılayarak makrofajları aktive eder; aktive makrofajlar ise IL-1, TNF ve kemokinler salgılayarak lenfositleri ve inflamasyonu uyarır. E şıkkında bu sitokinlerin salgılandığı hücreler ters verilmiştir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 73, "id": "2021-2022_Q73"}, {"kurul": "1", "year": "2022-2023", "q_num": 63, "id": "2022-2023_Q63"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 72, "question": "Aşağıda belirtilen inflamasyon ve Inflamasyon mediyatörleri ile ilgili hangi bilgi\nyanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Granülomatöz inflamasyon; Özel bir kronik iltihap paternidir, aktive makrofajlar, granulomlar, epiteloid hücreler'den oluşur"}, {"letter": "B", "text": "Faktör Xa damar geçirgenliğini artırır, trombin, lökositin endotele adezyonunu güçlendirir, fibrinopeptidler damar geçirgenliğini artırır, lökositler için kemotaktiktir,"}, {"letter": "C", "text": "Hageman faktör; KC de sentezlenir, endotel hasarlı bölgeyle karşılaşıncaya kadar dolaşımda inaktiftir, hasarlı bölge ile karşılaşınca aktive olur."}, {"letter": "D", "text": "Konvertaz etkisiyle en son C5a; C5-9 MAC oluşumunu başlatır"}, {"letter": "E", "text": "Bradikinin; Histamine benzer etki gösterir, Vasküler permeabiliteyi artırır, Ekstravasküler düz kas kasılmasını sağlar (bronş düz kası), deriye enjekte edilirse ağrı yapar."}], "answer": "D", "note": null, "id": "2019-2020_Q72", "prof_inferred": true, "explanation": "Kompleman sisteminde C5 konvertaz etkisiyle C5 parçalanarak C5a ve C5b oluşur. Membran Atak Kompleksi (MAC: C5b-9) oluşumunu başlatan molekül C5a değil, **C5b**'dir (C5a ise anaflatoksin ve kemotaktik maddedir).", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 57, "id": "2020-2021_Q57"}, {"kurul": "1", "year": "2021-2022", "q_num": 75, "id": "2021-2022_Q75"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 73, "question": "Kaşekside ön planda rol oynayan aşağıdakilerden hangisidir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "IL -8"}, {"letter": "B", "text": "TNF a"}, {"letter": "C", "text": "IFN a"}, {"letter": "D", "text": "IL -6"}, {"letter": "E", "text": "PAF"}], "answer": "B", "note": null, "id": "2019-2020_Q73", "prof_inferred": true, "explanation": "Kanser kaşeksisi (yağ ve kas dokusu kaybı, iştahsızlık) gelişiminde başrol oynayan temel sitokin Makrofajlar ve tümör hücrelerinden salınan **TNF-α** (Kaşektin)'dir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 58, "id": "2020-2021_Q58"}, {"kurul": "1", "year": "2022-2023", "q_num": 65, "id": "2022-2023_Q65"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 74, "question": "Fiziksel, kimyasal ve radyasyon etkisi ile İlgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Faz I reaksiyonlarında yer alan hücresel enzim sistemlerinin en önemlisi, sitokrom P-450 sistemidir"}, {"letter": "B", "text": "Fiziksel ajanların meydana getirmiş olduğu hasarlar; mekanik, termal, elektriksel ve iyonize radyasyona bağlı gelişenlerdir"}, {"letter": "C", "text": "Radyasyona bağlı değişiklikler günler hatta haftalar sonra ortaya çıkabilir."}, {"letter": "D", "text": "Hücre proliferasyonu. iyonizan radyasyon DNA'yı zedelediği için, hızlı bölünen hücreler dinlenme evresindeki hücrelere göre daha duyarlıdır"}, {"letter": "E", "text": "Radyasyona bağlı vasküler hasar; orta derecede duyarlı olan endotel hücrelerinin hasarı ile kan damarlarının daralmasına veya tıkanmasına neden olabilir"}], "answer": "C", "note": null, "id": "2019-2020_Q74", "prof_inferred": true, "explanation": "Şirin Küçük hocanın fiziksel/kimyasal/radyasyon hasarı sorularında radyasyonun vasküler fibrozis ve geç etkileri aylar-yıllar sonra (veya diğer yıllarda 'akut ortaya çıkar ve akut kaybolur' şeklinde yanlış ifadeyle) C şıkkında sorgulanmıştır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 67, "id": "2020-2021_Q67"}, {"kurul": "1", "year": "2021-2022", "q_num": 78, "id": "2021-2022_Q78"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 75, "question": "Radyasyon etkisi ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "lyonize radyasyonun en önemli hücresel hedefi DNA'dır."}, {"letter": "B", "text": "lyonize radyasyon, RNA'yı zedeler. Bu nedenle germ hücreleri, kemik iliği ve gastrointestinal sistem gibi hızlı bölünen hücreler radyasyon zedelenmesine çok duyarlıdır"}, {"letter": "C", "text": "Morfolojik olarak radyasyon etkisinde, DNA ve nükleusu etkilemesine ek olarak, sitoplazmik şişme, mitokondriyal distorsiyon ve endoplazmik retikulumun dejenerasyonunu içeren çeşitli sitoplazmik değişiklikleri başlatabilir."}, {"letter": "D", "text": "Radyasyona uğrayan dokularda vasküler değişiklikler ve interstisyel fibrozis belirgindir."}, {"letter": "E", "text": "lyonize radyasyon, hücreleri doğrudan veya su ya da moleküler oksijenden serbest radikaller oluşturarak dolaylı yoldan zedeleyebilir"}], "answer": "B", "note": null, "id": "2019-2020_Q75", "prof_inferred": true, "explanation": "İyonize radyasyonun hücredeki en önemli ve kritik hedefi RNA değil, **DNA**'dır. Hızlı bölünen hücrelerin (germ hücreleri, hematopoetik kemik iliği, GİS mukozası) radyasyona çok duyarlı olmasının nedeni DNA hasarının bölünmeyi durdurması ve apoptozu tetiklemesidir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 59, "id": "2020-2021_Q59"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 76, "question": "Lenfoma / lösemilerle ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "En sık mutasyona uğrayan transkripsiyon faktörü genleri, B hücre kökenli ALL'lerde TEL1, AML1, E2A, PAX5 ve EBE'dir"}, {"letter": "B", "text": "KLL/SLL yavaş büyüyen ve yavaş ilerleyen bir tümördür ve tümör hücrelerinde, apoptozu engelleyen bir protein olan BCL2 seviyeleri çok yüksektir"}, {"letter": "C", "text": "KLL/SLL, pan-B belirteçleri olan CD19, CD20 ve CD23'ü ve yüzey immunglobülinleri mevcuttur ve tümör hücreleri ayrıca CD5 de eksprese ederler"}, {"letter": "D", "text": "Multipl Myelomda, MYC proto-onkogeni ilgilendiren translokasyonu saptanmıştır ve Tümör hücreleri sıklıkla Epstein-Barr virüsü ile latent olarak enfektedir"}, {"letter": "E", "text": "Diffüz Büyük B Hücreli Lenfoma; BCL6 geninde yeniden düzenlenmeler ya da mutasyonlar belirlenmiştir. Bu tümörlerin üçte biri folliküler lenfomadan kaynaklanır ve BCL2 ile ilişkili (14:18) translokasyonu mevcuttur"}], "answer": "D", "note": null, "id": "2019-2020_Q76", "prof_inferred": true, "explanation": "MYC proto-onkogenini ilgilendiren t(8;14) translokasyonu ve yüksek oranda latent EBV enfeksiyonu Multipl Myelom'un değil, **Burkitt Lenfoma**'nın karakteristik özelliğidir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 64, "id": "2020-2021_Q64"}, {"kurul": "1", "year": "2021-2022", "q_num": 81, "id": "2021-2022_Q81"}, {"kurul": "1", "year": "2022-2023", "q_num": 69, "id": "2022-2023_Q69"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 77, "question": "Hodgkin ve Non Hodgkin lenfomalarla ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Hodgkin lenfomanın olmazsa olmaz özelliği Reed Sternberg hücresidir."}, {"letter": "B", "text": "Noduler skleroz Hodgkin lenfoma en sık görülen formdur. Özel bir RS hücre varyantı olan laküner hücre sık görülür."}, {"letter": "C", "text": "Non-Hodgkin Lenfomada; Tek bir aksiyal nod grubunda lokalize olma daha sıktır, komşuluk yoluyla düzenli yayılım, mezenterik nodlar ve Waldeyer halkası tutulumu seyrektir,"}, {"letter": "D", "text": "Mikst sellüler Hodgkin lenfomada, morfolojik olarak küçük lenfositler, eozinofiller, plazma hücreleri ve makrolajlardan oluşan heterojen bir inflamatuar infiltrasyon içinde çok sayıda RS hücresi bulunur"}, {"letter": "E", "text": "Lenfositten baskın Hodgkin lenfomada. Patlamış mısıra benzeyen multilobe ve şişkin nükleusa sahip lenfohistiyositik (L&H) varyant RS hücrelerinin varlığı ile karakterizedir."}], "answer": "C", "note": null, "id": "2019-2020_Q77", "prof_inferred": true, "explanation": "Tek bir aksiyal lenf nodu grubunda lokalize olma, komşuluk yoluyla düzenli yayılım, mezenterik nodların ve Waldeyer halkasının nadir tutulması Non-Hodgkin Lenfomanın değil, **Hodgkin Lenfoma**'nın klinik özellikleridir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 65, "id": "2020-2021_Q65"}, {"kurul": "1", "year": "2022-2023", "q_num": 70, "id": "2022-2023_Q70"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 78, "question": "Lenfoma ve Iösemilerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenfoblastik Lösemi; Lenfoblastik lösemi, ince, saç benzeri sitoplazmik çıkıntılar içeren lösemik hücrelerin varlığı ile karakterize, az görülen, yavaş seyirli bir B hücrell lenfomadır."}, {"letter": "B", "text": "Foiliküler Lenfomada; çoğu olguda, BCL2 over ekspresyonuna yol açan (14:18) translokasyonu vardır"}, {"letter": "C", "text": "Mantle Hücreli Lenfoma; Hücre siklusunun ilerlemesinde düzenleyici rol oynayan siklin D1' in overekspresyonu ile sonuçlanan (11 ;14) translokasyonu ile ilişkilidir."}, {"letter": "D", "text": "Burkitt lenfoma, kromozom 8 'de localize MYC genini ilgilendiren tranlokasyonlar içerir."}, {"letter": "E", "text": "Mikozis Fungoides ve Sezary Sendromu; Neoplastik CD4+ T hücrelerinin tümörleri olan bu tümörler deride yuvalanırlar."}], "answer": "A", "note": null, "id": "2019-2020_Q78", "prof_inferred": true, "explanation": "İnce, saç benzeri sitoplazmik çıkıntılar içeren, yavaş seyirli B hücreli neoplazi Lenfoblastik Lösemi değil, **Tüylü Hücreli Lösemi (Hairy Cell Leukemia)**'dir. Lenfoblastik lösemi (ALL) immatür lenfoblastların hızlı ve agresif seyirli tümörüdür.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 66, "id": "2020-2021_Q66"}, {"kurul": "1", "year": "2021-2022", "q_num": 74, "id": "2021-2022_Q74"}, {"kurul": "1", "year": "2022-2023", "q_num": 71, "id": "2022-2023_Q71"}]}, {"year": "2019-2020", "subject": "Patoloji", "q_num": 79, "question": "Tromboemboli ve amiloidoz ile ilgili aşağıdaki belirtilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Trombüs oluşumuna yol açan nedenler: (Virchow triad) ; Endotel hasarı, Staz veya türbülan kan akımı, kanın hiperkoagulabilitesidir."}, {"letter": "B", "text": "Arteryel trombüsler, en sık olarak sırasıyla koronerler, serebral arterler ve femoral arterlerde gelişir"}, {"letter": "C", "text": "Venöz tromboz /flebotromboz sıklıkla kalbe doğru bir miktar büyür ve emboliye eğilimli damar lümeninde uzun bir kitle oluşturur, en sık alt ekstremitelerin venleri etkilenir"}, {"letter": "D", "text": "AL amiloidi; B hücre diskrazisi ile birlikte bulunur, Aß Amiloid; Alzheimer hastalarında serebral plak ve kan damarlarında depolanır"}, {"letter": "E", "text": "Immunosit diskrazileri ile birlikte olan amiloidozlar; Multipl miyeloma, Monoklonal gammopati, Diger B hücre neoplazmları ile beraberdir ve Aß Amiloid depolanması vardır."}], "answer": "E", "note": null, "id": "2019-2020_Q79", "prof_inferred": true, "explanation": "Multipl miyelom ve monoklonal gammopati gibi immünosit (plazma hücresi) diskrazilerinde biriken amiloid tipi Aβ (Alzheimer'da biriken amiloid beta) değil, immünglobülin hafif zincirlerinden oluşan **AL (Amyloid Light chain)** amiloididir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 56, "id": "2020-2021_Q56"}, {"kurul": "1", "year": "2021-2022", "q_num": 72, "id": "2021-2022_Q72"}, {"kurul": "1", "year": "2022-2023", "q_num": 62, "id": "2022-2023_Q62"}]}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 80, "question": "Aşağıdaki tam kan parametrelerinden hangisi demir eksikliği anemisini beta\ntalasemi taşıyıcılığından ayırmada yol göstericidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hematokrit azalması"}, {"letter": "B", "text": "RDW artışı"}, {"letter": "C", "text": "MCV azalması"}, {"letter": "D", "text": "Hemoglobin konsantrasyon düşüklüğü"}, {"letter": "E", "text": "Ortalama eritrosit hemoglobin konsantrasyonu azalması"}], "answer": "B", "note": null, "id": "2019-2020_Q80", "explanation": "Demir eksikliği anemisi ile beta talasemi taşıyıcılığının her ikisinde de MCV, MCH ve Hb düşüktür; ancak demir eksikliği anemisinde anizositoza bağlı olarak **RDW (eritrosit dağılım genişliği) belirgin artmışken**, talasemi taşıyıcılığında RDW normaldir."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 81, "question": "Eritrosit indekslerinden MCV'si 60 fL, eritrosit sayısı 5 milyon olan bir kişinin\nhematokriti yaklaşık % kaçtır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "50"}, {"letter": "B", "text": "45"}, {"letter": "C", "text": "40"}, {"letter": "D", "text": "35"}, {"letter": "E", "text": "30"}], "answer": "E", "note": null, "id": "2019-2020_Q81", "explanation": "MCV = (Hematokrit [%] × 10) / Eritrosit sayısı [milyon/mm³] formülünden: 60 = (Hct × 10) / 5 → Hct × 10 = 300 → Hematokrit = %30 bulunur."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 82, "question": "B hücreli lenfomada artan antiapoptozis protein onkogen aşağıdakilerden\nhangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ras geni"}, {"letter": "B", "text": "c-myc"}, {"letter": "C", "text": "brca-1"}, {"letter": "D", "text": "bcl-2"}, {"letter": "E", "text": "c-erbB2"}], "answer": "D", "note": null, "id": "2019-2020_Q82", "explanation": "Folliküler lenfoma başta olmak üzere B hücreli lenfomalarda t(14;18) translokasyonu sonucu aşırı eksprese edilen ve mitokondriyal dış membran geçirgenliğini azaltarak apoptozu inhibe eden anti-apoptotik onkogen **BCL-2**'dir."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 83, "question": "Kanser hastalarının iskelet kasında proteolizin aktif olmasına rağmen bazı\naminoasitlerde rölatif eksiklik görülmesinin sebebi nedir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Deaminasyona uğraması"}, {"letter": "B", "text": "Glukoneogenezde kullanılması"}, {"letter": "C", "text": "Akut faz protein sentezinde kullanılması"}, {"letter": "D", "text": "Lipogenezde kullantıması"}, {"letter": "E", "text": "Poliaminlerin sentezinde kullanılması"}], "answer": "C", "note": null, "id": "2019-2020_Q83", "explanation": "Kanser hastalarında iskelet kasında proteoliz artmasına rağmen serbestleşen aminoasitlerin önemli bir kısmı karaciğerde **akut faz proteinlerinin sentezinde** kullanıldığı için bazı aminoasitlerde rölatif eksiklik gelişir."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 84, "question": "(+) Lewis kan grubu antijenlerinin siyalik asit eklenmiş sekli olup kolorektal\nkanserlerde miktar artan belirteç aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "CA 15.3"}, {"letter": "B", "text": "CA 19.9"}, {"letter": "C", "text": "CEA"}, {"letter": "D", "text": "Tiroglobulin"}, {"letter": "E", "text": "CA 72.4"}], "answer": "B", "note": null, "id": "2019-2020_Q84", "explanation": "Lewis kan grubu antijeninin siyalillenmiş türevi olan ve pankreas ile kolorektal kanserlerde düzeyi yükselen karbonhidrat yapılı tümör belirteci **CA 19-9**'dur."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 85, "question": "Aşağıdaki tümör markerlardan hangisi karbonhidrat yapılı değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "CEA"}, {"letter": "B", "text": "CA 72.4"}, {"letter": "C", "text": "CA 19.9"}, {"letter": "D", "text": "CA 125"}, {"letter": "E", "text": "CA 15.3"}], "answer": "A", "note": null, "id": "2019-2020_Q85", "explanation": "CA 19-9, CA 125, CA 15-3 ve CA 72-4 müsin/karbonhidrat antijeni (Cancer Antigen) grubu belirteçlerdir; **CEA (Karsinoembriyonik Antijen)** ise onkofetal antijen/glikoprotein grubunda sınıflandırılır."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 86, "question": "Hem trombin oluşumunu hem de plazmin oluşumunu teyit etmesi açısından\naşağıdaki koagulasyon testlerinden hangisi biyokimyasal olarak değerlendirilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aktive Parsiyel Tromboplastin Zamanı"}, {"letter": "B", "text": "Fibrinojen"}, {"letter": "C", "text": "D-dimer"}, {"letter": "D", "text": "Protrombin Zamanı"}, {"letter": "E", "text": "Von Willebrand Faktör"}], "answer": "C", "note": null, "id": "2019-2020_Q86", "explanation": "Çapraz bağlı fibrin pıhtısının oluşması için önce trombinin fibrinojeni fibrine çevirmesi ve Faktör XIIIa'nın çapraz bağlaması, ardından plazminin bu çapraz bağlı fibrini yıkması gerekir. Dolayısıyla **D-dimer** varlığı hem trombin hem de plazmin oluşumunu biyokimyasal olarak kanıtlar."}, {"year": "2019-2020", "subject": "Biyokimya", "q_num": 87, "question": "Kanın pıhtılaşma zamanında uzama ile birlikte kanamaya eğilim gösteren,\nerkeklerde görülen, kadınlar tarafından taşınan herediter karakterli, ömür boyu devam eden\nhastalıktır. Aşağıdakilerden hangi şıkta bu hastalık ve eksik olan faktör doğru olarak\nverilmiştir?", "professor": "Ayşe Özdemir", "options": [{"letter": "A", "text": "Von-Willebrand→Fak VIII eksikliği"}, {"letter": "B", "text": "K Vitamini eksikliği→Faktör-II,VII, IX, X eksikliği"}, {"letter": "C", "text": "Non trombositopenik purpuralar→lökosit eksikliği"}, {"letter": "D", "text": "Tromboasteni→ Trombosit eksikliği"}, {"letter": "E", "text": "Hemofili A→ Faktör- VIII eksikliği"}], "answer": "E", "note": null, "id": "2019-2020_Q87", "prof_inferred": true, "explanation": "X'e bağlı resesif kalıtılan (kadınların taşıyıcı olup erkeklerde hastalık görülen), aPTT ve pıhtılaşma zamanında uzama ile seyreden konjenital kanama bozukluğu **Hemofili A** olup **Faktör VIII eksikliği** sonucu gelişir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 85, "id": "2022-2023_Q85"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 88, "question": "Papillomaviruslerde DNA homolojisi ile 100'ün üzerinde tip tanımlanmıştır. Bu\ntiplerden en kanserojen olan tip grubu hangisidir?", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "16-18"}, {"letter": "B", "text": "20-22"}, {"letter": "C", "text": "22-24"}, {"letter": "D", "text": "26-28"}, {"letter": "E", "text": "12-14"}], "answer": "A", "note": null, "id": "2019-2020_Q88", "prof_inferred": true, "explanation": "Human Papillomavirus (HPV) tipleri arasında serviks kanseri ve anogenital kanserlerle en güçlü ilişkili yüksek riskli (onkojenik) tipler **HPV Tip 16 ve Tip 18**'dir (E6 proteini p53'ü, E7 proteini Rb'yi yıkar).", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 90, "id": "2021-2022_Q90"}, {"kurul": "1", "year": "2023-2024", "q_num": 93, "id": "2023-2024_Q93"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 89, "question": "Retroviruslarda virüse özgün pol geni ile kodlanan hangi enzim hastalık\netyolojisinde en önemlidir?", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Revers (ters) transkriptaz"}, {"letter": "B", "text": "RNA polimeraz"}, {"letter": "C", "text": "DNA polimeraz"}, {"letter": "D", "text": "Tag polimeraz"}, {"letter": "E", "text": "Integraz"}], "answer": "A", "note": null, "id": "2019-2020_Q89", "prof_inferred": true, "explanation": "Retrovirüslerde (HIV, HTLV) viral pol geni tarafından kodlanan **Revers transkriptaz (ters transkriptaz)** enzimi, tek iplikli viral RNA'dan çift iplikli proviral DNA sentezleyerek konak genomuna entegrasyonu ve patogenezi mümkün kılar.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 91, "id": "2021-2022_Q91"}, {"kurul": "1", "year": "2023-2024", "q_num": 92, "id": "2023-2024_Q92"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Nükleik asit replikasyonuna katılan ve antiviral ilaçlar için iyi bir hedef olan Herpes\nVirüs enzimi hangisidir?", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "DNA polimeraz"}, {"letter": "B", "text": "RNA polimeraz"}, {"letter": "C", "text": "Lipaz"}, {"letter": "D", "text": "Ligaz"}, {"letter": "E", "text": "Esteraz"}], "answer": "A", "note": null, "id": "2019-2020_Q90", "prof_inferred": true, "explanation": "Herpesvirüslerde viral nükleik asit replikasyonunu gerçekleştiren ve asiklovir, gansiklovir, foskarnet gibi antiviral ilaçların temel hedefi olan enzim viral **DNA polimeraz**'dır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 92, "id": "2021-2022_Q92"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 91, "question": "Intrauterin hayatta ve yeni doğanda konjenital ve perinatal infeksiyonlar; sağlıklı\nerişkinlerde mononükleoz yapan DNA virüsü hangisidir?", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Sitomegalovirus (CMV)"}, {"letter": "B", "text": "Herpesvirüs"}, {"letter": "C", "text": "Parvovirus"}, {"letter": "D", "text": "Papilloma virüs"}, {"letter": "E", "text": "Ebstein Barr virus"}], "answer": "A", "note": null, "id": "2019-2020_Q91", "prof_inferred": true, "explanation": "İntrauterin dönemde en sık konjenital enfeksiyon (TORCH) etkeni olan, yenidoğanda perinatal enfeksiyon ve sağlıklı erişkinlerde heterofil antikor negatif enfeksiyöz mononükleoz tablosu yapan DNA virüsü **Sitomegalovirüs (CMV)**'tür.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 93, "id": "2021-2022_Q93"}, {"kurul": "1", "year": "2023-2024", "q_num": 91, "id": "2023-2024_Q91"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 92, "question": "35 yaşında kadın hasta, tekrarlayan kandidüri sikayetiyle başvuruyor. Hastanın\ndaha önceki başvurularında flukonazol tedavisi sonrası şikayetlerinin azaldığı fakat kısa süre\nsonra idrar yolu şikâyetlerinin tekrarladığı öğreniliyor. Bu hastada enfeksiyon etkeni olarak\naşağıdaki mantarlardan hangisini öncelikli düşünürsünüz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Candida glabrata"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Candida parapsilosis"}, {"letter": "D", "text": "Candida tropicalis"}, {"letter": "E", "text": "Candida guilliermondii"}], "answer": "A", "note": null, "id": "2019-2020_Q92", "explanation": "Flukonazol tedavisine yanıt vermeyen veya flukonazol sonrası hızla nükseden tekrarlayan kandidüri/kandidiyazis olgularında flukonazole intrinsik veya kazanılmış direnci yüksek olan **Candida glabrata** (veya C. krusei) öncelikle düşünülmelidir."}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 93, "question": "18 yaşında kadın hastanın, kulak ağrısı şikâyetiyle başvurduğu klinikte verilen\namoksisilin-klavulonat etken maddeli antibiyotiğe rağmen şikâyetleri düzelmemiştir. Kulak\nağrısı daha da şiddetlenerek yeniden başvurduğunda dış kulak yolunda siyah renkli, pamuksu\nyapılar gözlenmiştir. Aşağıdaki etkenlerden hangisini öncelikle düşünürsünüz?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aspergillus niger"}, {"letter": "B", "text": "Aspergillus flavus"}, {"letter": "C", "text": "Candida albicans"}, {"letter": "D", "text": "Cryptococcus neoformans"}, {"letter": "E", "text": "Histoplasma capsulatum"}], "answer": "A", "note": null, "id": "2019-2020_Q93", "prof_inferred": true, "explanation": "Antibiyotik tedavisine yanıt vermeyen dış kulak yolu enfeksiyonunda (otomikoz) siyah renkli, pamuksu/küf benzeri yapıların görülmesi karakteristik olarak **Aspergillus niger** enfeksiyonunu gösterir.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 96, "id": "2024-2025_Q96"}]}, {"year": "2019-2020", "subject": "Mikrobiyoloji", "q_num": 94, "question": "Aşağıdaki mantarlardan hangisi fenol oksidaz aracılığıyla melanin üretimi ile diğer\ntürlerden ayrt edilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Cryptococcus neoformans"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Candida glabrata"}, {"letter": "D", "text": "Aspergillus fumigatus"}, {"letter": "E", "text": "Penicillium marneffei"}], "answer": "A", "note": null, "id": "2019-2020_Q94", "explanation": "Kapsüllü maya mantarı olan **Cryptococcus neoformans**, sahip olduğu fenol oksidaz (lakkaz) enzimi aracılığıyla katekolaminlerden melanin pigmenti üretir (Kafeik asit / Nijer tohumu agarında kahverengi-siyah koloni oluşturarak diğer mayalardan ayırt edilir)."}, {"year": "2019-2020", "subject": "Radyoloji", "q_num": 95, "question": "Aşağıdakilerden hangisi manyetik rezonans görüntülemenin klinik avantajlar\narasında yer almaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Yumuşak doku ayırt edebilme gücünün yüksek olması"}, {"letter": "B", "text": "lyonizan ışın kullanılmaması"}, {"letter": "C", "text": "Görüntüleme zamanının kısa olması"}, {"letter": "D", "text": "Kan akiminin kontrastsız görüntülenebilmesi"}, {"letter": "E", "text": "Kemiğe komşu yapıların çok iyi incelenmesi (kafa taban, beyin sapı, spinal kord, eklemler)"}], "answer": "C", "note": null, "id": "2019-2020_Q95", "explanation": "Manyetik Rezonans Görüntüleme (MRG) yüksek yumuşak doku kontrastı sağlar ve iyonizan radyasyon içermez; ancak BT ve röntgene kıyasla **görüntüleme (çekim) süresinin uzun olması** bir avantaj değil, dezavantajdır."}, {"year": "2019-2020", "subject": "Radyoloji", "q_num": 96, "question": "Aşağıdaki organlardan hangisine ait neoplazilerin görüntülenmesinde radyolojik\nyöntem olarak ultrasonografi tercih edilmez?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Meme"}, {"letter": "B", "text": "Tiroid"}, {"letter": "C", "text": "Testis"}, {"letter": "D", "text": "Karaciğer"}, {"letter": "E", "text": "Akciğer"}], "answer": "E", "note": null, "id": "2019-2020_Q96", "explanation": "Akciğer parankimi hava ile dolu olduğu ve ses dalgaları havada iletilemeyip tam yansıma yaptığı için **akciğer** neoplazilerinin görüntülenmesinde ultrasonografi (USG) tercih edilmez. Meme, tiroid, testis ve karaciğerde ise USG yaygın kullanılır."}, {"year": "2019-2020", "subject": "İmmünoloji", "q_num": 97, "question": "Aşağıdakilerden hangisi tümöre karşı edinsel immün cevapta en etkili hücredir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Antikorlar"}, {"letter": "B", "text": "Sitotoksik T hücreleri"}, {"letter": "C", "text": "Makrofajlar"}, {"letter": "D", "text": "NK Hücreleri"}, {"letter": "E", "text": "Monositler"}], "answer": "B", "note": null, "id": "2019-2020_Q97", "explanation": "Tümör hücrelerine karşı edinsel (adaptif) immün yanıtta MHC Sınıf I üzerindeki tümör antijenlerini tanıyarak tümör hücresini doğrudan lizise uğratan en etkili hücre **CD8+ Sitotoksik T Lenfositleri (CTL)**'dir."}, {"year": "2019-2020", "subject": "İmmünoloji", "q_num": 98, "question": "Aşağıdaki sitokin şiftlerinden hangisi Treg’lerin (Regülatör T hücreleri) tümör\nmikroçevresinde toplanmasında rol oynar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "IL-10 /TGF beta"}, {"letter": "B", "text": "IL-2 / IL-12"}, {"letter": "C", "text": "IL-1beta / TNF-alla"}, {"letter": "D", "text": "IL-2 / IFNgamma"}, {"letter": "E", "text": "IL-1beta / lL-6"}], "answer": "A", "note": null, "id": "2019-2020_Q98", "explanation": "Tümör mikroçevresinde immünsüpresif karakterdeki Regülatör T hücrelerinin (Treg) toplanmasında ve anti-tümör bağışıklığın baskılanmasında rol oynayan başlıca sitokin çifti **IL-10 ve TGF-β**'dır."}, {"year": "2019-2020", "subject": "İmmünoloji", "q_num": 99, "question": "Öz-antijenlere karşı olan immün cevap aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Glomerulonefrit"}, {"letter": "B", "text": "Antikor"}, {"letter": "C", "text": "T hücresi"}, {"letter": "D", "text": "Otoimmun Hastalık"}, {"letter": "E", "text": "Allerjik Hastalık"}], "answer": "D", "note": null, "id": "2019-2020_Q99", "explanation": "İmmün sistemin self-toleransı (öz-toleransı) kaybederek konağın kendi öz-antijenlerine karşı patolojik immün yanıt geliştirmesi sonucu ortaya çıkan tablo **Otoimmün Hastalık** olarak tanımlanır."}, {"year": "2019-2020", "subject": "İmmünoloji", "q_num": 100, "question": "Aşağıdakilerden hangisi Tip IIl Hipersensitivite reaksiyonlarına örnek olarak\nverilebilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Allerjik rinit"}, {"letter": "B", "text": "Grave's hastalığı"}, {"letter": "C", "text": "Myastenia gravis"}, {"letter": "D", "text": "Multiple Sklerozis"}, {"letter": "E", "text": "Sistemik lupus eritematozis"}], "answer": "E", "note": null, "id": "2019-2020_Q100", "explanation": "Tip III aşırı duyarlılık reaksiyonu dolaşan antijen-antikor (immün kompleks) birikimiyle oluşur ve en klasik sistemik örneği **Sistemik Lupus Eritematozus (SLE)**'dur. Alerjik rinit Tip I, Graves ve Myastenia Gravis Tip II, Multipl Skleroz Tip IV reaksiyon örneğidir."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 2, "question": "Anemi nedenlerinden eritrosit hücre seviyesinde olmayan sebep hangisidir?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Pirüvat Kinaz eksikliği"}, {"letter": "B", "text": "Retikülosit artışı"}, {"letter": "C", "text": "Orak şeklinde eritrosit"}, {"letter": "D", "text": "Glukoz 6-Fosfat Dehidrogenaz eksikliği"}, {"letter": "E", "text": "Globin sentezinde bozukluk"}], "answer": "B", "note": null, "id": "2020-2021_Q2", "explanation": "Pirüvat kinaz eksikliği, G6PD eksikliği, orak hücreli anemi ve talasemiler (globin sentez bozukluğu) doğrudan eritrosit içi (intrakorpüsküler) anemi nedenleridir. **Retikülosit artışı (retikülositoz)** ise bir anemi nedeni değil, kemik iliğinin anemiye/hemolize verdiği rejeneratif yanıttır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 2, "id": "2021-2022_Q2"}]}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 3, "question": "Çocukluk çağı kanserlerinden en sık görülen hangisidir?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Kronik lösemiler"}, {"letter": "B", "text": "Wilms tümörü"}, {"letter": "C", "text": "Akut lösemiler"}, {"letter": "D", "text": "Nöroblastom"}, {"letter": "E", "text": "Lenfomalar"}], "answer": "C", "note": null, "id": "2020-2021_Q3", "explanation": "Çocukluk çağında (0-15 yaş) en sık görülen malignite **Akut lösemilerdir** (tüm çocukluk kanserlerinin yaklaşık %30'u; bunun da %80'ini ALL oluşturur).", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 3, "id": "2021-2022_Q3"}]}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 4, "question": "Çocuklarda kanser tanısında uygulananlardan hangisi/leri doğrudur?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Periferik yayma/kemik iliği incelenmesi"}, {"letter": "B", "text": "Karaciğer/böbrek fonksiyon testleri"}, {"letter": "C", "text": "PA Akciğer grafisi/bilgisayarlı tomografi"}, {"letter": "D", "text": "Biyopsi yapılması"}, {"letter": "E", "text": "Hepsi"}], "answer": "E", "note": null, "id": "2020-2021_Q4", "explanation": "Çocukluk çağı kanserlerinin tanı, evreleme ve organ fonksiyon değerlendirmesinde periferik yayma/kemik iliği incelemesi, biyokimyasal testler, radyolojik görüntülemeler ve kesin tanı için doku biyopsisi birlikte kullanılır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 4, "id": "2021-2022_Q4"}]}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 5, "question": "Aşağıdaki durumların hangisinde primer immun yetmezlik düşünülmez?", "professor": "Bora Baysal", "options": [{"letter": "A", "text": "Anormal saç, parsiyel albinizm"}, {"letter": "B", "text": "Büyüme gelişme geriliği"}, {"letter": "C", "text": "Açıklanamayan çocuk ölümü öyküsü"}, {"letter": "D", "text": "Yılda 2 kez otitis media öyküsü"}, {"letter": "E", "text": "Yılda 2 kez ciddi sinüs enfeksiyonu"}], "answer": "D", "note": null, "id": "2020-2021_Q5", "explanation": "Çocuklarda primer immün yetmezlik uyarıcı bulguları (Jeffrey Modell kriterleri) arasında yılda ≥4 yeni otitis media, ≥2 ciddi sinüzit ve ≥2 pnömoni yer alır. **Yılda 2 kez otitis media** normal sağlıklı çocuklarda da sık görülebilen bir durumdur ve immün yetmezlik düşündürmez."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 6, "question": "11 aylıktan itibaren her ay solunum yolu enfeksiyonu geçiren 3 yaşında bir çocukta Ig\nG, Ig M ve Ig A düzeyleri düşük, Anti HBs ve Anti tetanus negatif, İzohemaglutinin düzeyi\ndüşük olarak saptanmıştır. Bu hastada en olası tanınız nedir?", "professor": "Bora Baysal", "options": [{"letter": "A", "text": "Süt çocuğunun geçici hipogamaglobunimesi"}, {"letter": "B", "text": "Yaygın değişken immun yetmezlik"}, {"letter": "C", "text": "Kronik granulomatöz hastalık"}, {"letter": "D", "text": "Otoimmun lenfoproliferatif hastalık"}, {"letter": "E", "text": "Hiperimmunglobulin E sendromu"}], "answer": "B", "note": null, "id": "2020-2021_Q6", "explanation": "IgG, IgA ve IgM düzeylerinin birlikte düşük olması, aşılara (anti-HBs, anti-tetanoz) antikor yanıtının olmaması ve izohemaglütinin düşüklüğü **Yaygın Değişken İmmün Yetmezlik (CVID)** ile uyumludur (Geçici hipogammaglobulinemide aşı yanıtları ve izohemaglütininler korunmuştur)."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 7, "question": "Oral olarak kullanılan demir preparatları için verilen bilgilerden hangisi yanlıştır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Oral kullanılırlar"}, {"letter": "B", "text": "Bu bileşiklerde demir ferrodemir halindedir"}, {"letter": "C", "text": "Mide barsak üzerine tahriş edici etkisi var"}, {"letter": "D", "text": "Aç karna verilmesi biyoyararlanımı azaltır"}, {"letter": "E", "text": "Demir tuzları günde bir kez tercihen yemek sonrası verilir"}], "answer": "D", "note": null, "id": "2020-2021_Q7", "explanation": "Oral demir preparatlarının (ferröz tuzlar) aç karnına alınması biyoyararlanımı azaltmaz, aksine **artırır** (gıdalar, fitatlar ve süt ürünleri emilimi azaltır; ancak GİS tahrişi/bulantı olursa tok karnına verilebilir)."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 8, "question": "Tümör hücrelerinde, tübülin sentezini arttırarak tübülin-mikrotübül dengesini bozan\nve sitotoksik etki ortaya çıkaran antineoplastik ilaç grubu aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Taksanlar"}, {"letter": "B", "text": "Antrasiklinler"}, {"letter": "C", "text": "Antitümör antibiyotikler"}, {"letter": "D", "text": "Monoklonal Antikorlar"}, {"letter": "E", "text": "Topoizomeraz I enzim inhibitörleri"}], "answer": "A", "note": null, "id": "2020-2021_Q8", "explanation": "**Taksanlar** (paklitaksel, dosetaksel) mikrotübüllerin polimerizasyonunu artırıp depolimerizasyonunu (yıkımını) engelleyerek mikrotübülleri aşırı stabilize eder ve mitozu metafaz-anafaz geçişinde durdurur."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 9, "question": "Aşağıdakilerden hangisi histamin H2 reseptör antagonisti bir ilaçdır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Betahistin"}, {"letter": "B", "text": "İmpromidin"}, {"letter": "C", "text": "Ranitidin"}, {"letter": "D", "text": "Fenilhistamin"}, {"letter": "E", "text": "Betazol"}], "answer": "C", "note": null, "id": "2020-2021_Q9", "explanation": "**Ranitidin** (famotidin, simetidin, nizatidin ile birlikte) mide pariyetal hücrelerindeki histamin H2 reseptörlerini selektif olarak bloke ederek mide asit salgısını azaltan bir H2 reseptör antagonistidir."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 11, "question": "Aşağıda verilen antineoplastik ilaçlardan hangisi folat antimetabolitidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Metotraksat"}, {"letter": "B", "text": "Sisplatin"}, {"letter": "C", "text": "Toporekan"}, {"letter": "D", "text": "Paklitaksel"}, {"letter": "E", "text": "Setiksimab"}], "answer": "A", "note": null, "id": "2020-2021_Q11", "explanation": "**Metotreksat**, dihidrofolat redüktaz (DHFR) enzimini kompetitif olarak inhibe ederek tetrahidrofolat ve pürin/timidilat sentezini bozan bir **folat antimetaboliti** antineoplastik ilaçtır."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 12, "question": "Ductus arteriozusun açık tutulması için kullanılan prostaglandin analoğu ilaç\nhangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Doksaprost"}, {"letter": "B", "text": "Alprostadil"}, {"letter": "C", "text": "Mizoprostol"}, {"letter": "D", "text": "Epoprostenol"}, {"letter": "E", "text": "İlioprost"}], "answer": "B", "note": null, "id": "2020-2021_Q12", "explanation": "Duktus arteriozusa bağımlı konjenital kalp hastalıklarında duktusun açık kalmasını sağlamak için kullanılan PGE1 analoğu ilaç **Alprostadil**'dir (kapatmak için ise indometazin/ibuprofen kullanılır).", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 15, "id": "2021-2022_Q15"}]}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 13, "question": "Seratonin agonist ve antagonistleriyle ilgili olarak aşağıdakilerden hangisi\ndoğrudur?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Koroner arterler hastalarında kontraendike olan migren ilacı Ondansetrondur."}, {"letter": "B", "text": "Antiserotonin ilaçlardan antiemetik etkili olan Metoklopramid, 5HT3 agonisti ve 5HT4 antagonistidir."}, {"letter": "C", "text": "Buspiron, 5HT1A reseptörlerini aktive ederek anksiyolitik etki gösterir."}, {"letter": "D", "text": "Kemoterapi esnasında ortaya çıkan şiddetli bulantı kusmaları önlemede siproheptadin kullanılır."}, {"letter": "E", "text": "5HT1D reseptör antagonisti Sumatriptan, akut migren tedavisinde kullanılır."}], "answer": "C", "note": null, "id": "2020-2021_Q13", "explanation": "**Buspiron**, 5-HT1A reseptörleri üzerinde parsiyel agonist etki göstererek sedasyon veya bağımlılık yapmadan anksiyolitik etki oluşturan ilaçtır. (Sumatriptan 5-HT1B/1D agonistidir ve koroner hastalıkta kontrendikedir; ondansetron 5-HT3 antagonistidir; metoklopramid 5-HT4 agonisti/D2 antagonistidir)."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 14, "question": "NSAİİ (nonstreoid antiinflamatuar ilaçlar) ile ilgili hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Yarılanma ömrü uzun olması sayesinde günde tek doz kullanılabilen ilaç Piroksikam'dır."}, {"letter": "B", "text": "İndometazin'in en sık görülen yan etkisi frontal başağrısıdır."}, {"letter": "C", "text": "Diklofenak karaciğer transaminaz yükseltebilir bu nedenle ilk 8 hafta takip edilmelidir."}, {"letter": "D", "text": "En güçlü antiinflamatur etkiye sahip olan analjezik ve antipiretik olarak da kullanılabilen ilaç Dipirondur"}, {"letter": "E", "text": "Hem COX inhibisyonu hem de fosfolipaz A inhibe eden ilaç Mefenamik asittir."}], "answer": "D", "note": null, "id": "2020-2021_Q14", "explanation": "**Dipiron (Metamizol)** güçlü analjezik, antipiretik ve spazmolitik etkiye sahiptir ancak **antiinflamatuar etkisi çok zayıftır** (en güçlü antiinflamatuar değildir). Agronülositoz yan etkisi nedeniyle kullanımı kısıtlanmıştır."}, {"year": "2020-2021", "subject": "Pediatri", "q_num": 15, "question": "Aşağıdakilerden hangisi NSAİ ilaçlar için doğrudur?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Analjezik etkisi esasen santral sinir sisteminde PGE2 sentezini baskılamalarına bağlıdır."}, {"letter": "B", "text": "NSAİİ, akut ağrıda etkili olduğu kadar kronik ağrılarda oldukça etkii ilaçlardır."}, {"letter": "C", "text": "Bu ilaçlara bağlı gelişen Gİ mukoza lezyonlarına analjezik veya NSAİİ gastropatisi adı verilir ve COX-2 selektif inhibtör ilaçlar daha fazla neden olur"}, {"letter": "D", "text": "Renal kan akımında ve glomerüler filtrasyon hızında (GFR) azalmaya neden olurlar"}, {"letter": "E", "text": "Selektif COX-2 inhibitörleri tromboksan inhibe ederken PGI2 inhibisyonu yapmazlar. Bu durum tromboza eğilimi artırır."}], "answer": "D", "note": null, "id": "2020-2021_Q15", "explanation": "NSAİ ilaçlar böbrekte vazodilatatör prostaglandinlerin (PGE2 ve PGI2) sentezini baskıladıkları için afferent arteriyolde vazokonstrüksiyona, **renal kan akımında ve GFR'de azalmaya** neden olurlar."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 16, "question": "En sık görülen Hodgkin dışı lenfoma tipi hangisidir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Matür T hücreli lenfoma"}, {"letter": "B", "text": "Diffüz büyük b hücreli lenfoma"}, {"letter": "C", "text": "MALT lenfoma"}, {"letter": "D", "text": "Küçük lenfoblastik lenfoma"}, {"letter": "E", "text": "Mantle hücreli lenfoma"}], "answer": "B", "note": null, "id": "2020-2021_Q16", "explanation": "Erişkinlerde en sık görülen Non-Hodgkin (Hodgkin dışı) lenfoma alt tipi **Diffüz Büyük B Hücreli Lenfoma (DBBHL)**'dır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 17, "question": "Aşağıdakilerden hangisi en sık lösemik dönüşüm gösteren myelodisplastik sendrom\ntipidir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "refrakter anemi"}, {"letter": "B", "text": "ring sideroblastlı refrakter anemi"}, {"letter": "C", "text": "multilineage displazili refrakter anemi"}, {"letter": "D", "text": "İzole del (5q) ile MDS"}, {"letter": "E", "text": "artmış blastlı tip 2 refrakter anemi"}], "answer": "E", "note": null, "id": "2020-2021_Q17", "explanation": "Miyelodisplastik sendrom (MDS) alt tipleri içinde kemik iliğinde %10-19 blast bulunan **Artmış blastlı tip 2 refrakter anemi (RAEB-2 / MDS-EB2)**, Akut Miyeloid Lösemiye (AML) dönüşüm riski en yüksek olan tiptir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 18, "question": "Aşağıdakilerden hangisi hemolitik anemide görülen laboratuvar bulgularından\ndeğildir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Haptoglobulin düzeyinin azalması"}, {"letter": "B", "text": "LDH artışı"}, {"letter": "C", "text": "Retikülositoz"}, {"letter": "D", "text": "İndirekt bilirubin artışı"}, {"letter": "E", "text": "Hemopeksin düzeyinde artma"}], "answer": "E", "note": null, "id": "2020-2021_Q18", "explanation": "Hemolitik anemilerde serbest hemoglobini bağlayan **haptoglobin** ve serbest hemi bağlayan **hemopeksin** düzeyleri dolaşımdan hızla temizlendikleri için **azalır** (artmaz). LDH, indirekt bilirubin ve retikülosit ise artar."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 19, "question": "Aşağıdakilerden hangisi immun hemolitik anemi nedenlerinden değildir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Uygunsuz kan transfüzyonu"}, {"letter": "B", "text": "Soğuk aglitünin hastalığı"}, {"letter": "C", "text": "Otoimmun hemolitik anemi"}, {"letter": "D", "text": "Yenidoğanın hemolitik hastalığı"}, {"letter": "E", "text": "Paroksisimal nokturnal hemoglobinüri"}], "answer": "E", "note": null, "id": "2020-2021_Q19", "explanation": "**Paroksismal Noktürnal Hemoglobinüri (PNH)**, PIGA genindeki somatik mutasyon sonucu GPI çapa proteinlerinin (CD55 ve CD59) eksikliğine bağlı kompleman aracılı yıkımla seyreden **non-immün** (antikor aracısız) kazanılmış intravasküler hemolitik anemidir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 21, "question": "Aşağıdakilerden hangisi multiple myelomda görülmez?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Hiperkalsemi"}, {"letter": "B", "text": "Böbrek yetmezliği"}, {"letter": "C", "text": "Anemi"}, {"letter": "D", "text": "Osteosklerotik kemik lezyonu"}, {"letter": "E", "text": "Kemik iliğindeki plazma hücrelerinde ≥ % 10 artış olması"}], "answer": "D", "note": null, "id": "2020-2021_Q21", "explanation": "Multiple myelomda osteolitik kemik lezyonları görülür; **osteosklerotik kemik lezyonu** görülmez. Hiperkalsemi, böbrek yetmezliği, anemi ve kemik iliğinde ≥%10 plazma hücresi tanı kriterleridir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 27, "id": "2019-2020_Q27"}]}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 23, "question": "18 yaşında aplastik anemi tanısı alaln bir hastada en uygun tedavi seçeneği\nhangisidir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "HLA uyumlu vericisi varsa kemik ilği nakli"}, {"letter": "B", "text": "steroid tedavisi"}, {"letter": "C", "text": "Anti timosit globulin"}, {"letter": "D", "text": "siklosporin"}, {"letter": "E", "text": "eltrombopag"}], "answer": "A", "note": null, "id": "2020-2021_Q23", "explanation": "Genç (<40 yaş) ağır aplastik anemi hastalarında **HLA tam uyumlu kardeş/verici varsa ilk tercih ve küratif tedavi allojenik kemik iliği (kök hücre) naklidir**. Uygun verici yoksa ATG + Siklosporin + Eltrombopag immünsüpresif tedavisi verilir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 24, "question": "Proto-onkogen aşağıdaki yollardan hangisi ile onkogene dönüşebilir ?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Duplikasyon"}, {"letter": "B", "text": "Apoptoz"}, {"letter": "C", "text": "Dimerizasyon"}, {"letter": "D", "text": "Amplifikasyon"}, {"letter": "E", "text": "Translasyon"}], "answer": "D", "note": null, "id": "2020-2021_Q24", "explanation": "Proto-onkogenler nokta mutasyonu, kromozomal translokasyon veya **gen amplifikasyonu** (ör. HER2 veya N-MYC kopya sayısının artması) yoluyla aşırı aktifleşerek onkogene dönüşürler."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 25, "question": "Annesi 50 yaşında kolon kanseri tanısı almış sağlıklı, 31 yaşında bir kadın tarama\ntestleri hakkında bilgi almak için size başvurdu. Aşağıdaki şıklardan hangisini önerilmez?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Yılda bir dışkıda gizli kan bakılması"}, {"letter": "B", "text": "Yılda bir fekal DNA bakılması"}, {"letter": "C", "text": "10 yılda bir kolonoskopi yapılması"}, {"letter": "D", "text": "Taramanın 40 yaşında başlamasını"}, {"letter": "E", "text": "5 yılda bir sigmoidoskopi yapılması"}], "answer": "B", "note": null, "id": "2020-2021_Q25", "explanation": "Kolorektal kanser taramasında dışkıda gizli kan testi yılda bir, fekal DNA testi ise **yılda bir değil, 3 yılda bir** yapılır. Birinci derece akrabasında 50 yaşında kolon kanseri olan bireyde taramaya 40 yaşında (veya tanı yaşından 10 yıl önce) başlanır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 26, "question": "Aşağıdakilerden hangisi kaşeksi sendromunun özelliklerinden birisi değildir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Yorgunluk ve bitkinlik"}, {"letter": "B", "text": "Anoreksi"}, {"letter": "C", "text": "Yağ ve kas dokusunun Kaybı"}, {"letter": "D", "text": "Hipolipidemi"}, {"letter": "E", "text": "Anemi"}], "answer": "D", "note": null, "id": "2020-2021_Q26", "explanation": "Kanser kaşeksisi sendromunda TNF-α etkisiyle lipoprotein lipaz (LPL) enzimi inhibe edilir ve adipoz dokuda lipoliz artar; bunun sonucunda hipolipidemi değil, **hiperlipidemi (hipertrigliseridemi)** ve serbest yağ asidi artışı görülür."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 27, "question": "Fizik muayenede Traube alanı kapalı saptanan bir hastada, bu alanı kapatacak\nbaşka bir sebep yokluğunda, aşağıdaki hastalıklardan hangisinin olması olası değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Polisitemia Vera"}, {"letter": "B", "text": "Aplastik Anemi"}, {"letter": "C", "text": "Esansiyel Trombositemi"}, {"letter": "D", "text": "Kronik Miyelositer Lösemi"}, {"letter": "E", "text": "Primer Miyeloskleroz"}], "answer": "B", "note": null, "id": "2020-2021_Q27", "explanation": "Traube alanının kapalı olması splenomegaliyi gösterir. Miyeloproliferatif hastalıklarda (KML, Primer Miyelofibroz, Polisitemia Vera, Esansiyel Trombositemi) splenomegali görülürken, **Aplastik Anemide splenomegali beklenmez**."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 28, "question": "Herikisi de talasemi taşıyıcısı olan anne ve babadan doğan çocuklarla ilgili olarak\naşağıdaki ifadelerden hangisi doğrudur?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Doğacak cocuklar %75 olasıklıkla talasemi intermediate olur."}, {"letter": "B", "text": "Doğacak cocuklar %25 olasılıkla talasemi taşıyıcısı olur"}, {"letter": "C", "text": "Doğacak cocuklar %75 olasılıkla talasemi taşıyıcı olur"}, {"letter": "D", "text": "Doğacak cocuklar %50 olasıklıkla sağlam olur."}, {"letter": "E", "text": "Doğacak cocuklar %25 olasılıkla talasemi majör olur"}], "answer": "E", "note": null, "id": "2020-2021_Q28", "explanation": "Talasemi otozomal resesif kalıtılır. Her ikisi de taşıyıcı (heterozigot: Bb) olan anne ve babadan doğacak çocukların her gebelikte **%25 olasılıkla sağlam (BB), %50 olasılıkla taşıyıcı (Bb) ve %25 olasılıkla talasemi majör (bb)** olma ihtimali vardır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 29, "question": "45 yaşında, solukluk dışında fiziken normal görülen kadın hastada eritrosit sayısı 5.6\nmilyon/mm3, hemoglobin 9.9 gr/dL, hemotokrit %31.2, ortalama hücre hacmi (MCV) 58.2 fl\n(düşük), eritrosit dağılım genişiliği (RDW) %14 (normal) saptanıyor. Serum ferritin düzeyi\nnormal saptanan hastanın periferik yaymasında hipokromi, mikrositoz ve hedef hücreleri\nizleniyor. Hemoglobin elektroforezinde HbA2 %4 bulunuyor. Bu olguda tanınız nedir.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Beta talasemi major"}, {"letter": "B", "text": "Alfa talasemi"}, {"letter": "C", "text": "Demir eksikliği anemisi"}, {"letter": "D", "text": "Beta talasemi minor"}, {"letter": "E", "text": "Sideroblastik anemi"}], "answer": "D", "note": null, "id": "2020-2021_Q29", "explanation": "Hafif anemiye rağmen eritrosit sayısının (RBC: 5.6 milyon) yüksek olması, MCV'nin çok düşük (58.2 fL), RDW ve ferritinin normal olması ve Hb elektroforezinde **HbA2'nin >%3.5 (%4)** saptanması **Beta talasemi minör (taşıyıcılığı)** için tanısaldır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 30, "question": "Anemik bir hastada anemi semptomların gelişiminde aşağıdakilerden hangisi etkili\ndeğildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Hastanın cinsiyeti"}, {"letter": "B", "text": "Hemoglobin düzeyi"}, {"letter": "C", "text": "Aneminin oluş hızı"}, {"letter": "D", "text": "Hastanın yaşı"}, {"letter": "E", "text": "Kardiyovasküler sistemin durumu"}], "answer": "A", "note": null, "id": "2020-2021_Q30", "explanation": "Anemi semptomlarının şiddetini belirleyen faktörler aneminin gelişim hızı, derinliği (Hb düzeyi), hastanın yaşı ve kardiyopulmoner rezerv durumudur; **hastanın cinsiyeti** semptom gelişiminde belirleyici değildir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 31, "question": "Demir eksikliği anemisiyle ilgili aşağıda verilen ifadelerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Serum demiri düşüktür"}, {"letter": "B", "text": "Demir bağlama kapasitesi artmıştır"}, {"letter": "C", "text": "Transferrin satürasyonu >%20"}, {"letter": "D", "text": "Ferritin düzeyi düşüktür"}, {"letter": "E", "text": "sTfR/log Ferritin İndeksi >2"}], "answer": "C", "note": null, "id": "2020-2021_Q31", "explanation": "Demir eksikliği anemisinde serum demiri ve ferritin düşer, TDBK artar; buna bağlı olarak **transferrin satürasyonu %20'nin (hatta <%15) altına düşer**. Transferrin satürasyonunun >%20 olması yanlıştır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 32, "question": "Philadelphia kromozumu hangi kromozolar arasındaki tranlokasyon sonucu gelişir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "8. kromozom ile 18. kromozom"}, {"letter": "B", "text": "9. kromozom ile 22. kromozom"}, {"letter": "C", "text": "6. kromozom ile 16. kromozom"}, {"letter": "D", "text": "3. kromozom ile 15. kromozom"}, {"letter": "E", "text": "2. kromozom ile 18. kromozom"}], "answer": "B", "note": null, "id": "2020-2021_Q32", "explanation": "Philadelphia (Ph) kromozumu, **9. kromozomdaki ABL1** geni ile **22. kromozomdaki BCR** geni arasındaki resiprokal translokasyon **t(9;22)(q34;q11)** sonucu oluşur ve tirozin kinaz aktiviteli BCR-ABL füzyon proteinini üretir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 33, "question": "Aşağıdaki şıklarda belirtilen ifadelerden hangisi aplastik anemide beklenen kemik\niliği bulgularındandır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Kemik iliği fibrozisi ile beraber hiposellüler kemik iliği"}, {"letter": "B", "text": "Kemik iliği infiltrasyonu ile beraber hiposellüler kemik iliği"}, {"letter": "C", "text": "Kemik iliği fibrozisi ile beraber hipersellüler kemik iliği"}, {"letter": "D", "text": "Kemik iliği infiltrasyonu ile beraber hipersellüler kemik iliği"}, {"letter": "E", "text": "Kemik iliği infiltrasyonu ve fibrozisi yokluğunda hiposellüler kemik iliği"}], "answer": "E", "note": null, "id": "2020-2021_Q33", "explanation": "Aplastik anemide kemik iliği biyopsisinde hematopoetik hücrelerin yerini yağ dokusu almıştır; **kemik iliği infiltrasyonu ve retikülin fibrozisi olmaksızın hiposellüler (<%25) kemik iliği** saptanır."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 34, "question": "Ağır/ciddi enfeksiyon durumunda lökositlerde aşağıdaki\nanomalilerden/değişikliklerden hangisi görülür?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Alder anomalisi"}, {"letter": "B", "text": "Chediak Higashi Anomalisi"}, {"letter": "C", "text": "Pelger Huet anomalisi"}, {"letter": "D", "text": "Auer cisimleri"}, {"letter": "E", "text": "Toksik granülasyon"}], "answer": "E", "note": null, "id": "2020-2021_Q34", "explanation": "Ağır bakteriyel enfeksiyon ve sepsis durumlarında nötrofillerin sitoplazmasındaki primer (azurofilik) granüllerin koyu-iri boyanmasıyla **toksik granülasyon** (ve Döhle cisimcikleri, sola kayma) görülür."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "Toprak yeme/pika yakınması olan bir kadında anemi saptanırsa bunun öncelikle ne\ntür bir anemi olmasını beklersiniz?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Demir eksikliği anemisi"}, {"letter": "B", "text": "Pernisyöz anemi"}, {"letter": "C", "text": "Folik asit eksikliğine bağlı makrositik anemi"}, {"letter": "D", "text": "Hemolitik anemi"}, {"letter": "E", "text": "Kronik hastalık anemisi"}], "answer": "A", "note": null, "id": "2020-2021_Q35", "explanation": "Toprak, kil, buz veya kireç yeme isteği olarak tanımlanan **pika (jeofaji/pagofaji)** semptomu klasik olarak **Demir Eksikliği Anemisi** ile ilişkilidir."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "Dünya Sağlık Örgütü 2018 sınıflamasına göre Esansiyel Trombositoz majör tanı\nkriterlerinden biri değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Trombosit sayısının ≥450 bin/L olması,"}, {"letter": "B", "text": "JAK 2 mutasyon varlığı,"}, {"letter": "C", "text": "CALR ve MPL genlerinde mutasyon varlığı,"}, {"letter": "D", "text": "Reaktif trombositoz bulgusu olmaması,"}, {"letter": "E", "text": "Büyük ve olgun görünümdeki megakaryositlerin proliferasyonu ile karekterize kemik iliği"}], "answer": "D", "note": null, "id": "2020-2021_Q36", "explanation": "DSÖ kriterlerine göre Esansiyel Trombositozda trombosit ≥450.000/µL, kemik iliğinde megakaryosit proliferasyonu, diğer miyeloid neoplazi kriterlerinin karşılanmaması ve JAK2/CALR/MPL mutasyonu majör kriterlerdir (Cevdet Hoca notlarında reaktif trombositoz dışlanması D şıkkı olarak sorgulanmıştır)."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Kronik lenfositer lösemi tanısı için aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Periferik kanda ≥5000/μL monoklonal B lenfosit olmalıdır,"}, {"letter": "B", "text": "Akım sitometride CD5, 19, 20 ve 23 pozitif klonal lenfositler saptanmalıdır,"}, {"letter": "C", "text": "Yukardaki a ve b şıklarında bahsedilen anomaliler en az 3 ay süreyle olmalıdır,"}, {"letter": "D", "text": "Kemik iliği tutulumuna bağlı sitopeni varlığında periferik kanda lenfositoz şart değildir."}, {"letter": "E", "text": "Tanı için kemik iliği biyopsisi mutlak şarttır."}], "answer": "E", "note": null, "id": "2020-2021_Q37", "explanation": "Kronik Lenfositer Lösemi (KLL) tanısı periferik kan yayması ve akım sitometri (flow sitometri) ile konur; **tanı için kemik iliği biyopsisi mutlak şart değildir**."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "En sık lenfadenopati saptanan bölge hangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Aksiller bölge"}, {"letter": "B", "text": "İnguinal bölge"}, {"letter": "C", "text": "Popliteal bölge"}, {"letter": "D", "text": "Baş-boyun bölgesi"}, {"letter": "E", "text": "Dirsek bölgesi"}], "answer": "D", "note": null, "id": "2020-2021_Q38", "explanation": "Klinikte fizik muayenede en sık lenfadenopati saptanan anatomik bölge **baş-boyun (servikal) bölgesidir**."}, {"year": "2020-2021", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Kanserojen subtrat ve ilişkili olduğu kanser cinsi eşleştimelerinden yanlış olan\nhangisidir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Berilyozis, mide kanseri"}, {"letter": "B", "text": "Kadmiyum, prostat kanseri"}, {"letter": "C", "text": "Benzen, lösemi"}, {"letter": "D", "text": "Radyum, akciğer kanseri"}, {"letter": "E", "text": "Aflatoksin, karaciğer kanseri"}], "answer": "A", "note": null, "id": "2020-2021_Q39", "explanation": "**Berilyum (berilyozis)** maruziyeti mide kanseri ile değil, **akciğer kanseri** ve kronik granülomatöz akciğer hastalığı ile ilişkilidir. Kadmiyum-prostat, benzen-lösemi, radyum/radon-akciğer ve aflatoksin-hepatoselüler karsinom eşleştirmeleri doğrudur."}, {"year": "2020-2021", "subject": "Tıbbi Genetik", "q_num": 40, "question": "Orak hücreler ve vasküler oklüzyon ile tanımlanan hemoglobinopatinin variant\ngrubu aşağıdakilerden hangisidir?", "professor": "Emine Berrin Yüksel", "options": [{"letter": "A", "text": "Hemoglobin F"}, {"letter": "B", "text": "Hemoglobin A"}, {"letter": "C", "text": "Hemoglobin C"}, {"letter": "D", "text": "Hemoglobin S"}, {"letter": "E", "text": "Hemoglobin Hammersmith"}], "answer": "D", "note": null, "id": "2020-2021_Q40", "explanation": "Beta globin zincirinin 6. pozisyonunda glutamik asit yerine valin geçmesiyle oluşan ve deoksijenasyonda polimerleşerek eritrositlerin oraklaşmasına ve vazo-oklüzyona yol açan varyant **Hemoglobin S (HbS)**'tir."}, {"year": "2020-2021", "subject": "Tıbbi Genetik", "q_num": 41, "question": "Aşağıdakilerden hangisi Ataksi-Telenjiektazi (AT) hastalığının özelliklerinden biri\ndeğildir?", "professor": "Emine Berrin Yüksel", "options": [{"letter": "A", "text": "Otozomal resesif kalıtım"}, {"letter": "B", "text": "Gelisme geriliği"}, {"letter": "C", "text": "Serebellar ataksi"}, {"letter": "D", "text": "Radiyal aks ve bas parmak malformasyonları"}, {"letter": "E", "text": "İmmun sistem defekti"}], "answer": "D", "note": null, "id": "2020-2021_Q41", "explanation": "Radiyal aks ve başparmak malformasyonları (aplastik/hipoplastik radius ve başparmak) Ataksi-Telanjiektazi'nin değil, **Fanconi Anemisi**'nin karakteristik konjenital anomalisidir."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 42, "question": "Doğal (natural) immünitede hangisi rol oynamaz?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "NK hücresi"}, {"letter": "B", "text": "Plazma hücresi"}, {"letter": "C", "text": "CD 4 + hücreler"}, {"letter": "D", "text": "CD 8+ hücreler"}, {"letter": "E", "text": "Makrofajlar"}], "answer": "B", "note": null, "id": "2020-2021_Q42", "explanation": "**Plazma hücreleri** B lenfositlerden farklılaşarak spesifik antikor sentezleyen **edinsel (adaptif/humoral)** immün sistem elemanlarıdır; doğal immünitede rol oynamazlar.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 69, "id": "2024-2025_Q69"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 43, "question": "Mast hücresi hangi tip aşırı duyarlık reaksiyonunda rol oynar?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tip I"}, {"letter": "B", "text": "Tip II"}, {"letter": "C", "text": "Tip III"}, {"letter": "D", "text": "Tip IV"}, {"letter": "E", "text": "Hiçbirisi"}], "answer": "A", "note": null, "id": "2020-2021_Q43", "explanation": "**Mast hücreleri** yüzeylerindeki yüksek afiniteli FcεRI reseptörleri aracılığıyla IgE antikorlarını bağlar ve alerjenle karşılaştığında degranüle olarak **Tip I (erken tip / anafilaktik) aşırı duyarlılık** reaksiyonlarında başrol oynar.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 60, "id": "2021-2022_Q60"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 44, "question": "Sistemik lupus eritematozus için spesifik otoantikor tipi hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Anti düzkas antikoru"}, {"letter": "B", "text": "ANA (antinükleer antikor)"}, {"letter": "C", "text": "Antimitokondrial antikor"}, {"letter": "D", "text": "Anti Sm (Smith) antikor"}, {"letter": "E", "text": "Antifosfolipid antikor"}], "answer": "D", "note": null, "id": "2020-2021_Q44", "explanation": "SLE'de ANA duyarlılığı en yüksek tarama testi iken, hastalık için **spesifitesi yüksek** olan otoantikorlar **Anti-dsDNA** ve **Anti-Sm (Smith)** antikorlarıdır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 58, "id": "2021-2022_Q58"}, {"kurul": "1", "year": "2024-2025", "q_num": 80, "id": "2024-2025_Q80"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 45, "question": "Aşağıdakilerden hangisi malign tümördür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Fibroma"}, {"letter": "B", "text": "Fibroadenoma"}, {"letter": "C", "text": "Papilloma"}, {"letter": "D", "text": "Kondroma"}, {"letter": "E", "text": "Seminoma"}], "answer": "E", "note": null, "id": "2020-2021_Q45", "explanation": "**Seminoma**, sonu '-oma' ekiyle bitmesine rağmen testis germ hücrelerinden köken alan **malign** bir tümördür (benzer şekilde lenfoma, melanom, mezotelyoma ve hepatoma da maligndir)."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 46, "question": "TP53 geni için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "DNA hasarı gibi stresler tarafından aktive edilir"}, {"letter": "B", "text": "Genomun bekçisi olarak adlandırılır"}, {"letter": "C", "text": "İnsan kanserlerinin p'inden fazlasında kusurludur"}, {"letter": "D", "text": "Hücreyi mitozun G2 evresinde duraklatır"}, {"letter": "E", "text": "Normalde hasarlı hücreyi apoptoza yönlendirir"}], "answer": "D", "note": null, "id": "2020-2021_Q46", "explanation": "Genomun bekçisi olan **TP53**, DNA hasarı varlığında p21 (CDKN1A) sentezini artırarak hücre siklusunu G2 evresinde değil, esas olarak **G1/S geçiş noktasında (geç G1 evresinde)** durdurur."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 47, "question": "Karsinogenezde aşırı reseptör ekspresyonu hangi kanserde görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Glioblastomada PDGF mevcudiyeti"}, {"letter": "B", "text": "Meme kanserinde HER2/NEU (CerbB2) ekspresyonu"}, {"letter": "C", "text": "Nöroblastomada Nmyc ekspresyonu"}, {"letter": "D", "text": "Kolon kanserinde ras ekspresyonu"}, {"letter": "E", "text": "TGF-betanın pankreas kanserinde ekspresyonu"}], "answer": "B", "note": null, "id": "2020-2021_Q47", "explanation": "Karsinogenezde büyüme faktörü reseptörlerinin aşırı ekspresyonuna en klasik örnek **meme karsinomlarında HER2/neu (ERBB2 / c-erbB2)** reseptör tirozin kinaz amplifikasyonudur.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 57, "id": "2021-2022_Q57"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 48, "question": "Çok erken evrede diyetin kontrolü ile düzeltilebilen genetik hastalık hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Marfan sendromu"}, {"letter": "B", "text": "Ehlers-Danloss sendromları"}, {"letter": "C", "text": "Kistik fibrozis"}, {"letter": "D", "text": "Fenilketonüri"}, {"letter": "E", "text": "Gaucher hastalığı"}], "answer": "D", "note": null, "id": "2020-2021_Q48", "explanation": "**Fenilketonüri (PKU)**, fenilalanin hidroksilaz eksikliği sonucu gelişir; yenidoğan taramasıyla çok erken evrede saptandığında **fenilalaninden kısıtlı diyet** ile mental retardasyon tamamen önlenebilir."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 49, "question": "Aşağıdakilerden hangisi lizozomal depo hastalığı değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Gaucher h."}, {"letter": "B", "text": "Tay-Sachs h."}, {"letter": "C", "text": "Niemann-Pick h."}, {"letter": "D", "text": "Sandhoff h."}, {"letter": "E", "text": "Hurler sendromu"}], "answer": "E", "note": "Cevaplama Durumu: Soru iptal edildi.", "id": "2020-2021_Q49", "explanation": "Şıklarda yer alan Gaucher, Tay-Sachs, Niemann-Pick, Sandhoff ve Hurler sendromunun tamamı lizozomal depo hastalığı olduğu için bu soru sınavda **iptal edilmiştir**."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 50, "question": "İleri yaşlarda Alzheimer hastalığı benzeri beyin değişiklikleri görülen genetik\nhastalık hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Trizomi 21"}, {"letter": "B", "text": "22q11.2 delesyon sendromu"}, {"letter": "C", "text": "Turner sendromu"}, {"letter": "D", "text": "Klinefelter sendromu"}, {"letter": "E", "text": "Leber'in herediter optik nöropatisi"}], "answer": "A", "note": null, "id": "2020-2021_Q50", "explanation": "**Trizomi 21 (Down sendromu)** hastalarında, amiloid prekürsör protein (APP) geninin 21. kromozomda yer alması nedeniyle 40 yaş sonrasında **Alzheimer hastalığı** benzeri nöropatolojik beyin değişiklikleri gelişir."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 51, "question": "Postmenopozal kadınlarda görülebilen \"itai-itai\" hastalığı hangi çevresel ajanın gıda\nile kontaminasyonu sonucu görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kurşun"}, {"letter": "B", "text": "Civa"}, {"letter": "C", "text": "Kadmiyum"}, {"letter": "D", "text": "Vinil klorür"}, {"letter": "E", "text": "İzopropil alkol"}], "answer": "C", "note": null, "id": "2020-2021_Q51", "explanation": "Japonya'da pirinç tarlalarının **kadmiyum** ile kontamine olması sonucu özellikle postmenopozal kadınlarda ağır osteomalazi, osteoporoz, patolojik kırıklar ve böbrek tübül hasarı ile seyreden **'İtai-İtai' (Ah-Ah) hastalığı** tanımlanmıştır."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 52, "question": "Herediter sferositoz için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Otozomal dominant geçişlidir"}, {"letter": "B", "text": "Eritrosit membran iskeletindeki anormalliklerle ilgilidir"}, {"letter": "C", "text": "Splenomegali vardır"}, {"letter": "D", "text": "Eritrositler soluk görünümdedir"}, {"letter": "E", "text": "Splenektomi yararlıdır"}], "answer": "D", "note": null, "id": "2020-2021_Q52", "explanation": "Herediter sferositozda ankirin/spektrin defekti sonucu membran kaybeden eritrositler küreleşir (sferosit); ortalarındaki fizyolojik solukluk kaybolur ve **hiperkromik (koyu boyanan)** görünürler (MCHC artar). 'Soluk görünümdedir' ifadesi yanlıştır."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 53, "question": "Periferik kan yaymalarında hedef (target) hücre (eritrositler) hangi kemik iliği\nhastalığında görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Herediter sferositoz"}, {"letter": "B", "text": "Orak hücreli anemi"}, {"letter": "C", "text": "Alfa talassemi"}, {"letter": "D", "text": "Glukoz 6 Fosfat Dehidrogenaz eksikliği"}, {"letter": "E", "text": "Paroksismal noktürnal hemoglobinüri"}], "answer": "C", "note": null, "id": "2020-2021_Q53", "explanation": "Periferik yaymada hedef (target) hücreler, hücre membran yüzeyinin hemoglobin hacmine oranla arttığı **Talasemiler (Alfa/Beta talasemi)**, hemoglobinopatiler, demir eksikliği ve karaciğer hastalıklarında görülür (Bülent Mızrak sorusunda C: Alfa talasemi)."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 54, "question": "Auer isimcikleri hangi kemik iliği hastalığında görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "AML (Akut myeloblastik lösemi)"}, {"letter": "B", "text": "Myelodisplastik sendorm"}, {"letter": "C", "text": "Kronik myelositer lösemi"}, {"letter": "D", "text": "Polistemia vera"}, {"letter": "E", "text": "Primer myelofibrozis"}], "answer": "A", "note": null, "id": "2020-2021_Q54", "explanation": "Auer cisimcikleri neoplastik miyeloblastların sitoplazmasında görülen azurofilik çubuklardır ve **Akut Miyeloblastik Lösemi (AML)** için karakteristiktir.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 76, "id": "2024-2025_Q76"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 55, "question": "İnfarktüs, nekroz ve şok ile ilgili aşağıda verilen bilgilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "İnfarktüs bir dokunun vasküler beslenmesinin kesilmesi ile oluşan iskemik nekroz alanıdır ve pulmoner infarktüs sık görülen bir komplikasyondur."}, {"letter": "B", "text": "İnfarktüsler renklerine göre ve mikrobiyal infeksiyon varlığı veya yokluğuna göre kırmızı /hemorajik veya beyaz /anemik ve septik veya aseptik olarak sınıflandırılır"}, {"letter": "C", "text": "Kırmızı infarktüsler; Akciğer ve ince barsak gibi çift dolaşımlı dokularda oluşur"}, {"letter": "D", "text": "Beyin bu genellemelerin istisnasını oluşturur: Merkezi sinir sisteminde iskemik doku hasarı likefaksiyon nekrozu ile sonuçlanır"}, {"letter": "E", "text": "Şok; kardiyak outputun ve/veya dolaşımdaki etkin kan hacminin azalması sonucu meydana gelen sistemik doku hiperperfüzyonu durumudur"}], "answer": "E", "note": null, "id": "2020-2021_Q55", "explanation": "Şok, kardiyak debinin veya etkin dolaşım hacminin azalması sonucu gelişen sistemik doku **hipoperfüzyonu** (azalmış kanlanma) durumudur; E şıkkında 'hiperperfüzyonu' denildiği için yanlıştır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 70, "id": "2019-2020_Q70"}, {"kurul": "1", "year": "2021-2022", "q_num": 71, "id": "2021-2022_Q71"}, {"kurul": "1", "year": "2022-2023", "q_num": 61, "id": "2022-2023_Q61"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 56, "question": "Tromboemboli ve amiloidoz ile ilgili aşağıdaki belirtilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Trombüs oluşumuna yol açan nedenler; (Virchow triadı) ; Endotel hasarı, Staz veya türbülan kan akımı, Kanın hiperkoagulabilitesidir."}, {"letter": "B", "text": "Arteryel trombüsler, en sık olarak sırasıyla koronerler, serebral arterler ve femoral arterlerde gelişir"}, {"letter": "C", "text": "Venöz tromboz /flebotromboz sıklıkla kalbe doğru bir miktar büyür ve emboliye eğilimli damar lümeninde uzun bir kitle oluşturur, en sık alt ekstremitelerin venleri etkilenir"}, {"letter": "D", "text": "AL amiloidi; B hücre diskrazisi ile birlikte bulunur, Aβ Amiloid; Alzheimer hastalarında serebral plak ve kan damarlarında depolanır"}, {"letter": "E", "text": "İmmunosit diskrazileri ile birlikte olan amiloidozlar; Multipl miyeloma, Monoklonal gammopati, Diğer B hücre neoplazmları ile beraberdir ve Aβ Amiloid depolanması vardır."}], "answer": "E", "note": null, "id": "2020-2021_Q56", "explanation": "Multipl miyelom ve diğer B hücre/plazma hücresi diskrazileri ile birlikte görülen amiloidozda biriken protein Aβ değil, immünglobülin hafif zincir yapısındaki **AL amiloididir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 79, "id": "2019-2020_Q79"}, {"kurul": "1", "year": "2021-2022", "q_num": 72, "id": "2021-2022_Q72"}, {"kurul": "1", "year": "2022-2023", "q_num": 62, "id": "2022-2023_Q62"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 57, "question": "Aşağıda belirtilen inflamasyon ve inflamasyon mediyatörleri ile ilgili hangi bilgi\nyanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Granülomatöz inflamasyon; Özel bir kronik iltihap paternidir, aktive makrofajlar, granulomlar, epiteloid hücreler’den oluşur"}, {"letter": "B", "text": "Faktör Xa damar geçirgenliğini artırır, trombin, lökositin endotele adezyonunu güçlendirir, fibrinopeptidler damar geçirgenliğini artırır, lökositler için kemotaktiktir,"}, {"letter": "C", "text": "Hageman faktör; KC de sentezlenir, endotel hasarlı bölgeyle karşılaşıncaya kadar dolaşımda inaktiftir., hasarlı bölge ile karşılaşınca aktive olur."}, {"letter": "D", "text": "Konvertaz etkisiyle en son C5a; C5-9 MAC oluşumunu başlatır"}, {"letter": "E", "text": "Bradikinin; Histamine benzer etki gösterir, Vasküler permeabiliteyi artırır, Ekstravasküler düz kas kasılmasını sağlar (bronş düz kası), deriye enjekte edilirse ağrı yapar."}], "answer": "D", "note": null, "id": "2020-2021_Q57", "explanation": "Kompleman kaskadında Membran Atak Kompleksi (C5b-9 MAC) oluşumunu başlatan bileşen C5a değil, **C5b**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 72, "id": "2019-2020_Q72"}, {"kurul": "1", "year": "2021-2022", "q_num": 75, "id": "2021-2022_Q75"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 58, "question": "Kaşekside ön planda rol oynayan aşağıdakilerden hangisidir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "IL - 8"}, {"letter": "B", "text": "TNF a"}, {"letter": "C", "text": "IFN a"}, {"letter": "D", "text": "IL-6"}, {"letter": "E", "text": "PAF"}], "answer": "B", "note": null, "id": "2020-2021_Q58", "explanation": "Kanser kaşeksisi patogenezinde iştah kaybı ve katabolizmadan sorumlu en önemli sitokin **TNF-α**'dır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 73, "id": "2019-2020_Q73"}, {"kurul": "1", "year": "2022-2023", "q_num": 65, "id": "2022-2023_Q65"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 59, "question": "Radyasyon etkisi ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "iyonize radyasyonun en önemli hücresel hedefi DNA'dir."}, {"letter": "B", "text": "İyonize radyasyon, RNA'yı zedeler. Bu nedenle germ hücreleri, kemik iliği ve gastrointestinal sistem gibi hızlı bölünen hücreler radyasyon zedelenmesine çok duyarlıdı"}, {"letter": "C", "text": "Morfolojik olarak radyasyon etkisinde, DNA ve nükleusu etkilemesine ek olarak, sitoplazmik şişme, mitokondriyal distorsiyon ve endoplazmik retikulumun dejenerasyonunu içeren çeşitli sitoplazmik değişiklikleri başlatabilir."}, {"letter": "D", "text": "Radyasyona uğrayan dokularda vasküler değişiklikler ve interstisyel fibrozis belirgindir."}, {"letter": "E", "text": "İyonize radyasyon, hücreleri doğrudan veya su ya da moleküler oksijenden serbest radikaller oluşturarak dolaylı yoldan zedeleyebilir"}], "answer": "B", "note": null, "id": "2020-2021_Q59", "explanation": "İyonize radyasyonun birincil hücresel hedefi RNA değil, **DNA** molekülünün doğrudan veya serbest radikaller aracılığıyla hasarlanmasıdır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 75, "id": "2019-2020_Q75"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 60, "question": "Malign tümör derecelendirmesinde hangisi kullanılır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenf düğümü metastazi sayısı"}, {"letter": "B", "text": "Tümör çapi"}, {"letter": "C", "text": "Tümörün çevre dokuya invazyonu"}, {"letter": "D", "text": "Tümörün sitolojik diferansiasyon derecesi"}, {"letter": "E", "text": "Karaciğer metastazının varlığı / yokluğu"}], "answer": "D", "note": null, "id": "2020-2021_Q60", "explanation": "Malign tümörlerin derecelendirmesinde (Grading) **tümörün sitolojik diferansiasyon derecesi** (normal dokuya benzerliği) kullanılır; diğer şıklar evreleme (TNM Staging) kriterleridir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 69, "id": "2019-2020_Q69"}, {"kurul": "1", "year": "2021-2022", "q_num": 80, "id": "2021-2022_Q80"}, {"kurul": "1", "year": "2022-2023", "q_num": 68, "id": "2022-2023_Q68"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 61, "question": "Hangisi mezensimal tümör değildir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Anjiosarkom"}, {"letter": "B", "text": "Bazal hücreli karsinom"}, {"letter": "C", "text": "Fibrosarkom"}, {"letter": "D", "text": "Snovyal sarkom"}, {"letter": "E", "text": "Glomus tümörü"}], "answer": "B", "note": null, "id": "2020-2021_Q61", "explanation": "**Bazal hücreli karsinom** mezenşimal değil, epidermis bazal tabakasından gelişen malign **epitelyal** bir tümördür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 68, "id": "2019-2020_Q68"}, {"kurul": "1", "year": "2021-2022", "q_num": 79, "id": "2021-2022_Q79"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 62, "question": "Aşağıdaki immünohistokimyasal belirleyicilerden hangisi, lenfosit predominant\nHodgkin hastalığında görülen Reed-Sternberg hücrelerinde karakteristik olarak pozitiftir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "CD 3"}, {"letter": "B", "text": "CD 1"}, {"letter": "C", "text": "CD 30"}, {"letter": "D", "text": "CD 20"}, {"letter": "E", "text": "CD 15"}], "answer": "D", "note": null, "id": "2020-2021_Q62", "explanation": "Nodüler Lenfosit Predominant Hodgkin Lenfomada (NLPHL) görülen 'patlamış mısır' (popcorn / L&H) hücreleri klasik RS hücrelerinden farklı olarak CD15 ve CD30 negatif, B hücre belirteci olan **CD20 pozitif**tir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 83, "id": "2021-2022_Q83"}, {"kurul": "1", "year": "2022-2023", "q_num": 74, "id": "2022-2023_Q74"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 63, "question": "Aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Faz I reaksiyonlarında yer alan hücresel enzim sistemlerinin en önemlisi, sitokrom P-450 sistemidir ve başta karaciğerin endoplazmik retikulumunda (ER) olmak üzere, deri, akciğerler, gastrointestinal (GI) mukoza ve pratik olarak her organda bulunur."}, {"letter": "B", "text": "Fiziksel ajanların meydana getirmiş olduğu hasar mekanik, termal, elektriksel ve iyonize radyasyona bağlı hasarlar şeklinde sınıflandırılabilir"}, {"letter": "C", "text": "Bu değişiklikler günler hatta haftalar sonra ortaya çıkabilir. Beyin hücrelerinin radyasyona duyarlılığının düşük olmasına karşın, radyasyondan sonraki vasküler hasar, dokularda radyasyon hasarının geç etkilerinin ortaya çıkmasına neden olabilir"}, {"letter": "D", "text": "Hücre proliferasyonu. iyonizan radyasyon DNA'yı zedelediği için, hızlı bölünen hücreler dinlenme evresindeki hücrelere göre daha duyarlıdır. DNA transkripsiyonunu bozan çok yüksek doz dışında, DNA hasarı nöronlar ve kas hücreleri gibi bölünmeyen hücrelerde yaşamla bağdaşır"}, {"letter": "E", "text": "Vasküler hasar; Radyasyona orta derecede duyarlı olan endotel hücrelerinin hasarı, kan damarlarının daralmasına veya tıkanmasına neden olabilir. Bu da iyileşme sürecinin aksamasına, kronik iskemik atrofiye yol açabilir."}], "answer": "C", "note": null, "id": "2020-2021_Q63", "explanation": "Radyasyona bağlı santral sinir sistemi / vasküler geç dönem değişiklikleri günler-haftalar içinde değil, **aylar hatta yıllar sonra** ortaya çıkar."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 64, "question": "Lenfoma / lösemilerle ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "En sık mutasyona uğrayan transkripsiyon faktörü genleri, B hücre kökenli A LL'lerde TE Lİ, AML1, E2A, PAX5 ve EBE'dir"}, {"letter": "B", "text": "KLL/SLL yavaş büyüyen ve yavaş ilerleyen bir tümördür ve tümör hücrelerinde, apoptozu engelleyen bir protein olan BCL2 seviyeleri çok yüksektir"}, {"letter": "C", "text": "KLL/SLL, pan-B belirteçleri olan CD19, CD20 ve CD23'ü ve yüzey immunglobulinleri mevcuttur ve tümör hücreleri ayrıca CD5'de eksprese ederler"}, {"letter": "D", "text": "Multipl Myelomda, MYC proto-onkogeni ilgilendiren translokasyonu saptanmıştır ve Tümör hücreleri sıklıkla Epstein-Barr virüsü latent olarak enfektedir"}, {"letter": "E", "text": "Diffüz Büyük B Hücreli Lenfoma; BCL6 geninde yeniden düzenlenmeler ya da mutasyonlar belirlenmiştir. Bu tümörlerin üçte biri folliküler lenfomadan kaynaklanır ve BCL2 ile ilişkili (14;18) translokasyonu mevcuttur"}], "answer": "D", "note": null, "id": "2020-2021_Q64", "explanation": "MYC translokasyonu ve yüksek sıklıkta latent EBV enfeksiyonu Multipl Myelom'un değil, **Burkitt Lenfoma**'nın özelliğidir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 76, "id": "2019-2020_Q76"}, {"kurul": "1", "year": "2021-2022", "q_num": 81, "id": "2021-2022_Q81"}, {"kurul": "1", "year": "2022-2023", "q_num": 69, "id": "2022-2023_Q69"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 65, "question": "Hodgkin ve Non Hodgkin lenfomalarla ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Hodgkin lenfomanm olmazsa olm az özelliği Reed Sternberg hücresidir."}, {"letter": "B", "text": "Noduler skleroz Hodgkin lenfoma en sık görülen formdur. Özel bir RS hücre varyantı olan laküner hücre sık görülür."}, {"letter": "C", "text": "Non-Hodgkin Lenfomada; Tek bir aksiyal nod grubunda lokalize olma daha sıktır, komşuluk yoluyla düzenli yayılım, mezenterik nodlar ve Waldeyer halkası tutulumu seyrektir,"}, {"letter": "D", "text": "Mikst sellüler Hodgkin lenfomada, morfolojik olarak küçük lenfositler, eozinofiller, plazma hücreleri ve makrofajlardan oluşan heterojen bir inflamatuar infiltrasyon içinde çok sayıda RS hücresi bulunur"}, {"letter": "E", "text": "Lenfositten baskın Hodgkin lenfomada. Patlamış mısıra benzeyen multilobe ve şişkin nükleusa sahip lenfohistiyositik (L&H) varyant RS hücrelerinin varlığı ile karakterizedir."}], "answer": "C", "note": null, "id": "2020-2021_Q65", "explanation": "Tek bir aksiyal lenf nodu grubunda lokalize olma ve komşuluk yoluyla düzenli yayılma Non-Hodgkin Lenfomanın değil, **Hodgkin Lenfoma**'nın özelliğidir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 77, "id": "2019-2020_Q77"}, {"kurul": "1", "year": "2022-2023", "q_num": 70, "id": "2022-2023_Q70"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 66, "question": "Lenfoma ve lösemilerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenfoblastik Lösemi; Lenfoblastik lösemi, ince, saç benzeri sitoplazmik çıkıntılar içeren lösemik hücrelerin varlığı ile karakterize, az görü len, yavaş seyirli bir B hücreli lenfomadır."}, {"letter": "B", "text": "Foiliküler Lenfomada; çoğu olguda, BCL2 over ekspresyonuna yol açan (14;18) translokasyonu vardır"}, {"letter": "C", "text": "Mantle H ücreli Lenfoma; Hücre siklusunun ilerlemesinde düzenleyici rol oynayan siklin D1’in overekspresyonu ile sonuçlanan (11 ;14) translokasyonu ile ilişkilidir."}, {"letter": "D", "text": "Burkitt lenfoma, kromozom 8 ’de localize MYC genini ilgilendiren tranlokasyonlar içerir."}, {"letter": "E", "text": "Mikozis Fungoides ve Sezary Sendromu; Neoplastik CD4+ T hücrelerinin tümörleri olan bu tümörler deride yuvalanırlar."}], "answer": "A", "note": null, "id": "2020-2021_Q66", "explanation": "İnce saç benzeri sitoplazmik çıkıntılar içeren ve yavaş seyirli olan B hücreli tümör Lenfoblastik Lösemi değil, **Tüylü Hücreli Lösemi (Hairy Cell Leukemia)**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 78, "id": "2019-2020_Q78"}, {"kurul": "1", "year": "2021-2022", "q_num": 74, "id": "2021-2022_Q74"}, {"kurul": "1", "year": "2022-2023", "q_num": 71, "id": "2022-2023_Q71"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 67, "question": "Fiziksel, kimyasal ve radyasyon etkisi ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Faz I reaksiyonlarında yer alan hücresel enzim sistemlerinin en önemlisi, sitokrom P-450 sistemidir."}, {"letter": "B", "text": "Fiziksel ajanların meydana getirmiş olduğu hasarlar; mekanik, termal, elektriksel ve iyonize radyasyona bağlı gelişenlerdir"}, {"letter": "C", "text": "Radyasyona bağlı morfolojik değişikler akut ortaya çıkar ve akut kaybolur."}, {"letter": "D", "text": "Hücre proliferasyonu. iyonizan radyasyon DNA'yı zedelediği için, hızlı bölünen hücreler dinlenme evresindeki hücrelere göre daha duyarlıdır"}, {"letter": "E", "text": "Radyasyona bağlı vasküler hasar; orta derecede duyarlı olan endotel hücrelerinin hasarı ile kan damarlarının daralmasına veya tıkanmasına neden olabilir"}], "answer": "C", "note": null, "id": "2020-2021_Q67", "explanation": "Radyasyona bağlı morfolojik ve vasküler değişiklikler akut ortaya çıkıp hemen kaybolmaz; obliteratif endarterit ve fibrozis nedeniyle **aylar-yıllar süren kalıcı/geç hasarlara** yol açar.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 74, "id": "2019-2020_Q74"}, {"kurul": "1", "year": "2021-2022", "q_num": 78, "id": "2021-2022_Q78"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 68, "question": "Kimyasal mediatörlerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Bradikinin; Vasküler permeabiliteyi artırır, arterioler dilatasyon ve brokokonstrüksiyon yapar."}, {"letter": "B", "text": "Kompleman sisteminde; Klasik yol, Antijen antikor kompleksi ile karşılaşma (C1 üzerinden), alternatif yol, Mikrobial yüzeyle temas, Lektin yolağı, Mannoz bağlayıcı lektinin direk C1’e bağlanması ile olur."}, {"letter": "C", "text": "Serotonin; Trombosit agregasyonu ile salınımı uyarılır ve vazokonstrüksiyona neden olur."}, {"letter": "D", "text": "TxA2; trombositlerde üretilir, trombosit agregasyonu ve vazokonstrüksiyon yapar."}, {"letter": "E", "text": "PGI2; vazokonstriksiyon sağlar, trombosit agregasyonnu inhibe eder."}], "answer": "E", "note": null, "id": "2020-2021_Q68", "explanation": "Endotel hücrelerinde sentezlenen **PGI2 (Prostasiklin)** trombosit agregasyonunu inhibe eder ancak vazokonstrüksiyon değil, güçlü **vazodilatasyon** yapar (vazokonstrüksiyon ve agregasyon yapan TxA2'dir).", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 82, "id": "2021-2022_Q82"}, {"kurul": "1", "year": "2022-2023", "q_num": 73, "id": "2022-2023_Q73"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 69, "question": "Aşağıdakilerden hangisi rejenerasyon yeteneği olmayan permanent hücredir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Hepatosit"}, {"letter": "B", "text": "Endotel hücresi"}, {"letter": "C", "text": "Deri epitel hücresi"}, {"letter": "D", "text": "İnce barsak epitel hücresi"}, {"letter": "E", "text": "İskelet kas hücresi"}], "answer": "E", "note": null, "id": "2020-2021_Q69", "explanation": "Bölünme (rejenerasyon) yeteneği olmayan **permanent (kalıcı) hücreler**: nöronlar, kalp kası hücreleri ve **iskelet kası hücreleri**dir. Hepatosit ve endotel stabil, deri ve bağırsak epiteli labil hücrelerdir."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 70, "question": "Aşağıdakilerden hangisi hücre çoğalması ve büyümesini inhibe eden, güçlü\nantiinflamatuar etkiye ve potent fibrojenik etkiye sahip skar oluşumunda en önemli\nstimülatör büyüme faktörüdür?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "VEGF"}, {"letter": "B", "text": "EGF"}, {"letter": "C", "text": "b-FGF"}, {"letter": "D", "text": "TGF-B"}, {"letter": "E", "text": "PDGF"}], "answer": "D", "note": null, "id": "2020-2021_Q70", "explanation": "**TGF-β (Transforming Growth Factor-Beta)** epitel hücre çoğalmasını inhibe eden, güçlü antiinflamatuar etki gösteren ve fibroblast göçü/kollajen sentezini uyararak **fibrozis (skar oluşumu)** gelişiminde en önemli rolü oynayan büyüme faktörüdür.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 61, "id": "2021-2022_Q61"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 71, "question": "Akut inflamasyonda aşağıdakilerden hangisi daha önce oluşur?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Lökosit marjinasyonu"}, {"letter": "B", "text": "Lökosit transmigrasyonu"}, {"letter": "C", "text": "Vazokonstrüksiyon"}, {"letter": "D", "text": "Vazodilatasyon"}, {"letter": "E", "text": "Eksüdasyon"}], "answer": "C", "note": null, "id": "2020-2021_Q71", "explanation": "Akut inflamasyonda damarsal değişikliklerin en başında saniyeler süren **geçici vazokonstrüksiyon** meydana gelir; hemen ardından histamin ve NO etkisiyle arteriyoler vazodilatasyon, permeabilite artışı (eksüdasyon) ve lökosit olayları başlar."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 72, "question": "Akut inflamasyonda lökositler için kemotaktik etki oluşturmayan aşağıdakilerden\nhangisidir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Solubl bakteriyel ürünler"}, {"letter": "B", "text": "Kompleman C3b"}, {"letter": "C", "text": "Kompleman C5a"}, {"letter": "D", "text": "Lökotrien B4"}, {"letter": "E", "text": "İnterlökin-8"}], "answer": "B", "note": null, "id": "2020-2021_Q72", "explanation": "**Kompleman C3b** kemotaktik bir faktör değil, fagositozu kolaylaştıran bir **opsonin**dir. Solübl bakteri ürünleri, C5a, LTB4 ve IL-8 (CXCL8) ise ana kemotaktik ajanlardır."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 73, "question": "Aşağıdakilerden hangisinde \"Zahn çizgileri\" görülmesi tipiktir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Kardiyovasküler trombüs"}, {"letter": "B", "text": "Derin venöz trombüs"}, {"letter": "C", "text": "Küçük arteryel trombüs"}, {"letter": "D", "text": "Postmortem trombüs"}, {"letter": "E", "text": "Taze gastrointestinal kanama"}], "answer": "A", "note": null, "id": "2020-2021_Q73", "explanation": "**Zahn çizgileri**, kalp boşluklarında veya aort/büyük arterlerde akan kan içinde oluşan **antemortem kardiyovasküler trombüslerde** açık renkli trombosit-fibrin tabakaları ile koyu renkli eritrosit tabakalarının ardışık dizilmesiyle oluşan karakteristik laminasyonlardır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 69, "id": "2021-2022_Q69"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 74, "question": "Majör histokompatibilite kompleks (doku uyum molekülleri)'ni kodlayan genler\nkümesi hangi kromozomda bulunur?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "3. kromozom"}, {"letter": "B", "text": "4. kromozom"}, {"letter": "C", "text": "5. kromozom"}, {"letter": "D", "text": "6. kromozom"}, {"letter": "E", "text": "10. kromozom"}], "answer": "D", "note": null, "id": "2020-2021_Q74", "explanation": "İnsanda Majör Histokompatibilite Kompleksi (**MHC / HLA**) moleküllerini kodlayan gen kümesi **6. kromozomun kısa kolunda (6p21)** yer alır."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 75, "question": "Trombositopeni, ekzema ve enfeksiyonlarla seyreden, özellikle T hücre immün\nyetmezliğine bağlı oluşan hastalık aşağıdakilerden hangisidir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Bruton Agammaglobülinemisi"}, {"letter": "B", "text": "DiGeorge Sendromu"}, {"letter": "C", "text": "İzole IgA yetmezliği"}, {"letter": "D", "text": "Yaygın değişken immün yetmezlik hastalığı"}, {"letter": "E", "text": "Wiskott-Aldrich Sendromu"}], "answer": "E", "note": null, "id": "2020-2021_Q75", "explanation": "**Wiskott-Aldrich Sendromu**, X'e bağlı resesif kalıtılan WASP gen mutasyonu sonucu **mikrotrombositopeni, egzema ve tekrarlayan fırsatçı enfeksiyonlar** (başlangıçta T hücre, giderek kombine immün yetmezlik) ile seyreden hastalıktır.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 64, "id": "2021-2022_Q64"}]}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 76, "question": "Aşağıdaki maddelerden hangisine mesleki uzun süreli maruziyette, akciğer ve deride\nhemanjiosarkom gelişim riskinde artış olur?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Asbest"}, {"letter": "B", "text": "Arsenik"}, {"letter": "C", "text": "Benzen"}, {"letter": "D", "text": "Kadmiyum"}, {"letter": "E", "text": "Etilen oksit"}], "answer": "B", "note": null, "id": "2020-2021_Q76", "explanation": "Cengiz Koçak hocanın mesleki karsinojenler ders notuna göre karaciğer/akciğer hemanjiyosarkomu vinil klorür ve **arsenik** maruziyeti ile ilişkilendirilmiş olup bu soruda cevap anahtarı **B (Arsenik)**'tir."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 78, "question": "Aşağıdakilerden hangisi folliküler lenfoma ve folliküler hiperplazi ayırımında,\nfolliküler lenfoma lehine bir bulgu değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Tüm lenf nodunda yaygın tutulum"}, {"letter": "B", "text": "Kapsül dışına yayılım"}, {"letter": "C", "text": "Uniform follikül şekil ve büyüklüğü"}, {"letter": "D", "text": "Mitoz hızının düşük olması"}, {"letter": "E", "text": "Germinal merkezlerde \"tingible cisim\" makrofajların çok olması"}], "answer": "E", "note": null, "id": "2020-2021_Q78", "explanation": "Germinal merkezlerde apoptotik hücre artıkları fagosite etmiş **'tingible body' (boyanabilir cisimcikli) makrofajların** bol bulunması, yüksek proliferasyon ve apoptoz hızına sahip **reaktif folliküler hiperplazi** lehinedir; folliküler lenfomada bu makrofajlar kaybolur."}, {"year": "2020-2021", "subject": "Patoloji", "q_num": 79, "question": "Aşağıdakilerden hangisi, lenf nodlarında \"nonspesifik reaktif parakortikal\nhiperplazi\" sebeplerinden değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Akut enfeksiyöz mononükleoz LAP"}, {"letter": "B", "text": "Sitomegalovirüs LAP"}, {"letter": "C", "text": "İlaç hipersensitivite LAP"}, {"letter": "D", "text": "Toksoplazma LAP"}, {"letter": "E", "text": "Postvaksinal LAP"}], "answer": "D", "note": null, "id": "2020-2021_Q79", "explanation": "**Toksoplazma lenfadenopatisi** parakortikal hiperplazi değil, folliküler hiperplazi + monositoid B hücre artışı + epiteloid histiyosit kümeleri triadı yapar. EBV, CMV, aşı sonrası ve ilaç reaksiyonları ise parakortikal hiperplazi nedenidir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 67, "id": "2021-2022_Q67"}]}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 80, "question": "Aşağıdaki laboratuvar bulgularından hangisi demir eksikliği anemisi ile beta\ntalasemi taşıyıcılığı arasında artış ya da azalış yönlerine göre farklı olan bulgulardan birisi\ndeğildir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "RDW"}, {"letter": "B", "text": "Retikulosit"}, {"letter": "C", "text": "MCV"}, {"letter": "D", "text": "Çinko protoporfirin"}, {"letter": "E", "text": "Ferritin"}], "answer": "C", "note": null, "id": "2020-2021_Q80", "explanation": "Demir eksikliği anemisi ile beta talasemi taşıyıcılığının her ikisinde de **MCV (Ortalama Eritrosit Hacmi) azalmıştır** (aynı yönde değişir). RDW, çinko protoporfirin, ferritin ve retikülosit ise ayırıcı tanıda farklılık gösterir."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 81, "question": "Non hem yapısındaki demirin, intestinal epitelden taşınmadan önce, hangi enzim ile\nferröz demir formuna dönüşümü gerçekleşir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Hem oksijenaz"}, {"letter": "B", "text": "Ferroportin"}, {"letter": "C", "text": "Ferritin redüktaz"}, {"letter": "D", "text": "Hephaestin"}, {"letter": "E", "text": "Ferroşelataz"}], "answer": "C", "note": null, "id": "2020-2021_Q81", "explanation": "Diyetle alınan ferrik (Fe+3) formdaki non-hem demirin duodenum enterositlerinden DMT1 taşıyıcısı ile emilebilmesi için önce lümende askorbik asit ve fırçamsı kenardaki **ferrik redüktaz (duodenal sitokrom b / ferritin redüktaz)** enzimi ile ferröz (Fe+2) forma indirgenmesi gerekir."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 82, "question": "Aşağıdaki genlerden hangisi tümör baskılayıcı gen sınıfında değildirler?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Rb geni"}, {"letter": "B", "text": "p53 geni"}, {"letter": "C", "text": "Bcl-2"}, {"letter": "D", "text": "Kadherinler"}, {"letter": "E", "text": "BRCA-1"}], "answer": "C", "note": null, "id": "2020-2021_Q82", "explanation": "**Bcl-2** apoptozu baskılayan bir **proto-onkogen / anti-apoptotik gen**dir; tümör baskılayıcı gen değildir. Rb, p53, E-kadherin ve BRCA-1 ise tümör baskılayıcı genlerdir."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 83, "question": "Metastaz gelişinceye kadar malign bir tümörü benign olanlardan ayıran en belirgin\nözellik aşağıdakilerden hangisidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Büyüme hızı"}, {"letter": "B", "text": "Diferansiyasyon derecesi"}, {"letter": "C", "text": "Anaplazik olması"}, {"letter": "D", "text": "İnvaziv olması"}, {"letter": "E", "text": "Çoğalma hızı"}], "answer": "D", "note": null, "id": "2020-2021_Q83", "explanation": "Uzak metastazdan sonra malign tümörü benign tümörden ayıran en güvenilir ve belirgin kriter çevre dokulara **invaziv olması (yerel invazyon)**'dur."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 84, "question": "Pelvik kitleleri olan postmenopozal kadınlarda ölçümü malign lezyonları benign\nlezyonlardan ayırmaya yardımcı olan tümör belirteci hangisidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "CEA"}, {"letter": "B", "text": "CA 19.9"}, {"letter": "C", "text": "CA 15.3"}, {"letter": "D", "text": "CA125"}, {"letter": "E", "text": "CA 72.9"}], "answer": "D", "note": null, "id": "2020-2021_Q84", "explanation": "Pelvik kitlesi olan postmenopozal kadınlarda seröz/müsinöz **over (yumurtalık) kanserlerini** benign kitlelerden ayırmada ve tedavi takibinde kullanılan temel tümör belirteci **CA 125**'tir."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 85, "question": "Aşağıdaki tümör belirteçlerinden hangisi onkofetal antijenler grubundadır?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "CA-15.3"}, {"letter": "B", "text": "CA 125"}, {"letter": "C", "text": "HCG"}, {"letter": "D", "text": "CA 19.9"}, {"letter": "E", "text": "CEA"}], "answer": "E", "note": null, "id": "2020-2021_Q85", "explanation": "Fetal yaşamda normal olarak üretilen ancak erişkinde tümör dokusunda yeniden eksprese edilen **onkofetal antijenler** başlıca **CEA (Karsinoembriyonik Antijen)** ve **AFP (Alfa-fetoprotein)**'dir."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 86, "question": "Platelet agregasyonunun gerçekleşemediği Glanzmann trombastenisinde\naşağıdakilerden hangisinin eksiklik durumu araştırılmalıdır?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "GP 1a-1b"}, {"letter": "B", "text": "GP IIb-IIIa"}, {"letter": "C", "text": "Trombosit sayısı"}, {"letter": "D", "text": "vWF"}, {"letter": "E", "text": "F VIIIa"}], "answer": "B", "note": null, "id": "2020-2021_Q86", "explanation": "**Glanzmann trombastenisi**, trombosit yüzeyindeki fibrinojen reseptörü olan **Glikoprotein IIb-IIIa (GpIIb/IIIa)** kompleksinin kalıtsal eksikliği sonucu trombosit agregasyonunun bozulduğu hastalıktır (GpIb-IX eksikliği ise Bernard-Soulier sendromudur)."}, {"year": "2020-2021", "subject": "Biyokimya", "q_num": 87, "question": "Aşağıdaki pıhtılaşma proteinlerinden hangisi karaciğer ve kemik iliğinde\nsentezlenip, fibrinojen pıhtı çapraz bağlarının sağlamlaştırılmasında görevlidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Faktör V"}, {"letter": "B", "text": "Faktör VIII"}, {"letter": "C", "text": "Faktör X"}, {"letter": "D", "text": "Faktör XII"}, {"letter": "E", "text": "Faktör XIII"}], "answer": "E", "note": null, "id": "2020-2021_Q87", "explanation": "**Faktör XIII (Fibrin stabilize edici faktör)**, trombin ile aktifleşerek gevşek fibrin monomerleri arasında kovalent çapraz bağlar oluşturan ve pıhtıyı stabilize eden transglutaminaz enzimidir."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 88, "question": "Başarılı geçen böbrek transplantasyonu sonrası immünsüpresif tedavi altındaki\nhastada öksürük ve ateş şikayeti gelişmiştir. Pnömoni düşünülen hastada antibiyotik\ntedavisine rağmen durum kötüleşmiştir. Yapılan akciğer biyopsisinde dar açı ile dallanan\nseptalı hifler görülmüştür. Klinik tablodan sorumlu en olası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aspergillus fumigatus"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Rhizopus spp."}, {"letter": "D", "text": "Cryptococcus neoformans"}, {"letter": "E", "text": "Penicillium spp."}], "answer": "A", "note": null, "id": "2020-2021_Q88", "explanation": "İmmünsüpresif hastada antibiyotiğe yanıtsız pnömoni ve doku biyopsisinde **45 derece dar açıyla (dikotom) dallanan septalı hiflerin** görülmesi invaziv **Aspergillus fumigatus** enfeksiyonu için tipiktir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 86, "id": "2023-2024_Q86"}]}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 89, "question": "35 yaşında AIDS hastası ateş ve baş ağrısı şikayetleri ile başvuruyor. Muayenesinde\nense sertliği saptanan hastadan lomber ponksiyon yapılıyor. Alınan beyin-omurilik sıvısı\nörneğinin çini mürekkebi ile boyamasında kapsüllü maya mantarı saptanmıştır. Etken olan\nmantarın tanımlanmasında aşağıdaki testlerden hangisi kullanılabilir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Fenol oksidaz testi"}, {"letter": "B", "text": "Germ tüp testi"}, {"letter": "C", "text": "Koagülaz testi"}, {"letter": "D", "text": "TSI besiyerine ekim"}, {"letter": "E", "text": "Sitrat testi"}], "answer": "A", "note": null, "id": "2020-2021_Q89", "explanation": "AIDS hastasında BOS'ta çini mürekkebi ile gösterilen kapsüllü maya **Cryptococcus neoformans** olup, tanımlanmasında melanin üretimini gösteren **fenol oksidaz (kafeik asit) testi** ve üreaz pozitifliği kullanılır."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Aşağıdaki mikotoksinlerden hangisi karaciğerde epoksite dönüşümü sonucunda p53\nmutasyonuna ve hepatoselüler karsinomaya neden olur?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aflatoksin B1"}, {"letter": "B", "text": "Sitrinin"}, {"letter": "C", "text": "Fumonizin"}, {"letter": "D", "text": "Trikoteken"}, {"letter": "E", "text": "Patulin"}], "answer": "A", "note": null, "id": "2020-2021_Q90", "explanation": "Aspergillus flavus tarafından üretilen **Aflatoksin B1**, karaciğerde sitokrom P450 ile epoksite dönüşerek TP53 geninin 249. kodonunda G→T mutasyonuna ve **hepatoselüler karsinoma (HCC)** gelişimine yol açar."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 91, "question": "HIV ile enfekta hastalarda görülen \"kaposi sarkomu\" hangi tip herpes virüs ile\nilişkilendirilmiştir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "8"}, {"letter": "B", "text": "7"}, {"letter": "C", "text": "6"}, {"letter": "D", "text": "1"}, {"letter": "E", "text": "2"}], "answer": "A", "note": null, "id": "2020-2021_Q91", "explanation": "HIV/AIDS hastalarında görülen vasküler endotelyal tümör olan **Kaposi sarkomu**, **Human Herpesvirus-8 (HHV-8 / KSHV)** enfeksiyonu ile doğrudan ilişkilidir."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 92, "question": "Herpes tip 1 ve 2 ayrımında ELISA testi neden tam ayırıcı değildir", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Genom homolojisinin % 50'den fazla olması"}, {"letter": "B", "text": "İçerdiği enzimlerin benzerliğinin % 50'den fazla olması"}, {"letter": "C", "text": "İçerdiği organel benzerliğinin % 50'den fazla olması"}, {"letter": "D", "text": "Revers transkriptaz içermesi"}, {"letter": "E", "text": "RNA polimeraz içermesi"}], "answer": "A", "note": null, "id": "2020-2021_Q92", "explanation": "HSV Tip 1 ve Tip 2 arasında **genomik DNA homolojisi %50'den fazla** olduğu ve ortak antijenik glikoproteinler taşıdıkları için standart serolojik ELISA testlerinde çapraz reaksiyon görülür (ayrım için tip-spesifik glikoprotein G bazlı test gerekir)."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 93, "question": "Hücreye girdikten sonra tek iplikçikli viral RNA’dan, çift iplikçikli DNA oluşumu\ngerçekleştiren ve provirus adı verilen bu DNA'yı hücrenin çekirdeğine taşınıp hücre DNA’sına\nentegre olmasına sebep olan virüs grubu hangisidir", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Retrovirüs"}, {"letter": "B", "text": "Hepatovirüs"}, {"letter": "C", "text": "Sitomegalovirüs"}, {"letter": "D", "text": "Rotavirüs"}, {"letter": "E", "text": "Rabdovirüs"}], "answer": "A", "note": null, "id": "2020-2021_Q93", "explanation": "Revers transkriptaz enzimi ile tek iplikli RNA'dan çift iplikli DNA (provirüs) sentezleyip integraz enzimiyle konak hücre DNA'sına entegre olan virüs ailesi **Retrovirüsler (Retroviridae)**'dir."}, {"year": "2020-2021", "subject": "Mikrobiyoloji", "q_num": 94, "question": "HPV tip 16, 18, 31, 45 için ilişkili hastalıklarından aşağıdakilerden hangisi \"en\ndoğrusudur\".", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Yaygın siğil (common wart) etkenidir"}, {"letter": "B", "text": "Basık siğil (flat wart) etkenidir"}, {"letter": "C", "text": "Plantar siğil etkenidir"}, {"letter": "D", "text": "Servikal karsinom etkenidir"}, {"letter": "E", "text": "Fokal epitelyal hiperplazi (Heck hastalığı) etkenidir"}], "answer": "D", "note": null, "id": "2020-2021_Q94", "explanation": "Yüksek riskli onkojenik HPV tipleri olan **HPV 16, 18, 31 ve 45** başlıca **servikal karsinom** (rahim ağzı kanseri) ve diğer anogenital/orofaringeal skuamöz hücreli kanserlerin etkenidir."}, {"year": "2020-2021", "subject": "Radyoloji", "q_num": 95, "question": "Aşağıdakilerden hangisi röntgenin temel görüntüleme alanlarından biri değildir?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Meme"}, {"letter": "B", "text": "Kemik"}, {"letter": "C", "text": "Eklem"}, {"letter": "D", "text": "Karaciğer"}, {"letter": "E", "text": "Akciğer"}], "answer": "D", "note": null, "id": "2020-2021_Q95", "explanation": "Direkt röntgen (radyografi) doğal kontrast farkı yüksek olan akciğer, kemik ve eklem görüntülemesinde ve mamografide temel yöntemdir; yumuşak doku parankim organı olan **karaciğerin** değerlendirilmesinde ise röntgen değil USG, BT ve MRG kullanılır."}, {"year": "2020-2021", "subject": "Radyoloji", "q_num": 96, "question": "Sık görülen ve erken tanıda etkili tedavi seçenekleri olan bazı malign neoplaziler\ngörüntüleme yöntemleri ile taranabilir. Aşağıdaki kanser- tarama yöntemi eşleştirmelerinden\nhangisi doğrudur?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Kolon kanseri-BT kolonografi"}, {"letter": "B", "text": "Meme kanseri-meme MRG"}, {"letter": "C", "text": "Prostat kanseri-pelvik USG"}, {"letter": "D", "text": "Akciğer kanseri-PET/BT"}, {"letter": "E", "text": "Serviks kanseri-pelvik USG"}], "answer": "A", "note": null, "id": "2020-2021_Q96", "explanation": "Radyolojik kanser tarama yöntemleri arasında **kolon kanseri için BT kolonografi** (sanal kolonoskopi) geçerli bir tarama seçeneğidir. Meme kanseri taraması MRG ile değil mamografi ile, akciğer kanseri taraması PET/BT ile değil düşük doz BT ile yapılır."}, {"year": "2020-2021", "subject": "İmmünoloji", "q_num": 97, "question": "Aşağıdakilerden hangisi/hangileri konak hücre zarlarının kesinlikle IgE ile değil\nIgM ve IgG ile etkileşmesiyle başlamamış olur?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Arthus reaksiyonları"}, {"letter": "B", "text": "Serum hastalığı"}, {"letter": "C", "text": "Tip I aşırı duyarlılık reaksiyonları"}, {"letter": "D", "text": "Tip II aşırı duyarlılık reaksiyonları"}, {"letter": "E", "text": "Tip IV aşırı duyarlılık reaksiyonları"}], "answer": "D", "note": "Cevaplama Durumu: Soru iptal edildi.", "id": "2020-2021_Q97", "explanation": "Soru kökündeki olumsuz ifade nedeniyle bu soru sınavda **iptal edilmiştir** (Tip II ve Tip III aşırı duyarlılık reaksiyonları IgE ile değil, IgG ve IgM antikorları ile başlar)."}, {"year": "2020-2021", "subject": "İmmünoloji", "q_num": 98, "question": "Yer fıstığına allerjisi olduğu bilinen 8 yaşındaki bir kız, farkında olmadan içinde eser\nmiktar fıstık bulunan tahıl tüketir. Bir saat içinde deride kızarıklık ve ürtiker şeklinde nefes\nalmada güçlük gibi solunumsal semptomlar gözlenir. Bu bulgular aşağıdakilerden hangisini\ngösterir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Tip I aşırı duyarlılık reaksiyonları"}, {"letter": "B", "text": "Arthus reaksiyonu"}, {"letter": "C", "text": "FcR taşıyan hücrelerin IgG ile kaplanmış konak hücreye bağlanması"}, {"letter": "D", "text": "IgG'nin solunum yollarındaki hücre dışı matrikse bağlanması"}, {"letter": "E", "text": "Lenfositlerin hücre yüzeyleriyle IgM-aracılı etkileşimi"}], "answer": "A", "note": null, "id": "2020-2021_Q98", "explanation": "Yer fıstığı alerjenine maruziyet sonrası dakikalar-bir saat içinde gelişen ürtiker, anjiyoödem ve bronkospazm (nefes darlığı), IgE ve mast hücresi aracılı **Tip I (anafilaktik / erken tip) aşırı duyarlılık reaksiyonu**dur."}, {"year": "2020-2021", "subject": "İmmünoloji", "q_num": 99, "question": "Streptococcus pyogenes ile enfeksiyon sırasında bir birey, kardiyak hasara sebep\nolan kalpteki moleküllerle yapısal benzerliği olan S. pyogenes antijenine karşı IgM veIgG\nantikorlatını yüksek miktarda üremiştir. Bu örnekte mikrop hangi işlev ile otoimmüniteye\nkatkıda bulunmuştur?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Anerji"}, {"letter": "B", "text": "Merkezi tolerans"}, {"letter": "C", "text": "Epitop yayılması"}, {"letter": "D", "text": "Moleküler mimikri (moleküler benzeşme)"}, {"letter": "E", "text": "Baskılamanın kaybı"}], "answer": "D", "note": null, "id": "2020-2021_Q99", "explanation": "Streptococcus pyogenes'in M proteini ile kalp kası sarkolemma/miyozin proteinleri arasındaki yapısal benzerlik sonucu üretilen antikorların kalp dokusuna saldırması (Akut Romatizmal Ateş) **moleküler mimikri (moleküler benzeşme)** mekanizmasının en klasik örneğidir."}, {"year": "2020-2021", "subject": "İmmünoloji", "q_num": 100, "question": "Aşağıdakilerden hangisi tümör hücrelerinin immün sistemden kaçışına kanıt\noluşturur?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Tümör hücrelerinin MHC sınıf I moleküllerini azaltması"}, {"letter": "B", "text": "Makrofajlar tarafından artmış miktarlarda tümör nekroz faktör (TNF) üretilmesi"}, {"letter": "C", "text": "Tümör hücre çoğalmasının IFN-gamma aracılı baskılanması"}, {"letter": "D", "text": "Tümöre özgül antijenlere karşı antikor üretilmesi"}, {"letter": "E", "text": "Artmış Bax belirmesi ile tümör hücre apoptozunun uyarılması"}], "answer": "A", "note": null, "id": "2020-2021_Q100", "explanation": "Tümör hücrelerinin CD8+ sitotoksik T lenfositleri tarafından tanınmasını önlemek için **yüzeylerindeki MHC Sınıf I moleküllerinin ekspresyonunu azaltması veya kaybetmesi**, tümörün immün sistemden kaçış (immune escape) mekanizmalarından biridir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 100, "id": "2023-2024_Q100"}]}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 1, "question": "Anemi tanımında aşağıdaki parametrelerden hangisi bulunur?\nI. Lökosit ve hemoglobin\nII. Eritrosit, monosit ve hemoglobin\nIII. Hematokrit ve trombosit\nIV. Eritrosit ve hemoglobin", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "I"}, {"letter": "B", "text": "II"}, {"letter": "C", "text": "III"}, {"letter": "D", "text": "IV"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "D", "note": null, "id": "2021-2022_Q1", "explanation": "Anemi, eritrosit kitlesinin (RBC), hemoglobin (Hb) konsantrasyonunun veya hematokrit (Hct) değerinin yaş ve cinsiyete göre normalin (-2 SD) altına düşmesi olarak tanımlanır; lökosit, monosit ve trombosit anemi tanımında yer almaz (Cevap: IV - Eritrosit ve hemoglobin)."}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 2, "question": "Anemi nedenlerinden eritrosit hücre seviyesinde olmayan sebep hangisidir?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Pirüvat Kinaz eksikliği"}, {"letter": "B", "text": "Retikülosit artışı"}, {"letter": "C", "text": "Orak şeklinde eritrosit"}, {"letter": "D", "text": "Glukoz 6-Fosfat Dehidrogenaz eksikliği"}, {"letter": "E", "text": "Globin sentezinde bozukluk"}], "answer": "B", "note": null, "id": "2021-2022_Q2", "explanation": "Eritrosit içi enzim ve yapı bozuklukları (pirüvat kinaz, G6PD, HbS, talasemi) doğrudan anemi nedenidir; **retikülosit artışı** ise bir anemi nedeni değil, kemik iliğinin rejeneratif yanıtıdır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 2, "id": "2020-2021_Q2"}]}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 3, "question": "Çocukluk çağı kanserlerinden en sık görülen hangisidir?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Kronik lösemiler"}, {"letter": "B", "text": "Wilms tümörü"}, {"letter": "C", "text": "Akut lösemiler"}, {"letter": "D", "text": "Nöroblastom"}, {"letter": "E", "text": "Lenfomalar"}], "answer": "C", "note": null, "id": "2021-2022_Q3", "explanation": "Çocukluk çağında en sık görülen malignite **Akut lösemilerdir** (başta ALL).", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 3, "id": "2020-2021_Q3"}]}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 4, "question": "Çocuklarda kanser tanısında uygulananlardan hangisi/leri doğrudur?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Periferik yayma/kemik iliği incelenmesi"}, {"letter": "B", "text": "Karaciğer/böbrek fonksiyon testleri"}, {"letter": "C", "text": "PA Akciğer grafisi/bilgisayarlı tomografi"}, {"letter": "D", "text": "Biyopsi yapılması"}, {"letter": "E", "text": "Hepsi"}], "answer": "E", "note": null, "id": "2021-2022_Q4", "explanation": "Çocuklarda kanser tanı ve evrelemesinde periferik yayma/kemik iliği, biyokimya, görüntüleme yöntemleri ve doku biyopsisinin tamamı kullanılır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 4, "id": "2020-2021_Q4"}]}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 5, "question": "Aşağıdakilerden hangisi en sık görülen primer immün yetmezliktir?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "Hücresel immün yetmezlik"}, {"letter": "B", "text": "T hücre defektleri"}, {"letter": "C", "text": "Hümoral immün yetmezlik"}, {"letter": "D", "text": "Kombine immün yetmezlik"}, {"letter": "E", "text": "Kompleman sistem bozuklukları"}], "answer": "C", "note": null, "id": "2021-2022_Q5", "explanation": "Tüm primer immün yetmezlikler içinde en sık görülen grup (%50-60'tan fazlası) **Hümoral (B hücre / antikor) immün yetmezliklerdir**."}, {"year": "2021-2022", "subject": "Pediatri", "q_num": 6, "question": "İmmün yetmezlik düşünülen bir hastada ilk önce hangisini bilmek istersiniz?", "professor": "Sema Yılmaz", "options": [{"letter": "A", "text": "İmmünglobin seviyesi"}, {"letter": "B", "text": "PPD testi"}, {"letter": "C", "text": "Sekretuvar IgA seviyesi"}, {"letter": "D", "text": "Aşıya karşı antikor seviyesi"}, {"letter": "E", "text": "Lenfosit sayısı"}], "answer": "E", "note": null, "id": "2021-2022_Q6", "explanation": "İmmün yetmezlik düşünülen bir çocukta ilk basamak tarama testi tam kan sayımı ve periferik yayma ile **mutlak lenfosit ve nötrofil sayısının** değerlendirilmesidir (ağır kombine immün yetmezlikte lenfopeni erken tanı koydurucudur)."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 7, "question": "Aşağıdakilerden hangisi histamin sentezinde hız kısıtlayıcı enzim olan histidin\ndekarboksilaz enzimini selektif inhibe eden ayrıca mevsimsel allerjinin profilaksisi amacıyla\nda kullanılabilen maddedir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Tritokalin"}, {"letter": "B", "text": "Zolantidin"}, {"letter": "C", "text": "Amodiakin"}, {"letter": "D", "text": "Betazol"}, {"letter": "E", "text": "Tiyazoetilamin"}], "answer": "A", "note": null, "id": "2021-2022_Q7", "explanation": "**Tritokalin**, L-histidinden histamin sentezleyen hız kısıtlayıcı enzim olan **histidin dekarboksilazı** selektif olarak inhibe eden ve mevsimsel alerji profilaksisinde kullanılan ilaçtır."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 8, "question": "Streptomyces tsukubanensis’ten elde edilen bir makrolid antibiyotik olup kalsinörin\ninhibitörü olan madde aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Takrolimus"}, {"letter": "B", "text": "Siklosporin"}, {"letter": "C", "text": "6-merkaptopurin"}, {"letter": "D", "text": "Mikofenolat mofetil"}, {"letter": "E", "text": "Metotreksat"}], "answer": "A", "note": null, "id": "2021-2022_Q8", "explanation": "**Takrolimus (FK506)**, *Streptomyces tsukubaensis*'ten elde edilen makrolid yapılı bir immünsüpresiftir; hücre içinde FKBP-12'ye bağlanarak **kalsinörini inhibe eder** ve IL-2 sentezini baskılar."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 9, "question": "Aktif romatoid artrit tedavisinde kullanılabilen, dihidrooratat dehidrojenaz enzim\ninhibitörü olan prodrug aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Leflunomid"}, {"letter": "B", "text": "Siklofosfamid"}, {"letter": "C", "text": "Siklosporin"}, {"letter": "D", "text": "Sirolimus"}, {"letter": "E", "text": "Mikofenolat mofetil"}], "answer": "A", "note": null, "id": "2021-2022_Q9", "explanation": "**Leflunomid**, aktif metaboliti teriflunomid aracılığıyla pirimidin sentezinde görevli **dihidrooratat dehidrojenaz** enzimini inhibe eden ve aktif romatoid artrit tedavisinde kullanılan bir ön ilaçtır (prodrug)."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 10, "question": "Suicide amacıyla yüksek miktarda demir alınımında aşağıdaki maddelerden hangisi\nkullanılabilir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Desferoksamin"}, {"letter": "B", "text": "Ferroz süksinat"}, {"letter": "C", "text": "Ferrik amonyum sitrat"}, {"letter": "D", "text": "Demir glukonat"}, {"letter": "E", "text": "Demir askorbat"}], "answer": "A", "note": null, "id": "2021-2022_Q10", "explanation": "Akut yüksek doz demir zehirlenmesinde (intihar veya çocuklarda kazara alım) ve kronik transfüzyonel hemosideroziste kullanılan spesifik parenteral demir şelatörü **Desferoksamin (Deferoksamin)**'dir."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 11, "question": "Aşağıda verilen ilaçlardan hangisinin emezis yapma oranı diğerlerinden daha\ndüşüktür?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Vinkristin"}, {"letter": "B", "text": "Sisplatin"}, {"letter": "C", "text": "Dokrubisin"}, {"letter": "D", "text": "Dozataksel"}, {"letter": "E", "text": "Siklofosfamid"}], "answer": "A", "note": null, "id": "2021-2022_Q11", "explanation": "Sisplatin en yüksek emetojenik potansiyele sahip antineoplastiktir; doksorubisin ve siklofosfamid de orta-yüksek derecede bulantı-kusma yapar. **Vinkristin** ise minimal (<%10) emetojenik etkiye sahiptir (başlıca yan etkisi periferik nöropatidir)."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 12, "question": "Miktortübülleri inhibe eden ve mitoz zehiri olarak da bilinen antineoplastik ilaç\naşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Vinblastin"}, {"letter": "B", "text": "5-Merkaptopürin"}, {"letter": "C", "text": "5-Azasitidin"}, {"letter": "D", "text": "Sisplatin"}, {"letter": "E", "text": "Sitarabin"}], "answer": "A", "note": null, "id": "2021-2022_Q12", "explanation": "**Vinblastin** (vinkristin ve vinorelbin gibi vinka alkaloidleri), tübülin proteinine bağlanarak mikrotübül polimerizasyonunu önler ve mitozu metafazda durduran bir **mitoz zehiridir**."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 13, "question": "Vasküler endoteliyal büyüme faktorünü ve tümör dokusunda anjigenezi inhibe eden\nilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Bevasizumab"}, {"letter": "B", "text": "Panitumumab"}, {"letter": "C", "text": "Rituksimab"}, {"letter": "D", "text": "Setuksimab"}, {"letter": "E", "text": "Trastuzumab"}], "answer": "A", "note": null, "id": "2021-2022_Q13", "explanation": "**Bevasizumab**, Vasküler Endotelyal Büyüme Faktörü (**VEGF-A**)'ne bağlanarak tümör anjiyogenezini inhibe eden rekombinant monoklonal antikordur. (Setuksimab ve Panitumumab EGFR'yi, Trastuzumab HER2'yi, Rituksimab CD20'yi hedefler)."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 14, "question": "COX-1 enzimi üzerinde inhibitör etkinliği COX-2'ye göre daha fazla olan ilaç\nhangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Selekoksib"}, {"letter": "B", "text": "Etodolak"}, {"letter": "C", "text": "Meloksikam"}, {"letter": "D", "text": "Ketoprofen"}, {"letter": "E", "text": "Rofekoksib"}], "answer": "D", "note": null, "id": "2021-2022_Q14", "explanation": "**Ketoprofen** non-selektif bir NSAİİ olup COX-1 üzerindeki inhibitör etkinliği COX-2'ye göre daha fazladır. Selekoksib, rofekoksib, meloksikam ve etodolak ise COX-2 seçiciliği yüksek ilaçlardır."}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 15, "question": "Ductus arteriozusun açık tutulması için kullanılan prostaglandin analoğu ilaç\nhangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Doksaprost"}, {"letter": "B", "text": "Alprostadil"}, {"letter": "C", "text": "Mizoprostol"}, {"letter": "D", "text": "Epoprostenol"}, {"letter": "E", "text": "İlioprost"}], "answer": "B", "note": null, "id": "2021-2022_Q15", "explanation": "Duktus arteriozusun açık tutulması gereken siyanotik konjenital kalp hastalıklarında kullanılan PGE1 analoğu **Alprostadil**'dir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 12, "id": "2020-2021_Q12"}]}, {"year": "2021-2022", "subject": "Farmakoloji", "q_num": 16, "question": "KT tedavisi alan kişide güçlü antiemetik etki için ilaç hangi reseptörü etkilemelidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "5-HT 3 antagonisti"}, {"letter": "B", "text": "5-HT 2A antagonsiti"}, {"letter": "C", "text": "5-HT 1B/D reseptör agonisti"}, {"letter": "D", "text": "Dopamin reseptör agonisti"}, {"letter": "E", "text": "TXA2 reseptör blokörü"}], "answer": "A", "note": null, "id": "2021-2022_Q16", "explanation": "Kemoterapiye bağlı akut ve şiddetli bulantı-kusmanın (emezis) önlenmesinde en güçlü antiemetik ilaçlar **5-HT3 (serotonin) reseptör antagonistleri**dir (ondansetron, granisetron, palonosetron)."}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 17, "question": "Tarama testleri konusunda verilen önermelerin hangisi doğrudur ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Tarama testinin duyarlılığı, gerçekten hasta olanları saptayabilme oranıdır."}, {"letter": "B", "text": "Taramadan hemen önce, toplumun sağlık davranışları taramanın yararı doğrultusunda değiştirilmelidir."}, {"letter": "C", "text": "Fenilketonüri taraması için 1. Basamak’ta özel programlar düzenlenmelidir."}, {"letter": "D", "text": "Tarama testinin özgüllüğü, hasta olma olasılığı olanları bulma gücüdür."}, {"letter": "E", "text": "Tarama testleri, 1. Basamak sağlık kurumlarında, hekim tarafından uygulanmalıdır."}], "answer": "A", "note": null, "id": "2021-2022_Q17", "explanation": "Bir tarama testinin **duyarlılığı (sensitivitesi)**, toplumda **gerçekten hasta olanların ne kadarını doğru saptayabildiğini** (Gerçek Pozitif / Toplam Hasta) gösterir; özgüllük (spesifisite) ise sağlam olanları doğru saptama gücüdür.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 40, "id": "K2_2020-2021_Q40"}, {"kurul": "7", "year": "2019-2020", "q_num": 138, "id": "K7_2019-2020_Q138"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 18, "question": "Toplum taramaları konusundaki önermelerden hangisi doğru değildir ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Taramalar; tüm toplumu içine alabileceği gibi, riskli gruplara yönelik de olabilir."}, {"letter": "B", "text": "Taraması yapılacak sorun, toplumda sık karşılaşılan bir sorun olmalıdır."}, {"letter": "C", "text": "Taramanın maliyeti, tedaviden düşük olmalıdır."}, {"letter": "D", "text": "Taramalar, sürekliliği sağlanabilecek yöntemler olmalıdır."}, {"letter": "E", "text": "Tarama yöntemleri, sağlık personeli tarafından kabul edilebilir olmalıdır."}], "answer": "E", "note": null, "id": "2021-2022_Q18", "explanation": "Wilson-Jungner toplum tarama kriterlerine göre tarama yönteminin sağlık personeli tarafından değil, **halk (hedef toplum) tarafından kabul edilebilir** ve uygulanabilir olması gerekir.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 39, "id": "K2_2020-2021_Q39"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 19, "question": "Aşağıdakilerden hangisi kitle taramalarında katılımı etkileyen faktörlerden\ndeğildir ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Kişinin bu hastalığın tedavisini bilmesi."}, {"letter": "B", "text": "Taramanın uygun yer ve zamanda yapılması."}, {"letter": "C", "text": "Sonuç olarak kişide hastalık çıkarsa tedavi konusunda güvence verilmesi."}, {"letter": "D", "text": "Taranacak hastalığın özelliklerinin kişi tarafından bilinmesi."}, {"letter": "E", "text": "Kişinin bu hastalığın kendisinde yaratacağı sorunları bilmesi"}], "answer": "A", "note": null, "id": "2021-2022_Q19", "explanation": "Kitle taramalarına halkın katılımını etkileyen faktörler arasında hastalığın kişi tarafından önemli görülmesi, uygun yer/zaman ve tanı konduğunda tedavi güvencesi bulunması yer alır; **kişinin hastalığın tıbbi tedavisinin detaylarını bilmesi** katılım şartı değildir.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 53, "id": "K2_2020-2021_Q53"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 20, "question": "Beklenen yaşam süresine ilişkin olarak verilen ifadelerin hangisi doğru değildir ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Kadın ve erkekler için ayrı ayrı hesaplanır."}, {"letter": "B", "text": "Doğumda beklenen yaşam süresi, var olan koşullarda yeni doğan bebeğin yaşaması beklenen ortalama yıl sayısıdır."}, {"letter": "C", "text": "Gelişmekte olan ülkelerde, gelişmiş ülkelerden çok daha düşüktür."}, {"letter": "D", "text": "Aynı mortalite trendleri devam ettiği taktirde, bir kişinin yaşaması beklenen ortalama yıl sayısıdır."}, {"letter": "E", "text": "Kadın ve erkekler için doğuşta (E0) ve 50 yaşta (E50) beklenen yaşam süresi olmak üzere ayrı ayrı hesaplanır."}], "answer": "E", "note": null, "id": "2021-2022_Q20", "explanation": "Beklenen yaşam süresi yaşam tabloları ile doğuşta (e0) ve istenilen her yaş (1 yaş, 5 yaş, 65 yaş vb.) için ayrı ayrı hesaplanabilir; **sadece doğuşta ve 50 yaşta hesaplandığı** ifadesi yanlıştır.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 49, "id": "K2_2020-2021_Q49"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 21, "question": "Türk Kanser Araştırma ve Savaş Kurumu’nun verilerine göre, ülkemizde kanser\ninsidansı aşağıdaki seçeneklerden hangisinde doğru olarak verilmiştir?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Onbinde 120-240"}, {"letter": "B", "text": "Yüzbinde 200"}, {"letter": "C", "text": "Onbinde 150-300"}, {"letter": "D", "text": "Yüzbinde 120-240"}, {"letter": "E", "text": "Yüzbinde 150-300"}], "answer": "B", "note": null, "id": "2021-2022_Q21", "explanation": "Türk Kanser Araştırma ve Savaş Kurumu ders verilerine göre ülkemizde genel kanser insidansı yaklaşık **yüzbinde 200** düzeyindedir.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 44, "id": "K2_2020-2021_Q44"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 22, "question": "Yaşlıda kanser gelişiminin artışı için aşağıda sayılan nedenlerden hangisi yanlıştır ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Yaşlanma ile DNA’da hasar birikimi meydana gelir."}, {"letter": "B", "text": "Yaşlıda DNA tamir mekanizması yetersiz kalmaktadır."}, {"letter": "C", "text": "Yaşlıda onkogen aktivasyonu daha zayıftır."}, {"letter": "D", "text": "Yaşlıda endokrin sistemdeki değişiklikler kanser riskini artırır."}, {"letter": "E", "text": "Yaşlıda immün sistemde zayıflama vardır."}], "answer": "C", "note": null, "id": "2021-2022_Q22", "explanation": "Yaşlanma ile birlikte DNA hasar birikimi artar, DNA onarım mekanizmaları ve immün gözetim zayıflar ve **onkogen aktivasyonu artar**; 'yaşlıda onkogen aktivasyonu daha zayıftır' ifadesi yanlıştır."}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 23, "question": "Umumi Hıfzıssıhha Yasası konusunda hangisi yanlıştır?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Bildirimi zorunlu hastalıklar yer alır."}, {"letter": "B", "text": "Depremlerde alınacak önlemler yazılıdır."}, {"letter": "C", "text": "Konut hijyeni kuralları yazılıdır."}, {"letter": "D", "text": "Gayri Sıhhi Müesseseler ile ilgili kurallar bulunur."}, {"letter": "E", "text": "Ulaşım araçları ile ilgili düzenlemeler vardır."}], "answer": "B", "note": null, "id": "2021-2022_Q23", "explanation": "1930 tarihli 1593 sayılı **Umumi Hıfzıssıhha Kanunu**'nda bildirimi zorunlu bulaşıcı hastalıklar, çevre/konut hijyeni, gayrisıhhi müesseseler ve ulaşım araçları yer alır; ancak **depremlerde alınacak önlemler** bu kanunda yer almaz.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 45, "id": "K2_2020-2021_Q45"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 24, "question": "Sağlık Bakanlığı ile ilgili yönetmelikler içinde hangisi yer almaz?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Oyuncaklar hakkında Yönetmelik"}, {"letter": "B", "text": "Ulaşım Hizmetleri Yönetmeliği"}, {"letter": "C", "text": "Tıbbi Cihaz Yönetmeliği"}, {"letter": "D", "text": "Güzellik ve Estetik Amaçlı Sağlık Kuruşları Hakkında Yönetmelik"}, {"letter": "E", "text": "Turizm Yatırım, İşletme ve Kuruluşlarının Denetimi Hakkında Yönetmelik"}], "answer": "B", "note": null, "id": "2021-2022_Q24", "explanation": "**Ulaşım Hizmetleri Yönetmeliği** Sağlık Bakanlığı'nın değil, Ulaştırma ve Altyapı Bakanlığı / belediyelerin görev alanındadır.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 46, "id": "K2_2020-2021_Q46"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 25, "question": "Aşağıdaki uygulamalardan hangisi Primer (Birincil) korunma önlemlerindendir ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Yenidoğan bebeklerde Fenil ketonüri taraması yapmak"}, {"letter": "B", "text": "Yenidoğan tetanozunu önlemek amacıyla tüm gebelerin tetanoza karşı bağışıklanması"}, {"letter": "C", "text": "Hastalık etkeninin ortadan kaldırılmasıyla hastalığın eradikasyonu"}, {"letter": "D", "text": "40 yaş üzeri kadınlarda meme kanseri taraması yapmak"}, {"letter": "E", "text": "Tütün kullanımına bağlı sağlık sorunlarının ortadan kaldırılması için tütün ekiminin ve ithalatının yasaklanması"}], "answer": "B", "note": null, "id": "2021-2022_Q25", "explanation": "**Birincil (Primer) korunma**, hastalık henüz ortaya çıkmadan sağlığı koruma ve bağışıklama (aşılama) uygulamalarıdır; **gebelerin tetanoza karşı aşılanması** primer korumadır. Taramalar (PKU, mamografi) sekonder koruma; etkenin/tütünün tamamen yasaklanması ise primordial (temel) korumadır.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 42, "id": "K2_2020-2021_Q42"}]}, {"year": "2021-2022", "subject": "Halk Sağlığı", "q_num": 26, "question": "“Sağlığı en kötü durumda olanlar, sağlık hizmetlerinden en az yaralanırlar” cümlesi\nile ilgili olarak aşağıdaki belirlemelerin hangisi doğru değildir ?", "professor": "Ufuk Berberoğlu", "options": [{"letter": "A", "text": "Sağlık hizmetlerinden yararlanma, sağlık durumu ile yakından ilişkilidir."}, {"letter": "B", "text": "Sağlığın bozulması, sağlığı bozulanlar aleyhine eşitsizliği artırabilir."}, {"letter": "C", "text": "Sağlık hizmetlerinden az yararlananlara erişmek için özel programlar yürütülmelidir."}, {"letter": "D", "text": "Sağlık hizmetlerini örgütleyenler hizmetlerden yararlanımı temel almalıdır."}, {"letter": "E", "text": "Sağlık hizmetlerinden yararlanımın tek itici gücü kaybedilen sağlık değildir."}], "answer": "D", "note": null, "id": "2021-2022_Q26", "explanation": "'Ters Hizmet Yasası'na göre sağlığı en kötü olanlar hizmetten en az yararlanır; bu nedenle sağlık hizmetlerini örgütleyenler mevcut yararlanımı (talebi) değil, toplumun **gerçek sağlık gereksinimini (ihtiyacını)** temel almalıdır.", "repeats": [{"kurul": "2", "year": "2020-2021", "q_num": 41, "id": "K2_2020-2021_Q41"}]}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 27, "question": "Allogeneik kemik iliği naklinin en çok yapıldığı hastalık hangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Aplastik anemi"}, {"letter": "B", "text": "Kronik miyeloid lösemi"}, {"letter": "C", "text": "Multipl myeloma"}, {"letter": "D", "text": "Akut miyeloblastik lösemi"}, {"letter": "E", "text": "Ewing sarkom"}], "answer": "D", "note": null, "id": "2021-2022_Q27", "explanation": "Erişkinlerde **allojenik hematopoetik kök hücre (kemik iliği) naklinin** dünyada ve ülkemizde en sık uygulandığı endikasyon **Akut Miyeloblastik Lösemi (AML)**'dir (otolog nakil ise en sık Multipl Myelomda yapılır)."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 28, "question": "Richter transformasyonunu tanımlayan seçenek hangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Esansiyel trombositozun miyelofibrozise dönüşmesi"}, {"letter": "B", "text": "Kronik miyeloid löseminin akut miyeloid lösemiye dönüşmesi"}, {"letter": "C", "text": "Miyelodisplastik sendromun akut miyeloid lösemiye dönüşmesi"}, {"letter": "D", "text": "Kronik lenfositik löseminin büyük B hücreli lenfomaya dönüşmesi"}, {"letter": "E", "text": "Mikozis fungoides hastalığının Sezary sendromuna dönüşmesi"}], "answer": "D", "note": null, "id": "2021-2022_Q28", "explanation": "**Richter transformasyonu (sendromu)**, yavaş seyirli **Kronik Lenfositik Lösemi (KLL)** hastalarının yaklaşık %5-10'unda hastalığın agresif seyirli **Diffüz Büyük B Hücreli Lenfomaya (DBBHL)** dönüşmesidir."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 29, "question": "Boyunda bilateral 2x3 cm ve 2x1 cm multipl palpabl lenfadenomegali, aksiller\nbilateral 2x2 cm ve inguinal alanda bilateral 3x2 cm lenfadenomegali ile başvuran 75 yaşında\nerkek hastada B semptomları da mevcut. Hemogramda lökosit: 23 000/mm3, nötrofil:\n3000/mm3, lenfosit: 20000/mm3, hb: 14 gr/dL, Trombosit: 234 000/mm3 saptanıyor. Periferik\nyaymada olgun görünümlü lenfositlerle %90 artmış bulunuyor. Olası tanınız nedir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Kronik myeloid lösemi"}, {"letter": "B", "text": "Hairy cell lösemi"}, {"letter": "C", "text": "Kronik lenfositik lösemi"}, {"letter": "D", "text": "Aplastik anemi"}, {"letter": "E", "text": "Polisitemia Vera"}], "answer": "C", "note": null, "id": "2021-2022_Q29", "explanation": "İleri yaş (75 yaş) erkek hastada yaygın simetrik lenfadenopati, belirgin mutlak lenfositoz (20.000/mm³) ve periferik yaymada %90 oranında küçük, olgun görünümlü lenfositlerin (ve Gumprecht gölge hücrelerinin) görülmesi **Kronik Lenfositik Lösemi (KLL)** için tipiktir."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 30, "question": "55 yaşında halsizlik, çabuk yorulma yakınması ile başvuran erkek hastada fizik\nmuayenede solukluk dışında patolojik bulgu saptanmamış. Laboratuvar incelemesinde Hb: 10\ngr/dL, MCV:65 fL; anemi dışında diğer tetkikleri ve PA akciğer grafisi normal bulunmuş.\nKronik hastalık ve ilaç kullanım öyküsü olmayan hastada tanı için öncelikle hangi inceleme\nönerilmelidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Flowsitometri"}, {"letter": "B", "text": "Tümör markerlerinin çalışılması"}, {"letter": "C", "text": "Ferritin, serum demir, demir bağlama kapasitesi ve endoskopi"}, {"letter": "D", "text": "Kemik iliği biyopsisi"}, {"letter": "E", "text": "Toraks tomografi ile görüntüleme"}], "answer": "C", "note": null, "id": "2021-2022_Q30", "explanation": "55 yaşındaki erkek veya postmenopozal kadın hastada hipokrom mikrositer anemi (Hb: 10, MCV: 65 fL) saptandığında ilk düşünülmesi gereken **Demir Eksikliği Anemisi** ve altta yatan **GİS gizli kanaması/malignitesi**dir; bu nedenle **ferritin, demir parametreleri ve GİS endoskopisi** yapılmalıdır."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 31, "question": "Aşağıdakilerden hangisi herediter bir aplastik anemi nedeni değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Fanconi anemisi"}, {"letter": "B", "text": "Diskeratozis konjenita"}, {"letter": "C", "text": "Shwachman-Diamond sendromu"}, {"letter": "D", "text": "Herediter sferositoz"}, {"letter": "E", "text": "Konjenital amegakaryositik trombositopeni"}], "answer": "D", "note": null, "id": "2021-2022_Q31", "explanation": "Fanconi anemisi, Diskeratozis konjenita, Shwachman-Diamond sendromu ve Konjenital amegakaryositik trombositopeni kalıtsal kemik iliği yetmezliği (aplastik anemi) nedenleridir. **Herediter sferositoz** ise eritrosit membran defektine bağlı kalıtsal **hemolitik anemi**dir."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 32, "question": "Aşağıdakilerden hangisi doğru değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Vucudumuzda 600 kadar lenf bezi vardır."}, {"letter": "B", "text": "Lenf bezlerinin büyümesine lenfadenomegali denir."}, {"letter": "C", "text": "En sık lenfadenomegali saptanan bölge baş-boyun bölgesidir."}, {"letter": "D", "text": "Mediasten ve batındaki lenf nodları palpe edilemez."}, {"letter": "E", "text": "Servikalde saptanan 2 cm den büyük lenf nodları anormal değildir."}], "answer": "E", "note": null, "id": "2021-2022_Q32", "explanation": "Erişkinde lenf nodlarının normal üst sınırı genel olarak 1 cm (inguinalde 1.5 cm, epitroklearda 0.5 cm)'dir; **servikalde 2 cm'den büyük lenf nodları patolojiktir** ('anormal değildir' ifadesi yanlıştır)."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 33, "question": "Kronik myeloproliferatif hastalık grubundan olmayan seçenek aşağıdakilerden\nhangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Kronik myeloid lösemi"}, {"letter": "B", "text": "Polisitemia vera"}, {"letter": "C", "text": "Esansiyel trombositoz"}, {"letter": "D", "text": "Kronik lenfositik lösemi"}, {"letter": "E", "text": "Primer myelofibrozis"}], "answer": "D", "note": null, "id": "2021-2022_Q33", "explanation": "**Kronik Lenfositik Lösemi (KLL)** miyeloproliferatif değil, **lenfoproliferatif** bir hastalıktır. KML, Polisitemia Vera, Esansiyel Trombositoz ve Primer Miyelofibrozis klasik kronik miyeloproliferatif hastalıkları oluşturur."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 34, "question": "Aşağıdakilerden hangisi Lökomoid reaksiyon için yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Philadelphia kromozomu pozitifliği"}, {"letter": "B", "text": "Lökosit sayısının >50.000/mm³ olması"}, {"letter": "C", "text": "Kanda olgun nötrofillerin belirgin artışı"}, {"letter": "D", "text": "Lökosit alkalen fosfataz (LAP) skorunda artış"}, {"letter": "E", "text": "Lenfositik lökomoid reaksiyonlar genellikle çocuklarda görülür"}], "answer": "A", "note": null, "id": "2021-2022_Q34", "explanation": "**Lökomoid reaksiyon** ağır enfeksiyon/inflamasyona ikincil gelişen reaktif lökositozdur (>50.000/mm³); LAP skoru yüksektir ve **Philadelphia kromozomu (BCR-ABL) negatiftir** (Ph pozitifliği KML'de görülür)."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "Aşağıdakilerden hangisi mikrositik anemi nedenlerinden biri değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Demir eksikliği"}, {"letter": "B", "text": "Sideroblastik anemi"}, {"letter": "C", "text": "Kronik hastalık anemisi"}, {"letter": "D", "text": "Hipotiroidizm"}, {"letter": "E", "text": "Talasemiler"}], "answer": "D", "note": null, "id": "2021-2022_Q35", "explanation": "**Hipotiroidizm** mikrositik değil, normositer veya **makrositer anemi** nedenidir. Demir eksikliği, talasemi, kronik hastalık ve sideroblastik anemi mikrositer anemi yapar."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "I- Peteşi, purpura, ekimoz\nII- Solukluk\nIII-Dalak boyutunda artış\nIV-Büyümüş lenf nodları\nV- Halsizlik\nYukarıdakilerden hangisi/hangileri aplastik aneminin klinik bulgularından biri değildir ?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "I ve II"}, {"letter": "B", "text": "I, II ve V"}, {"letter": "C", "text": "III ve IV"}, {"letter": "D", "text": "I ve V"}, {"letter": "E", "text": "II ve V"}], "answer": "C", "note": null, "id": "2021-2022_Q36", "explanation": "Aplastik anemide pansitopeniye bağlı halsizlik, solukluk, peteşi/purpura/ekimoz görülür; ancak **splenomegali (dalak büyümesi) ve lenfadenopati (III ve IV) görülmez**."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Dünya Sağlık Örgütü verilerine göre erkeklerde ve kadınlarda en sık ölüme neden\nolan kanserler sırasıyla aşağıdakilerden hangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Akciğer kanseri-Kolorektal karsinom"}, {"letter": "B", "text": "Prostat kanseri-Meme kanseri"}, {"letter": "C", "text": "Akciğer kanseri-Meme kanseri"}, {"letter": "D", "text": "Akciğer kanseri-Akciğer kanseri"}, {"letter": "E", "text": "Prostat kanseri-Akciğer kanseri"}], "answer": "D", "note": null, "id": "2021-2022_Q37", "explanation": "DSÖ verilerine göre dünya genelinde hem erkeklerde hem de kadınlarda kansere bağlı ölümlerin (mortalitenin) birinci sırasındaki neden **Akciğer kanseridir**."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "Türkiye Halk Sağlığı Kurumu verilerine göre ülkemizde erkeklerde ve kadınlarda\nen sık görülen kanserler sırasıyla aşağıdakilerden hangisidir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Akciğer kanseri-Kolorektal karsinom"}, {"letter": "B", "text": "Prostat kanseri-Meme kanseri"}, {"letter": "C", "text": "Akciğer kanseri-Meme kanseri"}, {"letter": "D", "text": "Akciğer kanseri-Akciğer kanseri"}, {"letter": "E", "text": "Prostat kanseri-Akciğer kanseri"}], "answer": "C", "note": null, "id": "2021-2022_Q38", "explanation": "Türkiye Halk Sağlığı verilerine göre ülkemizde en sık görülen (insidansı en yüksek) kanserler **erkeklerde Akciğer kanseri, kadınlarda ise Meme kanseridir**."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Akciğer grafisinde metastazı düşündüren çok sayıda bilateral nodüler lezyonlar\ngörülen 24 yaşında bir kadın hastada patolojik değerlendirmede epitelyal tümör metastazı\nsaptanmıştır.Primer tümörü araştırmak için aşağıdakilerden hangisinin yapılması önerilmez?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Ca 15-3 düzeyi tayini"}, {"letter": "B", "text": "Meme muayenesi"}, {"letter": "C", "text": "Jinekolojik muayene"}, {"letter": "D", "text": "Ayrıntılı anamnez"}, {"letter": "E", "text": "B-hCG düzeyi tayini"}], "answer": "A", "note": null, "id": "2021-2022_Q39", "explanation": "Tümör belirteçleri (**CA 15-3** vb.) duyarlılık ve özgüllükleri düşük olduğu için **primeri bilinmeyen metastatik tümörlerde primer odağı bulmak amacıyla tarama testi olarak önerilmez** (CA 15-3 sadece tanı almış meme kanserinde tedavi yanıtı ve nüks takibinde kullanılır)."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 40, "question": "Aşağıdakilerden hangisi tarama programı önerilen kanserlerden biri değildir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Meme Kanseri"}, {"letter": "B", "text": "Serviks Kanseri"}, {"letter": "C", "text": "Kolorektal Kanser"}, {"letter": "D", "text": "Malign Melanom"}, {"letter": "E", "text": "Pankreas Kanseri"}], "answer": "E", "note": null, "id": "2021-2022_Q40", "explanation": "**Pankreas kanseri** için genel popülasyona yönelik etkinliği kanıtlanmış standart bir toplum tarama programı yoktur. Meme, serviks ve kolorektal kanserler ulusal tarama programında yer alır."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 41, "question": "Aşağıdakilerden hangisinde bir kanser türü, viral etkeni ile birlikte verilmemiştir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Serviks Kanseri- Herpes Simpleks Virüs Tip 2"}, {"letter": "B", "text": "Erişkin T Hücreli Lösemi- İnsan T-Lenfotropik Virüs Tip 1"}, {"letter": "C", "text": "Hepatoselüler Kanser- Hepatit C Virüsü"}, {"letter": "D", "text": "Kaposi Sarkomu- İnsan Herpes Virüs Tip"}, {"letter": "E", "text": "Endemik Burkitt Lenfoma- Epstein-Barr Virüsü"}], "answer": "A", "note": null, "id": "2021-2022_Q41", "explanation": "**Serviks kanserinin** viral etkeni HSV Tip 2 değil, **Human Papillomavirus (HPV - özellikle Tip 16 ve 18)**'dir. HTLV-1 erişkin T hücreli lösemi, HCV hepatoselüler karsinom, HHV-8 Kaposi sarkomu ve EBV endemik Burkitt lenfoma etkenidir."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 42, "question": "Multiple Miyelom tanısı alan bir hastada kemoterapi ile beraber zoledronik asit\ntedavisi başlanmıştır. Aşağıdakilerden hangisi hastanın takibinde zolendronik asit\nkullanımının neden olabileceği yan etkilerden biridir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Anemi"}, {"letter": "B", "text": "Çene osteonekrozu"}, {"letter": "C", "text": "Kulak çınlaması"}, {"letter": "D", "text": "Hipotermi"}, {"letter": "E", "text": "Ciltte kızarıklık"}], "answer": "B", "note": null, "id": "2021-2022_Q42", "explanation": "Multipl miyelom ve kemik metastazlarında kullanılan intravenöz bifosfonatların (özellikle **zoledronik asit** ve pamidronat) en önemli ve spesifik yan etkilerinden biri **çene osteonekrozudur (ONJ)**."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 43, "question": "Aşağıdaki hematolojik hastalıklardan hangisi tanı anında diş eti hipertrofisine\nneden olabilir?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Otoimmun hemolitik anemi"}, {"letter": "B", "text": "Akut myeloid lösemi"}, {"letter": "C", "text": "Kronik lenfositik lösemi"}, {"letter": "D", "text": "Aplastik anemi"}, {"letter": "E", "text": "Myelodisplastik sendrom"}], "answer": "B", "note": null, "id": "2021-2022_Q43", "explanation": "**Akut Miyeloid Lösemi (AML - özellikle monositik alt tipler olan AML-M4 ve AML-M5)** tanı anında lösemik blastların diş etini infiltre etmesiyle **diş eti (gingiva) hipertrofisine** neden olur."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 44, "question": "Demir eksikliği anemisi olan bir hastanın fizik muayenesinde aşağıdaki bulgulardan\nhangisinin gözükmesi beklenmez?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Konjuktivalarda solukluk"}, {"letter": "B", "text": "Kaşık tırnak"}, {"letter": "C", "text": "Tinnitus"}, {"letter": "D", "text": "Ağız kenarında çatlaklar"}, {"letter": "E", "text": "Atrofik glossit"}], "answer": "C", "note": null, "id": "2021-2022_Q44", "explanation": "**Tinnitus (kulak çınlaması)** hastanın ifade ettiği subjektif bir **semptomdur**, hekimin fizik muayenede saptadığı objektif bir bulgu değildir. Solukluk, kaşık tırnak (koilonişi), angüler stomatit ve atrofik glossit ise fizik muayene bulgularıdır."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 45, "question": "Demir eksikliği anemisinden şüphelenilen bir hastanın periferik yaymasında\naşağıdaki hücrelerden hangisinin görülmesi beklenmez?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Kalem hücreleri"}, {"letter": "B", "text": "Hipokromik eritrositler"}, {"letter": "C", "text": "Target hücreleri"}, {"letter": "D", "text": "Megaloblastlar"}, {"letter": "E", "text": "Mikrositik eritrositler"}], "answer": "D", "note": null, "id": "2021-2022_Q45", "explanation": "**Megaloblastlar** B12 ve folat eksikliğinde (megaloblastik anemide) kemik iliğinde görülen dev eritroid öncüllerdir; demir eksikliği anemisinin periferik yaymasında görülmezler (hipokromi, mikrositoz, kalem hücreleri ve target hücreleri görülebilir)."}, {"year": "2021-2022", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 46, "question": "Periferik kan yaymasında görülen hücrelerle alakalı hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Retikülositler polikromazik olarak görülürler."}, {"letter": "B", "text": "Eritrositler ortalama 7 mikron büyüklüğündedir."}, {"letter": "C", "text": "Trombositler periferik kanın en küçük hücreleridir."}, {"letter": "D", "text": "Nötrofillerin granülleri yoktur."}, {"letter": "E", "text": "Monositlerin at nalına benzeyen lobları vardır"}], "answer": "D", "note": null, "id": "2021-2022_Q46", "explanation": "**Nötrofiller**, polimorfonükleer **granülositler** grubundadır ve sitoplazmalarında bol miktarda spesifik (sekonder) ve azurofilik (primer) **granüller bulunur**. 'Nötrofillerin granülleri yoktur' ifadesi yanlıştır."}, {"year": "2021-2022", "subject": "Tıbbi Genetik", "q_num": 47, "question": "β-talaseminin prenatal dönemde gözlemlenmemesinin sebebi aşağıdakilerden\nhangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Prenatal dönemde tek başına α-globin ifadesinin yeterli olması"}, {"letter": "B", "text": "Prenatal dönemde β-globin ifadesi yerine β-benzeri globinlerin ifadesinin etkin olması"}, {"letter": "C", "text": "β-globin gen mutasyonlarının postnatal dönemde oluşması"}, {"letter": "D", "text": "Postnatal dönemde α-globin gen ifadesinin koruyucu etkisinin ortadan kalkması"}, {"letter": "E", "text": "Postnatal dönemde Hb A etkin olurken prenatal dönemde Hb A2'nin etkin olması"}], "answer": "B", "note": null, "id": "2021-2022_Q47", "prof_inferred": true, "explanation": "Prenatal (fetal) dönemde ana hemoglobin HbF (α2γ2) olduğu, yani beta-globin yerine **beta-benzeri gama (γ) globin genlerinin etkin olarak ifade edildiği** için beta-talasemi prenatal dönemde klinik bulgu vermez."}, {"year": "2021-2022", "subject": "Tıbbi Genetik", "q_num": 48, "question": "Aşağıdaki gen mutasyonlarından hangisi trombofili ile ilişkilendirilmemektedir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Faktör V G1691A (Leiden) mutasyonu"}, {"letter": "B", "text": "Faktör II G20210A (Protrombin) mutasyonu"}, {"letter": "C", "text": "MTHFR C677T mutasyonu"}, {"letter": "D", "text": "MTHFR A1298C mutasyonu"}, {"letter": "E", "text": "Faktör VIII G1967A mutasyonu"}], "answer": "E", "note": null, "id": "2021-2022_Q48", "prof_inferred": true, "explanation": "Kalıtsal trombofili panelinde Faktör V Leiden (G1691A), Protrombin (Faktör II G20210A) ve MTHFR (C677T, A1298C) varyantları yer alır; **Faktör VIII G1967A mutasyonu** bilinen bir trombofili mutasyonu değildir (Faktör VIII eksikliği Hemofili A yapar)."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 49, "question": "Otosplenektomi hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Herediter sferositoz"}, {"letter": "C", "text": "Alfa talasemi"}, {"letter": "D", "text": "Beta talasemi"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}], "answer": "A", "note": null, "id": "2021-2022_Q49", "explanation": "Tekrarlayan vazo-oklüzif krizler ve enfarktlara bağlı **otosplenektomi** karakteristik olarak **Orak Hücreli Anemide** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 64, "id": "2019-2020_Q64"}, {"kurul": "1", "year": "2024-2025", "q_num": 74, "id": "2024-2025_Q74"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 50, "question": "Heinz cisimcikleri hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}, {"letter": "B", "text": "Orak hücreli anemi"}, {"letter": "C", "text": "Herediter sferositoz"}, {"letter": "D", "text": "Beta talasemi"}, {"letter": "E", "text": "Paroksismal noktürnal hemoglobülinüri"}], "answer": "A", "note": null, "id": "2021-2022_Q50", "explanation": "Oksidatif stres sonucu denatüre hemoglobinin çökmesiyle oluşan **Heinz cisimcikleri**, **Glukoz-6-Fosfat Dehidrogenaz (G6PD) eksikliğinde** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 65, "id": "2019-2020_Q65"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 51, "question": "Raynaud fenomeni hangi anemi türünde görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Beta talasemi"}, {"letter": "C", "text": "Sıcak antikorlu immünhemolitik anemiler"}, {"letter": "D", "text": "Soğuk antikorlu immünhemolitik anemiler"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği."}], "answer": "D", "note": null, "id": "2021-2022_Q51", "explanation": "Soğuğa maruziyetle uç kapillerlerde eritrosit aglütinasyonu ve **Raynaud fenomeni**, **soğuk antikorlu (IgM) otoimmün hemolitik anemilerde** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 66, "id": "2019-2020_Q66"}, {"kurul": "1", "year": "2024-2025", "q_num": 77, "id": "2024-2025_Q77"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 52, "question": "Aort anevrizması ve disseksiyonu hangi genetik hastalıkta sık görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Ehlers-Danlos sendromu"}, {"letter": "B", "text": "Marfan sendromu"}, {"letter": "C", "text": "Kistik fibrozis"}, {"letter": "D", "text": "Fenilketonüri"}, {"letter": "E", "text": "Tay-Sachs hastalığı"}], "answer": "B", "note": null, "id": "2021-2022_Q52", "explanation": "Fibrillin-1 (FBN1) gen mutasyonuna bağlı elastik lif bozukluğu, **aort anevrizması ve diseksiyonu** en sık **Marfan sendromunda** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 60, "id": "2019-2020_Q60"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 53, "question": "Sitolojik olarak “buruşmuş kağıt görüntüsü” hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tay-Sachs hastalığı"}, {"letter": "B", "text": "Niemann-Pick hastalığı"}, {"letter": "C", "text": "Gaucher hastalığı"}, {"letter": "D", "text": "Hurler sendromu"}], "answer": "C", "note": null, "id": "2021-2022_Q53", "explanation": "Kemik iliği ve dalak makrofajlarında glukoserebrozid birikimine bağlı **'buruşuk kağıt' (crinkled paper)** sitoplazmalı hücreler **Gaucher hastalığında** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 61, "id": "2019-2020_Q61"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 54, "question": "Di George sendromu için hangisi doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "22q11.2 delesyonu vardır"}, {"letter": "B", "text": "Timik hipoplazi vardır"}, {"letter": "C", "text": "Hipokalsemi vardır"}, {"letter": "D", "text": "Yele boyun vardır"}, {"letter": "E", "text": "T hücre immün yetmezliği vardır"}], "answer": "D", "note": null, "id": "2021-2022_Q54", "explanation": "**Yele boyun (webbed neck)** DiGeorge sendromunda değil, **Turner sendromunda (45,X0)** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 62, "id": "2019-2020_Q62"}, {"kurul": "1", "year": "2024-2025", "q_num": 72, "id": "2024-2025_Q72"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 55, "question": "Tümörlerde Warburg etkisini kullanan tanısal yönetm hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "İmmünhistokimyasal yöntemler"}, {"letter": "B", "text": "İmmünfloersan incelemelr"}, {"letter": "C", "text": "Bilgisayarlı tomografi"}, {"letter": "D", "text": "PET-CT"}, {"letter": "E", "text": "Ultrasonografik inceleme"}], "answer": "D", "note": null, "id": "2021-2022_Q55", "explanation": "Tümörlerin yüksek glukoz tüketimine (Warburg etkisi / aerobik glikoliz) dayanan görüntüleme yöntemi **PET-BT (18F-FDG PET)**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 58, "id": "2019-2020_Q58"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 56, "question": "Hangisi homolog rekombinasyon ile DNA onarımı kusurlarının mevcut olduğu\nhastalıklardan değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Herediter nonpolipöz kolon kanseri sendromu"}, {"letter": "B", "text": "Bloom sendromu"}, {"letter": "C", "text": "Fanconi anemisi"}, {"letter": "D", "text": "Ataksi-telanjiektazi"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": null, "id": "2021-2022_Q56", "explanation": "**Herediter Nonpolipozis Kolon Kanseri (Lynch sendromu)** homolog rekombinasyon değil, **DNA yanlış eşleşme onarımı (MMR)** kusuru sonucu gelişir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 59, "id": "2019-2020_Q59"}, {"kurul": "1", "year": "2024-2025", "q_num": 60, "id": "2024-2025_Q60"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 57, "question": "Karsinogenezde aşırı reseptör ekspresyonu hangi kanserde görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Glioblastomada PDGF mevcudiyeti"}, {"letter": "B", "text": "Meme kanserinde HER2/NEU (CerbB2) ekspresyonu"}, {"letter": "C", "text": "Nöroblastomada Nmyc ekspresyonu"}, {"letter": "D", "text": "Kolon kanserinde ras ekspresyonu"}, {"letter": "E", "text": "TGF-betanın pankreas kanserinde ekspresyonu"}], "answer": "B", "note": null, "id": "2021-2022_Q57", "explanation": "Büyüme faktörü reseptörünün aşırı ekspresyonuna en tipik örnek **meme kanserinde HER2/neu (c-erbB2)** amplifikasyonudur.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 47, "id": "2020-2021_Q47"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 58, "question": "Sistemik lupus eritematozus için spesifik otoantikor tipi hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Anti düzkas antikoru"}, {"letter": "B", "text": "ANA (antinükleer antikor)"}, {"letter": "C", "text": "Antimitokondrial antikor"}, {"letter": "D", "text": "Anti Sm (Smith) antikor"}, {"letter": "E", "text": "Antifosfolipid antikor"}], "answer": "D", "note": null, "id": "2021-2022_Q58", "explanation": "SLE için özgüllüğü (spesifisitesi) yüksek olan karakteristik otoantikor **Anti-Sm (Smith)** antikorudur.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 44, "id": "2020-2021_Q44"}, {"kurul": "1", "year": "2024-2025", "q_num": 80, "id": "2024-2025_Q80"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 59, "question": "Arthus reaksiyonu nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Deneysel görülen kütanöz vaskülitdir."}, {"letter": "B", "text": "Hepatit B'de görülen sistemik vaskülitdir"}, {"letter": "C", "text": "SLE'de görülen sistemik vaskülitdir."}, {"letter": "D", "text": "Poststreptokoksik glomerülonefritdir"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": "Orijinal 21-22 PDF'inde 'Şıklar boştu' notu yer almaktadır; şıklar 19-20 ve 24-25 çıkmışlarındaki aynı sorudan tamamlanmıştır.", "id": "2021-2022_Q59", "explanation": "**Arthus reaksiyonu**, lokal antijen enjeksiyonu sonrası antijen-antikor kompleksi (Tip III hipersensitivite) birikimiyle gelişen **deneysel akut kütanöz nekrotizan vaskülittir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 55, "id": "2019-2020_Q55"}, {"kurul": "1", "year": "2024-2025", "q_num": 65, "id": "2024-2025_Q65"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 60, "question": "Mast hücresi hangi tip aşırı duyarlık reaksiyonunda rol oynar?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tip I"}, {"letter": "B", "text": "Tip II"}, {"letter": "C", "text": "Tip III"}, {"letter": "D", "text": "Tip IV"}, {"letter": "E", "text": "Hiçbirisi"}], "answer": "A", "note": null, "id": "2021-2022_Q60", "explanation": "**Mast hücresi**, yüzeyindeki IgE antikorlarıyla alerjeni bağlayarak **Tip I (erken tip / anafilaktik) aşırı duyarlılık reaksiyonunda** temel rol oynar.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 43, "id": "2020-2021_Q43"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 61, "question": "Aşağıdakilerden hangisi hücre çoğalması ve büyümesini inhibe eden, güçlü\nantiinflamatuar etkiye ve potent fibrojenik etkiye sahip skar oluşumunda en önemli\nstimülatör büyüme faktörüdür?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "VEGF"}, {"letter": "B", "text": "EGF"}, {"letter": "C", "text": "b-FGF"}, {"letter": "D", "text": "TGF-β"}, {"letter": "E", "text": "PDGF"}], "answer": "D", "note": null, "id": "2021-2022_Q61", "explanation": "Hücre büyümesini inhibe eden, antiinflamatuar etkili ve **skar/fibrozis oluşumunda en önemli uyarıcı** olan büyüme faktörü **TGF-β**'dır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 70, "id": "2020-2021_Q70"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 62, "question": "Akut inflamasyonda polimorfik nüveli lökositlerin damar dışına çıktıktan sonra\nzedelenme alanına yönlenmesi ne şekilde adlandırılır?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Aktif hiperemi"}, {"letter": "B", "text": "Adhezyon"}, {"letter": "C", "text": "Karyoreksis"}, {"letter": "D", "text": "Kemotaksis"}, {"letter": "E", "text": "Karyolizis"}], "answer": "D", "note": null, "id": "2021-2022_Q62", "explanation": "Lökositlerin damar dışına çıktıktan sonra kimyasal uyaran gradyentine doğru (zedelenme alanına) yönelerek göç etmesine **kemotaksis** denir."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 63, "question": "Aşağıdakilerden hangisi plazma onkotik basınç azalması yoluyla ödeme sebep olan\netkenlerden değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Konjestif kalp yetmezliği"}, {"letter": "B", "text": "Nefrotik sendrom"}, {"letter": "C", "text": "Siroz"}, {"letter": "D", "text": "Malnütrisyon"}, {"letter": "E", "text": "Protein kaybettiren gastroenteropatiler"}], "answer": "A", "note": null, "id": "2021-2022_Q63", "explanation": "**Konjestif kalp yetmezliği** plazma onkotik basıncını azaltarak değil, venöz staza bağlı **kapiller hidrostatik basıncı artırarak** ödeme yol açar. Nefrotik sendrom, siroz, malnütrisyon ve protein kaybettiren enteropatiler hipoalbüminemi (onkotik basınç azalması) ile ödem yapar."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 64, "question": "Trombositopeni, ekzema ve enfeksiyonlarla seyreden, özellikle T hücre immün\nyetmezliğine bağlı oluşan hastalık aşağıdakilerden hangisidir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Bruton Agammaglobülinemisi"}, {"letter": "B", "text": "DiGeorge Sendromu"}, {"letter": "C", "text": "İzole IgA yetmezliği"}, {"letter": "D", "text": "Yaygın değişken immün yetmezlik hastalığı"}, {"letter": "E", "text": "Wiskott-Aldrich Sendromu"}], "answer": "E", "note": null, "id": "2021-2022_Q64", "explanation": "Trombositopeni, egzema ve tekrarlayan enfeksiyonlar triadı ile seyreden X'e bağlı hastalık **Wiskott-Aldrich Sendromu**dur.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 75, "id": "2020-2021_Q75"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 65, "question": "Migratuar (gezici) trombofilebit (Trousseau Fenomeni) en sık hangi malign\ntümörlerle bir arada görülür?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Pankreas adenokarsinomu"}, {"letter": "B", "text": "Kolon karsinomları"}, {"letter": "C", "text": "Mide karsinomları"}, {"letter": "D", "text": "Tiroid karsinomları"}, {"letter": "E", "text": "Beyin tümörleri"}], "answer": "A", "note": null, "id": "2021-2022_Q65", "explanation": "Trousseau fenomeni (gezici tromboflebit) en sık müsinöz adenokarsinomlarla, özellikle **pankreas adenokarsinomu** ile birlikte görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 51, "id": "2019-2020_Q51"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 66, "question": "Aşağıdakilerden hangisi folliküler paternde lenfoid hiperplazi- folliküler lenfoma\nayırımında, lenfoid hiperplazi lehine bir bulgu değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Foliküllerin subkortikal yerleşimli olması"}, {"letter": "B", "text": "Kapsül ötesine genişleme olmaması"}, {"letter": "C", "text": "Folikül sayısının az olması"}, {"letter": "D", "text": "Farklı şekil ve büyüklükte foliküller olması"}, {"letter": "E", "text": "Foliküllerde Bcl-2 antikoru ile boyanma olması (pozitif immünoreaktivite)"}], "answer": "E", "note": null, "id": "2021-2022_Q66", "explanation": "Reaktif folliküler hiperplazide germinal merkezlerde Bcl-2 negatiftir; **foliküllerde Bcl-2 pozitifliği Folliküler Lenfoma lehine** bir bulgudur.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 53, "id": "2019-2020_Q53"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 67, "question": "Aşağıdakilerden hangisi, lenf nodlarında \"nonspesifik reaktif parakortikal\nhiperplazi\" sebeplerinden değildir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Akut enfeksiyöz mononükleoz LAP"}, {"letter": "B", "text": "Sitomegalovirüs LAP"}, {"letter": "C", "text": "İlaç hipersensitivite LAP"}, {"letter": "D", "text": "Toksoplazma LAP"}, {"letter": "E", "text": "Postvaksinal LAP"}], "answer": "D", "note": null, "id": "2021-2022_Q67", "explanation": "**Toksoplazma LAP** parakortikal hiperplazi değil, folliküler hiperplazi + monositoid B hücre ve epiteloid histiyosit artışı yapar.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 79, "id": "2020-2021_Q79"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 68, "question": "Hasta kişinin ikizinden alınan doku transplantasyonuna ne ad verilir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Allograft"}, {"letter": "B", "text": "Ksenograft"}, {"letter": "C", "text": "Otograft"}, {"letter": "D", "text": "İzograft"}, {"letter": "E", "text": "Transgraft"}], "answer": "D", "note": null, "id": "2021-2022_Q68", "explanation": "Tek yumurta ikizinden alınan doku transplantasyonuna **izogreft** denir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 48, "id": "2019-2020_Q48"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 69, "question": "Aşağıdakilerden hangisinde \"Zahn çizgileri\" görülmesi tipiktir?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Kardiyovasküler trombüs"}, {"letter": "B", "text": "Derin venöz trombüs"}, {"letter": "C", "text": "Küçük arteryel trombüs"}, {"letter": "D", "text": "Postmortem trombüs"}, {"letter": "E", "text": "Taze gastrointestinal kanama"}], "answer": "A", "note": null, "id": "2021-2022_Q69", "explanation": "Makroskopik ve mikroskopik **Zahn çizgileri**, kalp boşlukları veya büyük arterlerde gelişen antemortem **kardiyovasküler trombüslerde** görülür.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 73, "id": "2020-2021_Q73"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 70, "question": "Aşağıdakilerden hangisi, p53 geninde mutasyonla karakterize, otozomal dominant\ngeçişli kanser sendromudur?", "professor": "Cengiz Koçak", "options": [{"letter": "A", "text": "Retinoblastom"}, {"letter": "B", "text": "Li-Fraumeni Sendromu"}, {"letter": "C", "text": "Familyal Melanom Sendromu"}, {"letter": "D", "text": "Cowden Sendromu"}, {"letter": "E", "text": "Peutz-Jeghers Sendromu"}, {"letter": "F", "text": "Hunter sendromu"}], "answer": "B", "note": null, "id": "2021-2022_Q70", "explanation": "Germline **TP53** gen mutasyonu sonucu genç yaşta sarkom, meme kanseri, lösemi, beyin tümörü ve adrenokortikal karsinom gelişimiyle karakterize otozomal dominant sendrom **Li-Fraumeni Sendromu**dur."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 71, "question": "İnfarktüs, nekroz ve şok ile ilgili aşağıda verilen bilgilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "İnfarktüs bir dokunun vasküler beslenmesinin kesilmesi ile oluşan iskemik nekroz alanıdır ve pulmoner infarktüs sık görülen bir komplikasyondur."}, {"letter": "B", "text": "İnfarktüsler renklerine göre ve mikrobiyal infeksiyon varlığı veya yokluğuna göre kırmızı /hemorajik veya beyaz /anemik ve septik veya aseptik olarak sınıflandırılır"}, {"letter": "C", "text": "Kırmızı infarktüsler; Akciğer ve ince barsak gibi çift dolaşımlı dokularda oluşur"}, {"letter": "D", "text": "Beyin bu genellemelerin istisnasını oluşturur: Merkezi sinir sisteminde iskemik doku hasarı likefaksiyon nekrozu ile sonuçlanır"}, {"letter": "E", "text": "Şok; kardiyak outputun ve/veya dolaşımdaki etkin kan hacminin azalması sonucu meydana gelen sistemik doku hiperperfüzyonu durumudur"}], "answer": "E", "note": null, "id": "2021-2022_Q71", "explanation": "Şok sistemik doku **hipoperfüzyonu** durumudur; E şıkkında 'hiperperfüzyonu' denildiği için yanlıştır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 70, "id": "2019-2020_Q70"}, {"kurul": "1", "year": "2020-2021", "q_num": 55, "id": "2020-2021_Q55"}, {"kurul": "1", "year": "2022-2023", "q_num": 61, "id": "2022-2023_Q61"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 72, "question": "Tromboemboli ve amiloidoz ile ilgili aşağıdaki belirtilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Trombüs oluşumuna yol açan nedenler; (Virchow triadı) ; Endotel hasarı, Staz veya türbülan kan akımı, Kanın hiperkoagulabilitesidir."}, {"letter": "B", "text": "Arteryel trombüsler, en sık olarak sırasıyla koronerler, serebral arterler ve femoral arterlerde gelişir"}, {"letter": "C", "text": "Venöz tromboz /flebotromboz sıklıkla kalbe doğru bir miktar büyür ve emboliye eğilimli damar lümeninde uzun bir kitle oluşturur, en sık alt ekstremitelerin venleri etkilenir"}, {"letter": "D", "text": "AL amiloidi; B hücre diskrazisi ile birlikte bulunur, Aβ Amiloid; Alzheimer hastalarında serebral plak ve kan damarlarında depolanır"}, {"letter": "E", "text": "İmmunosit diskrazileri ile birlikte olan amiloidozlar; Multipl miyeloma, Monoklonal gammopati, Diğer B hücre neoplazmları ile beraberdir ve Aβ Amiloid depolanması vardır."}], "answer": "E", "note": null, "id": "2021-2022_Q72", "explanation": "Multipl miyelom ve B hücre diskrazilerinde biriken amiloid Aβ değil, **AL amiloididir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 79, "id": "2019-2020_Q79"}, {"kurul": "1", "year": "2020-2021", "q_num": 56, "id": "2020-2021_Q56"}, {"kurul": "1", "year": "2022-2023", "q_num": 62, "id": "2022-2023_Q62"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 73, "question": "İnflamasyon mediyatörleri ile ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Kronik iltihabın mediatörleri; lenfosit, makrofaj, plazma hücresi, eozinofil, mast hücreleridir"}, {"letter": "B", "text": "Kanda monositlerin yarılanma ömrü 1 gündür, doku makrofajları ise aylarca yaşayabilirler."}, {"letter": "C", "text": "Asit ve nötral proteazlar: doku hasarı, kompleman komponentleri ve koagülasyon faktörlerinin lokal miktarı artar, reaktif oksijen ürünleri ve NO doku hasarı yapar"}, {"letter": "D", "text": "IL-1, IFN-γ dev hücre oluşumunu sağlar, özellikle IFN-γ makrofajların epiteloid histiositlere ve dev hücrelere dönüşümünde önemlidir"}, {"letter": "E", "text": "T lenfositlerden ; IL1, TNF ve kemokinler salgılanır ve Makrofajları uyarır, Makrofajlardan IFN gama salgılanır ve T lenfositleri uyarır"}], "answer": "E", "note": null, "id": "2021-2022_Q73", "explanation": "Kronik inflamasyonda T lenfositler IFN-γ salgılayarak makrofajları uyarır; makrofajlar ise IL-1 ve TNF salgılar. E şıkkında bu ilişki ters verilmiştir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 71, "id": "2019-2020_Q71"}, {"kurul": "1", "year": "2022-2023", "q_num": 63, "id": "2022-2023_Q63"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 74, "question": "Lenfoma ve lösemilerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenfoblastik Lösemi; Lenfoblastik lösemi, ince, saç benzeri sitoplazmik çıkıntılar içeren lösemik hücrelerin varlığı ile karakterize, az görülen, yavaş seyirli bir B hücreli lenfomadır."}, {"letter": "B", "text": "Foiliküler Lenfomada; çoğu olguda, BCL2 over ekspresyonuna yol açan (14;18) translokasyonu vardır"}, {"letter": "C", "text": "Mantle H ücreli Lenfoma; Hücre siklusunun ilerlemesinde düzenleyici rol oynayan siklin D1’in overekspresyonu ile sonuçlanan (11 ;14) translokasyonu ile ilişkilidir."}, {"letter": "D", "text": "Burkitt lenfoma, kromozom 8 ’de localize MYC genini ilgilendiren tranlokasyonlar içerir."}, {"letter": "E", "text": "Mikozis Fungoides ve Sezary Sendromu; Neoplastik CD4+ T hücrelerinin tümörleri olan bu tümörler deride yuvalanırlar."}], "answer": "A", "note": null, "id": "2021-2022_Q74", "explanation": "Saç benzeri sitoplazmik çıkıntılar içeren yavaş seyirli B hücreli tümör Lenfoblastik Lösemi değil, **Tüylü Hücreli Lösemi (Hairy Cell Leukemia)**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 78, "id": "2019-2020_Q78"}, {"kurul": "1", "year": "2020-2021", "q_num": 66, "id": "2020-2021_Q66"}, {"kurul": "1", "year": "2022-2023", "q_num": 71, "id": "2022-2023_Q71"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 75, "question": "Aşağıda belirtilen inflamasyon ve inflamasyon mediyatörleri ile ilgili hangi bilgi\nyanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Granülomatöz inflamasyon; Özel bir kronik iltihap paternidir, aktive makrofajlar, granulomlar, epiteloid hücreler’den oluşur"}, {"letter": "B", "text": "Faktör Xa damar geçirgenliğini artırır, trombin, lökositin endotele adezyonunu güçlendirir, fibrinopeptidler damar geçirgenliğini artırır, lökositler için kemotaktiktir,"}, {"letter": "C", "text": "Hageman faktör; KC de sentezlenir, endotel hasarlı bölgeyle karşılaşıncaya kadar dolaşımda inaktiftir., hasarlı bölge ile karşılaşınca aktive olur."}, {"letter": "D", "text": "Konvertaz etkisiyle en son C5a; C5-9 MAC oluşumunu başlatır"}, {"letter": "E", "text": "Bradikinin; Histamine benzer etki gösterir, Vasküler permeabiliteyi artırır, Ekstravasküler düz kas kasılmasını sağlar (bronş düz kası), deriye enjekte edilirse ağrı yapar."}], "answer": "D", "note": null, "id": "2021-2022_Q75", "explanation": "Membran Atak Kompleksi (C5b-9) oluşumunu başlatan C5a değil, **C5b**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 72, "id": "2019-2020_Q72"}, {"kurul": "1", "year": "2020-2021", "q_num": 57, "id": "2020-2021_Q57"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 76, "question": "Aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Kronik iltihabın mediatörleri;lenfosit, makrofaj, plazma hücresi, eozinofil, mast hücreleridir"}, {"letter": "B", "text": "Kanda monositlerin yarılanma ömrü 1 gündür, doku makrofajları ise aylarca yaşayabilirler. Monositler 24-48 saat içinde zedelenen bölgeye göç ederler. Ekstravasküler dokuda makrofajlara dönüşür"}, {"letter": "C", "text": "Asit ve nötral proteazlar: doku hasarı, Kompleman komponentleri ve koagülasyon faktörlerinin lokal miktarı artar, reaktif oksijen ürünleri ve NO: doku hasarı, Prostaglandinler, Sitokinler IL-1, TNF: inflamasyonu artırma, Büyüme faktörleri: fibroblast aktivasyonu ve fibrozis, anjiogeneze sebep olur"}, {"letter": "D", "text": "IL-1, IFN-γ dev hücre oluşumunu sağlar, Özellikle IFN-γ makrofajların epiteloid histiositlere ve dev hücrelere dönüşümünde önemlidir."}, {"letter": "E", "text": "T lenfositlerden ; IL1, TNF ve kemokinler salgılanır ve Makrofajları uyarır, Makrofajlardan IFN gama salgılanır ve T lenfositleri uyarır."}], "answer": "E", "note": null, "id": "2021-2022_Q76", "explanation": "T lenfositlerden IFN-γ salgılanarak makrofajları uyarır, makrofajlardan ise IL-1 ve TNF salgılanır; E şıkkında ters ifade edilmiştir."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 77, "question": "Aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Tümör antijenleri hücre yüzeyine MHC klas I moleküller tarafından sunulur ve CD8+ sitotoksik T lenfositler tarafından tanınır"}, {"letter": "B", "text": "IL1, iştahı bastırır ve lipoprotein lipazm etkisini, dolayısıyla yağ asitlerinin lipoproteinlerden serbest kalmasını inhibe eder"}, {"letter": "C", "text": "Mutant onkogenler, tümör baskılayıcı genler, ekspresyonları aşırı veya atipik olan proteinler, onkogen virüslerin ürünü tümör antijenleri, onkofetal antijenler, değişikliğe uğramış glikolipidler ve glikoproteinler, ayrıca hücre tipine-spesifik diferansiasyon antijenleri, farklı tümör antijeni sınıflarındandır"}, {"letter": "D", "text": "TGF-ß, güçlü bir immunosüpresandır ve bazı tümörlerin eksprese ettiği FasL, bağışıklık hücrelerinin yüzeyindeki Fas'a bağlanır ve bağışıklık hücresinin apopitoza girmesine yol açar"}, {"letter": "E", "text": "X-kromozomuna bağlı lenfoproliferatif hastalık geçer. Bu hastalığı olan erkek çocuklarda EBV enfeksiyonu gelişirse, kendi kendine iyileşen enfeksiyöz mononükleoz yerine, ölümle sonuçlanan enfeksiyöz mononükleoz veya daha da kötüsü, malign lenfoma olmaktadır."}], "answer": "B", "note": null, "id": "2021-2022_Q77", "explanation": "Kaşekside iştahı baskılayan ve lipoprotein lipazı inhibe eden ana mediyatör ders notunda **TNF-α (kaşektin)** olarak tanımlanmıştır (B şıkkında TNF-α yerine IL-1 yazıldığı için cevap anahtarında B işaretlenmiştir)."}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 78, "question": "Fiziksel, kimyasal ve radyasyon etkisi ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Faz I reaksiyonlarında yer alan hücresel enzim sistemlerinin en önemlisi, sitokrom P-450 sistemidir."}, {"letter": "B", "text": "Fiziksel ajanların meydana getirmiş olduğu hasarlar; mekanik, termal, elektriksel ve iyonize radyasyona bağlı gelişenlerdir"}, {"letter": "C", "text": "Radyasyona bağlı morfolojik değişikler akut ortaya çıkar ve akut kaybolur."}, {"letter": "D", "text": "Hücre proliferasyonu. iyonizan radyasyon DNA'yı zedelediği için, hızlı bölünen hücreler dinlenme evresindeki hücrelere göre daha duyarlıdır"}, {"letter": "E", "text": "Radyasyona bağlı vasküler hasar; orta derecede duyarlı olan endotel hücrelerinin hasarı ile kan damarlarının daralmasına veya tıkanmasına neden olabilir"}], "answer": "C", "note": null, "id": "2021-2022_Q78", "explanation": "Radyasyona bağlı morfolojik değişiklikler akut ortaya çıkıp akut kaybolmaz; vasküler endotel hasarı ve fibrozis nedeniyle **kronik/kalıcı geç etkiler** bırakır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 74, "id": "2019-2020_Q74"}, {"kurul": "1", "year": "2020-2021", "q_num": 67, "id": "2020-2021_Q67"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 79, "question": "Hangisi mezenşimal tümör değildir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Anjiosarkom"}, {"letter": "B", "text": "Bazal hücreli karsinom"}, {"letter": "C", "text": "Fibrosarkom"}, {"letter": "D", "text": "Snovyal sarkom"}, {"letter": "E", "text": "Glomus tümörü"}], "answer": "B", "note": null, "id": "2021-2022_Q79", "explanation": "**Bazal hücreli karsinom** mezenşimal değil, **epitelyal** kökenli malign bir tümördür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 68, "id": "2019-2020_Q68"}, {"kurul": "1", "year": "2020-2021", "q_num": 61, "id": "2020-2021_Q61"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 80, "question": "Malign tümör derecelendirmesinde hangisi kullanılır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenf düğümü metastazı sayısı"}, {"letter": "B", "text": "Tümör çapı"}, {"letter": "C", "text": "Tümörün çevre dokuya invazyonu"}, {"letter": "D", "text": "Tümörün sitolojik diferansiasyon derecesi"}, {"letter": "E", "text": "Karaciğer metastazının varlığı / yokluğu"}], "answer": "D", "note": null, "id": "2021-2022_Q80", "explanation": "Malign tümör derecelendirmesinde (Grade) **tümörün sitolojik diferansiasyon derecesi** kullanılır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 69, "id": "2019-2020_Q69"}, {"kurul": "1", "year": "2020-2021", "q_num": 60, "id": "2020-2021_Q60"}, {"kurul": "1", "year": "2022-2023", "q_num": 68, "id": "2022-2023_Q68"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 81, "question": "Lenfoma / lösemilerle ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "En sık mutasyona uğrayan transkripsiyon faktörü genleri, B hücre kökenli A LL’lerde T E Lİ, AML1, E2A, PAX5 ve EBE’dir"}, {"letter": "B", "text": "KLL/SLL yavaş büyüyen ve yavaş ilerleyen bir tümördür ve tümör hücrelerinde, apoptozu engelleyen bir protein olan BCL2 seviyeleri çok yüksektir"}, {"letter": "C", "text": "KLL/SLL, pan-B belirteçleri olan CD19, CD20 ve CD23'ü ve yüzey immunglobülinleri mevcuttur ve tümör hücreleri ayrıca CD5'de eksprese ederler"}, {"letter": "D", "text": "Multipl Myelomda, MYC proto-onkogeni ilgilendiren translokasyonu saptanmıştır ve Tümör hücreleri sıklıkla Epstein-Barr virüsü ile latent olarak enfektedir"}, {"letter": "E", "text": "Diffüz Büyük B Hücreli Lenfoma; BCL6 geninde yeniden düzenlenmeler ya da mutasyonlar belirlenmiştir. Bu tümörlerin üçte biri folliküler lenfomadan kaynaklanır ve BCL2 ile ilişkili (14;18) translokasyonu mevcuttur"}], "answer": "D", "note": null, "id": "2021-2022_Q81", "explanation": "MYC translokasyonu ve EBV ile latent enfeksiyon Multipl Myelom'un değil, **Burkitt Lenfoma**'nın özelliğidir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 76, "id": "2019-2020_Q76"}, {"kurul": "1", "year": "2020-2021", "q_num": 64, "id": "2020-2021_Q64"}, {"kurul": "1", "year": "2022-2023", "q_num": 69, "id": "2022-2023_Q69"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 82, "question": "Kimyasal mediatörlerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Bradikinin; Vasküler permeabiliteyi artırır, arterioler dilatasyon ve brokokonstrüksiyon yapar."}, {"letter": "B", "text": "Kompleman sisteminde; Klasik yol, Antijen antikor kompleksi ile karşılaşma (C1 üzerinden), alternatif yol, Mikrobial yüzeyle temas, Lektin yolağı, Mannoz bağlayıcı lektinin direk C1’e bağlanması ile olur."}, {"letter": "C", "text": "Serotonin; Trombosit agregasyonu ile salınımı uyarılır ve vazokonstrüksiyona neden olur."}, {"letter": "D", "text": "TxA2; trombositlerde üretilir, trombosit agregasyonu ve vazokonstrüksiyon yapar."}, {"letter": "E", "text": "PGI2; vazokonstriksiyon sağlar, trombosit agregasyonnu inhibe eder."}], "answer": "E", "note": null, "id": "2021-2022_Q82", "explanation": "**PGI2 (Prostasiklin)** vazokonstrüksiyon değil, **vazodilatasyon** yapar ve trombosit agregasyonunu inhibe eder.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 68, "id": "2020-2021_Q68"}, {"kurul": "1", "year": "2022-2023", "q_num": 73, "id": "2022-2023_Q73"}]}, {"year": "2021-2022", "subject": "Patoloji", "q_num": 83, "question": "Aşağıdaki immünohistokimyasal belirleyicilerden hangisi, lenfosit predominant\nHodgkin hastalığında görülen Reed-Sternberg hücrelerinde karakteristik olarak pozitiftir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "CD 1"}, {"letter": "B", "text": "CD 3"}, {"letter": "C", "text": "CD 15"}, {"letter": "D", "text": "CD 20"}, {"letter": "E", "text": "CD 30"}], "answer": "D", "note": null, "id": "2021-2022_Q83", "explanation": "Lenfosit predominant Hodgkin lenfomanın L&H (patlamış mısır) hücrelerinde B hücre belirteci olan **CD20** karakteristik olarak pozitiftir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 62, "id": "2020-2021_Q62"}, {"kurul": "1", "year": "2022-2023", "q_num": 74, "id": "2022-2023_Q74"}]}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 84, "question": "57 yaşında kadın hasta, halsizlik, yorgunluk ve tırnaklarda kolay kırılma şikayeti ile\ngeliyor. Mukozalar soluk, anguler stomatit, kaşık tırnak ve kalpte 2/6 sistolik üfürümü\nmevcut. Diğer fizik bakılarında anormal bulgusu yok. Bu hastada aşağıdaki laboratuvar\nbulgularından hangisi beklenemez?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Transferrin saturasyonunda düşüklük"}, {"letter": "B", "text": "Ferritinde düşüklük"}, {"letter": "C", "text": "Demir bağlama kapasitesinde artış"}, {"letter": "D", "text": "Mentzer indeksinde artış"}, {"letter": "E", "text": "Transferrin reseptör düzeylerinde düşüş"}], "answer": "E", "note": null, "id": "2021-2022_Q84", "explanation": "Kaşık tırnak, angüler stomatit ve solukluk ile başvuran demir eksikliği anemisi hastasında hücrelerin demir ihtiyacını karşılamak için **solübl transferrin reseptör (sTfR) düzeyi artar**, düşmez."}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 85, "question": "Aşağıdaki laboratuvar bulgularından hangisi B12 vitamin yetmezliğinde gözlenmez?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Periferik yaymada bazofilik noktalanma"}, {"letter": "B", "text": "Plazma metilmalonat düzeyinde azalma"}, {"letter": "C", "text": "Hiperplastik kemik iliği"}, {"letter": "D", "text": "MCV düzeyinde artış"}, {"letter": "E", "text": "Serum kobalamin düzeyinde azalma"}], "answer": "B", "note": null, "id": "2021-2022_Q85", "explanation": "B12 vitamini (kobalamin), metilmalonil-KoA mutaz enziminin kofaktörüdür; B12 eksikliğinde metilmalonil-KoA süksinil-KoA'ya dönüşemediği için **plazma ve idrar metilmalonik asit (metilmalonat) düzeyi artar**, azalmaz."}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 86, "question": "Aşağıdaki koagulasyon parametrelerinden hangisi pıhtı temelli bir ölçüm metodu\niçermez?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "PT"}, {"letter": "B", "text": "aPTT"}, {"letter": "C", "text": "Fibrinojen"}, {"letter": "D", "text": "D-Dimer"}, {"letter": "E", "text": "Faktör 8"}], "answer": "D", "note": null, "id": "2021-2022_Q86", "explanation": "PT, aPTT, fibrinojen ve Faktör VIII aktivitesi pıhtı oluşum süresine (koagülometrik/pıhtı temelli metoda) dayanarak ölçülürken; **D-Dimer** monoklonal antikorlarla **immünotürbidimetrik veya ELISA (immünolojik)** yöntemle ölçülür."}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 87, "question": "Aşağıdaki faktör eksikliklerinin hangisinde sadece protrombin zamanında uzama\nbeklersiniz?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Faktör II eksikliği"}, {"letter": "B", "text": "Faktör V eksikliği"}, {"letter": "C", "text": "Faktör VII eksikliği"}, {"letter": "D", "text": "Faktör X eksikliği"}, {"letter": "E", "text": "Faktör XII eksikliği"}], "answer": "C", "note": null, "id": "2021-2022_Q87", "explanation": "**Faktör VII** yalnızca ekstrensek yolağa özgü bir faktör olduğu için izole Faktör VII eksikliğinde **sadece Protrombin Zamanı (PT) uzar**, aPTT normaldir. Faktör II, V ve X ortak yolakta olduğundan ikisini de uzatır; Faktör XII ise sadece aPTT'yi uzatır."}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 88, "question": "Kanserli dokuda Warburg etkisi sonucu artan metabolit aşağıdakilerden\nhangisidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Pirüvat"}, {"letter": "B", "text": "Asetat"}, {"letter": "C", "text": "Laktat"}, {"letter": "D", "text": "Süksinat"}, {"letter": "E", "text": "Asetil CoA"}], "answer": "C", "note": null, "id": "2021-2022_Q88", "explanation": "Kanserli dokuda Warburg etkisi (aerobik glikoliz) sonucu pirüvat, laktat dehidrogenaz (LDH) ile hızla indirgenerek bol miktarda **Laktat (laktik asit)** birikimine yol açar."}, {"year": "2021-2022", "subject": "Biyokimya", "q_num": 89, "question": "Aşağıdakilerden hangisi onkofetal antijen grubuna giren bir tümör belirteçtir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "NSE"}, {"letter": "B", "text": "CEA"}, {"letter": "C", "text": "CA-19.9"}, {"letter": "D", "text": "CA-15.3"}, {"letter": "E", "text": "hCG"}], "answer": "B", "note": null, "id": "2021-2022_Q89", "explanation": "**CEA (Karsinoembriyonik Antijen)** ve AFP, embriyonik/fetal dönemde sentezlenen **onkofetal antijen** grubundaki tümör belirteçleridir."}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Papillomaviruslerde DNA hemolojisi ile 100'ün üzerinde tip tanımlanmıştır. Bu\ntiplerden en kanserojen olan tip grubu hangisidir?", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "16-18"}, {"letter": "B", "text": "20-22"}, {"letter": "C", "text": "22-24"}, {"letter": "D", "text": "26-28"}, {"letter": "E", "text": "12-14"}], "answer": "A", "note": null, "id": "2021-2022_Q90", "explanation": "HPV tipleri içinde servikal kanser açısından en yüksek riskli (onkojenik) grup **Tip 16 ve 18**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 88, "id": "2019-2020_Q88"}, {"kurul": "1", "year": "2023-2024", "q_num": 93, "id": "2023-2024_Q93"}]}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 91, "question": "Retrovirüslerde virüse özgün pol geni ile kodlanan hangi enzim hastalık\netyolojisinde en önemlidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Revers (ters) transkriptaz"}, {"letter": "B", "text": "RNA polimeraz"}, {"letter": "C", "text": "DNA polimeraz"}, {"letter": "D", "text": "Taq polimeraz"}, {"letter": "E", "text": "İntegraz"}], "answer": "A", "note": null, "id": "2021-2022_Q91", "explanation": "Retrovirüslerde pol geni ile kodlanan ve RNA'dan DNA sentezleyen temel enzim **Revers (ters) transkriptaz**'dır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 89, "id": "2019-2020_Q89"}, {"kurul": "1", "year": "2023-2024", "q_num": 92, "id": "2023-2024_Q92"}]}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 92, "question": "Nükleik asit replikasyonuna katılan ve antiviral ilaçlar için iyi bir hedef olan Herpes\nVirüs enzimi hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "DNA polimeraz"}, {"letter": "B", "text": "RNA polimeraz"}, {"letter": "C", "text": "Lipaz"}, {"letter": "D", "text": "Ligaz"}, {"letter": "E", "text": "Esteraz"}], "answer": "A", "note": null, "id": "2021-2022_Q92", "explanation": "Herpesvirüslerde nükleik asit replikasyonunu yapan ve asiklovir gibi antivirallerin hedefi olan enzim **DNA polimeraz**'dır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 90, "id": "2019-2020_Q90"}]}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 93, "question": "İntrauterin hayatta ve yeni doğanda konjenital ve perinatal infeksiyonlar; sağlıklı\nerişkinlerde mononükleoz yapan DNA virüsü hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Sitomegalovirus (CMV)"}, {"letter": "B", "text": "Herpesvirüs"}, {"letter": "C", "text": "Parvovirüs"}, {"letter": "D", "text": "Papilloma virüs"}, {"letter": "E", "text": "Ebstein Barr virus"}], "answer": "A", "note": null, "id": "2021-2022_Q93", "explanation": "Konjenital/perinatal enfeksiyonların en sık etkeni olan ve erişkinde mononükleoz tablosu yapan DNA virüsü **Sitomegalovirüs (CMV)**'tür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 91, "id": "2019-2020_Q91"}, {"kurul": "1", "year": "2023-2024", "q_num": 91, "id": "2023-2024_Q91"}]}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 94, "question": "Bilinç bulanıklığı ve yüksek ateş nedeniyle acil servise getirilen 43 yaşında erkek\nhastanın özgeçmişinde tip 1 diabetes mellitus tanısı olduğu ve ara ara diabetik ketoasidoz\nnedeniyle hastaneye yatırıldığı öğreniliyor. Sağ gözünde periorbital ödem olan hastanın ağız\niçinde sert damakta siyah nekrotik lezyon dikkat çekiyor. Bu lezyondan alınan biyopsi\nmateryalinde ise geniş açılı dallanma gösteren, septasız, düzensiz görünümde hifler\nsaptanıyor. Bu hastadaki lezyondan sorumlu en olası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Rhizopus spp."}, {"letter": "B", "text": "Aspergillus flavus"}, {"letter": "C", "text": "Aspergillus niger"}, {"letter": "D", "text": "Candida albicans"}, {"letter": "E", "text": "Cryptococcus neoformans"}], "answer": "A", "note": null, "id": "2021-2022_Q94", "explanation": "Diyabetik ketoasidoz öyküsü olan hastada periorbital ödem, sert damakta siyah nekrotik eskar (rinoserebral mukormikoz) ve biyopside **geniş (90°) açıyla dallanan, septasız (bölmeli olmayan) şeritvari hiflerin** görülmesi **Rhizopus spp. (Mucorales)** enfeksiyonu için tanısaldır."}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 95, "question": "Kriptokok menenjitinden şüphelenilen bir hastada beyin omurilik sıvısının\naşağıdaki yöntemlerden hangisi ile boyanması öncelikli tercih edilir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Çini mürekkebi ile boyama"}, {"letter": "B", "text": "Gram boyama"}, {"letter": "C", "text": "Giemsa boyama"}, {"letter": "D", "text": "Hematoksilen-eozin ile boyama"}, {"letter": "E", "text": "Laktofenol pamuk mavisi ile boyama"}], "answer": "A", "note": null, "id": "2021-2022_Q95", "explanation": "Kriptokok menenjiti (*Cryptococcus neoformans*) şüphesinde BOS örneğinde mantarın kalın polisakkarit kapsülünü negatif boyama (ışık halesi) şeklinde hızlıca göstermek için **Çini mürekkebi (India ink)** boyaması tercih edilir."}, {"year": "2021-2022", "subject": "Mikrobiyoloji", "q_num": 96, "question": "Hepatit ve karaciğer kanserine neden olabilen, özellikle Aspergillus flavus ile\nkontamine tahıllarda karşımıza çıkan mikotoksin aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aflatoksin"}, {"letter": "B", "text": "Fumonizin"}, {"letter": "C", "text": "Okratoksin"}, {"letter": "D", "text": "Ergot alkaloitleri"}, {"letter": "E", "text": "Sitrinin"}], "answer": "A", "note": null, "id": "2021-2022_Q96", "explanation": "*Aspergillus flavus* ile kontamine tahıl ve kuruyemişlerde bulunan, karaciğer hasarı ve hepatoselüler karsinoma yol açan mikotoksin **Aflatoksin**dir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 94, "id": "2022-2023_Q94"}]}, {"year": "2021-2022", "subject": "Radyoloji", "q_num": 97, "question": "Hangi görüntüleme yönteminde insan vücudunun enerji ile etkileşimi refleksiyon\n(yansıma) ile gerçekleşir?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Ultrasonografi"}, {"letter": "B", "text": "Radyografi"}, {"letter": "C", "text": "Bilgisayarlı tomografi"}, {"letter": "D", "text": "Manyetik rezonans görüntüleme"}, {"letter": "E", "text": "Nükleer tıp çalışmaları"}], "answer": "A", "note": null, "id": "2021-2022_Q97", "explanation": "Yüksek frekanslı ses dalgalarının dokulara çarpıp **yansıması (refleksiyon / eko)** prensibiyle çalışan görüntüleme yöntemi **Ultrasonografi (USG)**'dir."}, {"year": "2021-2022", "subject": "Radyoloji", "q_num": 98, "question": "Neoplazilerin radyolojik görüntülenmesi ile ilgili aşağıdaki ifadelerden hangisi\nyanlıştır?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Neoplazilerin görüntülenmesinde bilgisayarlı tomografi ve manyetik rezonans görüntülemede intravenöz kontrast madde uygulaması hassasiyeti artırır"}, {"letter": "B", "text": "Tümoral kalsifikasyonlar röntgen ve bilgisayarlı tomografide rahatlıkla görülebilir, manyetik rezonans çoğu zaman kalsifikasyonları göstermez"}, {"letter": "C", "text": "Tedaviye yanıtın değerlendirilmesinde radyolojik görüntülemenin rolü yoktur"}, {"letter": "D", "text": "Röntgenogramlar akciğer ve kemik tümörlerinin görüntülenmesinde yararlıdır"}, {"letter": "E", "text": "Radyolojik görüntüleme bazı tümörlerin evrelendirilmesinde kullanılabilir"}], "answer": "C", "note": null, "id": "2021-2022_Q98", "explanation": "Kanser hastalarında kemoterapi ve radyoterapiye **tedavi yanıtının değerlendirilmesinde** (tümör boyutunun RECIST kriterleriyle BT/MR'da küçülmesi veya PET-BT'de metabolik yanıt) radyolojik görüntüleme **çok kritik bir role sahiptir**; 'rolü yoktur' ifadesi yanlıştır."}, {"year": "2021-2022", "subject": "Radyoloji", "q_num": 99, "question": "Aşağıdaki mekanizmalardan hangisi immün sistemin hem kanser oluşumunu\nengelleyici hem de neoplastik hastalığı şekillendiren ikili fonksiyonunu en iyi şekilde\ntanımlar?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "İmmün gözetim"}, {"letter": "B", "text": "Equilibrium (Denge)"}, {"letter": "C", "text": "Kanserin immün şekillerdirilmesi (cancer immunoediting)"}, {"letter": "D", "text": "Escape (Kaçış)"}, {"letter": "E", "text": "Eliminasyon"}], "answer": "C", "note": null, "id": "2021-2022_Q99", "explanation": "İmmün sistemin bir yandan tümör hücrelerini yok ederek konağı koruması, diğer yandan immün yanıttan kaçabilen daha dirençli tümör varyantlarını seçerek tümörü şekillendirmesi süreci **Kanserin immün şekillendirilmesi (Cancer immunoediting)** olarak adlandırılır."}, {"year": "2021-2022", "subject": "Radyoloji", "q_num": 100, "question": "Aşağıdaki molekül ya da hücrelerden hangisinin tümör mikroçevresinde tümörün\nlehine çalışma olasılığı en azdır?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Myeloid kaynaklı suprasör hücreler (MDSC)"}, {"letter": "B", "text": "M2 tipi makrofajlar"}, {"letter": "C", "text": "M1 tipi makrofajlar"}, {"letter": "D", "text": "TGF-beta"}, {"letter": "E", "text": "T regülatör hücreler (Treg)"}], "answer": "C", "note": null, "id": "2021-2022_Q100", "explanation": "Tümör mikroçevresinde MDSC, M2 makrofajlar, Treg hücreleri ve TGF-β tümör gelişimini desteklerken (immünsüpresif/protümöral); klasik olarak aktive olan **M1 tipi makrofajlar** proinflamatuar sitokinler ve NO/ROS üreterek **anti-tümöral (tümör aleyhine)** etki gösterir."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 1, "question": "Aşağıdaki parametrelerden hangisi anemilerin sınıflandırılması esnasında\nkullanılmaz?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "Retikülosit Sayısı"}, {"letter": "B", "text": "Eritrosit Üretiminde Azalma"}, {"letter": "C", "text": "Eritrosit Yıkımında Artış"}, {"letter": "D", "text": "Hematokrit"}, {"letter": "E", "text": "MCV"}], "answer": "D", "note": null, "id": "2022-2023_Q1", "explanation": "Anemiler morfolojik olarak **MCV**'ye göre, kinetik/fizyopatolojik olarak ise **retikülosit sayısı**, **eritrosit üretiminde azalma** ve **eritrosit yıkımında artış / kan kaybına** göre sınıflandırılır. **Hematokrit** anemi tanısında kullanılır ancak sınıflandırma kriteri değildir."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 2, "question": "Demir eksikliği anemisinde tedaviye yanıtın değerlendirilmesinde en erken\nkullanılabilecek parametre aşağıdakilerden hangisidir?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "RDW"}, {"letter": "B", "text": "Retikülosit"}, {"letter": "C", "text": "MCV"}, {"letter": "D", "text": "Hemoglobin"}, {"letter": "E", "text": "LDH"}], "answer": "B", "note": null, "id": "2022-2023_Q2", "explanation": "Demir eksikliği anemisinde oral demir tedavisine başlandıktan sonra laboratuvarda **en erken yükselen (5-10. günlerde pik yapan)** yanıt parametresi **Retikülosit sayısıdır (retikülosit krizi)**."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 3, "question": "Çocukluk çağı lösemilerinde saptanan aşağıdaki sitogenetik anormalliklerden hangisi\nkötü prognostik değildir?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "t(4;11)"}, {"letter": "B", "text": "Hipodiploidi"}, {"letter": "C", "text": "t(12;21)"}, {"letter": "D", "text": "t(9;22)"}, {"letter": "E", "text": "del(7)"}], "answer": "C", "note": null, "id": "2022-2023_Q3", "explanation": "Çocukluk çağı B-ALL'de **t(12;21) [ETV6-RUNX1 / TEL-AML1]** translokasyonu **iyi prognoz** göstergesidir. t(9;22), t(4;11), hipodiploidi ve 7. kromozom delesyonu ise kötü prognostiktir."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 4, "question": "Aşağıdakilerin hangisi adölesan çağda en sık görülen malignitedir?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "Lösemiler"}, {"letter": "B", "text": "Lenfomalar"}, {"letter": "C", "text": "Santral Sinir Sistemi Tümörleri"}, {"letter": "D", "text": "Nöroblastom"}, {"letter": "E", "text": "Nefroblastom"}], "answer": "B", "note": null, "id": "2022-2023_Q4", "explanation": "Erken çocuklukta (1-10 yaş) akut lösemiler birinci sırada iken, **adölesan (ergenlik, 15-19 yaş) dönemde en sık görülen malignite Lenfomalardır** (özellikle Hodgkin lenfoma)."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 5, "question": "Aşağıdaki klinik durumlardan hangisi bir çocuk hastada immun yetmezlik açısından\nileri tetkik yapmayı gerektirmez?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "Postnatal 15. günde perianal apse nedeniyle yenidoğan yoğun bakım yatışı yapılan olgu"}, {"letter": "B", "text": "4 yaşında Enfeksiyöz Mononukleoz nedeniyle hastane yatış öyküsü olan olgu"}, {"letter": "C", "text": "1 yaşında 3 kez lober pnömoni nedeniyle hastane yatış öyküsü olan olgu"}, {"letter": "D", "text": "4 yaşında beyin apsesi nedeniyle hastaneye yatış öyküsü olan olgu"}, {"letter": "E", "text": "Kardeşinde immun yetmezlik öyküsü olan olgu"}], "answer": "B", "note": null, "id": "2022-2023_Q5", "explanation": "**4 yaşında geçirilen tek bir Enfeksiyöz Mononükleoz (EBV)** atağı ve yatışı çocukluk çağında sık karşılaşılan normal bir viral tablodur, primer immün yetmezlik açısından ileri tetkik gerektirmez. Yenidoğanda perianal apse (lökosit adezyon defekti/KGH), 1 yılda 3 lober pnömoni, beyin apsesi ve aile öyküsü ise mutlak tetkik gerektirir."}, {"year": "2022-2023", "subject": "Pediatri", "q_num": 6, "question": "Aşağıdakilerden hangisi humoral immun yetmezlik grubunda yer alır?", "professor": "Cemile Kübra Zeybek", "options": [{"letter": "A", "text": "Selektif IgA Eksikliği"}, {"letter": "B", "text": "Ağır Kombine İmmun Yetmezlik"}, {"letter": "C", "text": "Kompleman Defekti"}, {"letter": "D", "text": "Lökosit Adhezyon Defekti"}, {"letter": "E", "text": "Omenn Sendromu"}], "answer": "A", "note": null, "id": "2022-2023_Q6", "explanation": "**Selektif IgA Eksikliği**, B lenfosit/antikor üretimiyle ilgili **humoral immün yetmezlik** grubunda yer alır. Ağır kombine İY ve Omenn sendromu kombine; Lökosit adezyon defekti fagosit; kompleman defekti doğal immünite bozukluğudur."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 7, "question": "Otonom sinir sistemindeki otonom gangliyonlarındaki etki nörotransmitter ve\nreseptörü hangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Asetik kolin - Nikotinik NM tip"}, {"letter": "B", "text": "Asetik kolin - Nikotinik NN tip"}, {"letter": "C", "text": "Asetil kolin - Muskarinik reseptör"}, {"letter": "D", "text": "Noradrenalin - Adrenerjik Alfa2 reseptör"}, {"letter": "E", "text": "Adrenalin - Adrenerjik Beta reseptör"}], "answer": "B", "note": null, "id": "2022-2023_Q7", "explanation": "Hem sempatik hem de parasempatik tüm otonom gangliyonlarda pregangliyonik nöronlardan salınan nörotransmitter **Asetilkolin (ACh)** ve postgangliyonik hücre gövdesindeki reseptör **Nöronal tip Nikotinik (NN) reseptör**dür."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 8, "question": "Aşağıdakilerden hangi ilaç santral antikolinerjik etkili ilaç (atropin, skopolamin,\ntrisiklik antidepresanlar...) zehirlenmesinde antidot olarak kullanılır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Fizostigmin"}, {"letter": "B", "text": "Betanekol"}, {"letter": "C", "text": "Pilokarpin"}, {"letter": "D", "text": "Ambenonyum"}, {"letter": "E", "text": "Karbakol"}], "answer": "A", "note": null, "id": "2022-2023_Q8", "explanation": "**Fizostigmin**, tersiyer amin yapısında olduğu için kan-beyin bariyerini geçebilen bir antikolinesterazdır; bu sayede **atropin, skopolamin ve trisiklik antidepresanlara bağlı santral antikolinerjik zehirlenmelerde spesifik antidot** olarak kullanılır."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 9, "question": "Parasempatik sinir sistemi uyarılması (parasempatomimetik) durumunda aşağıdaki\nbulgulardan hangisi gözlenmez?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Kalpte negatif dromotrop etkilidir."}, {"letter": "B", "text": "Ciltte vazodilatasyon ve kızarma yapar."}, {"letter": "C", "text": "Barsak düz kasarlarını kasar ve peristaltizim artar."}, {"letter": "D", "text": "Trigon ve sfinkterleri kasıcı etki yapar."}, {"letter": "E", "text": "Tükrük bezlerinde sekresyon artışı yapar."}], "answer": "D", "note": null, "id": "2022-2023_Q9", "explanation": "Parasempatik (muskarinik M3) uyarı mesane detrusor kasını kasarken **trigon ve internal sfinkteri gevşeterek** miksiyonu (idrar yapmayı) sağlar. Trigon ve sfinkterleri kasıcı etki parasempatik değil, sempatik (alfa-1 adrenerjik) uyarı ile oluşur."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 10, "question": "I- Filgrastim, doğal G-CSF (Granülosit koloni stimüle edici faktör ) ile aynı biyolojik\naktiviteye sahiptir.\nII- Demir (III) sorbitol glukonik asit kompleksi paranteral kullanılan demir prepatıdır.\nIII- Demir bileşikleri çayla birlikte alındıklarında emilimleri artar.\nIV- Oral demir bileşikleri demir eksikliğinde rutin kullanılmaz.\nV- B-12 emilimi için extrinsik faktör gereklidir.\nYukarıda anemi tedavisiyle ilgili olarak verilen bilgilerden hangisi veya hangileri doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "I-II"}, {"letter": "B", "text": "I-II-III"}, {"letter": "C", "text": "I-III-V"}, {"letter": "D", "text": "II-III-V"}, {"letter": "E", "text": "I-II-III-IV"}], "answer": "A", "note": null, "id": "2022-2023_Q10", "explanation": "Filgrastim rekombinant G-CSF'dir (I doğru) ve Demir(III) sorbitol glukonik asit kompleksi parenteral demir preparatıdır (II doğru). Çay (tanenler) demir emilimini azaltır (III yanlış), demir eksikliğinde ilk tercih oral demirdir (IV yanlış) ve B12 emilimi için intrinsik faktör gerekir, B12'nin kendisi ekstrinsik faktördür (V yanlış)."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 11, "question": "İmmünomodülatör ilaçlarla ilgili olarak verilen bilgilerden hangisi doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Kalsinürin inhibitörleri interlökün-2 üretimi ve etkinlinğini inhibe ederler."}, {"letter": "B", "text": "Organ nakillerinde greft red reaksiyonlarını önleme amacıyla immünstimülan maddeler kullanılır."}, {"letter": "C", "text": "İmmünsüpresif ilaçlar interlökin-2 üretimini artırırlar."}, {"letter": "D", "text": "Glukokortikoitler sitokin genlerinin ekspresyonunu artırarak immünsüpresif etkide bulunurlar."}, {"letter": "E", "text": "Antiproliferatif ilaçlar, pürin sentezini artırırlar."}], "answer": "A", "note": null, "id": "2022-2023_Q11", "explanation": "**Kalsinörin inhibitörleri** (siklosporin ve takrolimus), T lenfositlerde NFAT defosforilasyonunu engelleyerek **interlökin-2 (IL-2) üretimini ve etkinliğini inhibe ederler**."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 12, "question": "Hangisi İmmün yetmezlik durumlarının tedavisinde kullanılan bir ilaçldır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Aldeslökin"}, {"letter": "B", "text": "FK506"}, {"letter": "C", "text": "Pimekrolimus"}, {"letter": "D", "text": "Metotraksat"}, {"letter": "E", "text": "Siklofosfamit"}], "answer": "A", "note": null, "id": "2022-2023_Q12", "explanation": "**Aldeslökin** rekombinant insan İnterlökin-2 (IL-2) preparatıdır ve immün sistemi uyarıcı (**immünstimülan**) etki gösterir; diğer şıklar (FK506/takrolimus, pimekrolimus, metotreksat, siklofosfamid) immünsüpresif ilaçlardır.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 46, "id": "2025-2026_Q46"}]}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 13, "question": "Aşağıdakilerden hangisi antineoplastik ilaçlara karşı gelişen dirençte rol oynayan\nmekanizmalardan birisi değildir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Malign hücre tarafından ilacın hücre içine uptake’inin artması."}, {"letter": "B", "text": "İlacın inaktivasyonunun hızlanması."}, {"letter": "C", "text": "İlacın DNA molekülü üzerinde yaptığı lezyonun onarınımının hızlanması."}, {"letter": "D", "text": "Purin ve pirimidin biyosentezinde yedek yolakları aktivasyonu veya normal yolaktaki enzimlerin üretiminin artması"}, {"letter": "E", "text": "Hücre içinde glutatyon üretiminin ve glutatyon S transferaz enziminin indüklenmesi."}], "answer": "A", "note": null, "id": "2022-2023_Q13", "explanation": "Antineoplastik ilaçlara direnç gelişiminde ilacın hücre içine alımının (uptake) artması değil, **azalması** veya P-glikoprotein (MDR1) pompasıyla hücre dışına atılımının (efflux) artması rol oynar."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 14, "question": "Topoizomeraz-I enzim inhibisyonu yapan antikanser ilaç aşağıdakilerden\nhangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "İrinotekan"}, {"letter": "B", "text": "Tioguanin"}, {"letter": "C", "text": "Klorambusil"}, {"letter": "D", "text": "Tenipozit"}, {"letter": "E", "text": "Bleomisin"}], "answer": "A", "note": null, "id": "2022-2023_Q14", "explanation": "**İrinotekan** (ve topotekan) kamptotesin türevi olup **Topoizomeraz-I** enzimini inhibe eden antineoplastik ilaçlardır. (Etopozid ve tenipozid ise Topoizomeraz-II inhibitörüdür).", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 44, "id": "2025-2026_Q44"}]}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 15, "question": "Sempatik postgangliyonik (adrenerjik) sinir uçları ile efektör hücreler arasındaki\nnöroefektör kavşaklarda impuls aşırımını, sinir ucu düzeyindeki veya efektör hücrelerin\nadrenerjik reseptörleri düzeyindeki etkileriyle bloke eden ilaçların genel isimlendiriilmesi\nnedir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Sempatolitik ilaçlar"}, {"letter": "B", "text": "Sempatomimemtik ilaçlar"}, {"letter": "C", "text": "Parasempatolitik ilaçlar"}, {"letter": "D", "text": "Parasempatomimemitk ilaçlar"}, {"letter": "E", "text": "Gangliyon blokörleri"}], "answer": "A", "note": null, "id": "2022-2023_Q15", "explanation": "Adrenerjik (sempatik) sinir uçlarından impuls aşırımını veya postsinaptik adrenerjik reseptörleri bloke ederek sempatik etkiyi ortadan kaldıran ilaçlara **Sempatolitik (antiadrenerjik) ilaçlar** denir."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 16, "question": "Aşağıdakilerden hangisi katekolamin sentezini inhibe etmek için kullanılabilir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Metirozin"}, {"letter": "B", "text": "Rezerpin"}, {"letter": "C", "text": "Nadolol"}, {"letter": "D", "text": "Moksisilit"}, {"letter": "E", "text": "Sildenafil"}], "answer": "A", "note": null, "id": "2022-2023_Q16", "explanation": "**Metirozin (alfa-metiltirozin)**, katekolamin sentezinde hız kısıtlayıcı enzim olan **tirozin hidroksilazı** kompetitif olarak inhibe ederek dopamin, noradrenalin ve adrenalin sentezini baskılar (feokromositoma tedavisinde kullanılır)."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 17, "question": "β2-adrenerjik reseptörlere afinitesi daha fazla olan ve bu reseptörde stimülasyon\nmeydana getirerek uterus gibi organlarda düz kas kasılmasını inhibe eden tokolitik ilaç\naşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Ritodrin"}, {"letter": "B", "text": "Fenilefrin"}, {"letter": "C", "text": "Metoksamin"}, {"letter": "D", "text": "Oksedrin"}, {"letter": "E", "text": "Nafazolin"}], "answer": "A", "note": null, "id": "2022-2023_Q17", "explanation": "**Ritodrin** (terbutalin ve salbutamol ile birlikte), selektif **β2-adrenerjik reseptör agonisti** olup uterus düz kasını gevşeterek erken doğum eylemini durdurmak için kullanılan **tokolitik** bir ilaçtır."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 18, "question": "Hem β1 hem de β2 adrenerjik reseptörler üzerinde güçlü agonist etki alfa\nadrenerjik reseptörler üzerinde ise terapötik düzeylerde etkisiz veya minimal düzeyde etki\ngösteren madde aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "İzoprenalin"}, {"letter": "B", "text": "Efedrin"}, {"letter": "C", "text": "Fenilefrin"}, {"letter": "D", "text": "Adrenalin"}, {"letter": "E", "text": "Amfetamin"}], "answer": "A", "note": null, "id": "2022-2023_Q18", "explanation": "**İzoprenalin (İzoproterenol)** sentetik bir katekolamindir; hem **β1 hem de β2 reseptörler üzerinde güçlü non-selektif agonist** etki gösterirken alfa reseptörler üzerinde terapötik dozda etkisi yoktur."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 19, "question": "l- Yüksek dozda blokaj ortaya çıkarır. Bunu depolarizasyonla blokaj ile yapar.\nll- TxA2 düzeyini azaltarak trombüs agregasyonunu zorlaştırır.\nIII- Hem sempatik hemde parasempatiktir.\nIV- ACTH düzeyini artırır.\nV- İştahı artırır.\nYukarıda nikotin ile ilgili olarak verilen bilgilerden hangisi veya hangileri doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "I-III-IV"}, {"letter": "B", "text": "II-III-V"}, {"letter": "C", "text": "IV-V"}, {"letter": "D", "text": "I-II-III-IV"}, {"letter": "E", "text": "I-IV-V"}], "answer": "A", "note": null, "id": "2022-2023_Q19", "explanation": "Nikotin düşük dozda gangliyonları uyarırken yüksek dozda depolarizasyonlu blokaj yapar (I doğru), hem sempatik hem parasempatik gangliyonları etkiler (III doğru) ve SSS uyarısıyla ACTH/kortizol/ADH salınımını artırır (IV doğru). Trombosit agregasyonunu zorlaştırmaz ve iştahı azaltır (II ve V yanlış)."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 20, "question": "• Gastroselektif özelliktedir.\n• M1 reseptörlerini selektif olarak bloke eder.\n• Mide paryetal hücrelerden asid salgılamasını belirgin derecedeinhibe eder.\nYukarıda bir kaç özelliği verilen ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Pirenzepin"}, {"letter": "B", "text": "Atropin"}, {"letter": "C", "text": "Skopalamin"}, {"letter": "D", "text": "Darifenasin"}, {"letter": "E", "text": "Hyosin n butilbromür"}], "answer": "A", "note": null, "id": "2022-2023_Q20", "explanation": "**Pirenzepin** (ve telenzepin), mide pariyetal hücrelerindeki/enterik gangliyonlardaki **M1 muskarinik reseptörleri selektif olarak bloke ederek** mide asit salgısını azaltan gastroselektif antimuskarinik ilaçtır."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 21, "question": "Aşağıda verilen ilaç etki mekanizmasıyla ilaçları eşleştiriniz:\nI. Siklofilin inhibisyonu\nII. Dihidrooratat dehidrojenaz enzim inhibisyonu", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "I -> Siklosporin | II -> Leflunomid"}, {"letter": "B", "text": "I -> Takrolimus | II -> Mikofenolat mofetil"}, {"letter": "C", "text": "I -> Sirolimus | II -> Siklofosfamid"}, {"letter": "D", "text": "I -> Leflunomid | II -> Siklosporin"}, {"letter": "E", "text": "I -> Azatiyoprin | II -> Metotreksat"}], "answer": "A", "note": "Orijinal PDF'te eşleştirme sorusu olarak verilmiştir.", "id": "2022-2023_Q21", "explanation": "**Siklosporin** hücre içinde **siklofilin** proteinine bağlanarak kalsinörini inhibe eder (I); **Leflunomid** ise **dihidrooratat dehidrojenaz** enzimini inhibe ederek pirimidin sentezini bozar (II)."}, {"year": "2022-2023", "subject": "Farmakoloji", "q_num": 22, "question": "Tanı anında metastatik olmayan ve lokal tedavisi tamamlanan olgulara, mikrometastatik odakların olabileceğinden yola çıkarak kemoterapi uygulanması ............. kemoterapi olarak adlandırılır.", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Adjuvan (Koruyucu / Sekonder)"}, {"letter": "B", "text": "Neoadjuvan"}, {"letter": "C", "text": "Palyatif"}, {"letter": "D", "text": "İndüksiyon"}, {"letter": "E", "text": "Konsolidasyon"}], "answer": "A", "note": "Orijinal PDF'te boşluk doldurma sorusu olarak verilmiştir (Cevap: Adjuvan, koruyucu, Sekonder).", "id": "2022-2023_Q22", "explanation": "Lokal tedavisi (cerrahi/radyoterapi) tamamlanmış ve görünür metastazı olmayan hastalarda olası mikrometastazları yok etmek ve nüksü önlemek amacıyla uygulanan tedaviye **Adjuvan (koruyucu) kemoterapi** denir."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 23, "question": "MGUS (Monoclonal gammopathy of undetermined significance) ile ilgili aşağıdaki\nifadelerden hangisi yanlıştır?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Kemik iliğinde plazma hücre oranı %10’un altındadır."}, {"letter": "B", "text": "M proteinin genellikle 3 g/dL’nin altındadır."}, {"letter": "C", "text": "70 yaşın üzerindeki kişilerde daha sık görülür."}, {"letter": "D", "text": "Hastalarda normokrom normositer anemi görülür"}, {"letter": "E", "text": "Hiperkalsemi, böbrek yetmezliği ve kemik lezyonları görülmez."}], "answer": "D", "note": null, "id": "2022-2023_Q23", "explanation": "**MGUS (Önemi Belirsiz Monoklonal Gammopati)**'ta kemik iliğinde plazma hücresi <%10, serum M proteini <3 g/dL'dir ve CRAB bulguları (**anemi, hiperkalsemi, böbrek yetmezliği, litik kemik lezyonu**) **görülmez**. Anemi varsa semptomatik myelom düşünülür."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 24, "question": "Yetmiş iki yaşında erkek hasta halsizlik, yorgunluk şikayetleri ile başvuruyor.\nLaboratuvarda Hb: 10 gr/dL, MCV: 102 fL, lökosit ve trombosit normal bulunuyor. Periferik\nyaymada nötrofillerde hiposegmentasyon izleniyor.Bu hastada en olası tanı aşağıdakilerden\nhangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Vitamin B12 eksikliği anemisi"}, {"letter": "B", "text": "Hairy cell lösemi"}, {"letter": "C", "text": "Miyelodisplastik sendrom"}, {"letter": "D", "text": "Akut miyeloblastik lösemi"}, {"letter": "E", "text": "Kronik miyeloid lösemi"}], "answer": "C", "note": null, "id": "2022-2023_Q24", "explanation": "İleri yaş hastada makrositer anemi (MCV: 102 fL) ve periferik yaymada nötrofillerde **hiposegmentasyon (psödo-Pelger-Huet anomalisi)** görülmesi **Miyelodisplastik Sendrom (MDS)** için tipiktir (B12 eksikliğinde hiposegmentasyon değil hipersegmentasyon görülür)."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 25, "question": "Kırk yedi yaşında erkek hasta halsizlik, yorgunluk, ateş ve istemsiz kilo kaybı\nşikayetleriyle başvuruyor. Fizik muayenede dalak kot altı 6 cm, karaciğer kot altı 3 cm ele\ngeliyor. Laboratuvarda Hb: 14 gr/dL, WBC: 78000/mm3, PLT: 617000/mm3 olarak\nsaptanıyor. Periferik yaymada tüm miyeloid ve eritroid hücre elemanları görülüyor. Lökosit\nalkalen fosfataz (LAP) skoru düşük saptanıyor. Bu hastada saptanacak en olası kromozomal\nanomali ve bununla ilişkili gen hangi seçenekte doğru verilmiştir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "t(8;14): cMyc"}, {"letter": "B", "text": "t(9;22): BCR-ABL"}, {"letter": "C", "text": "t(14;18): Bcl2"}, {"letter": "D", "text": "t(11;14): Cyclin D1"}, {"letter": "E", "text": "t(15;17): PML-RAR a"}], "answer": "B", "note": null, "id": "2022-2023_Q25", "explanation": "Splenomegali, belirgin lökositoz (78.000), trombositoz (617.000), periferik yaymada tüm miyeloid seri elemanlarının görülmesi ve düşük LAP skoru **Kronik Miyeloid Lösemi (KML)** tablosudur; karakteristik genetik anomalisi **t(9;22): BCR-ABL**'dir."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 26, "question": "Yetmiş bir yaşında, prostat operasyonu için hastaneye başvuran erkek hastanın\nyapılan tam kan sayımında Hb:13 gr/dL, WBC: 75000/mm3, PLT: 240000/mm3 olarak\nsaptanıyor. Fizik muayenede servikal ve aksiler lenfadenopati saptanıyor. Periferik yaymada\n%80 matür lenfosit, kemik iliğinde %70 oranında lenfosit artışı saptanıyor. Bu hastada en\nolası tanı aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Non-Hodgkin lenfoma"}, {"letter": "B", "text": "Kronik myeloid lösemi"}, {"letter": "C", "text": "Lökomoid reaksiyon"}, {"letter": "D", "text": "Kronik lenfositer lösemi"}, {"letter": "E", "text": "Hairy cell lösemi"}], "answer": "D", "note": null, "id": "2022-2023_Q26", "explanation": "İleri yaşta asemptomatik saptanan lenfadenopati, belirgin lökositoz (75.000/mm³) ve periferik yaymada %80, kemik iliğinde %70 oranında küçük matür lenfosit artışı **Kronik Lenfositer Lösemi (KLL)** için tanısaldır."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 27, "question": "Kırk sekiz yaşında erkek hasta son 6 haftadır baş ağrısı ve yaygın kaşıntı nedeniyle\nbaşvuruyor. Kaşıntısının özellikle sıcak duş sonrası arttığını belirtiyor. Sigara kullanmıyor,\nmalignite öyküsü yok, yüksek rakımda yaşamıyor, uyku apne sendromu ya da kronik\nobstrüktif akciğer hastalığı semptomları tariflemiyor. Laboratuvar incelemelerinde Hb: 18.6\ng/dL, Hct: %52.5, WBC: 6300/mm3, PLT: 182000/mm3, serum EPO düzeyi düşük saptanıyor.\nBilurubin düzeyi, serum kreatinin ve karaciğer fonksiyon testleri normal izleniyor.Bu hastada\naşağıdakilerden hangisi tanı kriterleri arasında yer almaz?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Parsiyel oksijen basıncı"}, {"letter": "B", "text": "Serum EPO düzeyi"}, {"letter": "C", "text": "Kemik iliği biyopsisi"}, {"letter": "D", "text": "Hemoglobin düzeyi"}, {"letter": "E", "text": "JAK-2 V617F mutasyonu"}], "answer": "A", "note": null, "id": "2022-2023_Q27", "explanation": "Sıcak duş sonrası kaşıntı (akuajenik pruritus), yüksek Hb/Hct ve düşük EPO düzeyi **Polisitemia Vera (PV)** tablosudur. DSÖ Polisitemia Vera tanı kriterlerinde Hb/Hct yüksekliği, kemik iliğinde panmiyelozis, JAK2 V617F mutasyonu ve düşük serum EPO düzeyi yer alır; **arteriyel parsiyel oksijen basıncı (PaO2)** PV tanı kriterleri arasında yer almaz (sekonder polisitemiyi dışlamada kullanılır)."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 28, "question": "Aşağıdaki pansitopeni nedenlerinden hangisinde kemik iliği hiposellüler olarak\ntespit edilir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "B12 vitamin eksikliği"}, {"letter": "B", "text": "Miyelodisplastik sendrom"}, {"letter": "C", "text": "Hipersplenizm"}, {"letter": "D", "text": "Miyelofibrozis"}, {"letter": "E", "text": "Fanconi Aplastik anemisi"}], "answer": "E", "note": null, "id": "2022-2023_Q28", "explanation": "B12 eksikliği, MDS, miyelofibrozis ve hipersplenizmde kemik iliği genellikle normosellüler veya hipersellülerdir; **Fanconi aplastik anemisinde** ise kemik iliği belirgin **hiposellülerdir**."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 29, "question": "Demir eksikliği anemisi ile Beta talasemi taşıyıcılığının ayırıcı tanısında aşağıdaki\nparametrelerden hangisi yararlıdır?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Ortalama eritrosit hacmi (MCV)"}, {"letter": "B", "text": "Ortalama eritrosit hemoglobin konsantrasyonu (MCHC)"}, {"letter": "C", "text": "Retikülosit sayısı"}, {"letter": "D", "text": "Eritrosit sayısı (RBC)"}, {"letter": "E", "text": "Ortalama eritrosit hemoglobin miktarı (MCH)"}], "answer": "D", "note": null, "id": "2022-2023_Q29", "explanation": "Demir eksikliği anemisi ile Beta talasemi taşıyıcılığının ayırıcı tanısında **Eritrosit sayısı (RBC)** çok değerlidir (Mentzer indeksi = MCV/RBC): Beta talasemi taşıyıcılığında eritrosit sayısı normal veya artmışken (>5 milyon), demir eksikliğinde azalmıştır."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 30, "question": "Elli yedi yaşında kadın hasta halsizlik, yorgunluk, tırnaklarda kolay kırılma ve son\n6 ayda 10 kg kilo kaybı şikayetleri ile başvuruyor. Fizik muayenede kan basıncı 120/50\nmmHg, nabız 98/dk, ateş 36.8 C, mukozalar soluk olarak değerlendiriliyor. Kalpte 2/6 sistolik\nüfürüm duyuluyor. Kaşık tırnak ve angüler stomatit saptanıyor. Hastanın gaytada gizli kan\ntesti pozitif olarak raporlanıyor.Bu hastada düşündüğümüz ön tanıya göre aşağıdaki\nlaboratuvar bulgularından hangisi beklenmez?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Transferrin reseptör düzeyinde düşüklük"}, {"letter": "B", "text": "Ferritinde düşüklük"}, {"letter": "C", "text": "Serum demir düzeyinde düşüklük"}, {"letter": "D", "text": "Serum demir bağlama kapasitesinde artış"}, {"letter": "E", "text": "Transferrin satürasyonunda düşüklük"}], "answer": "A", "note": null, "id": "2022-2023_Q30", "explanation": "Kaşık tırnak, angüler stomatit ve gaytada gizli kan pozitifliği olan hastada tanı **Demir Eksikliği Anemisi**dir; demir eksikliğinde serum **transferrin reseptör (sTfR) düzeyi düşmez, aksine belirgin artar**."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 31, "question": "Yirmi dört yaşında erkek hasta son 15 gündür başlayan yorgunluk, efor dispnesi ve\nyeni başlayan cilt ve ağız içi kanaması şikayetleri ile hastaneye başvuruyor. Fizik\nmuayenesinde solukluk, peteşi ve ekimoz izleniyor, ateş 38C olarak ölçülüyor. Lenfadenopati\nve organomegali bulunmayan hastanın göz dibi incelemesinde normokrom makrositer anemi;\ntam kan sayımında Hb: 7.2 g/dL, PLT: 40000/mm3, WBC: 1500/mm3 saptanması üzerine\nhastaya kemik iliği aspirasyonu ve biyopsisi yapılıyor ve kemik iliğinde aplazi ve yağ\ndokusunda artış görülüyor.Bu bulgulara göre bu olguda ilk düşünülmesi gereken tanı ve\netyolojik viral orjin eşleştirmelerinden hangisi doğrudur?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Aplastik anemi – Seronegatif hepatit virüsleri"}, {"letter": "B", "text": "Non-Hodgkin lenfoma - HIV"}, {"letter": "C", "text": "Miyelodisplastik sendrom – HHV8"}, {"letter": "D", "text": "Akut miyeloblastik lösemi - EBV"}, {"letter": "E", "text": "Saf eritroid aplazi – Parvovirüs B19"}], "answer": "A", "note": null, "id": "2022-2023_Q31", "explanation": "Pansitopeni ve kemik iliğinde aplazi/yağ dokusu artışıyla karakterize **Aplastik Anemi**nin viral etiyolojisinde en önemli ve ağır tablo oluşturan etken **Seronegatif (Non-A, Non-B, Non-C) hepatit virüsleri**dir."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 32, "question": "Kırk yaşında vejeteryan hasta halsizlik, yorgunluk ve hareketlerinde\nbeceriksizleşme şikayeti ile başvuruyor. Laboratuvarda Hb: 9 gr/dL, MCV: 110 fL, WBC:\n3000/mm3, PLT: 110000/mm3, LDH>660U/L, indirek bilurubin 3.2 mg/dL olarak saptanıyor.\nFizik muayenede skleralar subikterik ve konjonktivalar soluk bulunuyor, organomegali tespit\nedilmiyor.Bu hastadaki aneminin en olası nedeni aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Hipersplenizm"}, {"letter": "B", "text": "Paroksismal noktürnal hemoglobinüri"}, {"letter": "C", "text": "Vitamin B12 eksikliği"}, {"letter": "D", "text": "Aplastik anemi"}, {"letter": "E", "text": "Wilson hastalığı"}], "answer": "C", "note": null, "id": "2022-2023_Q32", "explanation": "Vejetaryan beslenme öyküsü, nörolojik bulgular (hareketlerde beceriksizlik/ataksi), makrositer pansitopeni (MCV: 110 fL) ve inefektif eritropoeze (kemik iliği içi yıkıma) bağlı yüksek LDH ve indirekt bilirubin tablosu **Vitamin B12 eksikliği (megaloblastik anemi)** için klasiktir."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 33, "question": "Herediter sferositoz ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Splenomegali beklenir."}, {"letter": "B", "text": "Hastalar en sık hemolitik anemi atağı ile başvururlar."}, {"letter": "C", "text": "Periferik yaymada sferositler görülür"}, {"letter": "D", "text": "Semptomatik hastalara splenektomi yapılır."}, {"letter": "E", "text": "En sık görülen kriz, aplastik krizdir."}], "answer": "E", "note": null, "id": "2022-2023_Q33", "explanation": "Herediter sferositozda en sık görülen kriz Parvovirüs B19'a bağlı aplastik kriz değil, enfeksiyonların tetiklediği **hemolitik krizdir** (aplastik kriz en ağır olanıdır ancak en sık olanı hemolitik krizdir)."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 34, "question": "Aşağıda verilen durumlardan hangisi intravasküler hemolize neden olur?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Herediter sferositoz"}, {"letter": "B", "text": "Paroksismal noktürnal hemoglobinüri"}, {"letter": "C", "text": "Orak hücreli anemi"}, {"letter": "D", "text": "Pirüvat kinaz eksikliği"}, {"letter": "E", "text": "Sıcak tip otoimmün hemolitik anemi"}], "answer": "B", "note": null, "id": "2022-2023_Q34", "explanation": "**Paroksismal Noktürnal Hemoglobinüri (PNH)**, CD55 ve CD59 eksikliği sonucu komplemanın eritrositleri damar içinde doğrudan parçalamasıyla **intravasküler hemolize** yol açar. Herediter sferositoz, orak hücreli anemi, pirüvat kinaz eksikliği ve sıcak tip OİHA'da ise yıkım ağırlıklı olarak ekstravaskülerdir (dalak/karaciğer)."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "Yirmi beş yaşında bayan hasta rutin kontrol amaçlı tetkiklerinde WBC: 7800/mm3,\nHb: 11 gr/dL, MCV: 68 fl, RDW normal, serum demir ve ferritin normal; hemoglobin\nelektroforezinde HbF: %0.3, HbA2: %6.8 saptanmıştır.Bu hastada en olası tanı\naşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Kronik hastalık anemisi"}, {"letter": "B", "text": "Kurşun intoksikasyonu"}, {"letter": "C", "text": "Beta talasemi minör"}, {"letter": "D", "text": "Demir eksikliği anemisi"}, {"letter": "E", "text": "Sideroblastik anemi"}], "answer": "C", "note": null, "id": "2022-2023_Q35", "explanation": "Hafif anemi, düşük MCV (68 fL), normal RDW, normal demir/ferritin ve hemoglobin elektroforezinde **HbA2'nin >%3.5 (%6.8)** olması **Beta talasemi minör (taşıyıcılığı)** tanısını koydurur."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "Aşağıdakilerden hangisi kronik lenfositik lösemisi olan bir hastada tedavi\nendikasyonu oluşturmaz?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Lenfosit sayısı 70000/mm3"}, {"letter": "B", "text": "Masif splenomegali"}, {"letter": "C", "text": "Gece terlemesi"}, {"letter": "D", "text": "Altı ay içinde vücut ağırlığının %10’undan fazla kilo kaybı"}, {"letter": "E", "text": "Aşırı yorgunluk (ECOG performans durumu>=2)"}], "answer": "A", "note": null, "id": "2022-2023_Q36", "explanation": "KLL'de **tek başına lökosit/lenfosit sayısının yüksek olması (70.000/mm³)** tedaviye başlama endikasyonu değildir! Tedavi endikasyonları: B semptomları (gece terlemesi, >%10 kilo kaybı, ateş), aşırı yorgunluk (ECOG ≥2), masif/semptomatik splenomegali veya LAP, kemik iliği yetmezliği (Hb <10, Plt <100.000) ve lenfosit ikiye katlanma süresinin <6 ay olmasıdır."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Lenfadenomegali ve nedenleri ile aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Bir cm üzerindeki lenf nodarı, tüm lenf nodu bölgeleri için patolojiktir."}, {"letter": "B", "text": "En sık lenfadenomegali saptanan lenf nodu bölgeleri baş-boyun, inguinal ve axiller lenf nodlarıdır."}, {"letter": "C", "text": "Lenf nodları, inflamatuar veya malign hücre infiltrasyonuna sekonder büyümektedir."}, {"letter": "D", "text": "Laboratuar ve fizik muayene bulguları lenfadenomegali etiolojisini saptamada klinisyene ipuçları vermektedir."}, {"letter": "E", "text": "Nedeni saptanamayan lenf nodlarından biyopsi planlanırsa, eksizyonel biyopsi tercih edilmelidir."}], "answer": "A", "note": null, "id": "2022-2023_Q37", "explanation": "Lenf nodu büyüklüğünde genel sınır 1 cm olmakla birlikte **inguinal bölgede 1.5 - 2 cm'ye kadar** olan lenf nodları fizyolojik/normal kabul edilebilir; epitroklear bölgede ise >0.5 cm patolojiktir. Bu nedenle '1 cm üzeri tüm bölgeler için patolojiktir' genellemesi yanlıştır."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "Hodgkin (HL) ve Hodgkin Dışı Lenfoma (HDL) ile ilgili aşagıdaki ifadelerden\nhangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "HL B hücreli lenfomalardır; HDL ise çoğunluğu B hücreli olmakla birlikte T hücreli lenfoma da görülebilir."}, {"letter": "B", "text": "HL’de extranodal tutulum nadirken HDL’de da extranodal tutulum daha sıktır."}, {"letter": "C", "text": "HL’de kemik iliği tutulumu görülmezken HDL’de kemik iliği tutulumu olabilir."}, {"letter": "D", "text": "HL önplanda santral lenf bezlerini tutarken HDL hem santral hem de periferik lenf bezlerini tutmaktadır."}, {"letter": "E", "text": "B semptomları her iki lenfoma tipinde de görülebilir."}], "answer": "C", "note": null, "id": "2022-2023_Q38", "explanation": "Hodgkin Lenfomada (HL) ileri evre (Evre IV) hastalıkta özellikle mikst sellüler ve lenfositten fakir alt tiplerde **kemik iliği tutulumu görülebilir**; 'HL'de kemik iliği tutulumu görülmez' ifadesi yanlıştır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 43, "id": "2023-2024_Q43"}]}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Lenfomalar ile ilgili aşağıdaki ifadelerden hangisi ya da hangileri yanlıştır?\nI. Lenfomalara lenfositlerin neoplastik klonal proliferasyonu ile karekterize heterojen\nhastalık grubudur.\nII. Çoğunlukla B lenfositten kaynaklanmakla birlikte lenfomaların %15’inde T ve B hücreli\nlenfoma birlikte bulunabilir.\nIII. Lenf düğümü (nodal) ve extranodal hastalık birlikte bulunmaz.\nIV. Ateş, kilo kaybı, gece terlemesi denilen “B semptonları” eşlik edebilir.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "I ve II"}, {"letter": "B", "text": "II ve III"}, {"letter": "C", "text": "I, III ve IV"}, {"letter": "D", "text": "I ve IV"}, {"letter": "E", "text": "II ve III"}], "answer": "E", "note": "Soru iptal edildi.", "id": "2022-2023_Q39", "explanation": "Lenfomalarda T ve B hücreli lenfomanın %15 oranında birlikte bulunması (II) ve nodal ile ekstranodal hastalığın birlikte bulunmaması (III) ifadeleri yanlıştır (B ve E şıkları aynı yazıldığı için sınavda iptal edilmiştir, cevap E: II ve III).", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 44, "id": "2023-2024_Q44"}]}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 40, "question": "Kanserde çevresel faktörlerin etkisi ile ilgili aşağıdaki ifadelerden hangisi ya da\nhangileri doğrudur?\nI. Çevresel faktörler sadece genomdaki değişikliklerle değil çeşitli epigenetik etkilerle de\nkarsinogeneze katkıda bulunabilirler.\nII. Tüm etkileri değerlendirildiğinde, çevresel faktörlerin genetik faktörlere göre\nkarsinogeneze etkileri daha fazladır.\nIII. Çeşitli karsinojen maddeler, öncelikle viral olmak üzere çeşitli enfeksiyonlar, iyonize\nradyasyon ve diyet başlıca çevresel faktörlendendir.\nIV. Asbest ve sigara akciğer kanseri için risk iken aflotoxin başta pankreas kanseri olmak\nüzere çeşitli gastrointestinal kanserlerin riskini artırmaktadır.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "I ve II"}, {"letter": "B", "text": "II ve III"}, {"letter": "C", "text": "II, III ve IV"}, {"letter": "D", "text": "I, II ve III"}, {"letter": "E", "text": "I, II, III ve IV"}], "answer": "D", "note": null, "id": "2022-2023_Q40", "explanation": "Çevresel faktörler genetik ve epigenetik mekanizmalarla karsinogenezde genetik kalıtımdan daha büyük paya sahiptir (I, II, III doğru). Ancak **aflatoksin** pankreas kanseri değil, **hepatoselüler karsinom (karaciğer kanseri)** riskini artırır (IV yanlış)."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 41, "question": "Kanser semptomatolojisi için aşağıdaki ifadelerden hangisi ya da hangileri\ndoğrudur?\nI. Kanserde görülen semptomlar çok çeşitli olabilir, özellikle erken evre kanserlerde hastalar\nasemptomatik olabilir.\nII. İleri evre-yaygın hastalıkta kanserler, Vena Cava Superior Sendromu, kranial metastaz\ngibi hayatı tehdit eden durumlara bağlı ciddi semptomlarla prezente olabilir.\nIII. Halsizlik, yorgunluk, kilo kaybı, kas kaybı; sistemik inflamasyon ile ilişkili genel\nsemptomlardır.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "Yalnız II"}, {"letter": "C", "text": "I ve II"}, {"letter": "D", "text": "I ve III"}, {"letter": "E", "text": "I, II ve III"}], "answer": "E", "note": null, "id": "2022-2023_Q41", "explanation": "Erken evre kanserler asemptomatik olabilir (I), ileri evrede VCS sendromu veya beyin metastazı gibi onkolojik acillerle başvurabilir (II) ve sistemik inflamasyona bağlı halsizlik/kilo kaybı/kaşeksi görülür (III). Üç öncül de doğrudur."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 42, "question": "Kanser, karsinogenez ve kanser sıklığı ile ilgili aşağıdaki ifadelerden hangisi ya da\nhangileri doğrudur?\nI. Kanser kontrolsüzce çoğalan ve etrafındaki dokulara saldırabilen hücrelerin olduğu\nhastalıklar için kullanılan bir terimdir.\nII. Karsinogenez, genetik ve çevresel faktörler sonucu oluşan genetik değişiklikler ile başlayıp\nçeşitli basamaklar sonucu kanser hücresi oluşumu sürecidir ve kanser türüne göre bu süreç\niçin gerekli süre değişebilmektedir.\nIII. Akciğer kanseri prevalansı yüksek kanserler arasında olsa da mortalitesi yüksek olduğu\niçin insidansı rölatif olarak daha düşüktür.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "Yalnız III"}, {"letter": "C", "text": "I ve II"}, {"letter": "D", "text": "I ve III"}, {"letter": "E", "text": "I, II ve III"}], "answer": "C", "note": null, "id": "2022-2023_Q42", "explanation": "Kanser tanımı (I) ve çok basamaklı karsinogenez süreci (II) doğrudur. Ancak akciğer kanseri insidansı (yeni vaka sıklığı) çok yüksek olan, mortalitesi yüksek olduğu için prevalansı insidansına yakın seyreden bir kanserdir; 'insidansı rölatif olarak daha düşüktür' (III) ifadesi yanlıştır."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 43, "question": "Kanser semptomatolojisi için aşağıdaki ifadelerden hangisi ya da hangileri\ndoğrudur?\nI. Kanserde görülen semptomlar çok çeşitli olabilir, özellikle erken evre kanserlerde hastalar\nasemptomatik olabilir.\nII. İleri evre-yaygın hastalıkta kanserler, Vena Cava Superior Sendromu, kranial metastaz\ngibi hayatı tehdit eden durumlara bağlı ciddi semptomlarla prezente olabilir.\nIII. Halsizlik, yorgunluk, kilo kaybı, kas kaybı; sistemik inflamasyon ile ilişkili genel\nsemptomlardır.", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "Yalnız II"}, {"letter": "C", "text": "I ve II"}, {"letter": "D", "text": "I ve III"}, {"letter": "E", "text": "I, II ve III"}], "answer": "E", "note": null, "id": "2022-2023_Q43", "explanation": "41. soru ile aynı sorudur; kanser semptomatolojisi ile ilgili I, II ve III numaralı ifadelerin tamamı doğrudur."}, {"year": "2022-2023", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 44, "question": "Splenomegali ve nedenleri ile aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Cevdet Duran", "options": [{"letter": "A", "text": "Dalak bir sekonder lenfoid organdır, filtreleme ve bağışıklık sistemi ile ilgili çeşitli fonksiyonları mevcuttur."}, {"letter": "B", "text": "Karaciğer hastalıklarında portal konjesyona sekonder splenomegali görülür."}, {"letter": "C", "text": "Splenomegali ayırıcı tanısında B semptomlar varlığında başta viral enfeksiyonlar akla gelmelidir."}, {"letter": "D", "text": "Hairy cell leukemia, KML, Primer myelofibrosis, Kala azar, Talasemi majör gibi hastalıklarda masif splenomegali görülebilir."}, {"letter": "E", "text": "Fizik muayenede hassasiyet saptanması durumunda öncelikle dalak enfaktı, enfeksiyonlar, abse ve dalak rüptürü düşünülmelidir."}], "answer": "C", "note": null, "id": "2022-2023_Q44", "explanation": "Splenomegaliye eşlik eden **B semptomları (ateş, gece terlemesi, kilo kaybı)** varlığında öncelikle viral enfeksiyonlar değil, **Lenfoma ve diğer hematolojik maligniteler** akla gelmelidir."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 45, "question": "33 yaşında bir erkekte son bir haftada, bulantı,kusma ve hafif sarılık gelişti. Fizik\nmuayenede ısı 37.4 C. Laboratuar incelemelerinde serum AST 208 U/lt, serum ALT 274\nU/lt.dir. Serolojik olarak HBsAg ve HBcAb pozitif. Karaciğer biyopsi örneğinde\nhepatositlerde fokal ölüm ve portal iltihabi hücre infiltrasyonu mevcut. Bu durumda\naşağıdaki mekanizmalardan hangisi en olası karaciğer hücre hasarına yol açmaktadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Aktive makrofajların sitokin salımı"}, {"letter": "B", "text": "HBsAg sunan hepatositlerin antikor ile hasarlanması"}, {"letter": "C", "text": "Dolaşımdaki HBsAgnin CD4+ lenfositlerce tanınması"}, {"letter": "D", "text": "MHC class1 moleküllerce sunulan viral peptidlerin CD8+ lenfositlerce tanınması"}, {"letter": "E", "text": "MHC clas II moleküllerce sunulan viral peptidlerin NK hücrelerce tanınması"}], "answer": "D", "note": null, "id": "2022-2023_Q45", "explanation": "Akut Hepatit B enfeksiyonunda karaciğer hücre (hepatosit) hasarı virüsün doğrudan sitopatik etkisinden ziyade, **enfekte hepatositlerin yüzeyindeki MHC Sınıf I molekülleriyle sunulan viral peptidlerin CD8+ sitotoksik T lenfositler (CTL) tarafından tanınarak apoptoza/nekroza uğratılması** sonucu oluşur.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 56, "id": "2023-2024_Q56"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 46, "question": "İki yatan hasta için laboratuar testleri isteniyor. Flebotomi işleminde kan örnekleri\nyanlış etiketleniyor. Ertesi gün hastalardan birisine kan transfüzyonu yapılıyor. Bir saat\niçerisinde hasta taşikardik ve hipotansif olup pembe renkli idrar çıkartıyor. Bu klinik tablo\niçin hangi mekanizma en muhtemeldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "NK hücreleri tarafından antikora bağlı hücresel sitotoksisite"}, {"letter": "B", "text": "Glomerüllerde antijen-antikor kompleksi birikimi"}, {"letter": "C", "text": "Eritrositlerin kompleman ile lizisi"}, {"letter": "D", "text": "Mast hücre degranülasyonu ve biyolojik aminlerin salınımı"}, {"letter": "E", "text": "TNF alfanın dolaşıma salınımı"}], "answer": "C", "note": null, "id": "2022-2023_Q46", "explanation": "Yanlış etiketlenmiş kan örneği nedeniyle gelişen ABO uyumsuz akut hemolitik transfüzyon reaksiyonunda (taşikardi, hipotansiyon, pembe idrar/hemoglobinüri), alıcıdaki önceden var olan IgM izohemaglütininleri verici eritrositlerine bağlanarak **kompleman sistemini (MAC) aktive eder ve intravasküler eritrosit lizisine** yol açar."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 47, "question": "24 yaşında bir kadında artan halsizlik, yüzde güneş ışığıyla artan deri lezyonları ile\nson bir ayda artralji ve myaljiler var. Fizik muayenede hafif ayak ödemi mevcut.\nOskültasyonda göğüs üzerinde sürtünme sesi işitiliyor. Laboratuar bulgularında pansitopeni\nve serum kreatini düzeyi 3 mg/dl. İdrarda hematürü ve proteinüri görülüyor. Serolojik olarak\nfalse-pozitif bir sifiliz testi saptanıyor. Böbrek biyopsisinde bazal membran ve mezangiumda\ngranüler IgG ve kompleman birikimi saptanıyor. Hastalığının patogenezinde en muhtemel\nolay hanigisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Antifosfolipid antikorlar"}, {"letter": "B", "text": "Apoptotik nukleusların defektif temizlenmesi"}, {"letter": "C", "text": "Artmış gamma interferon üretimi"}, {"letter": "D", "text": "Moleküler mimikri (taklit)"}, {"letter": "E", "text": "T hcrelerinin süperantijen le aktivasyonu"}], "answer": "B", "note": null, "id": "2022-2023_Q47", "explanation": "Malar raş (fotosensitivite), artralji, serözit, pansitopeni, yalancı pozitif sifiliz testi (antifosfolipid) ve immün kompleks nefriti olan 24 yaşındaki kadın hastada tanı **SLE (Sistemik Lupus Eritematozus)**'dur. SLE patogenezindeki temel olay **apoptotik hücre çekirdeklerinin (nükleer antijenlerin) defektif temizlenmesi** ve bunlara karşı otoantikor gelişmesidir."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 48, "question": "35 yaşında bir kadına myeloblastik lösemi neneyle allojenik hematopoitik kök hücre\ntransplantasyonu yapılıyor. Bir ay sonra deride yaygın, pullanan döküntüler gelişiyor. Ayrıca\nsarılık ve sulu diyare de mevcut. Deri biyopsisinde dermoepidermal bileşkede keratinosit\napopitozisi ve üst dermisde lenfositik infiltratlar izleniyor. aşağıdakilerden hangisi kök hücre\ntransplant komplikasyonunda rol oynayan en olası mekanizmadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut graft-versus-host hastalığı"}, {"letter": "B", "text": "Antikora bağlı hücresel sitotoksisite"}, {"letter": "C", "text": "Gecikmiş tip hipersensitivite reaksiyonu"}, {"letter": "D", "text": "İmmün kompleks oluşumu"}, {"letter": "E", "text": "Mast hücrelerinden sitokin salınımı"}], "answer": "A", "note": null, "id": "2022-2023_Q48", "explanation": "Allojenik hematopoetik kök hücre naklinden 1 ay sonra gelişen yaygın makülopapüler döküntü (deride keratinosit apoptozu), sarılık (safra kanalı hasarı) ve sulu-kanlı diyare (bağırsak kript apoptozu) triadı, verici T lenfositlerinin alıcı dokularına saldırdığı **Akut Graft-Versus-Host Hastalığı (GVHD)**'nın klasik tablosudur.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 59, "id": "2023-2024_Q59"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 49, "question": "İki yaşında bir oğlan çocuğu altı aylıktan beri devamlı enfeksiyon geçiriyor. (Otitis\nmedya, pnömoni ve impetigo gibi). Kültürde Haemophilus influenzae, Streptococcus\npneumoniae ve Staphylococcus aureus ürüyor. ayrıca diyaresi olup Giardia lamblia izlenmiş.\naile öyküsünde büyük erkek kardeşinin benzer enfeksiyonlardan öldüğü öğreniliyor. İki kız\nkardeşi ile anne ve babası normal. Bu çocukta en muhtemel olarak hangi laboratuvar bulgusu\nsaptanacaktır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "IgA yokluğu"}, {"letter": "B", "text": "Agammaglobulinemia"}, {"letter": "C", "text": "Kompleman C3de azalma"}, {"letter": "D", "text": "Yüksek titrede HIV-1 RNA"}, {"letter": "E", "text": "Pozitif ANA testi"}], "answer": "B", "note": null, "id": "2022-2023_Q49", "explanation": "6. aydan sonra (maternal IgG azalınca) başlayan tekrarlayan kapsüllü bakteri (S. pneumoniae, H. influenzae) ve Giardia enfeksiyonları ile X'e bağlı aile öyküsü (erkek kardeş ölümü) **Bruton hastalığı (X'e bağlı Agammaglobulinemi)** için tipiktir ve laboratuvarda **agammaglobulinemi** saptanır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 60, "id": "2023-2024_Q60"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 50, "question": "40 yaşında bir erkekte rutin muyene sürecinde pozitif guaiac testi saptanması\nüzerine kolonoskopi uygulanarak yukarı rektumda 0,9 cm çapında,sınırlı, saplı bir kitle\neksize ediliyor. Aşağıdaki terimlerden hangisi bu kitleyi en iyi tanımlamaktadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Adenoma"}, {"letter": "B", "text": "Karsinoma"}, {"letter": "C", "text": "Koristoma"}, {"letter": "D", "text": "hamartoma"}, {"letter": "E", "text": "Sarkoma"}], "answer": "A", "note": null, "id": "2022-2023_Q50", "explanation": "Kolonoskopide rektumda saptanan iyi sınırlı, saplı, glandüler epitel kaynaklı benign neoplastik polip **Adenoma** (tübüler/villöz adenom) olarak tanımlanır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 51, "question": "38 yaşında bir kadında son altı haftadır giderek kötüleşen abdominal distansiyon\nvar. Karın tomografisinde jejunumda 6 cm çapında bir kitlenin oluşturduğu tıkanma\ngörülüyor. Laparotomide kısmi barsak rezeksiyonu yapılıyor. Tümörün flow sitometrik\nanalizinde yüksek S faında klonal B lenfosit proliferasyonu saptanıyor. Hangi nükleer\nantijenin translokasyon sonucu aktivasyonu en muhtemeldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "APC"}, {"letter": "B", "text": "EGF"}, {"letter": "C", "text": "MYC"}, {"letter": "D", "text": "p53"}, {"letter": "E", "text": "RAS"}], "answer": "C", "note": null, "id": "2022-2023_Q51", "explanation": "İnce bağırsakta kitle oluşturan, S fazı (proliferasyon indeksi) çok yüksek klonal B hücreli lenfoma **Burkitt lenfoma** olup, karakteristik olarak t(8;14) translokasyonu sonucu **c-MYC** nükleer transkripsiyon faktörünün aktivasyonu ile gelişir."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 52, "question": "61 yaşında bir kadın son altı aydır pelvik ağırlık hissediyor. Fizik muayenede alt\nabdomende, hassas olmayan kitle palpe ediliyor. Karın ultrasonu uterus duvarında 12 cm\nçapında kitle gösteriyor.Total abdominal histerektomi uygulanıyor. Mikroskopik incelemede\niyi diferansiye leimyosarkom gözleniyor. Bir yıl sonra sağ akciğer alt lobda 4 cm kitle\nsaptanıyor. İnce iğne aspirasyon biyopsisinde az diferansiye sarkom görülüyor. Hastanın\nöyküsünde, erişkin hayatı boyunca sigara içtiği biliniyor. Bu bulguları açıklayan en iyi\nmekanizma hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Hastanın sigara içmeye devam etmesi"}, {"letter": "B", "text": "İkincil bir primer tümörün gelişmesi"}, {"letter": "C", "text": "Defektif bir Rb geni kalıtımı"}, {"letter": "D", "text": "HIV enfeksiyonu sonucu immünyetmezlik"}, {"letter": "E", "text": "Agressiv bir tümör subklonundan metastaz"}], "answer": "E", "note": null, "id": "2022-2023_Q52", "explanation": "Primer tümör iyi diferansiye leiomyosarkom iken 1 yıl sonra gelişen akciğer metastazının az diferansiye olması, tümör progresyonu sürecinde genetik instabiliteye bağlı olarak oluşan **daha agresif ve metastatik potansiyeli yüksek bir tümör alt klonundan (subklonundan) metastaz gelişmesi** ile açıklanır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 53, "question": "20. yüzyılın ikinci yarısındaki kanser ölümleri ile ilgili bir çalışma yapılmış.\nGeelişmiş uluslarda spesifik bir kanser tipinin, tarama ve önleme programları olmamasına\nrağmen azaldığı saptanmış. Bu çalışmada en muhtemel olarak hangi kanser tipi saptanmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Serebral glioma"}, {"letter": "B", "text": "Gastrik adenokarsinoma"}, {"letter": "C", "text": "Hepatik anjiosarkoma"}, {"letter": "D", "text": "Lösemi"}, {"letter": "E", "text": "Akciğerin küçük hücreli kanseri"}], "answer": "B", "note": null, "id": "2022-2023_Q53", "explanation": "20. yüzyılın ikinci yarısında gelişmiş ülkelerde özel bir tarama programı olmamasına rağmen buzdolabı kullanımının yaygınlaşması, gıdaların tuzlanması/tütsülenmesinin azalması ve H. pylori sıklığının düşmesiyle insidansı ve ölüm oranı belirgin azalan kanser **Mide (Gastrik) adenokarsinomudur**.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 67, "id": "2023-2024_Q67"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 54, "question": "55 yaşında bir kadın sol memsinde büyüen bir kitleyi bir yıldır farketmiş. Sol\nmemede 5 cm çapında, göğüs duvarına fikse, sert, düzensiz kitle saptanıyor. Sol aksillada,\nhassa olamayan lenfadenopati mevcut. Hepatosplenomegali yok. Akciğer tomografisinde,\nmultipl, bilateral \"gülle\" gibi nodüller görülüyor. Sol memeden alınan biyopside yüksek\ngrade'li infiltratif duktal kanser izleniyor. Akciğerlerindeki nodüller en muhtemel olarak\naşağıdakilerdn hangisine bağlıdır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tümörün internal mammary arteri invazyonu"}, {"letter": "B", "text": "Meme ve plevra arasındaki lenfatik bağlantılar"}, {"letter": "C", "text": "Knser hücre nukleuslarında östrojen resptörlerinin overekspresyonu"}, {"letter": "D", "text": "Meme kanserinin akciğere yakınlığı"}, {"letter": "E", "text": "Kanser hücre reseptörlerini bağlayan pulmoner kemokinler"}], "answer": "E", "note": null, "id": "2022-2023_Q54", "explanation": "Belirli kanser türlerinin belirli organlara metastaz yapma eğilimi (organ tropizmi / 'tohum ve toprak' hipotezi), kanser hücrelerinin yüzeyindeki kemokin reseptörleri (ör. meme kanserinde CXCR4 ve CCR7) ile hedef organda (akciğerde) yüksek oranda eksprese edilen **pulmoner kemokinlerin (CXCL12)** birbirine bağlanmasıyla açıklanır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 68, "id": "2023-2024_Q68"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 55, "question": "16 yaşında bir primigravid kadın gebeliğinin 18. haftasında fötal hareket\nhissetmiyor, ultrason çekiliyor. Amniotik sıvı belirgin azalmış. Fötal böbrekler kistik olup biri\ndiğerinden daha büyük. Fötal kardiak aktivite yok. Gebelik sonlandırılıp fötal otopsi\nyapılıyor. Multikistik renal displazi, hemivertebra, anal atrezi, trkeoözofageal fistül olup\nakciğerler 14 haftaya uymakta. Morfogenezdeki hangi hata fötal akciğerlerin böyle olmasına\nyol açmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Agenesis"}, {"letter": "B", "text": "Aplazi"}, {"letter": "C", "text": "Deformasyon"}, {"letter": "D", "text": "Disrupsiyon"}, {"letter": "E", "text": "Malformasyon"}], "answer": "C", "note": null, "id": "2022-2023_Q55", "explanation": "Renal agenezi veya multikistik displaziye bağlı ağır oligohidramniyos (amniyotik sıvı azlığı) sonucunda fetüsün uterus duvarı tarafından dıştan mekanik basıya uğraması ve akciğerlerin genişleyemeyerek hipoplazik kalması (Potter sekansı), ekstrensek mekanik güçlere bağlı geliştiği için bir **Deformasyon** örneğidir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 73, "id": "2023-2024_Q73"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 56, "question": "38. gebelik haftasında yenidoğan bir bebek gebelik haftasına göre küçüktür (small\nfor gestational age). Fizik muayenede microcephaly, frontal bossing, uzun ve dar alın,\nhypotelorism, maxillary ve mandibular hypoplasia, dar palpebral fissures,ince uzun philtrum,\nvermilion border of the upper lip, dental malocclusion, eyer burun, diş minesinde\nhypoplasia,ve uvular hypoplasia saptanıyor. Oküler sorunlar microphthalmia, corneal\nbulanıklık, coloboma, nystagmus, strabismus, and ptosisdir. Oskültasyonda sistolik murmur\nolup ekokardiografide membranöz ventriküler septal defekt mevcut. Aşağıdaki durumlardan\nhangisi en muhtemel olarak bunlara yol açmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Konjenital rubella"}, {"letter": "B", "text": "Fötal alkol sendromu"}, {"letter": "C", "text": "Maternal diabetes mellitus"}, {"letter": "D", "text": "Placenta previa"}, {"letter": "E", "text": "trizomi 21"}], "answer": "B", "note": null, "id": "2022-2023_Q56", "explanation": "SGA (düşük doğum ağırlığı), mikrosefali, dar palpebral fissürler, uzun ve düzleşmiş filtrum, ince üst dudak (vermilion sınırı) ve VSD gibi kardiyak defektler gebelikte teratojenik alkol maruziyetine bağlı **Fetal Alkol Sendromu**nun karakteristik bulgularıdır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 57, "question": "17 yaşında primigravid kadın, 34. haftada düşük doğum ağırlıklı oğlan çocuk\ndoğuruyor. Ekzojen sürfaktan veriliyor ve solunum güçlüğü çekmiyor. 3. günde hipotansiyon,\nkarın şişliği, barsak seslerininin olmaması yanısıra kanlı gaita dikkati çekiyor. Röntgende\npnömatozis intestinalis ve karında serbest hava bulunuyor. Barsak rezeksiyonu yapılıyor.\nAşağıdakilerden hangisi en muhtemel durumdur?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Duodenal atrezi"}, {"letter": "B", "text": "Hirschprung hastalığı"}, {"letter": "C", "text": "Meckel divertikülü"}, {"letter": "D", "text": "Mekonyum ileusu"}, {"letter": "E", "text": "Nekrotizan enterokolit"}], "answer": "E", "note": null, "id": "2022-2023_Q57", "explanation": "Prematüre ve düşük doğum ağırlıklı yenidoğanda oral beslenme sonrası gelişen karın distansiyonu, kanlı dışkılama, hipotansiyon ve radyografide bağırsak duvarında gaz (**pnömatozis intestinalis**) ile perforasyon (serbest hava) **Nekrotizan Enterokolit (NEK)** için tanısaldır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 58, "question": "6 yaşında bir çocuk, sağ uyluğunda giderek kötüleşen ağrıdan şikayet ediyor. Fizik\nmuayenede sağ inguinal bölgede şiş, ağrılı lenf bezleri saptanıyor. Lenf bezi biyopsisi yapılıyor\nve çok sayıda mitotik figür içeren, değişik boyutta germinal merkezler görülüyor. Yoğun\nparafolliküler ve sinüzoidal lökositler mevcutt. Bu değişikliklerin en muhtemel sebebi nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut lenfadenitis"}, {"letter": "B", "text": "Akut lenfoblastik lösemi"}, {"letter": "C", "text": "Kedi tırmığı hastalığı"}, {"letter": "D", "text": "Folliküler lenfoma"}, {"letter": "E", "text": "Sarkoidozis"}], "answer": "A", "note": null, "id": "2022-2023_Q58", "explanation": "Ağrılı inguinal lenf büyümesi, biyopside farklı boyutlarda aktif germinal merkezler (bol mitoz) ve sinüzoidlerde/parafoliküler alanda yoğun nötrofil infiltrasyonu drenaj bölgesindeki bakteriyel enfeksiyona ikincil gelişen **Akut nonspesifik lenfadenit** tablosudur.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 76, "id": "2023-2024_Q76"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 59, "question": "13 yaşında bir çocukta ani başlayan karın ağrısı ve kramp, göğüs ağrısı, balgamsız\nöksürük ve ateş var. Fizik muayenede ateş 39C, nabız 110/ dk, solunum 227dk ve tansiyon\n80/50 mm Hg. Yaygın abdominal hassasiyet var, ancak kitle ya da organomegali yok.\nLaboratuar çalışmalarında hemtokrit %18. Resimde periferik kan örneği görülmektedir.\nGöğüs filminde bilateral pulmoner infiltratlar mevcut. Aşağıdakilerden hangisi pulmoner\nsorunlara yolaçan mekanizmadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Pulmoner parenkimin kronik hipoksisi"}, {"letter": "B", "text": "Komplemen ın alternatif yolak aktivasyonunda defekt"}, {"letter": "C", "text": "Endotele yaygın eritrosit adhezyonu"}, {"letter": "D", "text": "Alveol bazal membranına otoantiko oluşumu"}, {"letter": "E", "text": "İntravasküle antikola oluşan hemolizis"}], "answer": "C", "note": null, "id": "2022-2023_Q59", "explanation": "Orak hücreli anemi hastasında ateş, göğüs ağrısı, öksürük ve akciğerde bilateral infiltratlarla karakterize **Akut Göğüs Sendromu**nun temel mekanizması, oraklaşmış eritrositlerin ve retikülositlerin pulmoner mikrovasküler **endotele yaygın adezyonu** ve vazo-oklüzyon oluşturmasıdır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 60, "question": "23 yaşında bir afrikan-amerikan erkek, fenasetin içeren bir antiinflamatuar ilaç\naldıktan sonra koyu kırmızı-kahverengi idrar çıkartıyor. Tüm hayatı boyunca sağlıklı olduğu\niçin şaşırıyor. Fizik mayenede ateşi yok, kaydadeğer bir bulgu saptanmıyor. Kanda hafif\nnormositik anemi saptanıyor; ancak periferik kanda supravital boyama ile Heinz cisimcikleri\n(denatüre globin) ile ısırı \"bite\" hücreleri gözleniyor. En muhtemel tanı hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Alfa talassemi minör"}, {"letter": "B", "text": "Beta talassemi minör"}, {"letter": "C", "text": "Glükoz-6-fosfat-dehidrojenaz yetmezliği"}, {"letter": "D", "text": "orak hücre trait (sickle cell trait)"}, {"letter": "E", "text": "Sıcak antikor otoimmün hemolitik anemisi"}], "answer": "C", "note": null, "id": "2022-2023_Q60", "explanation": "Oksidan bir ilaç (fenasetin, primakin, sülfonamid) alımı sonrası gelişen akut intravasküler hemoliz (koyu idrar) ve periferik yaymada supravital boyamayla **Heinz cisimcikleri** ile **ısırık (bite) hücrelerinin** görülmesi **Glukoz-6-Fosfat Dehidrogenaz (G6PD) eksikliği** için tanısaldır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 74, "id": "2023-2024_Q74"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 61, "question": "İnfarktüs, nekroz ve şok ile ilgili aşağıda verilen bilgilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "İnfarktüs bir dokunun vasküler beslenmesinin kesilmesi ile oluşan iskemik nekroz alanıdır ve pulmoner infarktüs sık görülen bir komplikasyondur."}, {"letter": "B", "text": "İnfarktüsler renklerine göre ve mikrobiyal infeksiyon varlığı veya yokluğuna göre kırmızı /hemorajik veya beyaz /anemik ve septik veya aseptik olarak sınıflandırılır"}, {"letter": "C", "text": "Kırmızı infarktüsler; Akciğer ve ince barsak gibi çift dolaşımlı dokularda oluşur"}, {"letter": "D", "text": "Beyin bu genellemelerin istisnasını oluşturur: Merkezi sinir sisteminde iskemik doku hasarı likefaksiyon nekrozu ile sonuçlanır"}, {"letter": "E", "text": "Şok; kardiyak outputun ve/veya dolaşımdaki etkin kan hacminin azalması sonucu meydana gelen sistemik doku hiperperfüzyonu durumudur"}], "answer": "E", "note": null, "id": "2022-2023_Q61", "explanation": "Şok, sistemik doku **hipoperfüzyonu** durumudur; E şıkkında 'hiperperfüzyonu' denildiği için yanlıştır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 70, "id": "2019-2020_Q70"}, {"kurul": "1", "year": "2020-2021", "q_num": 55, "id": "2020-2021_Q55"}, {"kurul": "1", "year": "2021-2022", "q_num": 71, "id": "2021-2022_Q71"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 62, "question": "Tromboemboli ve amiloidoz ile ilgili aşağıdaki belirtilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Trombüs oluşumuna yol açan nedenler; (Virchow triadı) ; Endotel hasarı, Staz veya türbülan kan akımı, Kanın hiperkoagulabilitesidir."}, {"letter": "B", "text": "Arteryel trombüsler, en sık olarak sırasıyla koronerler, serebral arterler ve femoral arterlerde gelişir"}, {"letter": "C", "text": "Venöz tromboz /flebotromboz sıklıkla kalbe doğru bir miktar büyür ve emboliye eğilimli damar lümeninde uzun bir kitle oluşturur, en sık alt ekstremitelerin venleri etkilenir"}, {"letter": "D", "text": "AL amiloidi; B hücre diskrazisi ile birlikte bulunur, Aβ Amiloid; Alzheimer hastalarında serebral plak ve kan damarlarında depolanır"}, {"letter": "E", "text": "İmmunosit diskrazileri ile birlikte olan amiloidozlar; Multipl miyeloma, Monoklonal gammopati, Diğer B hücre neoplazmları ile beraberdir ve Aβ Amiloid depolanması vardır."}], "answer": "E", "note": null, "id": "2022-2023_Q62", "explanation": "Multipl miyelom ve B hücre diskrazilerinde biriken amiloid Aβ değil, **AL amiloididir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 79, "id": "2019-2020_Q79"}, {"kurul": "1", "year": "2020-2021", "q_num": 56, "id": "2020-2021_Q56"}, {"kurul": "1", "year": "2021-2022", "q_num": 72, "id": "2021-2022_Q72"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 63, "question": "İnflamasyon mediyatörleri ile ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Kronik iltihabın mediatörleri; lenfosit, makrofaj, plazma hücresi, eozinofil, mast hücreleridir"}, {"letter": "B", "text": "Kanda monositlerin yarılanma ömrü 1 gündür, doku makrofajları ise aylarca yaşayabilirler."}, {"letter": "C", "text": "Asit ve nötral proteazlar: doku hasarı, kompleman komponentleri ve koagülasyon faktörlerinin lokal miktarı artar, reaktif oksijen ürünleri ve NO doku hasarı yapar"}, {"letter": "D", "text": "IL-1, IFN-γ dev hücre oluşumunu sağlar, özellikle IFN-γ makrofajların epiteloid histiositlere ve dev hücrelere dönüşümünde önemlidir"}, {"letter": "E", "text": "T lenfositlerden ; IL1, TNF ve kemokinler salgılanır ve Makrofajları uyarır, Makrofajlardan IFN gama salgılanır ve T lenfositleri uyarır"}], "answer": "E", "note": null, "id": "2022-2023_Q63", "explanation": "Kronik inflamasyonda T lenfositler IFN-γ salgılayarak makrofajları uyarır; makrofajlar ise IL-1 ve TNF salgılar (E şıkkında ters verilmiştir).", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 71, "id": "2019-2020_Q71"}, {"kurul": "1", "year": "2021-2022", "q_num": 73, "id": "2021-2022_Q73"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 65, "question": "Kaşekside ön planda rol oynayan aşağıdakilerden hangisidir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "IL – 8"}, {"letter": "B", "text": "TNF α"}, {"letter": "C", "text": "IFN α"}, {"letter": "D", "text": "IL – 6"}, {"letter": "E", "text": "PAF"}], "answer": "B", "note": null, "id": "2022-2023_Q65", "explanation": "Kaşekside ön planda rol oynayan temel sitokin **TNF-α**'dır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 73, "id": "2019-2020_Q73"}, {"kurul": "1", "year": "2020-2021", "q_num": 58, "id": "2020-2021_Q58"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 68, "question": "Malign tümör derecelendirmesinde hangisi kullanılır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenf düğümü metastazı sayısı"}, {"letter": "B", "text": "Tümör çapı"}, {"letter": "C", "text": "Tümörün çevre dokuya invazyonu"}, {"letter": "D", "text": "Tümörün sitolojik diferansiasyon derecesi"}, {"letter": "E", "text": "Karaciğer metastazının varlığı / yokluğu"}], "answer": "D", "note": null, "id": "2022-2023_Q68", "explanation": "Malign tümör derecelendirmesinde (Grading) **tümörün sitolojik diferansiasyon derecesi** kullanılır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 69, "id": "2019-2020_Q69"}, {"kurul": "1", "year": "2020-2021", "q_num": 60, "id": "2020-2021_Q60"}, {"kurul": "1", "year": "2021-2022", "q_num": 80, "id": "2021-2022_Q80"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 69, "question": "Lenfoma / lösemilerle ilgili aşağıdaki yargılardan hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "En sık mutasyona uğrayan transkripsiyon faktörü genleri, B hücre kökenli A LL’lerde T E Lİ, AML1, E2A, PAX5 ve EBE’dir"}, {"letter": "B", "text": "KLL/SLL yavaş büyüyen ve yavaş ilerleyen bir tümördür ve tümör hücrelerinde, apoptozu engelleyen bir protein olan BCL2 seviyeleri çok yüksektir"}, {"letter": "C", "text": "KLL/SLL, pan-B belirteçleri olan CD19, CD20 ve CD23'ü ve yüzey immunglobülinleri mevcuttur ve tümör hücreleri ayrıca CD5'de eksprese ederler"}, {"letter": "D", "text": "Multipl Myelomda, MYC proto-onkogeni ilgilendiren translokasyonu saptanmıştır ve Tümör hücreleri sıklıkla Epstein-Barr virüsü ile latent olarak enfektedir"}, {"letter": "E", "text": "Diffüz Büyük B Hücreli Lenfoma; BCL6 geninde yeniden düzenlenmeler ya da mutasyonlar belirlenmiştir. Bu tümörlerin üçte biri folliküler lenfomadan kaynaklanır ve BCL2 ile ilişkili (14;18) translokasyonu mevcuttur"}], "answer": "D", "note": null, "id": "2022-2023_Q69", "explanation": "MYC translokasyonu ve EBV ile latent enfeksiyon Multipl Myelom'un değil, **Burkitt Lenfoma**'nın özelliğidir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 76, "id": "2019-2020_Q76"}, {"kurul": "1", "year": "2020-2021", "q_num": 64, "id": "2020-2021_Q64"}, {"kurul": "1", "year": "2021-2022", "q_num": 81, "id": "2021-2022_Q81"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 70, "question": "Hodgkin ve Non Hodgkin lenfomalarla ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Hodgkin lenfomanm olmazsa olm az özelliği Reed Sternberg hücresidir."}, {"letter": "B", "text": "Noduler skleroz Hodgkin lenfoma en sık görülen formdur. Özel bir RS hücre varyantı olan laküner hücre sık görülür."}, {"letter": "C", "text": "Non-Hodgkin Lenfomada; Tek bir aksiyal nod grubunda lokalize olma daha sıktır, komşuluk yoluyla düzenli yayılım, mezenterik nodlar ve Waldeyer halkası tutulumu seyrektir,"}, {"letter": "D", "text": "Mikst sellüler Hodgkin lenfomada, morfolojik olarak k çük lenfositler, eozinofiller, plazma hücreleri ve makrofajlardan oluşan heterojen bir inflamatuar infiltrasyon içinde çok sayıda RS hücresi bulunur"}, {"letter": "E", "text": "Lenfositten baskın Hodgkin lenfomada. Patlamış mısıra benzeyen multilobe ve şişkin nükleusa sahip lenfohistiyositik (L&H) varyant RS hücrelerinin varlığı ile karakterizedir."}], "answer": "C", "note": null, "id": "2022-2023_Q70", "explanation": "Tek bir aksiyal lenf nodu grubunda lokalize olma ve komşuluk yoluyla düzenli yayılım Non-Hodgkin Lenfomanın değil, **Hodgkin Lenfoma**'nın özelliğidir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 77, "id": "2019-2020_Q77"}, {"kurul": "1", "year": "2020-2021", "q_num": 65, "id": "2020-2021_Q65"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 71, "question": "Lenfoma ve lösemilerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Lenfoblastik Lösemi; Lenfoblastik lösemi, ince, saç benzeri sitoplazmik çıkıntılar içeren lösemik hücrelerin varlığı ile karakterize, az gör len, yavaş seyirli bir B hücreli lenfomadır."}, {"letter": "B", "text": "Foiliküler Lenfomada; çoğu olguda, BCL2 over ekspresyonuna yol açan (14;18) translokasyonu vardır"}, {"letter": "C", "text": "Mantle H ücreli Lenfoma; Hücre siklusunun ilerlemesinde düzenleyici rol oynayan siklin D1’in overekspresyonu ile sonuçlanan (11 ;14) translokasyonu ile ilişkilidir."}, {"letter": "D", "text": "Burkitt lenfoma, kromozom 8 ’de localize MYC genini ilgilendiren tranlokasyonlar içerir."}, {"letter": "E", "text": "Mikozis Fungoides ve Sezary Sendromu; Neoplastik CD4+ T hücrelerinin tümörleri olan bu tümörler deride yuvalanırlar."}], "answer": "A", "note": null, "id": "2022-2023_Q71", "explanation": "Saç benzeri sitoplazmik çıkıntılar içeren yavaş seyirli B hücreli tümör Lenfoblastik Lösemi değil, **Tüylü Hücreli Lösemi (Hairy Cell Leukemia)**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 78, "id": "2019-2020_Q78"}, {"kurul": "1", "year": "2020-2021", "q_num": 66, "id": "2020-2021_Q66"}, {"kurul": "1", "year": "2021-2022", "q_num": 74, "id": "2021-2022_Q74"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 72, "question": "Germinal merkez B hücrelerinden köken alan non-Hodgkin lenfoma\naşağıdakilerden hangisidir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Mantle hücreli lenfoma"}, {"letter": "B", "text": "Mikozis fungoides"}, {"letter": "C", "text": "Lenfoblastik lenfoma"}, {"letter": "D", "text": "Foliküler lenfoma"}, {"letter": "E", "text": "Küçük lenfositik lenfoma"}], "answer": "D", "note": null, "id": "2022-2023_Q72", "explanation": "Lenf düğümünün **germinal merkez B hücrelerinden (sentrosit ve sentroblastlardan)** köken alan ve BCL2 pozitifliği gösteren non-Hodgkin lenfoma **Foliküler lenfoma**dır (Diffüz büyük B hücreli lenfoma ve Burkitt lenfoma da germinal merkez kökenlidir)."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 73, "question": "Kimyasal mediatörlerle ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Bradikinin; Vasküler permeabiliteyi artırır, arterioler dilatasyon ve brokokonstrüksiyon yapar."}, {"letter": "B", "text": "Kompleman sisteminde; Klasik yol, Antijen antikor kompleksi ile karşılaşma (C1 üzerinden), alternatif yol, Mikrobial yüzeyle temas, Lektin yolağı, Mannoz bağlayıcı lektinin direk C1’e bağlanması ile olur."}, {"letter": "C", "text": "Serotonin; Trombosit agregasyonu ile salınımı uyarılır ve vazokonstrüksiyona neden olur."}, {"letter": "D", "text": "TxA2; trombositlerde üretilir, trombosit agregasyonu ve vazokonstrüksiyon yapar."}, {"letter": "E", "text": "PGI2; vazokonstriksiyon sağlar, trombosit agregasyonnu inhibe eder."}], "answer": "E", "note": null, "id": "2022-2023_Q73", "explanation": "**PGI2 (Prostasiklin)** vazokonstrüksiyon değil, **vazodilatasyon** yapar ve trombosit agregasyonunu inhibe eder.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 68, "id": "2020-2021_Q68"}, {"kurul": "1", "year": "2021-2022", "q_num": 82, "id": "2021-2022_Q82"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 74, "question": "Aşağıdaki immünohistokimyasal belirleyicilerden hangisi, lenfosit predominant\nHodgkin hastalığında görülen Reed-Sternberg hücrelerinde karakteristik olarak pozitiftir?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "CD 1"}, {"letter": "B", "text": "CD 3"}, {"letter": "C", "text": "CD 15"}, {"letter": "D", "text": "CD 20"}, {"letter": "E", "text": "CD 30"}], "answer": "D", "note": null, "id": "2022-2023_Q74", "explanation": "Lenfosit predominant Hodgkin lenfomada görülen L&H (popcorn) hücrelerinde B hücre belirteci **CD20** pozitiftir.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 62, "id": "2020-2021_Q62"}, {"kurul": "1", "year": "2021-2022", "q_num": 83, "id": "2021-2022_Q83"}]}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 75, "question": "Akut inlamasyonda görülen, aşağıdaki değişiklilerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Vasodilatasyon"}, {"letter": "B", "text": "Vasküler permeabilitedeki artım"}, {"letter": "C", "text": "Lökositlerin emigrasyonu"}, {"letter": "D", "text": "Lökosit inaktivasyonu"}, {"letter": "E", "text": "Lökositik eksüdasyon"}], "answer": "D", "note": null, "id": "2022-2023_Q75", "explanation": "Akut inflamasyonda vazodilatasyon, vasküler permeabilite artışı, lökosit emigrasyonu ve lökosit aktivasyonu/eksüdasyonu görülür; **lökosit inaktivasyonu** görülmez."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 76, "question": "Hemostaz ve Tromboz ile ilgili aşağıdaki verilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Virchow triadı; endotel hasarı, kan akımında yavaşlama ve çalkantılı akımlar (anafor akımlar) ve kanın pıhtılaşma eğiliminin artması"}, {"letter": "B", "text": "Kalpte ve Aortada gelişen trombüslerde makroskopik ve mikroskopik olarak seçilebilen ZAHN çizgileri denen tabakalaşma vardır"}, {"letter": "C", "text": "Venöz Tromboz (Flebotromboz); çoğunluğu yüzeyel veya derin bacak venlerinde oluşur"}, {"letter": "D", "text": "Pulmoner embolilerin %60-80’i büyük çaplıdır ve ciddi klinik bulgu verir"}, {"letter": "E", "text": "Yaygın kanserli hastalarda gezici tromboflebit yada TROUSSEAU SENDROMU neden tromboembolik risk artışı vardır"}], "answer": "D", "note": null, "id": "2022-2023_Q76", "explanation": "Pulmoner embolilerin **%60-80'i küçük çaplıdır ve klinik olarak sessiz (asemptomatik)** seyreder; 'büyük çaplıdır ve ciddi klinik bulgu verir' ifadesi yanlıştır."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 77, "question": "Kimyasal mediatörlerle ilgili aşağıda verilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Vazodilatasyon yapanlar; Prostaglandinler, histamine, Nitric oksit"}, {"letter": "B", "text": "Yeni sentezlenenler; Prostaglandinler, lökotrienler, PAF, NO, aktive oksijen, sitokinler"}, {"letter": "C", "text": "Sekretuar granüllerde olanlar; Histamin, seratonin, lizozomal enzimler"}, {"letter": "D", "text": "Karaciğerde sentez edilerek plazmaya verilenler; kinin sistemi, pıhtılaşma sistemi, kompleman sistemi"}, {"letter": "E", "text": "Ağrı yapanlar; IL-1, TNF"}], "answer": "E", "note": null, "id": "2022-2023_Q77", "explanation": "Akut inflamasyonda **ağrı** oluşturan başlıca mediyatörler IL-1 ve TNF değil, **Bradikinin ve Prostaglandinler (PGE2)**'dir (IL-1 ve TNF ise ateş ve akut faz yanıtından sorumludur)."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 78, "question": "Lenfoid folliküler hiperplazi ile ilgili aşağıdaki verilenlerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "Germinal merkezlerde belirgin fagositik ve mitotik aktivite"}, {"letter": "B", "text": "Germinal merkezlerde lenfositlerin farklı şekil ve boyutlarda olması"}, {"letter": "C", "text": "Germinal merkezlerin şekil be boyutlarında çeşitlilik"}, {"letter": "D", "text": "Mitoz azdır ve tek başına nekrotik hücreler (apopİtoza giden hücreler) yoktur."}, {"letter": "E", "text": "Lenf nodu yapısı korunmuştur"}], "answer": "D", "note": null, "id": "2022-2023_Q78", "explanation": "Reaktif lenfoid folliküler hiperplazide germinal merkezlerde **mitotik aktivite yüksektir ve çok sayıda apoptotik/nekrotik hücre ile bunları fagosite eden tingible body makrofajları bulunur**. 'Mitoz azdır ve apoptotik hücre yoktur' ifadesi folliküler lenfoma özelliğidir."}, {"year": "2022-2023", "subject": "Patoloji", "q_num": 79, "question": "Aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "LTC4, D4, E4; Bronkokonstrüksiyon, vazokonstrüksiyon yapar"}, {"letter": "B", "text": "LTB4; Lökosit adezyon ve aktivasyonu yapar"}, {"letter": "C", "text": "C5a; Lökosit adezyonu, inaktivasyonu yapar"}, {"letter": "D", "text": "PAF; Bronkokonstrüksiyon, lökosit başlatıcısı"}, {"letter": "E", "text": "Nitrik oksid; Vazodilatasyon, sitotoksisite yapar"}], "answer": "C", "note": null, "id": "2022-2023_Q79", "explanation": "**Kompleman C5a** lökosit inaktivasyonu değil, güçlü **lökosit kemotaksisi, aktivasyonu**, adezyon artışı ve mast hücre degranülasyonu (anaflatoksin) yapar."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 80, "question": "Aşağıdaki laboratuvar bulgulardan hangisi demir eksikliği anemisini destekleyici\ndeğildir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Demir bağlama kapasitesi artar"}, {"letter": "B", "text": "Ferritin azalır"}, {"letter": "C", "text": "Retikülosit azalır"}, {"letter": "D", "text": "RDW azalır"}, {"letter": "E", "text": "Transferrin doygunluğu azalır"}], "answer": "D", "note": null, "id": "2022-2023_Q80", "explanation": "Demir eksikliği anemisinde anizositoz (farklı boyutlarda eritrositler) geliştiği için **RDW (eritrosit dağılım genişliği) azalmaz, belirgin olarak artar**."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 81, "question": "Aşağıdakilerden hangisi apoptozisi arttıran bir gen olup bozulması tümörün agresif\nve malign seyrine neden olur?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Bcl-xl"}, {"letter": "B", "text": "Bcl -2"}, {"letter": "C", "text": "myc"}, {"letter": "D", "text": "p53"}, {"letter": "E", "text": "CDK"}], "answer": "D", "note": null, "id": "2022-2023_Q81", "explanation": "**p53** tümör baskılayıcı geni DNA hasarı varlığında BAX ve PUMA'yı uyararak **apoptozisi artıran** bir gendir; mutasyonu/kaybı durumunda hücreler apoptozdan kaçar ve tümör agresif/tedaviye dirençli seyreder. (Bcl-2 ve Bcl-xL ise anti-apoptotiktir)."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 82, "question": "Aşağıdakilerden hangisi özellikle kolorektal kanserlerde yükselen onkofetal tür bir\ntümör belirteçtir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "CA 19.9"}, {"letter": "B", "text": "CA 72.4"}, {"letter": "C", "text": "CEA"}, {"letter": "D", "text": "AFP"}, {"letter": "E", "text": "CA 19.5"}], "answer": "C", "note": null, "id": "2022-2023_Q82", "explanation": "Özellikle **kolorektal karsinomlarda** (ve mide, pankreas, meme, akciğer kanserlerinde) yükselen onkofetal glikoprotein yapılı tümör belirteci **CEA (Karsinoembriyonik Antijen)**'dir."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 83, "question": "45 yaşında halsizlik ve ellerinde uyuşma şikayeti ile gelen bir kadın hasta, alınan\nanemnezinde yoğun çalıştığından beslenme düzeninin iyi olmadığını ve peptik ülseri sebebiyle\nher gün proton pompa inhibitörü kullandığını belirtiyor. yapılan fizik muayenesinde derin\ntendon reflekslerinde azalma saptanıyor. laboratuvar tetkiklerinde tam kan sayımı; WBC:\n4350 (6000-10000/mm3), RBC: 2,3*106 (4,5*106-5,5*106), Hb: 11g/dL, MCV: 111 fl, MCH:\n23,6 pg, RDW: %13,6, PLT: 135.000/mm3. Periferik yaymasında hipersegmente nötrofiller ve\nbazofilik lekelenme saptanıyor.Yukarıdaki hasta ile ilgili ayırıcı tanıda aşağıdakilerden\nhangisi ilk düşünmeniz gereken unsurlardandır?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Orak Hücre anemisi"}, {"letter": "B", "text": "Kemik iliği yetmezliği"}, {"letter": "C", "text": "Beta talasemi taşıyıcılığı"}, {"letter": "D", "text": "B12 vitamin eksikliği"}, {"letter": "E", "text": "Sideroblastik anemi"}], "answer": "D", "note": null, "id": "2022-2023_Q83", "explanation": "Düzensiz beslenme ve uzun süreli PPI (mide asit baskılayıcı) kullanımı öyküsü, nöropati (uyuşma, DTR azalması), makrositer anemi (MCV: 111 fL) ve periferik yaymada **hipersegmente nötrofiller** doğrudan **Vitamin B12 eksikliği (megaloblastik anemi)** tanısını gösterir."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 84, "question": "Aşağıdaki tümör belirteçlerinden hangisi asemptomatik bireylerde kanser erken\ntanısını sağlamak için yardımcı olabilir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "CEA"}, {"letter": "B", "text": "CA 19.9"}, {"letter": "C", "text": "AFP"}, {"letter": "D", "text": "PSA"}, {"letter": "E", "text": "Tiroglobulin"}], "answer": "D", "note": null, "id": "2022-2023_Q84", "explanation": "Tümör belirteçleri içinde organ özgüllüğü yüksek olduğu için **prostat kanseri erken tanısında/taramasında** (tuşe ile birlikte) kullanılan belirteç **PSA (Prostat Spesifik Antijen)**'dir."}, {"year": "2022-2023", "subject": "Biyokimya", "q_num": 85, "question": "Kanın pıhtılaşma zamanında uzama ile birlikte kanamaya eğilim gösteren,\nerkeklerde görülen, kadınlar tarafından taşınan herediter karakterli, ömür boyu devam eden\nhastalıktır. Aşağıdakilerden hangi şıkta bu hastalık ve eksik olan faktör doğru olarak\nverilmiştir*", "professor": "Ayşe Özdemir", "options": [{"letter": "A", "text": "Von-Willebrand-Fak VIII eksikliği"}, {"letter": "B", "text": "K Vitamini eksikliği-Faktör-II,VII,IX,X eksikliği"}, {"letter": "C", "text": "Non trombositopenik purpuralar-lökosit eksikliği"}, {"letter": "D", "text": "Tromboasteni- Trombosit eksikliği"}, {"letter": "E", "text": "Hemofili A- Faktör- VIII eksikliği"}], "answer": "E", "note": null, "id": "2022-2023_Q85", "explanation": "X'e bağlı resesif kalıtılan (kadınların taşıyıcı olup erkeklerde görülen) ve pıhtılaşma zamanı/aPTT uzamasıyla seyreden hastalık **Hemofili A — Faktör VIII eksikliği**dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 87, "id": "2019-2020_Q87"}]}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 86, "question": "İmmün sistemi baskılanmış bireylerde özellikle böbrek hastalığına ve ilerleyici\nmultifokal lökoensefalopatiye (PML) neden olan virüs grubu aşağıdakilerden hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Polyomaviridae"}, {"letter": "B", "text": "Papillomaviridae"}, {"letter": "C", "text": "Herpesviridae"}, {"letter": "D", "text": "Retroviridae"}, {"letter": "E", "text": "Onikoviridae"}], "answer": "A", "note": null, "id": "2022-2023_Q86", "explanation": "İmmünsüpresif bireylerde böbrek nakli nefropatisi/hemorajik sistit (**BK virüs**) ve ilerleyici multifokal lökoensefalopati - PML (**JC virüs**) tablolarına yol açan zarfsız DNA virüsü ailesi **Polyomaviridae**'dir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 87, "id": "2023-2024_Q87"}]}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 87, "question": "Humanpapillomavirüs (HPV) tiplerinin hangi özelliği, farklı hastalık tabloları\nyapmasına neden olur", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Dokuya özgü olması"}, {"letter": "B", "text": "Hücreye özgü olması"}, {"letter": "C", "text": "T helper'a (CD4) özgü olması"}, {"letter": "D", "text": "B lenfosite özgü olması"}, {"letter": "E", "text": "Bağımsız olması"}], "answer": "A", "note": null, "id": "2022-2023_Q87", "explanation": "Human Papillomavirus (HPV) tiplerinin deri veya mukozanın farklı bölgelerinde farklı klinik tablolar (siğil, kondilom, serviks kanseri) oluşturmasının temel nedeni **dokuya (epitel tipine) özgü tropizm** göstermeleridir."}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 88, "question": "Tanısında virüse karşı oluşmuş özgül antikorların \"enzim linked immunosorbant\nassay\" (ELISA) yöntemi veya partikül aglutinasyon ile saptanması ve “Western blot’’ (WB)\nyöntemi ile doğrulanması ile konulan virüs hangisi olabilir", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Human T Cell Lymphotropic Virus (1 ve 2)"}, {"letter": "B", "text": "Herpes virüs (1 ve 2)"}, {"letter": "C", "text": "Sitomegalovirüs (CMV)"}, {"letter": "D", "text": "Humanpapillomavirüs (HPV)"}, {"letter": "E", "text": "Epstein-Barr virüs"}], "answer": "A", "note": null, "id": "2022-2023_Q88", "explanation": "Retrovirüs ailesinden olan **HTLV-1 ve HTLV-2** (HIV'de olduğu gibi) tanısında tarama testi olarak ELISA/partikül aglütinasyonu ve doğrulama testi olarak **Western Blot (WB)** yöntemi kullanılır."}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 89, "question": "Human T Cell Lymphotropic Virus-1 (HTLV-1)'in etken olduğu düşünülen\nhastalığın özel ismi aşağıdakilerden hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Sezary T-cell leukemia (T hücre lösemisi)"}, {"letter": "B", "text": "Saçlı T-cell leukemia (T hücre lösemisi)"}, {"letter": "C", "text": "Baykuş gözü T-cell leukemia (T hücre lösemisi)"}, {"letter": "D", "text": "Hairy cell leukemia"}, {"letter": "E", "text": "Kaposi sarkomu"}], "answer": "A", "note": null, "id": "2022-2023_Q89", "explanation": "HTLV-1 erişkin T hücreli lösemi/lenfoma (ATLL - yonca yaprağı/çiçek hücreli) etkenidir; Serdar Güngör hocanın ders notunda ve sınav anahtarında A şıkkı (**Sezary T-cell leukemia / T hücre lösemisi**) doğru cevap olarak kabul edilmiştir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 88, "id": "2023-2024_Q88"}]}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Aşağıdakilerden hangisi Alfaherpesvirüs ailesinde değildir", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Herpes simpleks virüs 1(HSV 1)"}, {"letter": "B", "text": "Herpes simpleks virüs 2(HSV 2)"}, {"letter": "C", "text": "Varisella zoster virüs (VZV)"}, {"letter": "D", "text": "Herpes B"}, {"letter": "E", "text": "Cytomegalovirus (CMV)"}], "answer": "E", "note": null, "id": "2022-2023_Q90", "explanation": "Alfaherpesvirinae alt ailesinde HSV-1, HSV-2, VZV (HHV-3) ve Herpes B virüsü yer alır. **Sitomegalovirüs (CMV / HHV-5)** ise **Betaherpesvirinae** alt ailesindedir."}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 91, "question": "Girip İnfekte ettiği hücrede balonlaşma, Cowdry tip A intranükleer inklüzyon\ncisimcikleri, kromatin marginasyonu, multinükleer dev hücre oluşması karakteristik olan\nvirüs hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Human Herpes Virüs (HSV)"}, {"letter": "B", "text": "Adenovirüs"}, {"letter": "C", "text": "Coronavirüs"}, {"letter": "D", "text": "Retrovirüs"}, {"letter": "E", "text": "Human Papilloma Virüs (HPV)"}], "answer": "A", "note": null, "id": "2022-2023_Q91", "explanation": "Enfekte epitel hücrelerinde balonlaşma dejenerasyonu, kromatin marjinasyonu, **Cowdry tip A eozinofilik intranükleer inklüzyon cisimcikleri** ve **multinükleer dev hücreler (Tzanck hücreleri)** oluşturan virüs **Human Herpes Simplex Virüs (HSV)** (ve VZV)'dir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 89, "id": "2023-2024_Q89"}]}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 92, "question": "Flukonazol tedavisine rağmen tekrarlayan vajinal kandidiyazis şikayeti ile başvuran\nkadın hastada en olası fungal etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Candida krusei"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Candida tropicalis"}, {"letter": "D", "text": "Candida dubliniensis"}, {"letter": "E", "text": "Candida parapsilosis"}], "answer": "A", "note": null, "id": "2022-2023_Q92", "explanation": "**Candida krusei**, flukonazole **doğal (intrinsik) dirençli** bir maya mantarıdır; bu nedenle flukonazol tedavisine yanıtsız tekrarlayan kandidiyazis olgularında öncelikle akla gelmelidir."}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 93, "question": "Organ transplantasyonu sonrasında yüksek ateş ve baş ağrısı şikayetleri nedeniyle\nlomber ponksiyon yapılan hastada beyin omurilik sıvısında gerçek ya da yalancı hif\nyapmayan, kapsüllü maya hücreleri görülmüştür. En olası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Cryptococcus neoformans"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Rhizopus spp."}, {"letter": "D", "text": "Candida tropicalis"}, {"letter": "E", "text": "Aspergillus fumigatus"}], "answer": "A", "note": null, "id": "2022-2023_Q93", "explanation": "Organ nakli (immünsüpresif) hastasında menenjit yapan ve BOS'ta **gerçek veya yalancı hif oluşturmayan, geniş polisakkarit kapsüllü** tomurcuklanan maya hücreleri olarak görülen etken **Cryptococcus neoformans**'tır."}, {"year": "2022-2023", "subject": "Mikrobiyoloji", "q_num": 94, "question": "Hepatit ve karaciğer kanserine neden olabilen, özellikle Aspergillus flavus ile\nkontamine tahıllarda karşımıza çıkan mikotoksin aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aflatoksin"}, {"letter": "B", "text": "Fumonizin"}, {"letter": "C", "text": "Okratoksin"}, {"letter": "D", "text": "Ergot alkaloitleri"}, {"letter": "E", "text": "Sitrinin"}], "answer": "A", "note": null, "id": "2022-2023_Q94", "explanation": "*Aspergillus flavus* ile kontamine tahıllarda bulunan ve karaciğer kanserine (HCC) yol açan mikotoksin **Aflatoksin**dir.", "repeats": [{"kurul": "1", "year": "2021-2022", "q_num": 96, "id": "2021-2022_Q96"}]}, {"year": "2022-2023", "subject": "Radyoloji", "q_num": 95, "question": "Hangi görüntüleme yöntem(ler)inde insan vücudunun enerji ile etkileşimi emisyon\n(salım) aracılığıyla meydana gelmektedir?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Bilgisayarlı tomografi,radyografi"}, {"letter": "B", "text": "Ultrasonografi"}, {"letter": "C", "text": "PET-BT,manyetik rezonans"}, {"letter": "D", "text": "Radyografi,ultrasonografi"}, {"letter": "E", "text": "Manyetik rezonans,bilgisayarlı tomografi"}], "answer": "C", "note": null, "id": "2022-2023_Q95", "explanation": "Röntgen ve BT'de transmisyon (geçiş), USG'de refleksiyon (yansıma) kullanılırken; vücuttan dışarıya enerji salımı (**emisyon**) prensibiyle çalışan yöntemler **Nükleer Tıp (PET-BT, Sintigrafi)** ve radyoaktif/RF sinyali salan **Manyetik Rezonans (MRG)**'dır."}, {"year": "2022-2023", "subject": "Radyoloji", "q_num": 96, "question": "Aşağıdaki neoplazilerden hangisinin radyolojik bir tarama yöntemi yoktur?", "professor": "Senem Şentürk Güçel", "options": [{"letter": "A", "text": "Serviks kanseri"}, {"letter": "B", "text": "Kolon kanseri"}, {"letter": "C", "text": "Meme kanseri"}, {"letter": "D", "text": "Akciğer kanseri"}, {"letter": "E", "text": "Rektum kanseri"}], "answer": "A", "note": null, "id": "2022-2023_Q96", "explanation": "**Serviks kanserinin** taraması radyolojik görüntüleme ile değil, **Pap-smear (sitolojik inceleme) ve HPV DNA testi** ile yapılır."}, {"year": "2022-2023", "subject": "Tıbbi Genetik", "q_num": 97, "question": "β-talasemi fenotipinin doğumdan sonra kendisini göstermeye başlamasının sebebi\naşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Fetusta β-globin yerine β-globin benzeri globinlerin işlev görüyor olması"}, {"letter": "B", "text": "Doğum sonrası α-globin ifadesinin azalmasıyla β-globin ifadesi üzerindeki baskılamanın ortadan kalkması"}, {"letter": "C", "text": "Doğum sonrası β-globin gen ifadesine ihtiyaç duyulmaması"}, {"letter": "D", "text": "Doğum sonrası α-globin gen ifadesine ihtiyaç duyulmaması"}, {"letter": "E", "text": "Doğum sonrası γ-globin ifadesinin aşırı yükselme"}], "answer": "A", "note": null, "id": "2022-2023_Q97", "explanation": "Beta-talasemi fenotipinin doğumdan sonra ortaya çıkmasının nedeni, fetal dönemde beta-globin yerine **beta-benzeri globinlerin (özellikle gama-globin / HbF) işlev görüyor olması** ve doğumdan sonra HbF'ten HbA (α2β2) sentezine geçiş (globin switch) yaşanmasıdır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 98, "id": "2023-2024_Q98"}]}, {"year": "2022-2023", "subject": "Tıbbi Genetik", "q_num": 98, "question": "Venöz thromboz gelişme riskini yaklaşık 3 kat artıran, tekrarlayan düşüklerde sık\nrastlanan ve ikinci önemli genetik risk faktörü olarak gösterilen gen mutasyonu\naşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Faktör V Leiden G1691A mutasyonu"}, {"letter": "B", "text": "Prothrombin (FII) G20120A mutasyonu"}, {"letter": "C", "text": "MTHFR C677T mutasyonu"}, {"letter": "D", "text": "MTHFR A1298C mutasyonu"}, {"letter": "E", "text": "Faktör XIII V34L mutasyonu"}], "answer": "B", "note": null, "id": "2022-2023_Q98", "explanation": "Kalıtsal trombofililerde Faktör V Leiden'den sonra **ikinci en sık genetik risk faktörü** olan ve venöz tromboz riskini ~3 kat artıran mutasyon **Protrombin (Faktör II) G20210A mutasyonu**dur.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 97, "id": "2023-2024_Q97"}]}, {"year": "2022-2023", "subject": "İmmünoloji", "q_num": 99, "question": "Tümör mikroçevresinde aşağıdakilerden hangisi kötü prognoz göstergesidir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Th1"}, {"letter": "B", "text": "Th17"}, {"letter": "C", "text": "Regülatör T hücresi (Treg)"}, {"letter": "D", "text": "Plazma hücresi"}, {"letter": "E", "text": "B lenfosit"}], "answer": "C", "note": null, "id": "2022-2023_Q99", "explanation": "Tümör mikroçevresinde anti-tümör immün yanıtı (CTL ve NK hücrelerini) baskıladığı için varlığı **kötü prognoz** göstergesi olan hücre **Regülatör T hücresidir (Treg: CD4+ CD25+ FOXP3+)**.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 99, "id": "2023-2024_Q99"}]}, {"year": "2022-2023", "subject": "İmmünoloji", "q_num": 100, "question": "Kanserin 3E'sini oluşturan evreler (Eliminasyon, Equilibrium/Denge, Escape/Kaçış) ile uygun açıklamaların doğru eşleştirmesi hangisidir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Eliminasyon: Transforme hücrelerin yok edilmesi (İmmün gözetim) | Equilibrium: Artmış yaşama kapasiteli varyantların seçilmesi | Escape: Tümörün kontrolsüz hızla yayılması"}, {"letter": "B", "text": "Eliminasyon: Tümörün kontrolsüz yayılması | Equilibrium: İmmün gözetim | Escape: Varyantların seçilmesi"}, {"letter": "C", "text": "Eliminasyon: Varyantların seçilmesi | Equilibrium: Tümörün kontrolsüz yayılması | Escape: İmmün gözetim"}, {"letter": "D", "text": "Eliminasyon: Anjiyogenez | Equilibrium: Apoptoz | Escape: Metaplazi"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": "Orijinal PDF'te eşleştirme sorusu olarak verilmiştir.", "id": "2022-2023_Q100", "explanation": "Kanserin immün şekillendirilmesi (3E) evreleri: 1. **Eliminasyon**: Transforme hücrelerin immün sistemce tanınıp yok edilmesi (immün gözetim), 2. **Equilibrium (Denge)**: Sağ kalan genetik olarak kararsız tümör varyantlarının seçilmesi ve denge hali, 3. **Escape (Kaçış)**: İmmün sistemden kaçan varyantların kontrolsüz çoğalarak klinik kanser oluşturması."}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 1, "question": "Pediatrik yaş grubunda mean corpuscular volume için aşağıdakilerden hangisi\ndoğrudur?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "Alt sınırı; 80 – yaş formülüne göre hesaplanır."}, {"letter": "B", "text": "10 yaş altında alt sınır 80 fL’dir."}, {"letter": "C", "text": "Anizositoz göstergesidir."}, {"letter": "D", "text": "Menzter İndeksi hesaplamasında kullanılır."}, {"letter": "E", "text": "Düşük olması megaloblastik anemi lehinedir."}], "answer": "D", "note": null, "id": "2023-2024_Q1", "explanation": "Çocuklarda MCV alt sınırı 70 + yaş (üst sınırı 84 + 0.6×yaş) ile hesaplanır, anizositoz göstergesi RDW'dir ve MCV düşüklüğü mikrositer anemi lehinedir. **MCV değeri Mentzer indeksi (MCV / RBC) hesaplamasında** demir eksikliği ile talasemi taşıyıcılığını ayırt etmek için kullanılır.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 3, "id": "2024-2025_Q3"}]}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 2, "question": "Aşağıdakilerden hangisi izole beta talasemi taşıyıcılığı için beklenen laboratuar\nbulgularından birisi değildir?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "Hafif anemi"}, {"letter": "B", "text": "Düşük MCV"}, {"letter": "C", "text": "Yüksek RDW"}, {"letter": "D", "text": "Düşük MCH"}, {"letter": "E", "text": "Yüksek HbA2"}], "answer": "C", "note": null, "id": "2023-2024_Q2", "explanation": "İzole beta talasemi taşıyıcılığında (minör) hafif anemi, düşük MCV, düşük MCH ve yüksek HbA2 (>%3.5) görülür; ancak eritrositler homojen küçüldüğü için **RDW genellikle normaldir (yüksek RDW demir eksikliği anemisi lehinedir)**."}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 3, "question": "Li-fraumeni sendromunda mutasyon hangi gendedir?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "RAS"}, {"letter": "B", "text": "N-myc"}, {"letter": "C", "text": "C-myc"}, {"letter": "D", "text": "P53"}, {"letter": "E", "text": "RB-1"}], "answer": "D", "note": null, "id": "2023-2024_Q3", "explanation": "**Li-Fraumeni sendromu**, germline **TP53 (p53)** tümör süpresör gen mutasyonu sonucu gelişen ve genç yaşta sarkom, meme kanseri, beyin tümörü, lösemi ve adrenokortikal karsinom riskini artıran otozomal dominant sendromdur.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 5, "id": "2024-2025_Q5"}]}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 4, "question": "On yaşında bir çocuk invajinasyon kliniğinde getirilmiştir. Ultrasonda ilioçekal\nalanda kitle saptanmış olup total eksize edilmiştir. En olası tanı nedir?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "Lenfoblastik lenfoma"}, {"letter": "B", "text": "Large-cell lenfoma"}, {"letter": "C", "text": "Burkitt lenfoma"}, {"letter": "D", "text": "Kolon adenokanseri"}, {"letter": "E", "text": "Hodgkin lenfoma"}], "answer": "C", "note": null, "id": "2023-2024_Q4", "explanation": "Çocuklarda ileoçekal bölgede hızlı büyüyen kitle ve buna bağlı **invajinasyon (intussusepsiyon)** tablosu ile başvuran en sık Non-Hodgkin lenfoma alt tipi **sporadik Burkitt lenfoma**dır."}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 5, "question": "Aşağıdakilerden hangisi çocuklarda immunyetmezlik şüphelendiren bir durum\ndeğildir?", "professor": "Aysel Burcu İbili", "options": [{"letter": "A", "text": "1 yılda ≥4 yeni otitis media"}, {"letter": "B", "text": "≥2 ay çok az etkili veya etkisiz antibiyotik tedavisi"}, {"letter": "C", "text": "Yılda 3 kez antibiyotik kullanmak"}, {"letter": "D", "text": "1 yılda ≥2 bakteriyel pnömoni"}, {"letter": "E", "text": "Ailede primer immün yetmezlik öyküsü"}], "answer": "C", "note": null, "id": "2023-2024_Q5", "explanation": "Primer immün yetmezlik uyarıcı kriterleri arasında yılda ≥4 otitis media, ≥2 pnömoni, ≥2 ay etkisiz antibiyotik kullanımı ve aile öyküsü yer alır; **yılda 3 kez antibiyotik kullanmak** tek başına immün yetmezlik şüphelendiren bir kriter değildir."}, {"year": "2023-2024", "subject": "Pediatri", "q_num": 6, "question": "Süt çocuğu geçici hipogammaglobulinemisiyle ilgili aşağıdakilerden hangisi\ndoğrudur?", "professor": "Aysel Burcu İbili", "options": [{"letter": "A", "text": "48 aya kadar uzayabilir"}, {"letter": "B", "text": "Karşılaşılan enfeksiyonlar uygun antibiyotiklerle tedavi edilebilir"}, {"letter": "C", "text": "İzohemaglutinin yoktur"}, {"letter": "D", "text": "IVIG tedavisi şarttır"}, {"letter": "E", "text": "Aşılara yanıt yoktur"}], "answer": "B", "note": null, "id": "2023-2024_Q6", "explanation": "**Süt çocuğunun geçici hipogammaglobulinemisinde** hücresel bağışıklık, izohemaglütininler ve aşı yanıtları normaldir; IVIG genellikle gerekmez ve **karşılaşılan enfeksiyonlar uygun antibiyotiklerle kolayca tedavi edilebilir** (genellikle 24-36 ayda kendiliğinden düzelir)."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 7, "question": "Oral demir preparatları ile ilgili hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Biyoyararlanımı en fazla olan Demir Sülfat ve Demir Glisin sülfattır"}, {"letter": "B", "text": "Demir glukonat en az yan etki gösterendir"}, {"letter": "C", "text": "Askorbik asitle alınımı absorbsiyonu artırırken, yan etkilerini de artırır."}, {"letter": "D", "text": "Sık verilmesi durumunda mukozal blok gelişeceğinden dozlar arası interval uzun tutulması gerekir."}, {"letter": "E", "text": "Demir, mukozal membrandan Fe+3 formunda emilir,"}], "answer": "E", "note": null, "id": "2023-2024_Q7", "explanation": "Oral alınan demir preparatları bağırsak mukozal membranından (DMT1 taşıyıcısı ile) Fe+3 (ferrik) formda değil, **Fe+2 (ferröz) formda** emilir."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 8, "question": "Otonom sinir sistemiyle ilgili hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Parasempatik inervasyon alan organlarda ve dokularda muskarinik reseptörler etki gösterir."}, {"letter": "B", "text": "Noradrenalin sinaptik aralıktan reuptake yapılarak etkisi sonlandırılır"}, {"letter": "C", "text": "Beta reseptörler uyarılması durumunda kalp dokusunda negatif (-) inotrop etki meydana gelir"}, {"letter": "D", "text": "Vasküler ve diğer düz kaslarda alfa reseptörleri uyarılınca kasılma görülür."}, {"letter": "E", "text": "Gastrointestinal kanal ve mesane düz kaslarında muskarinik reseptörler gevşeme etkisi gösterir."}], "answer": "C", "note": null, "id": "2023-2024_Q8", "explanation": "Kalp dokusunda **Beta-1 adrenerjik reseptörlerin** uyarılması negatif değil, **pozitif (+) inotrop, pozitif kronotrop ve pozitif dromotrop** etki meydana getirir."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 9, "question": "Preanestezik medikasyonda trakeobronşiyal ve faringeal sekresyonları azaltmak için\nkullanılan antikolinerjik ilaç hangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Skopolamin"}, {"letter": "B", "text": "Pilokarpin"}, {"letter": "C", "text": "Glikopirolat"}, {"letter": "D", "text": "Darifenasin"}, {"letter": "E", "text": "Biperiden"}], "answer": "C", "note": null, "id": "2023-2024_Q9", "explanation": "**Glikopirolat**, kuaterner amin yapılı olduğu için kan-beyin bariyerini geçmeyen (santral yan etki yapmayan) ve **preanestezik medikasyonda trakeobronşiyal/faringeal salgıları azaltmak için** tercih edilen antimuskarinik ilaçtır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 10, "question": "Antispazmodik etkisi sayesinde biliyer kolik, renal kolik,gastrointestinal spazmlar\ngibi geniş kullanım alanı olan antikolinerjik hangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Skopolamin"}, {"letter": "B", "text": "Hyosin butilbromür"}, {"letter": "C", "text": "Darifenasin"}, {"letter": "D", "text": "Glikopirolat"}, {"letter": "E", "text": "Oksibutinin"}], "answer": "B", "note": null, "id": "2023-2024_Q10", "explanation": "**Hyosin-N-butilbromür (Skopolamin butilbromür)**, kuaterner amonyum türevi bir antimuskarinik olup gastrointestinal spazmlar, biliyer kolik ve renal kolikte **antispazmodik** olarak yaygın kullanılır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 11, "question": "Atropin zehirlenmesinde antidot olarak kullanılan Fizostigmin etki mekanizması\nhangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "AsetilKolinesteraz enzimini aktivasyonu"}, {"letter": "B", "text": "AsetilKolinesteraz enzimini inhibisyonu"}, {"letter": "C", "text": "Muskarinik agonist"}, {"letter": "D", "text": "Muskarinik antagonist"}, {"letter": "E", "text": "Otonom gangliyonlardaki Nikonitik reseptörleri uyarmak"}], "answer": "B", "note": null, "id": "2023-2024_Q11", "explanation": "**Fizostigmin**, kan-beyin bariyerini geçebilen tersiyer amin yapılı bir karbamat türevidir ve **Asetilkolinesteraz enzimini reverzibl inhibe ederek** sinaptik aralıktaki asetilkolini artırır, böylece atropin zehirlenmesinde antidot olarak etki gösterir."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 12, "question": "Parasempatomimetiklerin endikasyonlarından biri değildir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Ağız kuruluğunu giderme"}, {"letter": "B", "text": "Postoperatif paralitik ileus"}, {"letter": "C", "text": "Nörojenik mesane bozuklukları"}, {"letter": "D", "text": "Tükrük ve bronş salgılarını azaltmak amaçlı"}, {"letter": "E", "text": "Göz ameliyatlarında miyozis oluşturmak için"}], "answer": "D", "note": null, "id": "2023-2024_Q12", "explanation": "Parasempatomimetik ilaçlar tükürük, gözyaşı ve bronş salgılarını **artırır** (Sjögren/kserostomi tedavisinde kullanılır); **salgıları azaltmak için parasempatomimetikler değil antimuskarinikler (atropin, glikopirolat)** kullanılır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 13, "question": "Kronik böbrek yetmezliğine bağlı anemide hangisi kullanılır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Darbepoetin alfa"}, {"letter": "B", "text": "Demir bisglisinat"}, {"letter": "C", "text": "Filgrastim"}, {"letter": "D", "text": "Siyanokobalamin"}, {"letter": "E", "text": "Demir III hidroksit polimaltoz kompleksi"}], "answer": "A", "note": null, "id": "2023-2024_Q13", "explanation": "Kronik böbrek yetmezliğinde böbrekten eritropoetin (EPO) sentezi azaldığı için gelişen normokrom normositer aneminin tedavisinde rekombinant eritropoetin analoğu olan **Darbepoetin alfa** (veya Epoetin alfa) kullanılır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 14, "question": "Adrenelin için verilen bilgilerden hangisi doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Yüksek doz adrenalin, Total Periferik damar Direncini artırır."}, {"letter": "B", "text": "Normal doz adrenalin, cilt ve mukozada kasılmaya neden olur."}, {"letter": "C", "text": "Normal doz da Beta reseptörleri üzerindeki etkisi alfa reseptörlerine olandan daha fazladır."}, {"letter": "D", "text": "Alfa2 reseptör uyarısıyla insülin salınımını artırır."}, {"letter": "E", "text": "Beta1 reseptör uyrasını bağlı olarak negatif inotropiye neden olur."}], "answer": "A", "note": null, "id": "2023-2024_Q14", "explanation": "**Yüksek doz adrenalin** uygulandığında damarlardaki alfa-1 adrenerjik vazokonstrüktör etki baskın hale geçer ve **Total Periferik Damar Direncini (TPR) artırır** (düşük dozda beta-2 etkisiyle TPR düşer; alfa-2 uyarı insülini azaltır; beta-1 pozitif inotropi yapar).", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 49, "id": "2025-2026_Q49"}]}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 15, "question": "Aşağıda verilen adrenerjiklerden hangisinin etkisi sadece alfa reseptörlerine olup\nimidazolin türevi bir lokal dekonjestandır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Nafazolin"}, {"letter": "B", "text": "Efedrin"}, {"letter": "C", "text": "Dobutamin"}, {"letter": "D", "text": "Terbutalin"}, {"letter": "E", "text": "Korbadrin"}], "answer": "A", "note": null, "id": "2023-2024_Q15", "explanation": "**Nafazolin** (oksimetazolin ve ksilometazolin gibi), sadece alfa adrenerjik reseptörleri uyaran **imidazolin türevi** bir ilaç olup nazal ve konjonktival **lokal dekonjestan** olarak kullanılır.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 33, "id": "2024-2025_Q33"}]}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 16, "question": "Beta-1 adrenerjik reseptörlerin aracılık ettiği sempatik stimülasyonu selektif bir\nşekilde bloke eden ve bu reseptörlere Beta-2 reseptörlerden 100 kat daha fazla afinite gösteren\nen kısa etkili beta-blokör aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Esmolol"}, {"letter": "B", "text": "Oksimetazolin"}, {"letter": "C", "text": "Ergotamin"}, {"letter": "D", "text": "Salmaterol"}, {"letter": "E", "text": "Lofeksidin"}], "answer": "A", "note": null, "id": "2023-2024_Q16", "explanation": "**Esmolol**, plazma eritrosit esterazları ile hızla yıkılan, yarı ömrü ~9 dakika olan **en kısa etkili, kardiyoselektif (Beta-1 seçici) intravenöz beta-blokör** ilaçtır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 17, "question": "T ve B lenfositlerinin pürin sentezinde rol oynayan inozin monofosfat dehidrojenaz\nenzimini inhibe eden ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Mikofenolat mofetil"}, {"letter": "B", "text": "Takrolimus"}, {"letter": "C", "text": "Siklosporin"}, {"letter": "D", "text": "Sirilimus"}, {"letter": "E", "text": "Pemetreksed"}], "answer": "A", "note": null, "id": "2023-2024_Q17", "explanation": "**Mikofenolat mofetil**, aktif metaboliti mikofenolik asit aracılığıyla T ve B lenfositlerin de novo guanozin (pürin) sentezinde görevli **inozin monofosfat dehidrojenaz (IMPDH)** enzimini selektif inhibe eden immünsüpresif ilaçtır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 18, "question": "Protein ekspresyonunun düzenlenmesinden ve hücre içindeki zarar görmüş veya\neskimiş proteinlerin parçalanmasından sorumlu olan preotozom inhibitörü ilaç\naşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Bortezomib"}, {"letter": "B", "text": "Rituksimab"}, {"letter": "C", "text": "Nilotinib"}, {"letter": "D", "text": "Prednizon"}, {"letter": "E", "text": "Formestan"}], "answer": "A", "note": null, "id": "2023-2024_Q18", "explanation": "**Bortezomib**, memeli hücrelerinde 26S **proteazom kompleksini inhibe ederek** hücre içi protein yıkımını bozan, NF-κB sinyalini baskılayan ve **Multipl Myelom** tedavisinde kullanılan hedefe yönelik ilaçtır."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 19, "question": "V.rosea bitkisinin dimerik alkaloidlerinden, mtitozun metafaz (M) fazını durduran\nve mitoz zehiri olarak da bilinen ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Vinblastin"}, {"letter": "B", "text": "Sisplatin"}, {"letter": "C", "text": "Epurobisin"}, {"letter": "D", "text": "Dakarbazin"}, {"letter": "E", "text": "Kabazitaksel"}], "answer": "A", "note": null, "id": "2023-2024_Q19", "explanation": "*Vinca rosea* (Cezayir menekşesi) bitkisinden elde edilen **Vinblastin** (ve vinkristin), tübüline bağlanıp mikrotübül polimerizasyonunu önleyerek **mitozu metafaz (M) evresinde durduran** mitoz zehiridir."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 20, "question": "Aşağıda verilen antineoplastik ilaç ve etki mekanizması eşleştirmelerinden hangisi\ndoğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "İrinotekan - Topoizomeraz-I inhibisyonu"}, {"letter": "B", "text": "Metotraksat - HMG KoA enzim aktivasyonu"}, {"letter": "C", "text": "Gefitinib - Vaskuler endoteliyal büyüme faktörü inhibisyonu"}, {"letter": "D", "text": "Panitumumab - B tipi lenfositlerin CD20 antijeni bağlanarak"}, {"letter": "E", "text": "Trastuzumab - Epidermal büyüme faktör reseptörü inhibisyonu"}], "answer": "A", "note": null, "id": "2023-2024_Q20", "explanation": "**İrinotekan — Topoizomeraz-I inhibisyonu** eşleştirmesi doğrudur. (Metotreksat DHFR inhibitörüdür; Gefitinib EGFR tirozin kinaz inhibitörüdür; Panitumumab anti-EGFR antikordur; Trastuzumab anti-HER2 antikordur)."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 21, "question": "Aşağıda verilen ilaç ve etki yeri eşleştirmelerinden hangisi doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Filgrastim - lökosit büyüme faktörü"}, {"letter": "B", "text": "Aldeslökin - Koloni sitümüle edici faktör"}, {"letter": "C", "text": "Tosilizumab- HER-2 agonisti"}, {"letter": "D", "text": "Anakinra- VEGF antagonisti"}, {"letter": "E", "text": "Adalimumab - EGFR agonisti"}], "answer": "A", "note": null, "id": "2023-2024_Q21", "explanation": "**Filgrastim**, rekombinant insan granülosit koloni stimüle edici faktörü (**G-CSF / lökosit büyüme faktörü**) olup kemoterapiye bağlı nötropeni tedavisinde kullanılır. (Tosilizumab anti-IL6R, Anakinra IL-1R antagonisti, Adalimumab anti-TNFα antikordur)."}, {"year": "2023-2024", "subject": "Farmakoloji", "q_num": 22, "question": "Beta adrenerjik reseptörler üzerinde parsiyel (kısmi) agonist etki gösteren b-blokör ilaçlara ...... ........ ........ gösteren ilaçlar adı verilir.", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "İntrinsik sempatomimetik etkinlik (İSE)"}, {"letter": "B", "text": "Membran stabilize edici etkinlik"}, {"letter": "C", "text": "Kardiyoselektif antagonist etkinlik"}, {"letter": "D", "text": "Alfa-1 blokör etkinlik"}, {"letter": "E", "text": "Sempatolitik etkinlik"}], "answer": "A", "note": "Orijinal PDF'te boşluk doldurma sorusu olarak verilmiştir (Cevap: İntrinsik sempatomimetik etkinlik, İSE).", "id": "2023-2024_Q22", "explanation": "Beta adrenerjik reseptörleri bloke ederken aynı zamanda zayıf parsiyel agonist etki gösteren beta-blokörlere (pindolol, asebutolol, karteolol, celiprolol) **İntrinsik Sempatomimetik Etkinlik (İSE / ISA)** gösteren ilaçlar denir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 23, "question": "Aşağıdakilerden hangisi KLL'nin tedavi endikasyonlarından biri değildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Günlük aktiviteyi sınırlayan aşırı halsizlik olması (ECOG performans skorunun 2 ve üzerinde olması)"}, {"letter": "B", "text": "Kosta alt kenarını 10 cm geçen ağrılı splenomegali olması"}, {"letter": "C", "text": "Son 6 ayda vücut ağırlığının >%10'undan fazla kilo kaybı olması"}, {"letter": "D", "text": "Tek bir ölçümde WBC: 90.000 saptanması"}, {"letter": "E", "text": "Tanı anında normal sınırlarda iken, takipte Hb<10 gr/dl, PLT (trombosit)<100.000 olması"}], "answer": "D", "note": null, "id": "2023-2024_Q23", "explanation": "Kronik Lenfositer Lösemi (KLL)'de **tek bir ölçümde lökosit (WBC) sayısının 90.000/mm³ olması** tek başına tedaviye başlama endikasyonu değildir. B semptomları, ECOG ≥2, masif/semptomatik splenomegali ve kemik iliği yetmezliği (Hb <10, Plt <100.000) tedavi endikasyonlarıdır."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 24, "question": "Aşağıdakilerden hangisi polisitemia vera'da beklenen bir bulgu değildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Hb düzeyi yüksekliği"}, {"letter": "B", "text": "JAK-2 V617F mutasyonu varlığı"}, {"letter": "C", "text": "EPO düşüklüğü"}, {"letter": "D", "text": "Kemik iliğinde eritrositer seri başta olmak üzere 3 seride de proliferasyon görülebilmesi"}, {"letter": "E", "text": "BCR ABL pozitifliği"}], "answer": "E", "note": null, "id": "2023-2024_Q24", "explanation": "Polisitemia Vera (PV), **BCR-ABL negatif** kronik miyeloproliferatif bir neoplazidir; olguların >%95'inde JAK2 V617F mutasyonu pozitiftir, Hb/Hct yüksektir ve EPO düzeyi düşüktür. **BCR-ABL pozitifliği** PV'de değil KML'de görülür."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 25, "question": "21 yaş/bayan hasta poliklinğie halsizlik şikayeti ile başvuruyor. Fizik muayenede\nciltte ve konjonktivada solukluk dışında ek patolojik bulgu izlenmiyor. Laboratuvar\ntetkiklerinde Hb: 9.2 gr/dl, MCV: 68, WBC ve PLT normal saptanıyor. Bu hasta için en olası\ntanı aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "B12 vitamin eksikliğine bağlı anemi"}, {"letter": "B", "text": "Hipotiroidiye bağlı anemi"}, {"letter": "C", "text": "Demir eksikliği anemisi"}, {"letter": "D", "text": "Folik asit eksikliğine bağlı anemi"}, {"letter": "E", "text": "Myelodisplastik sendrom"}], "answer": "C", "note": null, "id": "2023-2024_Q25", "explanation": "Reprodüktif çağdaki (21 yaş) genç kadın hastada izole hipokrom mikrositer anemi (Hb: 9.2 g/dL, MCV: 68 fL) tablosunun en sık ve en olası nedeni **Demir Eksikliği Anemisi**dir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 26, "question": "Aşağıdaki anemi çeşitlerinin hangisinde, periferik kanda eritrosit sayısı (RBC)\nnormal veya artmış olarak izlenir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Demir eksikliği anemisi"}, {"letter": "B", "text": "Beta talasemi taşıyıcılığı"}, {"letter": "C", "text": "Sideroblastik anemi"}, {"letter": "D", "text": "Megaloblastik anemi"}, {"letter": "E", "text": "Kronik hastalık anemisi"}], "answer": "B", "note": null, "id": "2023-2024_Q26", "explanation": "**Beta talasemi taşıyıcılığında (minör)** kemik iliğinde eritropoetin uyarısına yanıt olarak kompanzatuar eritroid hiperplazi geliştiği için **periferik kanda eritrosit sayısı (RBC) normal veya artmış (>5 milyon/mm³)** olarak izlenir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 27, "question": "64yaş/erkek hastanın halsizlik nedeniyle başvurusunda yapılan tetkiklerinde Hb:\n8.5 gr/dl, MCV: 87, WBC: 3230/mm3 (Normali 4000-10000), PLT: 60.000 olarak saptanmış.\nFizik muayenede lenfadenopati ve splenomegali yok. Bu hasta için en olası tanı\naşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Sideroblastik anemi"}, {"letter": "B", "text": "Demir eksikliği anemisi"}, {"letter": "C", "text": "Hemolitik anemi"}, {"letter": "D", "text": "Aplastik anemi"}, {"letter": "E", "text": "Karaciğer sirozu"}], "answer": "D", "note": null, "id": "2023-2024_Q27", "explanation": "Fizik muayenede **lenfadenopati ve splenomegali olmaksızın** üç seride birden düşüklük (**pansitopeni**: Hb: 8.5, WBC: 3230, Plt: 60.000) saptanan hastada şıklar arasında en olası tanı **Aplastik Anemi**dir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 28, "question": "Aşağıdakilerden hangisi intravasküler hemoliz ile uyumlu laboratuvar\nbulgularından birisi değildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Haptoglobulin düzeyi artar"}, {"letter": "B", "text": "Laktat dehidrogenaz (LDH) düzeyi artar"}, {"letter": "C", "text": "Retikülosit sayısı artar"}, {"letter": "D", "text": "İndirek bilurubin düzeyi artar"}, {"letter": "E", "text": "Hemoglobinüri, hemosiderinüri görülür"}], "answer": "A", "note": null, "id": "2023-2024_Q28", "explanation": "İntravasküler hemolizde serbest hemoglobini bağlayan **haptoglobin düzeyi artmaz, aksine belirgin olarak azalır**. LDH, indirekt bilirubin ve retikülosit artışı ile hemoglobinüri/hemosiderinüri ise tipik bulgulardır."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 29, "question": "Aşağıdakilerden hangisi, Multipl Myelomda tedaviye başlama endikasyonlarından\nbirisi değildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Sedimentasyon yüksekliği"}, {"letter": "B", "text": "İlerleyici litik kemik lezyonları"}, {"letter": "C", "text": "Böbrek yetmezliği"}, {"letter": "D", "text": "Anemi"}, {"letter": "E", "text": "Hiperkalsemi"}], "answer": "A", "note": null, "id": "2023-2024_Q29", "explanation": "Multipl Myelomda tedaviye başlama endikasyonları **CRAB** kriterleridir (**C**: Hiperkalsemi, **R**: Renal yetmezlik, **A**: Anemi, **B**: İlerleyici litik kemik lezyonları). **Tek başına sedimantasyon yüksekliği** tedavi endikasyonu değildir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 30, "question": "52 yaş/kadın hasta halsizlik, iştahsızlık, çabuk doyma şikayetleri ile başvuruyor.\nFizik muayenesinde solukluk ve inguinal bölgeye kadar uzanan splenomegali saptanıyor.\nLaboratuvar tetkiklerinde Hb: 10.5 gr/dl, WBC: 32000 (4000-10000), PLT: 650000. BCR ABL\npozitifliği mevcut. Bu hastanın en olası tanısı aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Primer Myelofibroz"}, {"letter": "B", "text": "Esansiyel Trombositoz"}, {"letter": "C", "text": "Kronik Myeloid Lösemi"}, {"letter": "D", "text": "Myelodisplastik Sendrom"}, {"letter": "E", "text": "Polisitemia Vera"}], "answer": "C", "note": null, "id": "2023-2024_Q30", "explanation": "Masif splenomegali, lökositoz (32.000), trombositoz (650.000) ve **BCR-ABL pozitifliği** olan hastada kesin tanı **Kronik Miyeloid Lösemi (KML)**'dir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 31, "question": "Aşağıdaki anemi türlerinden hangisinde retikülositoz görülür?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Megaloblastik anemi"}, {"letter": "B", "text": "Kronik böbrek yetmezliğine bağlı anemi"}, {"letter": "C", "text": "Hipotiroidiye sekonder anemi"}, {"letter": "D", "text": "Akut kan kaybına bağlı anemi"}, {"letter": "E", "text": "Demir eksikliği anemisi"}], "answer": "D", "note": null, "id": "2023-2024_Q31", "explanation": "**Akut kan kaybına bağlı anemide** (ve hemolitik anemilerde) kemik iliği sağlam olduğu ve EPO uyarısı arttığı için **retikülositoz** görülür. Megaloblastik anemi, KBY anemisi, hipotiroidi ve demir eksikliği anemisi ise hipoproliferatif (retikülosit düşük/normal) anemilerdir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 32, "question": "Aşağıdaki laboratuvar bulgularından hangisi megaloblastik anemi ile uyumlu\ndeğildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "MCV: 124 olması"}, {"letter": "B", "text": "Retikülositoz"}, {"letter": "C", "text": "Trombositopeni"}, {"letter": "D", "text": "Nötrofillerde hipersegmentasyon"}, {"letter": "E", "text": "LDH düzeylerinde artış"}], "answer": "B", "note": null, "id": "2023-2024_Q32", "explanation": "Megaloblastik anemide (B12/folat eksikliği) DNA sentez kusuru ve inefektif eritropoez nedeniyle kemik iliğinde hücreler olgunlaşamadan yıkılır; bu nedenle periferik kanda **retikülositoz görülmez** (retikülosit sayısı düşüktür; tedavi verildikten sonra yükselir)."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 33, "question": "82 yaş/erkek hasta halsizlik, .abuk yorulma şikayetleri ile başvuruyor. Laboratuvar\ntetkiklerinde Hb: 8.7 gr/dl, MCV: 105, WBC: 3500 (4000-10000), PLT: 95000. Periferik\nyaymada \"Pelger huet anomalisi\" izlenmekte olup nötrofiller hiposegmente görülüyor. Bu\nhastada en olası tanı aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Vitamin B12 eksikliği"}, {"letter": "B", "text": "Kronik Myeloid Lösemi"}, {"letter": "C", "text": "Myelodisplastik Sendrom"}, {"letter": "D", "text": "Akut Myeloblastik Lösemi"}, {"letter": "E", "text": "Hairy Cell Lösemi"}], "answer": "C", "note": null, "id": "2023-2024_Q33", "explanation": "82 yaşında ileri yaş hastada makrositer sitopeni (MCV: 105 fL) ve periferik yaymada nötrofillerde **hiposegmentasyon (psödo-Pelger-Huet anomalisi)** görülmesi **Miyelodisplastik Sendrom (MDS)** için tipiktir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 34, "question": "45 yaş/kadın hasta üşüme, yorgunluk, uyku hali, çarpıntı şikayetleri ile başvuruyor.\nAnamnezde hastanın 5 yıl önce histerektomi operasyonu olduğu öğreniliyor. Laboratuvar\nincelemelerinde Hb: 9.6 gr/dl, MCV: 73, RDW: 19, serum ferritin: 3 saptanıyor. Bu hasta için\nbundan sonraki adımda en uygun yaklaşım aşağıdkilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Oral demir tedavisi başlanması"}, {"letter": "B", "text": "Parenteral demir tedavisi başlanması"}, {"letter": "C", "text": "Endoskopi-kolonoskopi yapılması"}, {"letter": "D", "text": "Vitamin B12 ve Folik asit düzeyi bakılması"}, {"letter": "E", "text": "Kemik iliği biyopsisi yapılması"}], "answer": "C", "note": null, "id": "2023-2024_Q34", "explanation": "5 yıl önce histerektomi olmuş (menstrüel kan kaybı olmayan) 45 yaşındaki kadın hastada **Demir Eksikliği Anemisi** (Hb: 9.6, MCV: 73, ferritin: 3) saptandığında, altta yatan gizli gastrointestinal kanama veya maligniteyi dışlamak için **mutlaka üst ve alt GİS endoskopisi (endoskopi-kolonoskopi)** yapılmalıdır."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "25 yaş/erkek hasta halsizlik, yorgunluk ve sık tekrarlayan burun kanaması\nşikayetleri ile başvuruyor. Fizik muayenede konjonktivada solukluk ve ciltte peteşiler\nsaptanıyor. FM'de periferik LAP izlenmiyor, KC-dalak ele gelmiyor. Laboratuvarda Hb: 8.8\ngr/dl, MCV: 106, WBC: 1500 (4000-10000), PLT: 28000. Retikülosit yüzdesi % 0.2. Bu hastada\nen olası tanı ve kesin tedavi yöntemi aşağıdakilerden hangisinde doğru olarak verilmiştir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Saf eritroid aplazi-kemik iliği incelemesi"}, {"letter": "B", "text": "Paroksismal nokturnal hemoglobinüri-akım sitometri"}, {"letter": "C", "text": "Sıcak tip otoimmün hemolitik anemi-direk coombs testi"}, {"letter": "D", "text": "Akut lenfoblastik lösemi-sitogenetik analiz"}, {"letter": "E", "text": "Aplastik anemi-kemik iliği incelemesi"}], "answer": "E", "note": null, "id": "2023-2024_Q35", "explanation": "Organomegali ve LAP olmaksızın ağır **pansitopeni** (Hb: 8.8, WBC: 1500, Plt: 28.000) ve **retikülositopeni (%0.2)** ile başvuran genç hastada en olası tanı **Aplastik Anemi** olup kesin tanı **kemik iliği biyopsisi/incelemesi** ile konur."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "21 yaş/erkek hasta. Daha önceden bilinen kronik hastalık tariflemiyor. Mersin\ndoğumlu, Uşak'ta yaşıyor. Acil servise baş dönmesi, baygınlık hissi, çarpıntı gibi şikayetlerle\nbaşvuran hastanın Hb: 7.5, MCV: 90, LDH: 500 (yüksek), İNdirek bilurubin hakimiyeti olan\nbilurubin yüksekliği mevcut. İdarda hemoglobinüri mevcut. Periferik yaymada eritrositlerde\nmembrana bağlı inklüzyonlar izlenmekte. Dün akşam yemeğinde bakla yeme öyküsü de olan\nhastada en olası tanınız aşağıdakilerden hangisidir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}, {"letter": "B", "text": "Paroksismal nokturnal hemoglobinüri"}, {"letter": "C", "text": "Orak hücreli anemi"}, {"letter": "D", "text": "Beta talasemi major"}, {"letter": "E", "text": "Sıcak antikor aracılı otoimmün hemolitik anemi"}], "answer": "A", "note": null, "id": "2023-2024_Q36", "explanation": "Bakla yeme (favizm) sonrası gelişen akut intravasküler hemoliz (hemoglobinüri, yüksek LDH ve indirekt bilirubin) ve periferik yaymada membrana bağlı inklüzyonlar (**Heinz cisimcikleri**) **Glukoz-6-Fosfat Dehidrogenaz (G6PD) eksikliği** için tanısaldır."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Kanser etiolojisi ve epidemiyolojisi ile ilgili aşağıdaki ifadelerden hangisi ya da\nhangileri doğrudur? Kanser etrafındaki dokuları invaze eden kontrolsüzce çoğalan hücrelerin\noluşturduğu hastalıklar için kullanılan bir terimdir.Karsinogenez, çeşitli faktörler sonucu\noluşan genetik/epigenetik değişiklikler ile başlayıp kanser hücresinin oluşumu ile sonuçlanan\nmultistep süreçtir. Erkeklerde akciğer ve prostat kanseri kadınlarda ise meme kanseri\ninsidansı yüksek kanserlerdir.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "I ve III"}, {"letter": "B", "text": "I - II ve III"}, {"letter": "C", "text": "Yalnız III"}, {"letter": "D", "text": "II ve III"}, {"letter": "E", "text": "I ve II"}], "answer": "B", "note": null, "id": "2023-2024_Q37", "explanation": "Kanserin tanımı (I), çok basamaklı (multistep) genetik/epigenetik karsinogenez süreci (II) ve erkeklerde akciğer/prostat, kadınlarda meme kanseri insidansının yüksek olması (III) ifadelerinin **üçü de (I, II ve III) doğrudur**."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "Kanser semptomatolojisi için aşağıdaki ifadelerden hangisi ya da hangileri\ndoğrudur?Erken evre kanserlerde hastalar asemptomatik olabilir.Halsizlik, yorgunluk, kas\nkaybı; özellikle ileri evre-kontrolsüz kanserlerde görülen sistemik inflamasyon ile ilişkili genel\nsemptomlardır.Kanserlerde ilk prezentasyon kolon kanserinde olduğu gibi barsak\nalışkanlıklarının değişmesi gibi klinisyenler tarafından kolayca gözden kaçabilecek\nsemptomlarla olabilir.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "Yalnız II"}, {"letter": "C", "text": "Yalnız III"}, {"letter": "D", "text": "I ve III"}, {"letter": "E", "text": "I - II ve III"}], "answer": "E", "note": null, "id": "2023-2024_Q38", "explanation": "Erken evre kanserlerin asemptomatik olabilmesi (I), ileri evrede sistemik inflamasyona bağlı halsizlik/kas kaybı (II) ve bağırsak alışkanlığı değişikliği gibi sinsi semptomlarla başlayabilmesi (III) ifadelerinin **tamamı (I, II ve III) doğrudur**."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Kanserde erken tehiş ile ilgili aşağıdaki ifadelerden hangisi doğrudur? Birçok\nkanserde sağkalımı belirleyen en önemli faktör evredir, bu nedenle erken teşhiş ile geç evrede\nkanser tanısı alan hasta oranını azaltarak daha iyi sağkalım hedeflenir. Sağlık personelinin ve\nhalkın düşük kanser farkındalığı kanser tanısında geç kalmaya neden olabilir.Erken teşhis\nkonulan hastalarda küratif yaklaşımlarla hastalıksız sağkalım hedeflenirken, erken tanı\nkonulamayan metastatik hastalıkta hedef palyatif yaklaşımlardır.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "I ve II"}, {"letter": "C", "text": "II ve III"}, {"letter": "D", "text": "I ve III"}, {"letter": "E", "text": "I - II ve III"}], "answer": "E", "note": null, "id": "2023-2024_Q39", "explanation": "Sağkalımı belirleyen en önemli faktörün evre olması (I), düşük farkındalığın geç tanıya yol açması (II) ve erken evrede küratif, metastatik evrede palyatif hedeflerin bulunması (III) ifadelerinin **tamamı (I, II ve III) doğrudur**."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 40, "question": "Kanserde tarama ve ulusal kanser tarama programımızla ile ilgili aşağıdaki\nifadelerden hangisi doğrudur? Tarama programlarında hedef premalign lezyonları ya da\nasemptomatik erken evre kanseri yakalamaktır.Kanser taramasında taranacak kanser ile\nilgili risk faktörlerini ve risk faktörlerini taşıyan bireyleri belirlemek olmalıdır. Ülkemizde\nprostat kanseri taramasında 50 yaşından itibaren PSA bakılması önerilmektedir.Meme\nkanseri taramasında Sağlık Bakanlığı’nca 40-69 yaş arasında 2 yılda bir mamografi\nönerilmektedir.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "I – II – III"}, {"letter": "B", "text": "I – II"}, {"letter": "C", "text": "II – III – IV"}, {"letter": "D", "text": "I – II – III – IV"}, {"letter": "E", "text": "I – II – IV"}], "answer": "E", "note": null, "id": "2023-2024_Q40", "explanation": "Ulusal kanser tarama programımızda meme (40-69 yaş 2 yılda bir mamografi), serviks ve kolorektal kanserler yer alır (I, II ve IV doğru); **ülkemizde prostat kanseri için PSA ile rutin ulusal toplum taraması önerilmemektedir** (III yanlış)."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 41, "question": "Kanserde çevresel faktörlerin etkisi ile ilgili aşağıdaki ifadelerden hangisi ya da\nhangileri doğrudur? Çevresel faktörler sadece genomdaki değişikliklerle değil çeşitli\nepigenetik etkilerle de karsinogeneze katkıda bulunabilirler. Tüm etkileri\ndeğerlendirildiğinde, çevresel faktörlerin genetik faktörlere göre karsinogeneze etkileri daha\nfazladır. İşlenmiş et Dünya Sağlık Örgütü tarafından kategori 1 karsinojen (kesin karsinojen)\nolarak sınıflandırılmaktadır. HCV, HBV, HPV ve EBV virüsleri insan vücudunda\nkansinogenezle ile ilişkili virüslerdendir.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "I – II"}, {"letter": "B", "text": "I – II – III"}, {"letter": "C", "text": "II – III – IV"}, {"letter": "D", "text": "II – III"}, {"letter": "E", "text": "I – II – III – IV"}], "answer": "E", "note": null, "id": "2023-2024_Q41", "explanation": "Çevresel faktörlerin genetik/epigenetik etkisi (I), genetik faktörlerden daha büyük paya sahip olması (II), işlenmiş etin DSÖ Grup 1 kesin karsinojen olması (III) ve HCV, HBV, HPV, EBV'nin onkojenik virüsler olması (IV) ifadelerinin **tamamı (I-II-III-IV) doğrudur**."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 42, "question": "Aşağıdaki hastalıklardan hangisi malign lenfoid hastalık değildir?", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "Multipl Myelom"}, {"letter": "B", "text": "Akut Myeloid Lösemi (AML)"}, {"letter": "C", "text": "Kronik Lenfositer Lösemi (KLL)"}, {"letter": "D", "text": "Hodgkin Lenfoma"}, {"letter": "E", "text": "Akut Lenfoblastik Lösemi (ALL)"}], "answer": "B", "note": null, "id": "2023-2024_Q42", "explanation": "Multipl Myelom, KLL, Hodgkin Lenfoma ve ALL **lenfoid** kökenli malignitelerdir; **Akut Miyeloid Lösemi (AML)** ise miyeloid seri öncüllerinden köken alan **miyeloid** bir malignitedir."}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 43, "question": "Hodgkin (HL) ve Hodgkin Dışı Lenfoma (HDL) ile ilgili aşağıdaki ifadelerden\nhangisi yanlıştır?", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "HL’de extranodal tutulum nadirken HDL’de da extranodal tutulum daha sıktır."}, {"letter": "B", "text": "HL B hücreli lenfomalardır; HDL ise çoğunluğu B hücreli olmakla birlikte T hücreli lenfoma da görülebilir."}, {"letter": "C", "text": "HL’de kemik iliği tutulumu görülmezken HDL’de kemik iliği tutulumu olabilir."}, {"letter": "D", "text": "HL önplanda santral lenf bezlerini tutarken HDL hem santral hem de periferik lenf bezlerini tutmaktadır."}, {"letter": "E", "text": "B semptomları her iki lenfoma tipinde de görülebilir."}], "answer": "C", "note": null, "id": "2023-2024_Q43", "explanation": "Hodgkin Lenfomada (HL) ileri evre (Evre IV) hastalıkta **kemik iliği tutulumu görülebilir**; 'HL'de kemik iliği tutulumu görülmez' ifadesi yanlıştır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 38, "id": "2022-2023_Q38"}]}, {"year": "2023-2024", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 44, "question": "Lenfomalar ile ilgili aşağıdaki ifadelerden hangisi ya da hangileri yanlıştır?\nLenfositlerin neoplastik klonal proliferasyonu ile karekterize heterojen hastalık\ngrubudur.Çoğunlukla B lenfositten kaynaklanmakla birlikte lenfomaların %15’inde T ve B\nhücreli lenfoma birlikte bulunabilir.Lenf düğümü (nodal) ve extranodal hastalık birlikte\nbulunmaz.Ateş, kilo kaybı, gece terlemesi denilen “B semptonları” eşlik edebilir.", "professor": "Ahmet Bilgehan Şahin", "options": [{"letter": "A", "text": "I – II"}, {"letter": "B", "text": "I – III – IV"}, {"letter": "C", "text": "I – IV"}, {"letter": "D", "text": "II – III"}, {"letter": "E", "text": "II – III"}], "answer": "D", "note": "Cevaplama Durumu: Soru iptal edildi .", "id": "2023-2024_Q44", "explanation": "Lenfomalarda %15 oranında T ve B hücreli lenfomanın birlikte bulunması (II) ve nodal ile ekstranodal hastalığın birlikte bulunmaması (III) ifadeleri yanlıştır (D ve E şıkları aynı yazıldığı için sınavda iptal edilmiştir).", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 39, "id": "2022-2023_Q39"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 45, "question": "30 yaşında bir adam ormanda tek başına odun kesiyor ve motorlu testerenin\nbacağında derin bir kesik oluşmasına neden olur. Çok miktarda kan kaybeder. Ertesi güne\nkadar bulunamaz Aşağıdaki kan analizlerinden hangisinde belirgin artış , şokta büyük\nolasılıkla geri dönülemez bir aşamaya ulaştığını gösteriyor ?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Antidiüretik hormon"}, {"letter": "B", "text": "Bikarbonat"}, {"letter": "C", "text": "Kateşolaminler"}, {"letter": "D", "text": "Laktat dehidrojenaz"}, {"letter": "E", "text": "Protrombin"}], "answer": "D", "note": null, "id": "2023-2024_Q45", "explanation": "Ağır hipovolemik/hemorajik şokta yaygın hücresel hipoksi ve membran bütünlüğünün bozulması (hücre nekrozu) sonucunda dolaşımda **Laktat Dehidrojenaz (LDH)** ve laktat düzeylerinin belirgin artışı, şokun **geri dönüşümsüz (irreverzibl) evreye** ulaştığını gösterir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 46, "question": "63 yaşında bir erkek, kronik artrit hastasıdır son 15 yıldır. Fizik muayenede ulnar\ndeviasyon görülüyor, kuğu boynu deformitelerine neden olan kemik ankilozuyla birlikte.\nLaboratuar çalışmaları 4,2 g protein olduğunu göstermektedir24 saatlik idrar toplamada.\nSerum kreatinin düzeyi 3,1 g/dL ve üre nitrojeni 3 g/dL. C-reaktif protein düzeyi belirgin\nşekilde yükselmiş. Rektal biyopsi yapılır, mukozada H&E boyama ile amorf pembe\nmalzemenin birikmesi izlenir. Materyal Kongo kırmızısı ile pozitif boyanır. Aşağıdaki\nproteinlerden hangisinin bu materyalin öncüsü olması daha olasıdır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut faz reaktanı"}, {"letter": "B", "text": "Beta-2 mikroglobülin"}, {"letter": "C", "text": "Lambda hafif zincir"}, {"letter": "D", "text": "Transtretin"}, {"letter": "E", "text": "Romatoid faktör"}], "answer": "A", "note": null, "id": "2023-2024_Q46", "explanation": "15 yıllık kronik inflamatuar hastalık (**Romatoid Artrit**) zemininde gelişen nefrotik sendrom ve rektal biyopside Kongo kırmızısı pozitif amiloid birikimi **Sekonder (Reaktif / AA) Amiloidoz**dur; öncül proteini karaciğerden salınan bir **akut faz reaktanı olan SAA (Serum Amiloid A)**'dır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 47, "question": "40 yaşında bir erkeğe perfore sigmoid kolon divertikülü nedeniyle laparotomi\nyapıldı. Bir yara enfeksiyonu ameliyat sonrası süreci zorlaştırdı ve ameliyat yarası ayrılma\nmeydana geldi. Birincil kapatma artık mümkün değildi,ve yara \"granüle olmuş\"tu. Altı hafta\nsonra, yara orijinal boyutunun sadece %10'u kadardır. Aşağıdakilerden hangisi son 6\nhaftadaki yara büyüklüğünde gözlenen azalmayı en iyi şekilde açıklayan süreçtir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Adheziv glikoproteinlerin üretimi"}, {"letter": "B", "text": "Kollajen sentezinde artış"}, {"letter": "C", "text": "Metalloproteinazlrın inhibisyonu"}, {"letter": "D", "text": "Myofibroblast kontraksiyonu"}, {"letter": "E", "text": "Subkütan ödeömin çözülmesi"}], "answer": "D", "note": null, "id": "2023-2024_Q47", "explanation": "Geniş doku kaybı olan ve sekonder iyileşen yaraların (granülasyon dokusunun) 6 hafta içinde orijinal boyutunun %10'una kadar küçülmesini sağlayan temel mekanizma, düz kas aktini içeren **miyofibroblastların kontraksiyonudur (yara kontraksiyonu)**.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 81, "id": "2024-2025_Q81"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 48, "question": "11 yaşındaki çocuk düşüp elini kesti. Yara enfekte oldu. Bakteriler hücre dışı\nmatrikse doğru uzanır kılcal damarların etrafında. Bu enfeksiyona verilen inflamatuar\nyanıtta, aşağıdaki hücrelerden hangisi bakterileri yok eder?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "B lenfosit"}, {"letter": "B", "text": "Fibroblast"}, {"letter": "C", "text": "Makrofaj"}, {"letter": "D", "text": "Mast hücresi"}, {"letter": "E", "text": "T lenfosit"}], "answer": "C", "note": null, "id": "2023-2024_Q48", "explanation": "Verilen şıklar arasında ekstrasellüler matriksteki bakterileri fagosite ederek hücre içinde öldüren fagositik doğal immün sistem hücresi **Makrofaj**dır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 49, "question": "37 yaşında erkek hasta bir süredir midepigastrik ağrı çekiyordu. Üst\ngastrointestinal endoskopi şunu gösterir: Midede 2 cm'lik, keskin sınırlı, sığ ülserasyon\nantrumda görülüyor. Ülserden alınan biyopsinin mikroskobik incelenmesi temelde\nanjiyogenez, fibrozis ve mononükleer hücre sızıntılarını gösterir( Lenfositler, makrofajlar ve\nplazma hücreleri ile). Aşağıdaki terimlerden hangisi bu patolojiyi en iyi şekilde tanımlar?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut iltihap"}, {"letter": "B", "text": "Kronik iltihap"}, {"letter": "C", "text": "Fibrinöz iltihap"}, {"letter": "D", "text": "Granülomatöz iltihap"}, {"letter": "E", "text": "Seröz iltihap"}], "answer": "B", "note": null, "id": "2023-2024_Q49", "explanation": "Biyopside yeni damar oluşumu (**anjiyogenez**), **fibrozis** ve **mononükleer hücre infiltrasyonu (lenfosit, makrofaj, plazma hücresi)** triadı **Kronik İltihap (Kronik İnflamasyon)** için tanısaldır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 50, "question": "35 yaşında bir kadın asetilsalisilik asit (aspirin) kullanıyor artrit için. Bu terapiyle\neklem ağrıları azalsa da, inflamatuar süreç devam ediyor. Aspirin tedavisi aşağıdaki\naracılardan hangisi esas olarak sentezindeki azalma yoluyla ağrıyı hafifletir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kompleman C1q"}, {"letter": "B", "text": "Lökotrien E4"}, {"letter": "C", "text": "Histamin"}, {"letter": "D", "text": "Nitrik oksit"}, {"letter": "E", "text": "Prostoglandinler"}], "answer": "E", "note": null, "id": "2023-2024_Q50", "explanation": "Aspirin (asetilsalisilik asit), COX-1 ve COX-2 enzimlerini irreversibl asetilleyerek **Prostaglandinlerin (özellikle PGE2 ve PGI2)** sentezini azaltır ve bu yolla inflamatuar ağrıyı hafifletir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 51, "question": "Bir deneyde bakteriler belirli miktarlarda eklenir antikoagülan ile muamele edilmiş\nnormal insan kanına. Bakterilerin, nötrofiller tarafından fagosite edildiği gözlendi veya lizize\nuğradığı saptandı. Aşağıdaki plazma bileşenlerinin hangisi bu etkileri kolaylaştırmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kompleman"}, {"letter": "B", "text": "Fibrin"}, {"letter": "C", "text": "Kallikrein"}, {"letter": "D", "text": "Plasmin"}, {"letter": "E", "text": "Trombin"}], "answer": "A", "note": null, "id": "2023-2024_Q51", "explanation": "Plazmada bulunan **Kompleman sistemi**, bakterileri **C3b** ile opsonize ederek nötrofiller tarafından fagositozunu kolaylaştırır ve **Membran Atak Kompleksi (C5b-9 MAC)** oluşturarak bakterilerin doğrudan lizise uğramasını sağlar.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 78, "id": "2024-2025_Q78"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 52, "question": "Farmakolojik bir ajanın 6 aylık randomize bir çalışmasında, bir grup hasta\nsiklooksijenaz-2 (COX-2) inhibitörünü alıyor, ve bir kontrol grubu bunu almıyor. Her iki\nyetişkin erkek grubunda da hafif konjestif kalp yetmezliği ve iki taraflı simetrik artrit var\nküçük eklemlerde. Deneme sırasındaki laboratuvar ölçümleri hiçbir farklılık göstermedi iki\ngrup arasında lökosit sayısı, trombosit sayısı,hemoglobin ve kreatinin. İlacın verildiği grup\nkontroldekilerden farklı subjektif bulguları rapor eder. Aşağıdaki bulgulardan hangisinin\nbildirilmiş olması muhtemeldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Ayak bileğinde şişme"}, {"letter": "B", "text": "Morarma (berelenmeye) yatkınlık"}, {"letter": "C", "text": "Azalmış artrit ağrısı"}, {"letter": "D", "text": "Artmış astım atakları"}, {"letter": "E", "text": "Artmış ateşli ataklar"}], "answer": "C", "note": null, "id": "2023-2024_Q52", "explanation": "Selektif **COX-2 inhibitörü** kullanan artritli hastalarda prostaglandin sentezinin baskılanmasına bağlı olarak kontrol grubuna kıyasla **artrit (eklem) ağrısında belirgin azalma** görülür."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 53, "question": "56 yaşında kadına sol memesinde kanser teşhisi konuldu.Koltuk altı lenf düğümü\ndisseksiyonu ile birlikte mastektomi uygulandı. Ameliyattan sonra sol kolda 6 aydır devam\neden belirgin bir şişlik gelişir. muayenede ateşi 36.9°C. Sol kolu hassas veya eritemli değil ve\nhareketle ağrılı değil. Fakat hamur kıvamında şiştir. Bu olayların en muhtemel mekanizması\naşağıdakilerden hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Sellülitis"}, {"letter": "B", "text": "Konjestif kalp yetmezliği"}, {"letter": "C", "text": "Azalmış plazma onkotik basıncı"}, {"letter": "D", "text": "Lenfödem"}, {"letter": "E", "text": "Flebotrombozis"}], "answer": "D", "note": null, "id": "2023-2024_Q53", "explanation": "Meme kanseri nedeniyle yapılan mastektomi ve **aksiller lenf nodu diseksiyonu** sonrasında lenfatik drenajın bozulmasına bağlı olarak aynı taraf kolda gelişen ağrısız, eritemsiz, gode bırakmayan/hamur kıvamındaki şişlik **Lenfödem**dir (sekonder lenfatik obstrüksiyon)."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 54, "question": "İğne batması yaralanmasından kaynaklanan yüzeysel bir delik yarası sağlıklı bir\ninsanda az miktarda kanamaya neden olur. Bu yaralanma meydana geldikten sonra saniyeler\niçinde kanama durur. Aşağıdaki mekanizmalar dan hangisi büyük ihtimalle küçük\narteriyollerdeki bu kan kaybını durduracaktır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Fibrin polimerizasyonu"}, {"letter": "B", "text": "Nötrofil kemotaksisi"}, {"letter": "C", "text": "Trombosit agregasyonu"}, {"letter": "D", "text": "Proteiin C aktivasyonu"}, {"letter": "E", "text": "Vazokonstrksiyon"}], "answer": "E", "note": null, "id": "2023-2024_Q54", "explanation": "Endotel/damar yaralanmasından hemen sonra **ilk birkaç saniye içinde** küçük arteriyollerde kan kaybını durduran ilk hemostatik yanıt, nörojenik refleks ve endotelin salınımına bağlı **geçici arteriyoler vazokonstrüksiyondur**."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 55, "question": "23 yaşında bir kadının bilinci bozuldu ve sSon 24 saattir geveleyerek konuşmaya\nbaşladı. Bir kafa CT taraması şunları gösterir:sağ temporal hemorajik enfarktüs. Serebral\nanjiyografi, distal sağ orta serebral arter tıkanıklığını gösteriyor. Son 3 yılda bir pulmoner\nemboli atağı geçirdi. 18 ay önceki hamileliği düşükle sonuçlandı. Laboratuvar çalışmaları\nfrengi için serolojik testin yanlış pozitif olduğunu gösteriyor, normal protrombin zamanı (PT),\nartmış parsiyel tromboplastin süresi (PTT) ve normal trombosit sayısı saptanıyor\nAşağıdakilerden hangisi Bu bulguların en olası nedenidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Antifosfolipid antikoru"}, {"letter": "B", "text": "Dissemine intravasküler koagülasyon"}, {"letter": "C", "text": "Faktör V mutasyonu"}, {"letter": "D", "text": "Hiperkolestrolemi"}, {"letter": "E", "text": "von Willebrand hastalığı"}], "answer": "A", "note": null, "id": "2023-2024_Q55", "explanation": "Genç kadında tekrarlayan arteriyel/venöz trombozlar (inme, pulmoner emboli), **tekrarlayan gebelik kayıpları (düşük)**, **yalancı pozitif sifiliz (VDRL) testi** ve in vitro uzamış aPTT (lupus antikoagülanı) tablosu **Antifosfolipid Antikor Sendromu** için klasiktir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 56, "question": "33 yaşında bir erkekte son bir haftada, bulantı,kusma ve hafif sarılık gelişti. Fizik\nmuayenede ısı 37.4 C. Laboratuar incelemelerinde serum AST 208 U/lt, serum ALT 274\nU/lt.dir. Serolojik olarak HBsAg ve HBcAb pozitif. Karaciğer biyopsi örneğinde\nhepatositlerde fokal ölüm ve portal iltihabi hücre infiltrasyonu mevcut. Bu durumda\naşağıdaki mekanizmalardan hangisi en olası karaciğer hücre hasarına yol açmaktadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Aktive makrofajların sitokin salımı"}, {"letter": "B", "text": "HBsAg sunan hepatositlerin antikor ile hasarlanması"}, {"letter": "C", "text": "Dolaşımdaki HBsAgnin CD4+ lenfositlerce tanınması"}, {"letter": "D", "text": "MHC class1 moleküllerce sunulan viral peptidlerin CD8+ lenfositlerce tanınması"}, {"letter": "E", "text": "MHC clas II moleküllerce sunulan viral peptidlerin NK hücrelerce tanınması"}], "answer": "D", "note": null, "id": "2023-2024_Q56", "explanation": "Akut Hepatit B enfeksiyonunda hepatosit ölümü, enfekte karaciğer hücrelerinin yüzeyindeki **MHC Sınıf I molekülleriyle sunulan viral peptidlerin CD8+ sitotoksik T lenfositler tarafından tanınması** ve apoptoza uğratılması sonucu gerçekleşir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 45, "id": "2022-2023_Q45"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 57, "question": "Fungal sporlara \"allerjik\" olan bir laboratuvar teknisyeni, bir cuma öğleden sonra,\nkazayla bir fungus kültürüne maruz kalır. Bir saat içerisinde hapşırma, gözlerde sulanma ve\nburun akıntısı gelişir. Eve döndükten sonra birkaç saat içerisinde düzelir, ancak ertesi sabah\nsemptomlar tekrar ortaya çıkar; oysa ev ortamında laboratuvardaki fungus mevcut değildir.\nSemptomları hafta sonu boyunca devam eder. Aşağıdaki hücrelerden hangisi, hastanın burun\nakıntısının mikroskopik incelemesinde en muhtemel baskın tip olacaktır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Dendritic cells"}, {"letter": "B", "text": "Eozinofil lökositler"}, {"letter": "C", "text": "Makrofajlar"}, {"letter": "D", "text": "Mast hücreleri"}, {"letter": "E", "text": "NK hücreler"}], "answer": "B", "note": null, "id": "2023-2024_Q57", "explanation": "Alerjik rinit ve astımda (Tip I hipersensitivite) alerjen maruziyetinden saatler sonra ortaya çıkan ve günlerce süren **geç faz reaksiyonunda** mukozada ve burun salgısında en baskın inflamatuar hücre **Eozinofil lökositlerdir**."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 58, "question": "28 yaşında bir erkekte son iki gündür hemoptizi ve hematüri var. Fizik muayenede\nateşi 36,8 derece, solunum 19/dk ve tansiyon 150/90 mm Hg. Laboratuvar bulgularında\nkreatinin 3,8 mg/dl, üre nitrojeni 35 mg/dl. İdrar tahlilinde +4 hematüri, +2 proteinüri olup\nglükoz yoktur. Böbrek biyopsisinin mikroskopik incelemesinde glomerül hasarı ile\nkompleman C3 ve anti IgG ile lineer imünfloresans saptanmaktadır. Bu hastanın durumunda\naşağıdaki otoantikorların hangisi en yüksek spesifiteye sahiptir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Anti–basement membrane"}, {"letter": "B", "text": "Anticardiolipin"}, {"letter": "C", "text": "Anti–double-stranded DNA"}, {"letter": "D", "text": "Antihistone"}, {"letter": "E", "text": "Anti–SS-A"}], "answer": "A", "note": null, "id": "2023-2024_Q58", "explanation": "Hemoptizi (akciğer kanaması) ve hematüri/hızlı ilerleyen glomerülonefrit ile başvuran ve böbrek biyopsisinde **lineer IgG ve C3 immünfloresan birikimi** saptanan hastada tanı **Goodpasture sendromu** olup spesifik otoantikoru **Anti-glomerüler bazal membran (Anti-GBM; Tip IV kollajen alfa-3 zincirine karşı) antikorudur**."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 59, "question": "35 yaşında bir kadına myeloblastik lösemi neneyle allojenik hematopoitik kök hücre\ntransplantasyonu yapılıyor. Bir ay sonra deride yaygın , pullanan döküntüler gelişiyor. Ayrıca\nsarılık ve sulu diyare de mevcut. Deri biyopsisinde dermoepidermal bileşkede keratinosit\napopitozisi ve üst dermisde lenfositik infiltratlar izleniyor. aşağıdakilerden hangisi kök hücre\ntransplant komplikasyonunda rol oynayan en olası mekanizmadır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut graft-versus-host hastalığı"}, {"letter": "B", "text": "Antikora bağlı hücresel sitotoksisite"}, {"letter": "C", "text": "Gecikmiş tip hipersensitivite reaksiyonu"}, {"letter": "D", "text": "İmmün kompleks oluşumu"}, {"letter": "E", "text": "Mast hücrelerinden sitokin salınımı"}], "answer": "A", "note": null, "id": "2023-2024_Q59", "explanation": "Allojenik kök hücre naklinden 1 ay sonra gelişen deri döküntüsü (keratinosit apoptozu), sarılık ve diyare tablosu, verici T lenfositlerinin alıcı dokularını hedef aldığı **Akut Graft-Versus-Host Hastalığı (GVHD)**'dır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 48, "id": "2022-2023_Q48"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 60, "question": "İki yaşında bir oğlan çocuğu altı aylıktan beri devamlı enfeksiyon geçiriyor. (Otitis\nmedya, pnömoni ve impetigo gibi). Kültürde Haemophilus influenzae, Streptococcus\npneumoniae ve Staphylococcus aureus ürüyor. ayrıca diyaresi olup Giardia lamblia izlenmiş.\naile öyküsünde büyük erkek kardeşinin benzer enfeksiyonlardan öldüğü öğreniliyor. İki kız\nkardeşi ile anne ve babası normal. Bu çocukta en muhtemel olarak hangi laboratuar bulgusu\nsaptanacaktır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "IgA yokluğu"}, {"letter": "B", "text": "Agammaglobulinemia"}, {"letter": "C", "text": "Kompleman C3de azalma"}, {"letter": "D", "text": "Yüksek titrede HIV-1 RNA"}, {"letter": "E", "text": "Pozitif ANA testi"}], "answer": "B", "note": null, "id": "2023-2024_Q60", "explanation": "6. aydan sonra başlayan tekrarlayan piyojenik bakteri (S. pneumoniae, H. influenzae, S. aureus) ve Giardia lamblia enfeksiyonları ile X'e bağlı kalıtım öyküsü **Bruton hastalığı (X'e bağlı Agammaglobulinemi)** olup laboratuvarda **agammaglobulinemi** saptanır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 49, "id": "2022-2023_Q49"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 61, "question": "9 yıldır uyuşturucu kullanımı enjeksiyon öyküsü olan 28 yaşında kadın hasta kronik\nsulu ishal geliştirmiştir. Fizik muayenede ateş yok ve hafif kas kaybı var. Onun vücut kitle\nindeksi 18dir. Dışkısındaki laboratuvar çalışmaları Cryptosporidium parvum kistlerini\ngösteriyor. Bir ay sonra kriptokokal menenjit hastalığına yakalandı ve başarıyla tedavi edildi.\nOral kandidiyaz 1 ay sonra teşhis konuldu. Bu hastada aşağıdaki neoplazmlardan hangisinin\ngelişmesien yüksek ihtimaldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Serebral astrositoma"}, {"letter": "B", "text": "Servikal clear cell karsinoma"}, {"letter": "C", "text": "Serebral non-Hodgkin lenfoma"}, {"letter": "D", "text": "Akciğer adenokarsinomu"}, {"letter": "E", "text": "Retropreitoneal sarkom"}], "answer": "C", "note": null, "id": "2023-2024_Q61", "explanation": "İV ilaç kullanımı, kriptosporidiyoz, kriptokok menenjiti ve oral kandidiyazis ile başvuran **AIDS (ileri HIV)** hastasında EBV enfeksiyonuna ikincil olarak gelişme olasılığı en yüksek malignite **Primer Serebral (SSS) Non-Hodgkin Lenfoma**dır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 62, "question": "Kaydedilen kanser ölümlerine ilişkin epidemiyolojik bir çalışma 20. yüzyılın son\nyarısı yürütüldü. Belirli bir kansere bağlı ölümler önemli ölçüde arttı gelişmiş milletlerde.\nErkeklerde kanserden ölümlerin yüzde 30'undan fazlası, kadınlarda kanserden ölümlerin\n%24'ünden fazlasının nedeni 1998 yılında bu neoplazm tarafından tespit edilmiştir. Bazı\nülkelerde önleme stratejileri bu kanserden ölümleri azalttı. Aşağıdakilerden hangi\nneoplazmlar büyük olasılıkla bu çalışmayla tanımlandı?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Serebral glioma"}, {"letter": "B", "text": "Bronkojenik karsinoma"}, {"letter": "C", "text": "Hepatosellüler karsinoma"}, {"letter": "D", "text": "Kolon adenokarsinomu"}, {"letter": "E", "text": "Deri malign melanomu"}], "answer": "B", "note": null, "id": "2023-2024_Q62", "explanation": "20. yüzyılın ikinci yarısında sigara kullanımına paralel olarak insidansı hızla artan ve hem erkeklerde hem de kadınlarda kansere bağlı ölümlerin birinci sırasına yerleşen malignite **Bronkojenik karsinom (Akciğer kanseri)**'dur."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 63, "question": "53 yaşında erkek hastaya ağız kanseri teşhisi konuldu ve 1 yıl önce radyasyon ve\nkemoterapi tedavisi görmüş, şimdi iseboynunun pozitron emisyon tomografisi (PET) taraması\nile artantutlumun bir odağını gösterir. Bu odak resekte edildi ve mikroskobik incelemede\nbunun bir metastaz olduğu anlaşıldı. Moleküler analizi p53, PTEN ve c-MYCde mutasyonları\ngösteriyor. Aşağıdaki metabolik yollardan hangisi üyük olasılıkla kanser hücresinin hayatta\nkalmasını ve çoğalmasını desteklemek için yukarı regüle edilmiştir(up-regulated)?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Aerobik glikolizis"}, {"letter": "B", "text": "Glukoneogenezis"}, {"letter": "C", "text": "Heksoz monofosfat şantı"}, {"letter": "D", "text": "Oksidatif fosforilasyon"}, {"letter": "E", "text": "Pürin degradasyonu"}], "answer": "A", "note": null, "id": "2023-2024_Q63", "explanation": "PET-BT'de yüksek FDG (glukoz) tutulumu gösteren ve c-MYC/p53/PTEN mutasyonları taşıyan kanser hücrelerinde biyosentez ve hızlı çoğalmayı desteklemek için yukarı regüle edilen metabolik yol **Aerobik glikoliz (Warburg etkisi)**'dir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 64, "question": "51 yaşında sağlıklı bir erkeğe tarama kolonoskopisi yapıldı. Belirtilen tek\nlezyon,sigmoid bölgede bulunan 0,6 cm çapında sapsız bir kitledir. Bu kütle,yüzeyden 0.2 cm\nkabarıktır. Pürüzsüz bronz bir yüzeye sahiptir ve iyi tanımlanmış sınırları vardır. Aşağıdaki\nterimlerden hangisi en bu kütlenin mikroskobik görünümünü tanımlaması muhtemeldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Adenoma"}, {"letter": "B", "text": "Papilloma"}, {"letter": "C", "text": "Fibroma"}, {"letter": "D", "text": "Karsinoma"}, {"letter": "E", "text": "Sarkoma"}], "answer": "A", "note": null, "id": "2023-2024_Q64", "explanation": "Tarama kolonoskopisinde sigmoid kolonda saptanan 0.6 cm çapında, iyi sınırlı, sesil (sapsız) benign glandüler neoplastik polip **Adenoma** olarak tanımlanır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 65, "question": "54 yaşında bir kadın sağ göğsünde bir yumru fark ediyor. Fizik muayenede,\nareolanın altındaki alttaki dokulara sabitlenmiş 2 cm'lik bir kitle ve üç sert, hassas olmayan,\nsağ palpe edilebilen lenf düğümleri var. Ailede kanser öyküsü yok. Eksizyonel meme biyopsisi\nyapılır, ve mikroskobik inceleme, şekildeki bulguları gösterir. Önümüzdeki 6 ay içinde ek lenf\ndüğümleri büyümüş ve BT taramaları akciğerde, karaciğer ve beyinde nodüller olduğunu\ngösteriyor. Aşağıdaki moleküler anormalliklerden hangisinin karsinom hücrelerinde bulunma\nolasılığı en yüksektir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "ERBB2(HER2) gen amplifikasyonu"}, {"letter": "B", "text": "RB gen kopyası delesyonu"}, {"letter": "C", "text": "BCR-C-ABL gen füzyonu"}, {"letter": "D", "text": "BRCA1 gen kopyasının inaktivasyonu"}, {"letter": "E", "text": "Bir TP53 gen kopyasının mutasyonu"}], "answer": "A", "note": null, "id": "2023-2024_Q65", "image": "data:image/jpeg;base64,", "explanation": "Aile öyküsü olmayan (sporadik) meme karsinomunda erken lenf nodu ve uzak organ (akciğer, karaciğer, beyin) metastazı ile agresif seyir gösteren olgularda tümör hücrelerinde en olası somatik genetik anomali **ERBB2 (HER2/neu) gen amplifikasyonudur**."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 66, "question": "3 yaşında bir çocukta sağ gözde görme ile ilgili zorluk var. Fizik muayenedesağ\ngözde lökokori var, arka kamarada bir kitle ile uyumlu. MR görüntüleme,göz yuvarlağını\nneredeyse dolduran bir kütleyi gösterir. Çocuğun Sağ gözü enüklee edilir. Moleküler analizde\nneoplastik hücreler, bir genin her iki kopyasının da olmadığını gösterir. Bu gen hücre\ndöngüsünün kontrolüne katkıda bulunur. Bu neoplazmada aşağıdaki genlerden hangisinin\nmutasyona uğraması daha olasıdır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "BCR-ABL"}, {"letter": "B", "text": "BCL2"}, {"letter": "C", "text": "KRAS"}, {"letter": "D", "text": "NF1"}, {"letter": "E", "text": "RB"}], "answer": "E", "note": null, "id": "2023-2024_Q66", "explanation": "3 yaşında çocukta lökokori ve göz içi kitle (**Retinoblastom**) gelişiminde her iki alleli (kopyası) da inaktive olan ve G1/S hücre döngüsü kontrol noktasını düzenleyen tümör süpresör gen **RB (RB1)** genidir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 67, "question": "20. yüzyılın ikinci yarısındaki kanser ölümleri ile ilgili bir çalışma yapılmış.\nGeelişmiş uluslarda spesifik bir kanser tipinin, tarama ve önleme programları olmamasına\nrağmen azaldığı saptanmış. Bu çalışmada en muhtemel olarak hangi kanser tipi saptanmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Serebral glioma"}, {"letter": "B", "text": "Gastrik adenokarsinoma"}, {"letter": "C", "text": "Hepatik anjiosarkoma"}, {"letter": "D", "text": "Lösemi"}, {"letter": "E", "text": "Akciğerin küçük hücreli kanseri"}], "answer": "B", "note": null, "id": "2023-2024_Q67", "explanation": "20. yüzyılın ikinci yarısında gelişmiş ülkelerde özel bir tarama programı olmamasına rağmen gıda saklama koşullarının (soğutma/buzdolabı) iyileşmesiyle insidansı ve mortalitesi belirgin azalan kanser **Gastrik adenokarsinom (Mide kanseri)**'dur.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 53, "id": "2022-2023_Q53"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 68, "question": "55 yaşında bir kadın sol memsinde büyüen bir kitleyi bir yıldır farketmiş. Sol\nmemede 5 cm çapında, göğüs duvarına fikse, sert, düzensiz kitle saptanıyor. Sol aksillada,\nhassa olamayan lenfadenopati mevcut. Hepatosplenomegali yok. Akciğer tomografisinde,\nmultipl, bilateral \"gülle\" gibi nodüller görülüyor. Sol memeden alınan biyopside yüksek\ngrade'li infiltratif duktal kanser izleniyor. Akciğerlerindeki nodüller en muhtemel olarak\naşağıdakilerdn hangisine bağlıdır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tümörün internal mammary arteri invazyonu"}, {"letter": "B", "text": "Meme ve plevra arasındaki lenfatik bağlantılar"}, {"letter": "C", "text": "Knser hücre nukleuslarında östrojen resptörlerinin overekspresyonu"}, {"letter": "D", "text": "Meme kanserinin akciğere yakınlığı"}, {"letter": "E", "text": "Kanser hücre reseptörlerini bağlayan pulmoner kemokinler"}], "answer": "E", "note": null, "id": "2023-2024_Q68", "explanation": "Meme kanserinin akciğere metastaz yapma eğilimi (organ tropizmi), meme kanseri hücrelerindeki kemokin reseptörlerini (CXCR4, CCR7) bağlayan **pulmoner kemokinler** ile açıklanır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 54, "id": "2022-2023_Q54"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 69, "question": "23 yaşındaki bir kadın göğüs cildinde bir nodül fark etti üst göğsü. Nodülün uzun\nyıllar boyu değişmediği ve boyutunun değişmeden mevcut olduğunu bildirdi. Eksize edilir ve\nmikroskobik görünümü şekilde gösterilmiştir. Aşağıdaki neoplazmlardan hangisinin bu\nlezyonun olma olasılığı yüksektir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Fibroadenoma"}, {"letter": "B", "text": "Hemanjioma"}, {"letter": "C", "text": "Leiomyoma"}, {"letter": "D", "text": "Lipoma"}, {"letter": "E", "text": "Nevüs"}], "answer": "B", "note": null, "id": "2023-2024_Q69", "image": "data:image/jpeg;base64,", "explanation": "Ciltte uzun yıllardır değişmeden duran ve mikroskopide eritrositlerle dolu, tek katlı endotelle döşeli çok sayıda vasküler kanaldan oluşan benign vasküler tümör **Hemanjiom (Kapiller/Kavernöz Hemanjiom)**'dur."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 70, "question": "Epidemiyolojik bir çalışma 50 yaşından büyüklerin kişilere uygulanan kanser\ntarama tekniklerinin sağlık hizmetlerinin faydalarını analiz ediyor.. Aşağıdaki tanı\ntaramalarından hangisi en büyük olasılıkla Avrupa ve Kuzey Amerikada'de kanser\nölümlerinin azaltılması üzerindeki etkisi vardır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akciğer röntgeni"}, {"letter": "B", "text": "Mamografi"}, {"letter": "C", "text": "Serum tümör markerları"}, {"letter": "D", "text": "Dışkıda gizli kan testi"}, {"letter": "E", "text": "İdrar sitolojisi"}], "answer": "B", "note": null, "id": "2023-2024_Q70", "explanation": "Avrupa ve Kuzey Amerika'da 50 yaş üstü kadınlarda uygulanan ve meme kanseri mortalitesini kanıtlanmış şekilde azaltan radyolojik tarama yöntemi **Mamografi**dir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 71, "question": "Aterosklerotik kardiyovasküler komplikasyonların görüldüğü ailelerden deneklerle\nbir klinik çalışma yapılmıştır. Hastalık ve tendinöz ksantomlar 30 yaşından önce ortaya çıktı.\nBu ailelerdeki çocukların bir kısmının erken aterom oluşumu var. Bu etkilenen bireyler\nHMG-CoA redüktaz inhibe eden farmakolojik ajanlarla tedaviden yarar görüyor. Bu\nailelerde etkilenen bireyler hangi yüzey reseptörü Için bir hücreyi kodlayan bir gende\nmutasyon olması muhtemeldir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kortizol"}, {"letter": "B", "text": "İnsülin"}, {"letter": "C", "text": "LDL resptörü"}, {"letter": "D", "text": "Leptin"}, {"letter": "E", "text": "TGF-alfa"}], "answer": "C", "note": null, "id": "2023-2024_Q71", "explanation": "30 yaşından önce tendinöz ksantomlar ve erken ateroskleroz ile seyreden ve statinlerden (HMG-KoA redüktaz inhibitörleri) yarar gören **Ailesel Hiperkolesterolemi**, **LDL reseptörü** genindeki mutasyon sonucu gelişir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 72, "question": "11 yaşında zihinsel engelli bir çocuk beslenme ve giyinme dahil günlük yaşam\naktiviteleri gerçekleştirebiliyor. Fizik muayenede brakisefali ve belirgin epikantal kıvrımları\nolan oblik palpebral fissürler var. Her elin avuç içinde transvers çizgi görülür. Oskültasyonda\ngöğüste, derece III/VI sistolik üfürüm var. 20 yaşına kadar aşağıdaki hastalıklardan hangisini\ngeliştirmesi daha olasıdır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut lösemi"}, {"letter": "B", "text": "Akut myokard enfarktı"}, {"letter": "C", "text": "Aort disseksiyonu"}, {"letter": "D", "text": "Kronik böbrek yetmezliği"}, {"letter": "E", "text": "Karaciğer sirozu"}], "answer": "A", "note": null, "id": "2023-2024_Q72", "explanation": "Zihinsel engel, brakisefali, epikantal kıvrımlar, avuç içinde tek transvers (simian) çizgi ve konjenital kalp hastalığı (endokardiyal yastık defekti) **Down sendromu (Trizomi 21)** bulgularıdır; bu çocuklarda 20 yaşına kadar **Akut lösemi (ALL ve AML-M7)** gelişme riski 10-20 kat artmıştır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 73, "question": "16 yaşında bir primigravid kadın gebeliğinin 18. haftasında fötal hareket\nhissetmiyor, ultrason çekiliyor. Amniotik sıvı belirgin azalmış. Fötal böbrekler kistik olup biri\ndiğerinden daha büyük. Fötal kardiak aktivite yok. Gebelik sonlandırılıp fötal otopsi\nyapılıyor. Multikistik renal displazi, hemivertebra, anal atrezi, trkeoözofageal fistül olup\nakciğerler 14 haftaya uymakta. Morfogenezdeki hangi hata fötal akciğerlerin böyle olmasına\nyol açmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Agenesis"}, {"letter": "B", "text": "Aplazi"}, {"letter": "C", "text": "Deformasyon"}, {"letter": "D", "text": "Disrupsiyon"}, {"letter": "E", "text": "Malformasyon"}], "answer": "C", "note": null, "id": "2023-2024_Q73", "explanation": "Multikistik renal displaziye bağlı ağır oligohidramniyos sonucunda fetüsün uterus duvarı tarafından mekanik basıya uğraması ve akciğer hipoplazisi gelişmesi (Potter sekansı), ekstrensek mekanik güçlerle oluştuğu için bir **Deformasyon** örneğidir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 55, "id": "2022-2023_Q55"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 74, "question": "23 yaşında bir afrikan-amerikan erkek, fenasetin içeren bir antiinflamatuar ilaç\naldıktan sonra koyu kırmızı-kahverengi idrar çıkartıyor. Tüm hayatı boyunca sağlıklı olduğu\niçin şaşırıyor. Fizik mayenede ateşi yok, kaydadeğer bir bulgu saptanmıyor. Kanda hafif\nnormositik anemi saptanıyor; ancak periferik kanda supravital boyama ile Heinz cisimcikleri\n(denatüre globin) ile ısırı \"bite\" hücreleri gözleniyor. En muhtemel tanı hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Alfa talassemi minör"}, {"letter": "B", "text": "Beta talassemi minör"}, {"letter": "C", "text": "Glükoz-6-fosfat-dehidrojenaz yetmezliği"}, {"letter": "D", "text": "orak hücre trait (sickle cell trait)"}, {"letter": "E", "text": "Sıcak antikor otoimmün hemolitik anemisi"}], "answer": "C", "note": null, "id": "2023-2024_Q74", "explanation": "Oksidan ilaç (fenasetin) alımı sonrası akut intravasküler hemoliz ve supravital boyamada **Heinz cisimcikleri** ile **ısırık (bite) hücreleri** görülmesi **Glukoz-6-Fosfat Dehidrogenaz (G6PD) yetmezliği** için tanısaldır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 60, "id": "2022-2023_Q60"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 75, "question": "Mutasyonları kalıtsal olarak alan hastalarda klinik bir çalışmada eritosit membran\nhücre iskeletindeki spektrin için ana bağlanma bölgesi olan ankirin seviyesini azaltıyor.\nSplenomegali ile kronik anemi prevalansı artan bir artış gösterir. Birçok hastalarda\nsplenektominin aneminin şiddetini azalttığı gözlemlenmiştir. Splenektominin bu yararlı etkisi\nbüyük olasılıkla aşağıdaki süreçlerden hangisi ile ilgilidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Eritrositlerin opsonizasyonunu ve dalaktaki lizisi azaltmak"}, {"letter": "B", "text": "Dalaktaki makrofajlarda reaktif oksijen türevlerini azaltmak"}, {"letter": "C", "text": "Dalaktaki eritrosit sekestrasyon ve lizisini azaltmak"}, {"letter": "D", "text": "Eritrositlerin dalak sinüzoidlerindeki deformabilitesini artırmak"}, {"letter": "E", "text": "Dalaktaki demir birikimini artırmak"}], "answer": "C", "note": null, "id": "2023-2024_Q75", "explanation": "Ankirin mutasyonuna bağlı **Herediter Sferositozda** esnekliğini kaybeden küresel eritrositler dalak kordonlarında takılıp makrofajlarca yıkılır; **splenektomi, dalaktaki eritrosit sekestrasyonunu ve lizisini ortadan kaldırarak** anemiyi düzeltir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 76, "question": "6 yaşında bir çocuk, sağ uyluğunda giderek kötüleşen ağrıdan şikayet ediyor. Fizik\nmuayenede sağ inguinal bölgede şiş, ağrılı lenf bezleri saptanıyor. Lenf bezi biyopsisi yapılıyor\nve çok sayıda mitotik figür içeren, değişik boyutta germinal merkezler görülüyor. Yoğun\nparafolliküler ve sinüzoidal lökositler mevcutt. Bu değişikliklerin en muhtemel sebebi nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Akut lenfadenitis"}, {"letter": "B", "text": "Akut lenfoblastik lösemi"}, {"letter": "C", "text": "Kedi tırmığı hastalığı"}, {"letter": "D", "text": "Folliküler lenfoma"}, {"letter": "E", "text": "Sarkoidozis"}], "answer": "A", "note": null, "id": "2023-2024_Q76", "explanation": "Alt ekstremite enfeksiyonuna ikincil gelişen ağrılı inguinal lenf büyümesi, aktif germinal merkezler ve yoğun nötrofil infiltrasyonu **Akut nonspesifik lenfadenit** tablosudur.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 58, "id": "2022-2023_Q58"}]}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 77, "question": "Son 3 ay içinde 18 aylık bir kız çocuğunda seboreik cilt döküntüleri gelişti.\nTekrarlayan üst solunum yolu rahatsızlığı geçirdive Streptococcus pneumoniae'nin neden\nolduğu orta kulak enfeksiyonları geçirmişti. Fizik muayene aynı zamanda hepatosplenomegali\nve genel lenfadenopati olduğunu gösteriyor. Sağ kulakta işitme azalmıştır. Bir kafatası\nradyografisinde sağ temporal kemikte kapsayan genişleyen, 2 cm'lik litik bir lezyonu\ngösteriyor. Laboratuvar çalışmalarında anemi, trombositopeni veya lökopeni görülmedi. Kitle\nkürete edilir. Bu kitlenin mikroskobik incelemesinde görülme olasılığı en yüksek olan nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Birbeck granülleri olan histiositler"}, {"letter": "B", "text": "CD3 pozitif lenfositler"}, {"letter": "C", "text": "Russell cisimcikleri olan plama hücreleri"}, {"letter": "D", "text": "Reed-Sternberg hücreleri"}, {"letter": "E", "text": "Serebriform nukleuslu Sezary hücreleri"}], "answer": "A", "note": null, "id": "2023-2024_Q77", "explanation": "Küçük çocukta seboreik deri döküntüleri, tekrarlayan otitis media, hepatosplenomegali, lenfadenopati ve kafatası kemiğinde (temporal kemikte) zımba deliği şeklinde litik lezyon **Langerhans Hücreli Histiyositoz** tablosudur; elektron mikroskopisinde tenis raketi şeklindeki **Birbeck granülleri** (ve CD1a, Langerin pozitifliği) tanısaldır."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 78, "question": "60 yaşındaki bir kadın, son 5 haftadır baş ağrısı ve baş dönmesi yaşıyor. Ülser için\nomeprazol kullanıyor. Fizik muayenesinde ateşsiz, normotansif , yüz pletorik veya siyanotik\nbir görünüme sahiptir. Hafif splenomegali var, ama başka anormal bulgu yok. Laboratuvar\nçalışmalarında hemoglobin , 21,7 g/dL; hematokrit, %65; trombosit sayımı, 400.000/mm3; ve\nWBC sayımı, 30.000/mm3, %85 polimorfonükleer lökositler, %10 lenfositler ve %5\nmonositler. Periferik kan yaymasında anormal derecede büyük trombositler görülüyorve\nçekirdekli eritrositler mevcut. Aşağıdakilerden hangisi bu hastanın hastalığının doğal\nseyrinde en karakteristiktir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Midede non-Hodgkin lenfoma gelişimi"}, {"letter": "B", "text": "Monoklonal serım immünglobülinde artış"}, {"letter": "C", "text": "Ekstramedüller hematopoiezis ile birlikte kemik iliğinde fibrozis"}, {"letter": "D", "text": "Tedavisiz spontan remisyon ve rölapslar"}, {"letter": "E", "text": "Akut B lenfoblastik lösemiye transformasyon"}], "answer": "C", "note": null, "id": "2023-2024_Q78", "explanation": "Pletorik yüz, splenomegali, çok yüksek Hb (21.7 g/dL) ve Hct (%65), lökositoz ve trombositoz ile başvuran hastada tanı **Polisitemia Vera (PV)**'dır; hastalığın doğal seyrinde geç dönemde ('spent phase' / tükenmişlik fazı) **ekstramedüller hematopoez ile birlikte kemik iliğinde sekonder miyelofibrozis** gelişimi karakteristiktir."}, {"year": "2023-2024", "subject": "Patoloji", "q_num": 79, "question": "2 yaşındaki bir çocuğun ebeveynleri endişeli çünkü oğullarının sağ gözünde hiç\ngörüş yok gibi görünüyor. Muayenede şaşılık ve gözbebeğinde beyazımsı bir görünüm var.\nOrbital palpasyonla hassasiyet mevcut. Vizyon açık, sol sağlam görünüyor. Sağ gözün\nenükleasyonu gerçekleştirilir, ardından radyasyon ve kemoterapi uygulanır. Orada sağda\ntekrarlama yok ama 5 yaşında benzer bir lezyon var sol gözde. 12 yaşındayken çocukta sol\nfemur distalinin osteosarkomu gelişir. Bu bulguları üretme olasılığı en yüksek olan genetik\nmekanizmalar nelerdir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Anöploidi"}, {"letter": "B", "text": "Kromozomal translokasyon"}, {"letter": "C", "text": "X-linked gen bozukluğu"}, {"letter": "D", "text": "Germline mutasyon"}, {"letter": "E", "text": "Mültifaktöryel kalıtım"}], "answer": "D", "note": null, "id": "2023-2024_Q79", "explanation": "Çocukta önce bilateral **Retinoblastom** (sağ ve sol gözde), yıllar sonra ise femurda **Osteosarkom** gelişmesi, RB1 tümör süpresör genindeki ilk vuruşun kalıtsal olarak tüm vücut hücrelerinde bulunduğu **Germline mutasyon** (kalıtsal retinoblastom) mekanizmasıyla açıklanır."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 80, "question": "Pıhtılaşma zamanının aşağıdakilerden hangisinde kısalır?", "professor": "Ayşe Özdemir", "options": [{"letter": "A", "text": "Kanama sonrası"}, {"letter": "B", "text": "Tıkanma sarılıkları"}, {"letter": "C", "text": "Vitamin K eksikliği"}, {"letter": "D", "text": "Heparin tedavisi"}, {"letter": "E", "text": "Aspirin kullanımı"}], "answer": "A", "note": null, "id": "2023-2024_Q80", "explanation": "Akut **kanama sonrasında** tromboplastin ve koagülasyon faktörlerinin refleks aktivasyonu ile trombosit salınımı sonucunda **pıhtılaşma zamanı kısalır**; K vitamini eksikliği, tıkanma sarılığı ve heparin tedavisinde ise pıhtılaşma zamanı uzar."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 81, "question": "Fibrin ağı (pıhtı) oluşması hangi aşamada görülür?", "professor": "Ayşe Özdemir", "options": [{"letter": "A", "text": "Faz 4"}, {"letter": "B", "text": "Faz 2"}, {"letter": "C", "text": "Faz 3"}, {"letter": "D", "text": "Faz 1"}, {"letter": "E", "text": "Fibrinoliz"}], "answer": "C", "note": null, "id": "2023-2024_Q81", "explanation": "Klasik pıhtılaşma aşamalarında: Faz 1 tromboplastin (protrombinaz) oluşumu, Faz 2 trombin oluşumu, **Faz 3 ise fibrinojenden fibrin ağı (pıhtı) oluşması**, Faz 4 ise pıhtı retraksiyonu/fibrinolizdir."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 82, "question": "Ortalama hücredeki hemoglobin konsantrasyonu hesaplamasında kullanılan bir\nparametre aşağıdakilerden hangisidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "RBC (kırmızı kan hücre) sayısı"}, {"letter": "B", "text": "Retikülosit"}, {"letter": "C", "text": "MCV (ortalama hücre hacmi)"}, {"letter": "D", "text": "HTC (hematokrit)"}, {"letter": "E", "text": "RDW (hücre dağılım genişiliği)"}], "answer": "D", "note": null, "id": "2023-2024_Q82", "explanation": "Ortalama Eritrosit Hemoglobin Konsantrasyonu (**MCHC**) = (Hemoglobin / **Hematokrit [Hct]**) × 100 formülüyle hesaplanır; dolayısıyla hesaplamada **HTC (Hematokrit)** kullanılır."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 83, "question": "Aşağıdaki olaylardan hangisi kanser metabolizmasında gelişen durumlardan değil?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Hemoglobin oksijen disosiyasyon eğrisi sağa kayar"}, {"letter": "B", "text": "Cori döngüsü yavaşlar"}, {"letter": "C", "text": "Plasma serbest yağ asidi artar"}, {"letter": "D", "text": "LDL kolesterol düzeyi azalır"}, {"letter": "E", "text": "İnsülin sensitivitesi azalır."}], "answer": "B", "note": null, "id": "2023-2024_Q83", "explanation": "Kanser hastalarında tümörün aerobik glikolizle (Warburg etkisi) ürettiği yoğun laktat karaciğere taşınarak glukoneogenezle tekrar glukoza çevrilir; bu nedenle **Cori döngüsü (laktat-glukoz döngüsü) yavaşlamaz, aksine aşırı hızlanır**."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 84, "question": "Multiple miyelomda yükselen ve HLA ailesinin düşük molekül ağırlıklı proteini olan\ntümör belirteç aşağıdakilerden hangisidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Tiroglobulin"}, {"letter": "B", "text": "c-ERB 2"}, {"letter": "C", "text": "Beta2 mikroglobulin"}, {"letter": "D", "text": "Alfa fetoprotein"}, {"letter": "E", "text": "Regan izoenzimi"}], "answer": "C", "note": null, "id": "2023-2024_Q84", "explanation": "Multipl miyelom ve lenfomalarda düzeyi yükselen, tüm çekirdekli hücrelerin yüzeyindeki **MHC Sınıf I (HLA) moleküllerinin hafif zincirini** oluşturan düşük molekül ağırlıklı protein ve prognostik belirteç **Beta-2 mikroglobulin**dir."}, {"year": "2023-2024", "subject": "Biyokimya", "q_num": 85, "question": "22 yaşında kadın hastaya yapılan tam kan incelemesinde aşağıdaki sonuçlar elde\nediliyor. Hemoglobin 11.0 g/dL (11.7-15.7 g/dL)Hematokrit %34 (%35-47)RBC 5.8 x 1012/L\n( 3.8-5.2 x 1012/L)MCV 59.4 fL ( 80-100 fL)MCHC31 9% (32-36%)RDW 14.2% (11.5-14.5%)\nBuna göre ön tanıyı kesinleştirmek için aşağıdaki laboratuvar testlerinden hangisinin tanısal\ndeğeri diğerlerine göre daha yüksektir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "B12 vitamin düzeyi"}, {"letter": "B", "text": "Ferritin düzeyi"}, {"letter": "C", "text": "Hb A2 düzeyi"}, {"letter": "D", "text": "Hb A1c düzeyi"}, {"letter": "E", "text": "Transferrin saturasyonu"}], "answer": "C", "note": null, "id": "2023-2024_Q85", "explanation": "Hafif anemi (Hb: 11.0), yüksek RBC (5.8 milyon), çok düşük MCV (59.4 fL), normal RDW (%14.2) ve Mentzer indeksinin (59.4 / 5.8 = 10.2) <13 olması **Beta talasemi taşıyıcılığını** gösterir; kesin tanı için hemoglobin elektroforezinde **HbA2 düzeyi** (>%3.5) bakılmalıdır."}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 86, "question": "Başarılı geçen böbrek transplantasyonu sonrası immünsüpresif tedavi altındaki\nhastada öksürük ve ateş şikayeti gelişmiştir. Pnömoni düşünülen hastada antibiyotik\ntedavisine rağmen durum kötüleşmiştir. Yapılan akciğer biyopsisinde dar açı ile dallanan\nseptalı hifler görülmüştür. Klinik tablodan sorumlu en olası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aspergillus fumigatus"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Rhizopus spp."}, {"letter": "D", "text": "Cryptococcus neoformans"}, {"letter": "E", "text": "Penicillium spp."}], "answer": "A", "note": null, "id": "2023-2024_Q86", "explanation": "Böbrek nakli sonrası immünsüpresif hastada antibiyotiğe yanıtsız pnömoni ve akciğer biyopsisinde **dar (45°) açıyla dallanan septalı hiflerin** görülmesi invaziv **Aspergillus fumigatus** enfeksiyonu için tanısaldır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 88, "id": "2020-2021_Q88"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 87, "question": "İmmün sistemi baskılanmış bireylerde özellikle böbrek hastalığına ve ilerleyici\nmultifokal lökoensefalopatiye (PML) neden olan virüs grubu aşağıdakilerden hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Polyomaviridae"}, {"letter": "B", "text": "Papillomaviridae"}, {"letter": "C", "text": "Herpesviridae"}, {"letter": "D", "text": "Retroviridae"}, {"letter": "E", "text": "Onikoviridae"}], "answer": "A", "note": null, "id": "2023-2024_Q87", "explanation": "İmmünsüpresif bireylerde böbrek hastalığına (BK virüs nefropatisi) ve ilerleyici multifokal lökoensefalopatiye - PML (JC virüs) neden olan zarfsız DNA virüs ailesi **Polyomaviridae**'dir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 86, "id": "2022-2023_Q86"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 88, "question": "Human T Cell Lymphotropic Virus-1 (HTLV-1)'in etken olduğu düşünülen\nhastalığın özel ismi aşağıdakilerden hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Sezary T-cell leukemia (T hücre lösemisi)"}, {"letter": "B", "text": "Saçlı T-cell leukemia (T hücre lösemisi)"}, {"letter": "C", "text": "Baykuş gözü T-cell leukemia (T hücre lösemisi)"}, {"letter": "D", "text": "Hairy cell leukemia"}, {"letter": "E", "text": "Kaposi sarkomu"}], "answer": "A", "note": null, "id": "2023-2024_Q88", "explanation": "Serdar Güngör hocanın ders notuna ve çıkmış soru anahtarına göre HTLV-1'in etken olduğu T hücreli lösemi şıklarda **Sezary T-cell leukemia (T hücre lösemisi)** olarak işaretlenmiştir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 89, "id": "2022-2023_Q89"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 89, "question": "Girip İnfekte ettiği hücrede balonlaşma, Cowdry tip A intranükleer inklüzyon\ncisimcikleri, kromatin marginasyonu, multinükleer dev hücre oluşması karakteristik olan\nvirüs hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Human Herpes Virüs (HSV)"}, {"letter": "B", "text": "Adenovirüs"}, {"letter": "C", "text": "Coronavirüs"}, {"letter": "D", "text": "Retrovirüs"}, {"letter": "E", "text": "Human Papilloma Virüs (HPV)"}], "answer": "A", "note": null, "id": "2023-2024_Q89", "explanation": "Enfekte hücrede balonlaşma dejenerasyonu, kromatin marjinasyonu, **Cowdry tip A intranükleer inklüzyon cisimcikleri** ve **multinükleer dev hücreler (Tzanck hücreleri)** oluşturan virüs **Human Herpes Virüs (HSV)**'dir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 91, "id": "2022-2023_Q91"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Menenjit şüphesi ile yatırılan AIDS hastasından alınan beyin omurilik sıvısında\nkapsüllü bir maya mantarı gözlenmiştir.En olası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Cryptococcus neoformans"}, {"letter": "B", "text": "Candida albicans"}, {"letter": "C", "text": "Malassezia furfur"}, {"letter": "D", "text": "Rhizopus arizonae"}, {"letter": "E", "text": "Histoplasma capsulatum"}], "answer": "A", "note": null, "id": "2023-2024_Q90", "explanation": "AIDS hastasında menenjit yapan ve BOS'ta geniş polisakkarit **kapsüllü maya mantarı** olarak görülen fırsatçı etken **Cryptococcus neoformans**'tır."}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 91, "question": "İntrauterin hayatta ve yeni doğanda konjenital ve perinatal infeksiyonlar; sağlıklı\nerişkinlerde mononükleoz yapan DNA virüsü hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Sitomegalovirus (CMV)"}, {"letter": "B", "text": "Herpesvirüs"}, {"letter": "C", "text": "Parvovirüs"}, {"letter": "D", "text": "Papilloma virüs"}, {"letter": "E", "text": "Ebstein Barr virus"}], "answer": "A", "note": null, "id": "2023-2024_Q91", "explanation": "İntrauterin dönemde konjenital ve yenidoğanda perinatal enfeksiyonların en sık viral etkeni olan ve sağlıklı erişkinlerde heterofil antikor negatif mononükleoz yapan DNA virüsü **Sitomegalovirüs (CMV)**'tür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 91, "id": "2019-2020_Q91"}, {"kurul": "1", "year": "2021-2022", "q_num": 93, "id": "2021-2022_Q93"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 92, "question": "Retroviruslarda virusa özgün pol geni ile kodlanan hangi enzim hastalık\netyolojisinde en önemlidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "Revers (ters) transkriptaz"}, {"letter": "B", "text": "RNA polimeraz"}, {"letter": "C", "text": "DNA polimeraz"}, {"letter": "D", "text": "Taq polimeraz"}, {"letter": "E", "text": "İntegraz"}], "answer": "A", "note": null, "id": "2023-2024_Q92", "explanation": "Retrovirüslerde pol geni ile kodlanan ve viral RNA'dan çift iplikli proviral DNA sentezleyen karakteristik enzim **Revers (ters) transkriptaz**'dır.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 89, "id": "2019-2020_Q89"}, {"kurul": "1", "year": "2021-2022", "q_num": 91, "id": "2021-2022_Q91"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 93, "question": "Papillomaviruslerde DNA homolojisi ile 100'ün üzerinde tip tanımlanmıştır. Bu\nTiplerden en kanserojen olan tip grubu hangisidir.", "professor": "Serdar Güngör", "options": [{"letter": "A", "text": "16-18"}, {"letter": "B", "text": "20-22"}, {"letter": "C", "text": "22-24"}, {"letter": "D", "text": "26-28"}, {"letter": "E", "text": "12-14"}], "answer": "A", "note": null, "id": "2023-2024_Q93", "explanation": "HPV tipleri içinde servikal karsinom açısından en yüksek riskli (onkojenik) grup **Tip 16 ve 18**'dir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 88, "id": "2019-2020_Q88"}, {"kurul": "1", "year": "2021-2022", "q_num": 90, "id": "2021-2022_Q90"}]}, {"year": "2023-2024", "subject": "Mikrobiyoloji", "q_num": 94, "question": "55 yaşında erkek hasta prostat kanseri nedeniyle opere edildikten sonra hastanede\nyatışı sırasında idrarda yanma, sık idrara çıkma ve idrar kaçırma şikayetleri başlamıştır.\nHastadan alınan idrar kültüründe krem rengi, S tipi koloniler üremiştir. Gram boyamada\ntomurcuklanan maya hücreleri görülürken yapılan germ tüp testi pozitif saptanmıştır. En\nolası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Candida albicans"}, {"letter": "B", "text": "Candida glabrata"}, {"letter": "C", "text": "Candida tropicalis"}, {"letter": "D", "text": "Candida parapsilosis"}, {"letter": "E", "text": "Cryptococcus neoformans"}], "answer": "A", "note": null, "id": "2023-2024_Q94", "explanation": "İdrar kültüründe krem rengi maya kolonileri oluşturan ve insan serumunda 37°C'de 2-3 saat inkübe edildiğinde **Germ tüp (çimlenme borusu) testi pozitif** saptanan en sık maya etkeni **Candida albicans**'tır."}, {"year": "2023-2024", "subject": "Radyoloji", "q_num": 95, "question": "X-ışınları hangi görüntüleme yöntemlerinde enerji kaynağı olarak kullanılır?", "professor": "Tuğberk Baştürk", "options": [{"letter": "A", "text": "Röntgen ve ultrasonografi"}, {"letter": "B", "text": "Röntgen, floroskopi ve ultrasonografi"}, {"letter": "C", "text": "Röntgen, floroskopi ve bilgisayarlı tomografi"}, {"letter": "D", "text": "Röntgen, floroskopi ve manyetik rezonans görüntüleme"}, {"letter": "E", "text": "Ultrasonografi ve bilgisayarlı tomografi"}], "answer": "C", "note": null, "id": "2023-2024_Q95", "explanation": "**X-ışınları (iyonizan radyasyon)**; **Röntgen (direkt radyografi), Floroskopi ve Bilgisayarlı Tomografi (BT)** yöntemlerinde enerji kaynağı olarak kullanılır (Ultrasonografide ses dalgaları, MRG'de manyetik alan ve radyo dalgaları kullanılır)."}, {"year": "2023-2024", "subject": "Radyoloji", "q_num": 96, "question": "Tiroid neoplazilerinin görüntülenmesinde en yararlı görüntüleme yöntemi\nhangisidir?", "professor": "Tuğberk Baştürk", "options": [{"letter": "A", "text": "Ultrasonografi"}, {"letter": "B", "text": "Radyografi"}, {"letter": "C", "text": "Bilgisayarlı tomografi"}, {"letter": "D", "text": "Manyetik rezonans görüntüleme"}, {"letter": "E", "text": "Floroskopi"}], "answer": "A", "note": null, "id": "2023-2024_Q96", "explanation": "Tiroid bezi yüzeyel yerleşimli olduğu için **tiroid nodüllerinin ve neoplazilerinin** saptanmasında, karakterizasyonunda (TI-RADS) ve biyopsi kılavuzluğunda en yararlı ve ilk tercih görüntüleme yöntemi **Ultrasonografi (USG)**'dir."}, {"year": "2023-2024", "subject": "Tıbbi Genetik", "q_num": 97, "question": "Venöz thromboz gelişme riskini yaklaşık 3 kat artıran, tekrarlayan düşüklerde sık\nrastlanan ve ikinci önemli genetik risk faktörü olarak gösterilen gen mutasyonu\naşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Faktör V Leiden G1691A mutasyonu"}, {"letter": "B", "text": "Prothrombin (FII) G20120A mutasyonu"}, {"letter": "C", "text": "MTHFR C677T mutasyonu"}, {"letter": "D", "text": "MTHFR A1298C mutasyonu"}, {"letter": "E", "text": "Faktör XIII V34L mutasyonu"}], "answer": "B", "note": null, "id": "2023-2024_Q97", "explanation": "Kalıtsal trombofililerde Faktör V Leiden'den sonra **ikinci en sık genetik risk faktörü** olan ve venöz tromboz riskini ~3 kat artıran mutasyon **Protrombin (Faktör II) G20210A mutasyonu**dur.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 98, "id": "2022-2023_Q98"}]}, {"year": "2023-2024", "subject": "Tıbbi Genetik", "q_num": 98, "question": "β-talasemi fenotipinin doğumdan sonra kendisini göstermeye başlamasının sebebi\naşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Fetusta β-globin yerine β-globin benzeri globinlerin işlev görüyor olması"}, {"letter": "B", "text": "Doğum sonrası α-globin ifadesinin azalmasıyla β-globin ifadesi üzerindeki baskılamanın ortadan kalkması"}, {"letter": "C", "text": "Doğum sonrası β-globin gen ifadesine ihtiyaç duyulmaması"}, {"letter": "D", "text": "Doğum sonrası α-globin gen ifadesine ihtiyaç duyulmaması"}, {"letter": "E", "text": "Doğum sonrası γ-globin ifadesinin aşırı yükselmesi"}], "answer": "A", "note": null, "id": "2023-2024_Q98", "explanation": "Beta-talasemi fenotipinin doğumdan sonra ortaya çıkmasının nedeni, fetal dönemde beta-globin yerine **beta-benzeri globinlerin (gama-globin / HbF) işlev görüyor olması** ve doğum sonrası gama-beta globin değişiminin (switch) gerçekleşmesidir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 97, "id": "2022-2023_Q97"}]}, {"year": "2023-2024", "subject": "İmmünoloji", "q_num": 99, "question": "Tümör mikroçevresinde aşağıdakilerden hangisi kötü prognoz göstergesidir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Th1"}, {"letter": "B", "text": "Th17"}, {"letter": "C", "text": "Regülatör T hücresi (Treg)"}, {"letter": "D", "text": "Plazma hücresi"}, {"letter": "E", "text": "B lenfosit"}], "answer": "C", "note": null, "id": "2023-2024_Q99", "explanation": "Tümör mikroçevresinde anti-tümör immün yanıtı baskılayarak tümörün kaçışını kolaylaştıran ve **kötü prognoz** göstergesi olan hücre **Regülatör T hücresidir (Treg)**.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 99, "id": "2022-2023_Q99"}]}, {"year": "2023-2024", "subject": "İmmünoloji", "q_num": 100, "question": "Aşağıdakilerden hangisi tümör hücrelerinin immün sistemden kaçışına kanıt\noluşturur?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "Tümör hücrelerinin MHC sınıf I moleküllerini azaltması"}, {"letter": "B", "text": "Makrofajlar tarafından artmış miktarlarda tümör nekroz faktör (TNF) üretilmesi"}, {"letter": "C", "text": "Tümör hücre çoğalmasının IFN-gamma aracılı baskılanması"}, {"letter": "D", "text": "Tümöre özgül antijenlere karşı antikor üretilmesi"}, {"letter": "E", "text": "Artmış Bax belirmesi ile tümör hücre apoptozunun uyarılması"}], "answer": "A", "note": null, "id": "2023-2024_Q100", "explanation": "**Tümör hücrelerinin yüzeylerindeki MHC Sınıf I moleküllerinin ekspresyonunu azaltması**, CD8+ sitotoksik T lenfositler tarafından tanınmalarını engelleyerek **tümörün immün sistemden kaçışına** doğrudan kanıt oluşturur.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 100, "id": "2020-2021_Q100"}]}, {"year": "2024-2025", "subject": "Tıbbi Genetik", "q_num": 1, "question": "Genetik trombofililerin en yaygın nedeni olarak gösterilen ve homozigot bireylerde\ntromboz riskini 50 ila 100 kat artıran gen mutasyonu aşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Prothrombin (FII) G20120A mutasyonu"}, {"letter": "B", "text": "MTHFR C677T mutasyonu"}, {"letter": "C", "text": "Faktör XIII V34L mutasyonu"}, {"letter": "D", "text": "Faktör V Leiden G1691A mutasyonu"}, {"letter": "E", "text": "MTHFR A1298C mutasyonu"}], "answer": "D", "note": null, "id": "2024-2025_Q1", "explanation": "Kalıtsal trombofililerin **en yaygın nedeni** olan, Faktör V'in Aktive Protein C (APC) tarafından yıkılmasını engelleyen (APC direnci) ve homozigotlarda tromboz riskini 50-100 kat artıran mutasyon **Faktör V Leiden (G1691A) mutasyonu**dur."}, {"year": "2024-2025", "subject": "Tıbbi Genetik", "q_num": 2, "question": "β-talasemi fenotipinin prenatal dönemde gözlemlenmeyip postnatal dönemde kendini\ngöstermeye başlamasının sebebi aşağıdakilerden hangisidir?", "professor": "Metin Çalışkan", "options": [{"letter": "A", "text": "Postnatal dönemde α-globin ifadesinin artması sebebiyle β-globin ifadesinin baskılanması"}, {"letter": "B", "text": "Postnatal dönemde α-globin ifadesinin azalmasıyla β-globin ifadesi üzerindeki baskılamanın ortadan kalkması"}, {"letter": "C", "text": "Postnatal dönemde β-globin ifadesine ihtiyaç duyulmaması"}, {"letter": "D", "text": "Postnatal dönemde γ-globin ifadesinin aşırı yükselmesi"}, {"letter": "E", "text": "Postnatal dönemde globin değişimi sebebiyle γ-globin ifadesinin azalarak β-globin ifadesinin artması"}], "answer": "E", "note": null, "id": "2024-2025_Q2", "explanation": "Fetal dönemde HbF (α2γ2) baskınken doğumdan sonra **globin değişimi (hemoglobin switch) nedeniyle γ-globin ifadesinin azalarak β-globin ifadesinin artması**, β-talasemi fenotipinin postnatal 3-6. aylarda ortaya çıkmasına neden olur."}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 3, "question": "Pediatrik yaş grubunda mean corpuscular volume için aşağıdakilerden hangisi\ndoğrudur?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "Alt sınırı (80 + yaş) formülüne göre hesaplanır."}, {"letter": "B", "text": "10 yaş altında alt sınır 80 fL'dir."}, {"letter": "C", "text": "Yüksek olması megaloblastik anemi göstergesi olabilir."}, {"letter": "D", "text": "Anizositoz göstergesi olabilir."}, {"letter": "E", "text": "İzole B12 eksikliğine bağlı anemilerde MCV düşmesi beklenir."}], "answer": "C", "note": null, "id": "2024-2025_Q3", "explanation": "Pediatrik yaş grubunda MCV alt sınırı 70 + yaş (fL) formülüyle hesaplanır ve **MCV'nin yüksek olması (makrositoz) Vitamin B12 veya folat eksikliğine bağlı megaloblastik anemi göstergesi olabilir**.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 1, "id": "2023-2024_Q1"}]}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 4, "question": "Ülkemizde; İnfant dönemindeki demir profilaksisi ile ilgili aşağıdaki bilgilerden\nhangisi doğrudur?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "Tüm bebeklere 2. ayda başlanması önerilir."}, {"letter": "B", "text": "Tüm bebeklere 4. ayda başlanması önerilir."}, {"letter": "C", "text": "1 yaşında hemogram kontrolü neticesinde endikasyon dahilinde başlanır."}, {"letter": "D", "text": "Demir profilaksisi eskiden uygulanan bir yöntem olup güncelliğini yitirmiştir."}, {"letter": "E", "text": "İnfantın term ve preterm olmasına göre önerilen profilaksi başlama zamanı değişir."}], "answer": "E", "note": null, "id": "2024-2025_Q4", "explanation": "Ülkemizde Sağlık Bakanlığı 'Demir Gibi Türkiye' programına göre bebeklerde demir profilaksisine **term (zamanında doğan) bebeklerde 4. ayda (1-2 mg/kg/gün), preterm/düşük doğum ağırlıklı bebeklerde ise 2. ayda (2 mg/kg/gün)** başlanır; dolayısıyla **term ve preterm olmaya göre başlama zamanı değişir**."}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 5, "question": "Li-fraumeni sendromunda mutasyon hangi gendedir?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "RAS"}, {"letter": "B", "text": "N-myc"}, {"letter": "C", "text": "C-myc"}, {"letter": "D", "text": "P53"}, {"letter": "E", "text": "RB-1"}], "answer": "D", "note": null, "id": "2024-2025_Q5", "explanation": "**Li-Fraumeni sendromunda** germline mutasyon tümör süpresör gen olan **TP53 (p53)** genindedir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 3, "id": "2023-2024_Q3"}]}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 6, "question": "Süt çocuğunun geçici hipogammaglobulinemisi olan bebeklerde hangi tedavi yöntemi\ngenellikle uygulanmaz?", "professor": "Aysel Burcu İbili", "options": [{"letter": "A", "text": "Antibiyotik tedavisi"}, {"letter": "B", "text": "Aşılama"}, {"letter": "C", "text": "Düzenli takip"}, {"letter": "D", "text": "IVIG tedavisi"}, {"letter": "E", "text": "Semptomatik tedavi"}], "answer": "D", "note": null, "id": "2024-2025_Q6", "explanation": "**Süt çocuğunun geçici hipogammaglobulinemisi** benign ve kendi kendini sınırlayan bir durumdur; antikor yanıtları korunduğu için **IVIG (intravenöz immünglobulin) tedavisi genellikle uygulanmaz**.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 79, "id": "2025-2026_Q79"}]}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 7, "question": "Süt çocuğunun geçici hipogammaglobulinemisi hangi özellik ile tanımlanır?", "professor": "Aysel Burcu İbili", "options": [{"letter": "A", "text": "Şiddetli immün yetmezlik"}, {"letter": "B", "text": "Anneden gelen antikorların azalması ve bebeğin antikor üretiminin geç başlaması"}, {"letter": "C", "text": "Hayat boyu süren antikor eksikliği"}, {"letter": "D", "text": "Doğumdan itibaren şiddetli enfeksiyonlar"}, {"letter": "E", "text": "B lenfosit eksikliği nedeniyle ciddi hastalıklar"}], "answer": "B", "note": null, "id": "2024-2025_Q7", "explanation": "Süt çocuğunun geçici hipogammaglobulinemisi, **plasenta yoluyla anneden geçen IgG antikorlarının 3-6. aylarda azalması ve bebeğin kendi IgG sentezinin geç olgunlaşması (fizyolojik hipogammaglobulineminin uzaması)** ile tanımlanır."}, {"year": "2024-2025", "subject": "Pediatri", "q_num": 8, "question": "9 yaşında daha önce bilinen hiç bir rahatsızlığı olmayan erkek hasta, acil servise ateş,\ngribal semptomlar, vücutta morarma ve solukluk şikayeti ile getiriliyor. Hastanın kanlarında,\nhemoglobin 9.5 g/dL, total lökosit sayısı 58000/µL, yüzde 97'si lenfosit ağırlıklı, nötrofil sayısı\n740/µL, trombosit sayısı ise 54000/µL olarak saptanıyor. Crp pozitif, üre, kreatinin, ALT\nnormal saptanıyor. Sınırda AST yüksekliğine ek LDH, ürik asit ve fosfor sınırda yüksek\nbulunuyor. En olası tanı aşağıdakilerden hangisidir?", "professor": "Mesut Saka", "options": [{"letter": "A", "text": "İzole bakteriel enfeksiyon"}, {"letter": "B", "text": "İzole viral enfeksiyon"}, {"letter": "C", "text": "Lösemi"}, {"letter": "D", "text": "Lenfoma"}, {"letter": "E", "text": "İstismar"}], "answer": "C", "note": null, "id": "2024-2025_Q8", "explanation": "9 yaşında çocukta ateş, solukluk, morarma (peteşi/ekimoz), **anemi (Hb: 9.5), ağır nötropeni (740/µL), trombositopeni (54.000/µL) ve lenfosit/blast ağırlıklı belirgin lökositoz (58.000/µL)** ile LDH/ürik asit yüksekliği **Akut Lösemi (ALL)** için tipiktir."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 9, "question": "Otuz yaşındaki bir kadın hasta yüksek ateş, üşüme, titreme ve genital bölgede ağrılı\nkabarcıklar yakınması ile hastaneye başvurmuştur. Hasta, genital uçuğu olan partneriyle\nkorunmasız cinsel ilişki yaşadığını belirtmiştir. Hastanın yapılan muayenesinde vulva, vajina,\nserviks ve perinede ağrılı veziküler ve ülsere lezyonlar saptanmıştır. Yukarıda tanımlanan\nklinik tabloya yol açabilen en olası etken aşağıdakilerden hangisidir?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Herpes Simpleks Virus tip 1"}, {"letter": "B", "text": "Herpes Simpleks Virus tip 2"}, {"letter": "C", "text": "Varisella Zoster Virus"}, {"letter": "D", "text": "Human Herpes Virus-6"}, {"letter": "E", "text": "Sitomegalovirus"}], "answer": "B", "note": null, "id": "2024-2025_Q9", "explanation": "Korunmasız cinsel ilişki sonrası vulva, vajina, serviks ve perinede yüksek ateş ve **ağrılı veziküler/ülsere lezyonlarla (genital herpes)** seyreden tablonun en sık etkeni **Herpes Simpleks Virüs Tip 2 (HSV-2)**'dir."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 10, "question": "Aşağıdakilerden hangisi HPV’nin servikal onkogenezinden sorumlu genlerdir?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "L1, L2"}, {"letter": "B", "text": "L2, E6"}, {"letter": "C", "text": "L6, L7"}, {"letter": "D", "text": "E6, E7"}, {"letter": "E", "text": "L1, E7"}], "answer": "D", "note": null, "id": "2024-2025_Q10", "explanation": "Yüksek riskli HPV tiplerinde (HPV 16, 18) servikal karsinogenezden sorumlu viral onkogenler **E6** (p53'ü yıkar) ve **E7** (Rb proteinini bağlayarak inaktive eder) genleridir."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 11, "question": "Yirmi iki yaşındaki tıp fakültesi öğrencisi erkek hasta, göğüs sol yan tarafından\nsırtına doğru olan bölgenin cildinde şiddetli ağrı yakınması ile hastaneye başvuruyor.\nHastadan alınan anamnezde final sınavı dönemi nedeniyle yorgun ve stresli olduğu sırada bu\nlezyonların ortaya çıktığı ve son üç gündür yüksek ateşle seyreden viral bir üst solunum yolu\nenfeksiyonu nedeniyle semptomatik ilaçlar kullandığı öğreniliyor. Yapılan muayenesinde sol\ntorakal sırt bölgesinde dermatom görüntüsüyle uyumlu ağrılı ve eritemli zemin üzerinde çok\nsayıda veziküler lezyon olduğu görülüyor.Tanımlanan klinik tablo ve en olası etken\naşağıdakilerden hangisidir?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Uçuk - Herpes Simpleks Virus tip 1"}, {"letter": "B", "text": "Su çiçeği - Herpes Simpleks Virus tip 2"}, {"letter": "C", "text": "Zona - Varicella Zoster Virus"}, {"letter": "D", "text": "Enfeksiyöz mononükleozis - Epistein Barr Virus"}, {"letter": "E", "text": "Kondiloma - Human Papilloma Virus"}], "answer": "C", "note": null, "id": "2024-2025_Q11", "explanation": "Stres/yorgunluk sonrası tek taraflı torakal **dermatom hattı boyunca** şiddetli radiküler ağrı ve eritemli zeminde grup yapmış veziküllerle karakterize tablo **Zona (Herpes Zoster)** olup etkeni **Varicella Zoster Virüs (VZV / HHV-3)**'tür.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 88, "id": "2025-2026_Q88"}]}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 12, "question": "Epstein-Barr virüs aşağıdaki hücrelerden hangisinde latent enfeksiyon oluşturur?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Makrofaj"}, {"letter": "B", "text": "Epitel hücreleri"}, {"letter": "C", "text": "Eritrosit"}, {"letter": "D", "text": "B lenfosit"}, {"letter": "E", "text": "Nötrofil"}], "answer": "D", "note": null, "id": "2024-2025_Q12", "explanation": "**Epstein-Barr Virüsü (EBV / HHV-4)** orofarenks epitelinde çoğaldıktan sonra CD21 reseptörü aracılığıyla **B lenfositleri** enfekte eder ve ömür boyu **B lenfositlerde latent** kalır."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 13, "question": "Aşağıdaki hangisi, en sık görülen konjenital enfeksiyon etkeni olup, gebelerin\nTORCH testi kapsamında taraması yapılan, fetüste mikrosefali, mental gerilik, spastisite,\nperiventriküler kalsifikasyon ya da doğum sonrası bebekte duyma bozuklukları ve zeka\ngeriliği gibi geç sekeller bırakabilen virüstür?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Herpes Simplex Virus -1"}, {"letter": "B", "text": "Herpes Simplex Virus – 2"}, {"letter": "C", "text": "Cytomegalovirus"}, {"letter": "D", "text": "Epstein-Barr Virus"}, {"letter": "E", "text": "Human Herpes Virus – 6"}], "answer": "C", "note": null, "id": "2024-2025_Q13", "explanation": "En sık konjenital TORCH enfeksiyonu etkeni olan ve fetüste **mikrosefali, periventriküler kalsifikasyon, koryoretinit ve sensörinöral işitme kaybı** yapan virüs **Sitomegalovirüs (CMV)**'tür.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 89, "id": "2025-2026_Q89"}]}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 14, "question": "Aşağıdakilerden virüslerden hangisi renal transplantlılarda en sık üreteral stenoza,\nkemik iliği transplantlılarda ise hemorajik sistide neden olurken, bulaştığı kişide böbreklerde\nömür boyu persistan kalmaktadır?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "BK Virüs"}, {"letter": "B", "text": "JC Virüs"}, {"letter": "C", "text": "SV 40 Virüs"}, {"letter": "D", "text": "MCP Virüs"}, {"letter": "E", "text": "TSP Virüs"}], "answer": "A", "note": null, "id": "2024-2025_Q14", "explanation": "Böbrek tübül epitelinde ömür boyu latent kalan, renal transplant hastalarında **üreteral stenoz / allogreft nefropatisi** ve kemik iliği nakli hastalarında **hemorajik sistit** yapan polyomavirüs **BK Virüs**tür."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 15, "question": "Aşağıdaki bilgilerden hangisi Herpesviridae ailesi için yanlıştır?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Zarflı, çift iplikli DNA virüsleridir."}, {"letter": "B", "text": "Primer enfeksiyon, virüsün vucuda girdiği bölgeyi inerve eden nöron boyunca retrograd transportla ulaştığı gangliyonda gelişir."}, {"letter": "C", "text": "Enfekte ettiği nöronlarda LAT geniyle apoptozu inhibe ederek, ömür boyu latent kalır."}, {"letter": "D", "text": "Virüse ait en erken, erken ve geç viral genlerin sentezi konak hücre çekirdeğinde, bu genlerden protein sentezi ise konak hücre sitoplazmasında gerçekleşir."}, {"letter": "E", "text": "Asiklovir aktif virüsler tarafından aktifleştirildikten sonra etki gösteren bir ön ilaç olduğundan latent Herpesviruslara etkisizdir."}], "answer": "B", "note": null, "id": "2024-2025_Q15", "explanation": "Herpesvirüslerde **primer enfeksiyon** gangliyonda değil, **virüsün vücuda girdiği mukoza veya deri epitel hücrelerinde** başlar; virüs daha sonra duyusal sinir aksonları boyunca retrograd taşınıp gangliyonda **latent** enfeksiyon oluşturur."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 16, "question": "Aşağıdakilerden hangisi Human Papilloma Virus ile ilgili yanlış bir bilgidir?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Çıplak virüs olduğu için çevre koşullarına, fiziksel ve kimyasal ajanlara daha dayanıklı olup ortak kullanılan tuvaletlerden vs. bulaşabilir."}, {"letter": "B", "text": "Servikal kanserden başlıca tip 16 ve 18 sorumludur."}, {"letter": "C", "text": "Oral kavite papillomları ve genital kondilomlardan başlıca tip 6 ve 35 sorumludur."}, {"letter": "D", "text": "HPV aşıları, hastalıktan korunmada ve bulaş olduktan sonra ise HPV kaynaklı genital kanser proflaksisinde kullanılır."}, {"letter": "E", "text": "HPV bulaşının yaygın olmasının nedeni poligamik HPV pozitif erkeklerin ağrısız ya da asemptomatik olmaları nedeniyle virüsü fazla partnere bulaştırmalarıdır."}], "answer": "C", "note": null, "id": "2024-2025_Q16", "explanation": "Oral papillomlar ve benign genital kondilomlardan (Condyloma acuminatum) başlıca **HPV Tip 6 ve Tip 11** sorumludur (Tip 35 yüksek riskli gruptadır, C şıkkı yanlıştır)."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 17, "question": "Antianemik ilaçlarla ilgili hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Vücut demir emilimini kontrol altında tutar, üstüste demir ilacı alınırsa emilim kısıtlanır, buna mukozal blok denir."}, {"letter": "B", "text": "Oral tedavide yetersizlik/ciddi intolerans veya demir açığının fazla olduğu durumlarda intravenöz form ilaçlar tercih edilir"}, {"letter": "C", "text": "Oral yoldan alınan ilaçlarda ferrik (Fe+3) formu ferröz (Fe+2) formuna göre biyoyararlanımı daha yüksektir."}, {"letter": "D", "text": "Oral demir ilaçlarında en sık bulantı ve gastrointestinal yan etkiler görülür"}, {"letter": "E", "text": "Demir toksisitesinde desferoksamin şelatör olarak kullanılır."}], "answer": "C", "note": null, "id": "2024-2025_Q17", "explanation": "Oral yoldan alınan demir ilaçlarında **ferröz (Fe+2) formun biyoyararlanımı ve emilimi ferrik (Fe+3) forma göre çok daha yüksektir**; 'ferrik formun biyoyararlanımı daha yüksektir' ifadesi yanlıştır."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 18, "question": "Aşağıdakilerden demir ilacı İV (intravenöz) yoldan kullanılır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Demir hidroksi polimaltoz"}, {"letter": "B", "text": "Demir glukonat"}, {"letter": "C", "text": "Demir Sülfat"}, {"letter": "D", "text": "Demir fumarat"}, {"letter": "E", "text": "Demir Glisin sülfat"}], "answer": "A", "note": null, "id": "2024-2025_Q18", "explanation": "Şıklardaki demir sülfat, demir glukonat, demir fumarat ve demir glisin sülfat oral kullanılan ferröz (Fe+2) tuzlardır; Bilge Özcan hocanın ders notuna göre bu soruda A şıkkı (**Demir hidroksi polimaltoz / Ferrik kompleks**) cevap anahtarında işaretlenmiştir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 19, "question": "Otonom sinir sistemiyle ilgili yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Hem sempatik hem de parasempatik otonom gangliyonlar kolinerjik sinapslardır."}, {"letter": "B", "text": "Noradrenalin sinaptik uçlarda MAO enzimi tarafından yıkılır."}, {"letter": "C", "text": "Asetilkolinin sinaptik aralıktaki eliminasyonu psödokolinesterazla sağlanır."}, {"letter": "D", "text": "Sempatik sinir sisteminin innerve ettiği dokularda α ve β reseptörleri üzerinden etki eder"}, {"letter": "E", "text": "Asetilkolin sinaptik uçlarda vezikğllerde depolanır."}], "answer": "C", "note": null, "id": "2024-2025_Q19", "explanation": "Asetilkolinin kolinerjik sinaptik aralıktaki hızlı eliminasyonu plazmadaki psödokolinesteraz (bütirilkolinesteraz) ile değil, sinaptik kavşakta bulunan **gerçek Asetilkolinesteraz (AChE)** enzimi ile sağlanır."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 20, "question": "Otonom sinir sistemi ile ilgili hangisi doğrudur?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Vasküler dokularda relaksasyon sağlamak için M2 reseptörleri uyarılması gereklidir."}, {"letter": "B", "text": "Kalpte (+) inotropi sağlamak için α2 reseptörler uyarılmalıdır."}, {"letter": "C", "text": "Kalpte (-) kronotropi için β reseptörler bloke edilmelidir."}, {"letter": "D", "text": "Sfinkterlerde kasılma sağlamak M reseptörleri uyarılmalıdır."}, {"letter": "E", "text": "Bronşlarda gevşeme sağlamak için β reseptörler bloke edilmelidir."}], "answer": "C", "note": null, "id": "2024-2025_Q20", "explanation": "Kalpte SA düğümünde sempatik etkiyi sağlayan β1 reseptörlerin bloke edilmesi (beta-blokörler) kalp hızını azaltır, yani **negatif (-) kronotropi** sağlar (C şıkkı doğrudur)."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 21, "question": "Bradiartmi gelişen bir hastada vagal etkileri ortadan kaldırmak için hangi\nantimuskarinik ilaç verilmelidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Atropin sülfat"}, {"letter": "B", "text": "Asetilkolin"}, {"letter": "C", "text": "Hyosin-N-Butil bromür"}, {"letter": "D", "text": "Darifenasin"}, {"letter": "E", "text": "Pirenzepin"}], "answer": "A", "note": null, "id": "2024-2025_Q21", "explanation": "Semptomatik sinüs bradikardisi ve AV blok (bradiaritmi) gelişen hastada vagal (parasempatik M2) tonusu ortadan kaldırarak kalp hızını artırmak için ilk tercih intravenöz ilaç **Atropin sülfat**tır."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 22, "question": "Selektif M3 blokörü olup üriner antispazmodik olan ilaç hangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Solifenasin"}, {"letter": "B", "text": "Atropin"}, {"letter": "C", "text": "Triheksifenidil"}, {"letter": "D", "text": "Tripitramin"}, {"letter": "E", "text": "Pirenzepin"}], "answer": "A", "note": null, "id": "2024-2025_Q22", "explanation": "**Solifenasin** (ve darifenasin), mesane detrusor kasındaki **M3 muskarinik reseptörleri selektif olarak bloke eden** ve aşırı aktif mesane / üriner inkontinans tedavisinde kullanılan üriner antispazmodiktir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 23, "question": "Nondepolarize edici kas gevşetici (d-tubokurarin) etkinliğini sonlandırmada\nkullanılan kolinomimetik ilaç hangisidir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Neostigmin"}, {"letter": "B", "text": "Pilokarpin"}, {"letter": "C", "text": "Galantamin"}, {"letter": "D", "text": "Atropin"}, {"letter": "E", "text": "Sevimelin"}], "answer": "A", "note": null, "id": "2024-2025_Q23", "explanation": "Ameliyat sonunda non-depolarizan (kompetitif) nöromüsküler blokörlerin (d-tübokürarin, roküronyum, veküronyum) etkisini sonlandırmak (dekürarizasyon) için kullanılan antikolinesteraz **Neostigmin**dir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 24, "question": "Parasempatomimetik ilaçların kullanım alanlarından değildri?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Postoperatif paralitik ileus"}, {"letter": "B", "text": "mesane atonisi"}, {"letter": "C", "text": "Kompetitif tipteki nöromusküler bloke edicilerin etkisini sonlandırmak için"}, {"letter": "D", "text": "Myastenia gravis"}, {"letter": "E", "text": "Parkinson hastalığı"}], "answer": "E", "note": null, "id": "2024-2025_Q24", "explanation": "**Parkinson hastalığında** striatal dopamin azalmış ve asetilkolin göreceli olarak artmıştır; bu nedenle tedavisinde parasempatomimetikler değil, santral etkili **antimuskarinikler (biperiden, triheksifenidil, benztropin)** veya dopaminerjik ilaçlar kullanılır."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 25, "question": "Antineoplastik ilaçlar için verilen bilgilerden hangisi doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Kapesitabin gibi antimetabolit grubu ilaçlar döneme özgü etki gösterir."}, {"letter": "B", "text": "Döneme-özgü ilaçlar, yavaş gelişen bir lökopeni yaparlar ve bunun düzelmesi de yavaş olur."}, {"letter": "C", "text": "Kullanılan ilacın seçiciliği tek bir yapıya özgüyse yan tesir profili daha fazladır."}, {"letter": "D", "text": "Alkilleyici grubunda antineoplastikler döneme özgü etkilidirler."}, {"letter": "E", "text": "Döneme özgü etkinlik gösteren antineoplastikler, tüm hücre döngülerinde, DNA'yı etkileyerek hücrelerin ölümüne neden olurlar."}], "answer": "A", "note": null, "id": "2024-2025_Q25", "explanation": "**Kapesitabin** (5-FU ön ilacı), metotreksat, sitarabin ve gemsitabin gibi **antimetabolit grubu ilaçlar hücre siklusunun S fazına (DNA sentez dönemine) özgü** etki gösterirler."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 26, "question": "Antineoplastik ilaçların normal dozda kullanımını en çok kısıtlayan neden\naşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Kemik iliği süpresyonu"}, {"letter": "B", "text": "Hızlı çoğalan epitel hücrelerinin inhibisyonu"}, {"letter": "C", "text": "Teratojenik etkileri"}, {"letter": "D", "text": "Mutajenik etkileri"}, {"letter": "E", "text": "Hiperürisemi yapmaları"}], "answer": "A", "note": null, "id": "2024-2025_Q26", "explanation": "Klasik sitotoksik antineoplastik ilaçların normal/yüksek dozda kullanımını en çok kısıtlayan (doz kısıtlayıcı) temel toksisite **kemik iliği süpresyonudur (miyelosüpresyon / nötropeni, trombositopeni)**."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 27, "question": "Sisplatin ve türevlerinin nefrotoksik ve myelotoksik etkilerini azaltmak için\nkullanılan antidot aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Amifostin"}, {"letter": "B", "text": "Mitotan"}, {"letter": "C", "text": "Venetoklaks"}, {"letter": "D", "text": "Hidroksiüre"}, {"letter": "E", "text": "Pimekrolimus"}], "answer": "A", "note": null, "id": "2024-2025_Q27", "explanation": "Sisplatin ve alkilleyici ajanların **nefrotoksik** ve miyelotoksik yan etkilerini azaltmak için kullanılan serbest radikal süpürücü (tiyol/sülfhidril donörü) sitoprotektif ajan **Amifostin**dir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 28, "question": "Sisplatin ve türevlerinin nefrotoksik ve myelotoksik etkilerini azaltmak için\nkullanılan antidot aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Amifostin"}, {"letter": "B", "text": "Mitotan"}, {"letter": "C", "text": "Venetoklaks"}, {"letter": "D", "text": "Hidroksiüre"}, {"letter": "E", "text": "Pimekrolimus"}], "answer": "A", "note": null, "id": "2024-2025_Q28", "explanation": "27. soru ile aynı sorudur; sisplatinin nefrotoksik ve miyelotoksik etkilerini önleyen sitoprotektif antidot **Amifostin**dir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 29, "question": "Bir protein kinaz enzimi olan mTOR enzim inhibisyonuyla, T-hücre aktivasyon\nve proliferasyonunu inhibe eden ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Sirolimus"}, {"letter": "B", "text": "Takrolimus"}, {"letter": "C", "text": "Azatiyoprin"}, {"letter": "D", "text": "Tosilizumab"}, {"letter": "E", "text": "Abatasept"}], "answer": "A", "note": null, "id": "2024-2025_Q29", "explanation": "**Sirolimus (Rapamisin)**, hücre içinde FKBP-12'ye bağlanarak **mTOR (mammalian target of rapamycin)** kinazı inhibe eder ve IL-2'ye yanıt olarak T hücrelerinin G1'den S fazına geçişini (proliferasyonunu) durdurur."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 30, "question": "İnozin monofosfat dehidrojenaz enzim inhibisyonu yaparak etki eden ön ilaç\naşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Mikofenolat mofetil"}, {"letter": "B", "text": "Anakinra"}, {"letter": "C", "text": "Klorambusil"}, {"letter": "D", "text": "Leflunomid"}, {"letter": "E", "text": "Etanersept"}], "answer": "A", "note": null, "id": "2024-2025_Q30", "explanation": "**Mikofenolat mofetil**, **inozin monofosfat dehidrojenaz (IMPDH)** enzimini inhibe ederek T ve B lenfosit proliferasyonunu baskılayan immünsüpresif bir ön ilaçtır."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 31, "question": "Lokal anastezik etkili olup intrinsik sempatomimemitk etkinlik göstermeyen beta\nbloker ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Metoprolol"}, {"letter": "B", "text": "Sotalol"}, {"letter": "C", "text": "Atenolol"}, {"letter": "D", "text": "Esmolol"}, {"letter": "E", "text": "Nadolol"}], "answer": "A", "note": null, "id": "2024-2025_Q31", "explanation": "**Metoprolol**, kardiyoselektif (Beta-1 seçici), **intrinsik sempatomimetik etkinliği (İSE) olmayan** ve hafif membran stabilize edici (lokal anestezik) etkiye sahip beta-blokördür.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 47, "id": "2025-2026_Q47"}]}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 32, "question": "Aşağıdakilerden hangisi alfa2 seçiciliği en fazla olan ilaçtır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Rovolsin"}, {"letter": "B", "text": "Tolazolin"}, {"letter": "C", "text": "Ergotamin"}, {"letter": "D", "text": "Azapetin"}, {"letter": "E", "text": "Prazosin"}], "answer": "A", "note": null, "id": "2024-2025_Q32", "explanation": "Numan Taşpınar hocanın alfa-blokörler ders notuna göre **alfa-2 adrenerjik reseptör seçiciliği en yüksek** olan selektif alfa-2 blokör alkaloid **Rovolsin (Rauwolscine / α-yohimbin)**'dir."}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 33, "question": "Aşağıda verilen adrenerjik etkili ilaçlardan hangisinin etkisi sadece alfa\nreseptörlerine olup imidazolin türevi bir lokal dekonjestandır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Oksimetazolin"}, {"letter": "B", "text": "Terbutalin"}, {"letter": "C", "text": "Dobutamin"}, {"letter": "D", "text": "Korbadrin"}, {"letter": "E", "text": "Efedrin"}], "answer": "A", "note": null, "id": "2024-2025_Q33", "explanation": "**Oksimetazolin** (ve nafazolin), sadece alfa reseptörleri uyaran **imidazolin türevi** bir lokal nazal dekonjestandır.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 15, "id": "2023-2024_Q15"}]}, {"year": "2024-2025", "subject": "Farmakoloji", "q_num": 34, "question": "Bronkodilatör etkisi en fazla olan ve astım tedavisinde kullanılan beta2 reseptör\nagonisti aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Salbutamol"}, {"letter": "B", "text": "Prazosin"}, {"letter": "C", "text": "Metoksamin"}, {"letter": "D", "text": "Oksedrin"}, {"letter": "E", "text": "Dekstroamfetamin"}], "answer": "A", "note": null, "id": "2024-2025_Q34", "explanation": "Astım ve KOAH akut ataklarında hızlı ve güçlü bronkodilatasyon sağlamak için kullanılan kısa etkili selektif **beta-2 reseptör agonisti (SABA)** **Salbutamol (Albuterol)**'dür.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 50, "id": "2025-2026_Q50"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 35, "question": "Ateş, yaygın lefadenopati, hepatosplenomegali ve atipik lenfositoz saptanan bir\nhastada aşağıdaki hastalıklardan hangisi düşünülmez?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Kronik lenfositer lösemi"}, {"letter": "B", "text": "Akut lenfoblastik lösemi"}, {"letter": "C", "text": "Burkitt lenfoma"}, {"letter": "D", "text": "Diffüz büyük B hücreli lenfoma"}, {"letter": "E", "text": "Aplastik anemi"}], "answer": "E", "note": null, "id": "2024-2025_Q35", "explanation": "Ateş, yaygın lenfadenopati, hepatosplenomegali ve atipik lenfositoz lenfoproliferatif hastalıklarda (KLL, ALL, Burkitt ve DBBHL) görülür; **Aplastik anemide ise pansitopeni vardır ve lenfadenopati/hepatosplenomegali beklenmez**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 36, "question": "Halsizlik ile başvuran 78 yaşındaki erkek hastanın tekiklerinde demir eksikliği\nanemisi saptanıyor. Gaytada gizli kan testi pozitif saptanıyor. Bu hasta için öncelikle\nyapılması gereken işlem aşağıdakilerden hangisidir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Baryumlu kolon grafisi çekilmesi"}, {"letter": "B", "text": "Gaytada parazit testi"}, {"letter": "C", "text": "B12 ve folik asit tedavisi başlanması"}, {"letter": "D", "text": "Oral demir başlanarak 1 ay sonra kontrole çağrılması"}, {"letter": "E", "text": "Gastroskopi ve kolonoskopi yapılması"}], "answer": "E", "note": null, "id": "2024-2025_Q36", "explanation": "78 yaşındaki ileri yaş erkek hastada **demir eksikliği anemisi ve gaytada gizli kan pozitifliği** saptandığında altta yatan gastrointestinal sistem malignitesini (özellikle kolon ve mide kanserini) saptamak için **öncelikle gastroskopi ve kolonoskopi yapılmalıdır**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 37, "question": "Erişkinde aşağıdaki hastalıkların hangisinde dalakta büyüme beklenmez?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Kronik miyelofibrosiz"}, {"letter": "B", "text": "Kronik miyeloid lösemi"}, {"letter": "C", "text": "Aplastik anemi"}, {"letter": "D", "text": "Esansiyel trombositoz"}, {"letter": "E", "text": "Hairy cell lösemi"}], "answer": "C", "note": null, "id": "2024-2025_Q37", "explanation": "Miyeloproliferatif hastalıklarda (Kronik miyelofibrozis, KML, Esansiyel trombositoz) ve Tüylü hücreli lösemide (Hairy cell lösemi) splenomegali görülürken; **Aplastik anemide dalakta büyüme (splenomegali) beklenmez**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 38, "question": "Aşağıdakilerden hangisi anemi tanısında kullanılan parametrelerden biri değildir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Hemoglobin"}, {"letter": "B", "text": "Hemotokrit"}, {"letter": "C", "text": "AST ( Aspartat aminotransferaz )"}, {"letter": "D", "text": "Serum demiri"}, {"letter": "E", "text": "Serum total demir bağlama kapasitesi"}], "answer": "C", "note": null, "id": "2024-2025_Q38", "explanation": "Hemoglobin, hematokrit, serum demiri ve TDBK anemi tanı ve ayırıcı tanısında kullanılır; **AST (Aspartat aminotransferaz)** ise karaciğer/kas enzimidir, anemi tanı parametresi değildir."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 39, "question": "Aşağıdaki hastalık - tanı eşleştirmelerinden hangisi yanlıştır?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Paroksismal notürnal hemoglobinüri – Flow sitometri testi"}, {"letter": "B", "text": "Talasemi – Hemoglobin elektroforezi"}, {"letter": "C", "text": "Otoimmun hemolitik anemi – Direkt coombs testi"}, {"letter": "D", "text": "Megaloblastik anemi – B12, Folat düzeyi"}, {"letter": "E", "text": "Miyelofibrozis – Protein elektroforezi"}], "answer": "E", "note": null, "id": "2024-2025_Q39", "explanation": "**Miyelofibrozis** tanısı protein elektroforezi ile değil, **kemik iliği biyopsisinde retikülin/kollajen fibrozisin gösterilmesi**, periferik yayma (lökoeritroblastik tablo, gözyaşı hücreleri) ve JAK2/CALR/MPL mutasyon analizi ile konur (Protein elektroforezi Multipl Myelom tanısında kullanılır)."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 40, "question": "Kırk dört yaşında erkek hasta solukluk, halsizlik ile hastaneye başvuruyor. Fizik\nmuayenede subikter saptanıyor. Laboratuvar tetkiklerinde; hemoglobin 8.2g/dL, lökosit\n4100/mm3, trombosit 145.000/mm3, MCV 119 fL saptanıyor. Bu hastanın ayırıcı tanısında\naşağıdakilerden hangisi tanı koymada en az yardımcı olur?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Serum laktat dehidrogenaz düzeyi"}, {"letter": "B", "text": "Retikülosit sayımı"}, {"letter": "C", "text": "İdrarda ürobilinojen tayini"}, {"letter": "D", "text": "Serum folik asit ve B-12 düzeyi"}, {"letter": "E", "text": "Serum ferritin düzeyi"}], "answer": "E", "note": null, "id": "2024-2025_Q40", "explanation": "Subikter, makrositer anemi (MCV: 119 fL) ve sınırda lökopeni/trombositopeni ile başvuran hastada ön tanılar **megaloblastik anemi (B12/folat eksikliği)** ve **hemolitik anemi**dir (LDH, retikülosit, ürobilinojen, B12/folat yardımcıdır); **serum ferritin düzeyi** ise mikrositer demir eksikliği anemisi tanısında kullanılır."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 41, "question": "Pernisyöz anemili hastanın tetkiklerinde aşağıdaki bulgulardan hangisi beklenmez?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "İndirekt hiperbilirubinemi"}, {"letter": "B", "text": "Lökopeni"}, {"letter": "C", "text": "Kemik iliğinde megaloblast artışı"}, {"letter": "D", "text": "Periferik yaymada makrositler"}, {"letter": "E", "text": "Retikülositoz"}], "answer": "E", "note": null, "id": "2024-2025_Q41", "explanation": "Pernisyöz anemide (B12 eksikliği) kemik iliğinde megaloblast artışı, inefektif eritropoeze bağlı indirekt hiperbilirubinemi, lökopeni ve periferik yaymada makrositler/hipersegmente nötrofiller görülür; ancak tedavi öncesinde **retikülositoz beklenmez**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 42, "question": "Glukoz – 6 fosfat dehidrogenaz eksikliği ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "X’e bağlı kalıtılır."}, {"letter": "B", "text": "Hemoliz intravaskülerdir."}, {"letter": "C", "text": "Hastaya bakla tüketiminden kaçınılması önerilir."}, {"letter": "D", "text": "Hemolizin en sık nedeni ilaçlardır"}, {"letter": "E", "text": "Enfeksiyonlar hemolizi tetkikleyebiir"}], "answer": "D", "note": null, "id": "2024-2025_Q42", "explanation": "G6PD eksikliği X'e bağlı kalıtılır, intravasküler hemoliz ve favizm (bakla) yapar; ancak akut hemolitik atakları tetikleyen **en sık neden ilaçlar değil, akut viral ve bakteriyel enfeksiyonlardır**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 43, "question": "Erişkinlerde extranodal lenfomalar aşağıdaki organlardan hangisinde en sık ortaya\nçıkar?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Beyin"}, {"letter": "B", "text": "Paranazal sinüsler"}, {"letter": "C", "text": "Mide"}, {"letter": "D", "text": "Cilt"}, {"letter": "E", "text": "Akciğer"}], "answer": "C", "note": null, "id": "2024-2025_Q43", "explanation": "Erişkinlerde ekstranodal Non-Hodgkin lenfomaların en sık tuttuğu sistem gastrointestinal sistem olup, **en sık ortaya çıktığı organ Mide**dir (özellikle *H. pylori* ilişkili gastrik MALT lenfoma ve DBBHL)."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 44, "question": "Aşağıdaki anemilerden hangisi hemoglobin yapısında meydana gelen değişimle\ngelişmemektedir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Hidrops fetalis"}, {"letter": "B", "text": "Orak hücreli anemi"}, {"letter": "C", "text": "Talasemi majör"}, {"letter": "D", "text": "Talasemi intermedia"}, {"letter": "E", "text": "Pürivat kinaz eksikliği"}], "answer": "E", "note": null, "id": "2024-2025_Q44", "explanation": "Hidrops fetalis (alfa talasemi majör), orak hücreli anemi, talasemi majör ve talasemi intermedia hemoglobin (globin) yapı/sentez bozukluklarıdır. **Pirüvat kinaz eksikliği** ise hemoglobin yapısıyla değil, eritrosit **glikolitik yolak enzim eksikliğiyle** gelişen hemolitik anemidir."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 45, "question": "Halsizlik, kilo kaybı, batında dolgunluk hissi ile başvuran 67 yaşında erkek hastanın\nfizik muyensinde belirgin splenomegali saptanıyor. Tetkiklerinde; hemoglobin 12.5g/dL,\nlökosit 45.000/mm3, trombosit 560.000/mm3 saptanıyor. PCR ile yapılan moleküler analizde\nBCR-ABL füzyon geni saptanıyor. Bu hasta ile ilgili en olası tanı aşağıdakilerden hangisidir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Polisitemia vera"}, {"letter": "B", "text": "Primer miyelofibrosiz"}, {"letter": "C", "text": "Aplastik anemi"}, {"letter": "D", "text": "Kronik miyelositer lösemi"}, {"letter": "E", "text": "Esansiyel trombositoz"}], "answer": "D", "note": null, "id": "2024-2025_Q45", "explanation": "Belirgin splenomegali, lökositoz (45.000), trombositoz (560.000) ve moleküler analizde **BCR-ABL füzyon geni** pozitifliği **Kronik Miyelositer Lösemi (KML)** için tanısaldır."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 46, "question": "Yaklaşık 1 ay önce Multiple miyelom tanısı almış 65 yaşında erkek hasta acil servise\npoliüri, polidipsi, ağız kuruluğu ve konstipasyon şikayeti ile başvuruyor. Bu hastada aşağıdaki\nelektrolit tetkiklerinden öncelikle hangisini istemek gerekir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Kalsiyum"}, {"letter": "B", "text": "Potasyum"}, {"letter": "C", "text": "Magnezyum"}, {"letter": "D", "text": "Sodyum"}, {"letter": "E", "text": "Klor"}], "answer": "A", "note": null, "id": "2024-2025_Q46", "explanation": "Multipl miyelom hastasında poliüri, polidipsi, ağız kuruluğu (dehidratasyon) ve konstipasyon semptomları osteolitik kemik yıkımına bağlı gelişen **Hiperkalsemi**nin klasik kliniğidir; öncelikle **serum Kalsiyum** düzeyi istenmelidir."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 47, "question": "Talasemi majör tanısı konan bir hastanın hemoglobin elektroforez sonucu ile en\nuyumlu seçenek aşağıdakilerden hangisidir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "HbA % 96 HbF % 0.5 HbA2 % 3.5"}, {"letter": "B", "text": "HbA % 0 HbF % 92 HbA2 % 8"}, {"letter": "C", "text": "HbA % 60 HbF % 30 HbA2 % 10"}, {"letter": "D", "text": "HbA % 0 HbF % 15 HbA2 % 85"}, {"letter": "E", "text": "HbA % 20 HbF % 80 HbA2 % 0"}], "answer": "B", "note": null, "id": "2024-2025_Q47", "explanation": "Beta talasemi majör (homozigot β0/β0) hastasında beta globin zinciri hiç sentezlenemediği için **HbA (%0) yoktur**; hemoglobinin tamamına yakınını **HbF (%90-95)** ve artmış **HbA2 (%5-8)** oluşturur.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 62, "id": "2025-2026_Q62"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 48, "question": "Aşağıdakilerden hangisi Kronik lenfositer lösemide tedaviye başlama\nendikasyonlarında biri değildir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "Lenfosit sayısının 100.000’nin üzerinde olması"}, {"letter": "B", "text": "Semptomatik splenomegali varlığı"}, {"letter": "C", "text": "KLL ile ilişkili olarak anemi olması"}, {"letter": "D", "text": "KLL ile ilişkili olarak trombositopeni olması"}, {"letter": "E", "text": "İki ayda lenfosit sayısında %50’den fazla artış olması"}], "answer": "A", "note": null, "id": "2024-2025_Q48", "explanation": "KLL'de semptomatik splenomegali, anemi, trombositopeni ve lenfosit sayısının kısa sürede hızla ikiye katlanması tedavi endikasyonudur; ancak **tek başına lenfosit sayısının >100.000/mm³ olması** tedaviye başlama endikasyonu değildir."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 49, "question": "Kanser taramaları için aşağıdaki ifadelerden hangisi ya da hangileri doğrudur?\nKanser taramalarının amacı pre-malign lezyonları veya erken evre malign lezyonları\nyakalayarak hastanın sağkalımını uzatmaktır.Kolorektal kanser taramasında, özgünlük ve\nduyarlılığı farklı olsa da kolonoskopi, sigmoidoskopi, BT kolonografi, gaytada gizli kan gibi\nçeşitli yöntemler hasta tercihine göre seçilebilir.Meme kanseri taraması; Gail modeli gibi\nbireylerin hayat boyu meme kanseri gelişme riskini öngören risk hesaplama araçlarına göre\nplanlanır. Akciğer kanseri taramasında balgam sitoloji veya akciğer grafisi yerine HRCT-\nYüksek çözünürlüklü bilgisayarlı tomografi (High-resolution computed tomography)\nkullanılması önerilmektedir.", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Yalnız 1"}, {"letter": "B", "text": "Yalnız 2"}, {"letter": "C", "text": "1 ve 2"}, {"letter": "D", "text": "1, 2 ve 3"}, {"letter": "E", "text": "2, 3 ve 4"}], "answer": "D", "note": null, "id": "2024-2025_Q49", "explanation": "Akciğer kanseri taramasında yüksek çözünürlüklü BT (HRCT - interstisyel akciğer hastalıklarında kullanılır) değil, **Düşük Doz Bilgisayarlı Tomografi (LDCT - Low-Dose CT)** kullanılması önerilir (4. öncül yanlış; 1, 2 ve 3 doğrudur).", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 66, "id": "2025-2026_Q66"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 50, "question": "Aşağıdakilerden hangisi B lenfositinden köken alan non-Hodgkin lenfomalardan\nbiridir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Mikozis fungoides"}, {"letter": "B", "text": "Enteropati ile ilişkili lenfoma"}, {"letter": "C", "text": "Foliküler lenfoma"}, {"letter": "D", "text": "Periferik nazal tip lenfoma"}, {"letter": "E", "text": "HTLV-1 virüsü ile ilişkili lenfoma"}], "answer": "C", "note": null, "id": "2024-2025_Q50", "explanation": "Mikozis fungoides, enteropati ilişkili lenfoma, periferik nazal tip NK/T hücreli lenfoma ve HTLV-1 ilişkili erişkin T hücreli lenfoma T/NK hücre kökenlidir; **Foliküler lenfoma** ise germinal merkez **B lenfositlerinden** köken alır.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 68, "id": "2025-2026_Q68"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 51, "question": "Hodgkin dışı lenfoma tiplerinden hangisinde t(11;18) ve trizomi 3 sitogenetik\nanomalileri görülür?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Foliküler lenfoma"}, {"letter": "B", "text": "Mantle hücreli lenfoma"}, {"letter": "C", "text": "Burkitt lenfoma"}, {"letter": "D", "text": "Malt lenfoma"}, {"letter": "E", "text": "Anaplastik LCL"}], "answer": "D", "note": null, "id": "2024-2025_Q51", "explanation": "Ekstranodal marjinal zon lenfoması olan **MALT lenfoma**da karakteristik olarak **t(11;18)(q21;q21)** translokasyonu ve **trizomi 3** sitogenetik anomalileri görülür (t(14;18) foliküler, t(11;14) mantle, t(8;14) Burkitt lenfomada görülür).", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 70, "id": "2025-2026_Q70"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 52, "question": "Akciğer kanseri epidemiyolojisi ve risk faktörleri ile ilgili aşağıdaki ifadelerden\nhangileri doğrudur? Kanser ilişkili ölümlerin başında gelmektedir.Başta sigara olmak üzere,\nhava kirliliği, radon gazı, asbest maruziyeti, radyoterapi öyküsü önemli risk faktörleri\narasındadır.Hastaların ¾’ünden fazlasından küçük hücreli dışı akciğer kanseri\ngörülmektedir.Sigaranın bırakılması erken evre akciğer kanserine sahip bireylerde nüks\nriskini azaltır.", "professor": "Murat Eser", "options": [{"letter": "A", "text": "1 ve 2"}, {"letter": "B", "text": "1,2 ve 3"}, {"letter": "C", "text": "2 ve 4"}, {"letter": "D", "text": "1,3 ve 4"}, {"letter": "E", "text": "1,2,3 ve 4"}], "answer": "E", "note": null, "id": "2024-2025_Q52", "explanation": "Akciğer kanseriyle ilgili verilen 4 öncülün **tamamı (1, 2, 3 ve 4) doğrudur**: Kanser ölümlerinin 1. nedenidir, sigara/radon/asbest/RT risk faktörüdür, >%75-85'i küçük hücreli dışı (KHDAK) tiptedir ve sigaranın bırakılması erken evrede nüksü azaltır.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 65, "id": "2025-2026_Q65"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 53, "question": "Hodgkin lenfoma en çok aşağıdaki viruslardan hangisiyle ilişkilidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Parvovirus"}, {"letter": "B", "text": "Epstein-Barr virusu"}, {"letter": "C", "text": "Hepatit B virusu"}, {"letter": "D", "text": "Rotavirus"}, {"letter": "E", "text": "İnsan papilloma virusu tip 16"}], "answer": "B", "note": null, "id": "2024-2025_Q53", "explanation": "**Hodgkin lenfoma** (özellikle mikst sellüler ve lenfositten fakir alt tipler) etiyolojisinde en sık ilişkili olan onkojenik virüs **Epstein-Barr virüsü (EBV)**'dür.", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 67, "id": "2025-2026_Q67"}]}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 54, "question": "Dünya genelinde kadınlarda en ölümcül(mortal) kanser aşağıdakilerden hangisidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Meme kanseri"}, {"letter": "B", "text": "Akciğer kanseri"}, {"letter": "C", "text": "Kolon kanseri"}, {"letter": "D", "text": "Mesane kanseri"}, {"letter": "E", "text": "Pankreas kanseri"}], "answer": "B", "note": null, "id": "2024-2025_Q54", "explanation": "Dünya genelinde kadınlarda insidansı en yüksek kanser meme kanseri iken, **en ölümcül (mortalitesi en yüksek) kanser Akciğer kanseridir**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 55, "question": "Burkitt lenfomalarda en sık gözlenen kromozomal anomali aşağıdakilerden\nhangisidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "4;11 Translokasyonu"}, {"letter": "B", "text": "14;18 Translokasyonu"}, {"letter": "C", "text": "8;14 Translokasyonu"}, {"letter": "D", "text": "4;11 Translokasyonu"}, {"letter": "E", "text": "1;11 Translokasyonu"}], "answer": "C", "note": null, "id": "2024-2025_Q55", "explanation": "**Burkitt lenfomada** en sık gözlenen karakteristik kromozomal anomali, 8. kromozomdaki c-MYC onkogeni ile 14. kromozomdaki IgH lokusu arasındaki **t(8;14) translokasyonudur**."}, {"year": "2024-2025", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 56, "question": "Aşağıdaki Hodgkin dışı lenfoma tiplerinden en sık görülen hangisidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Malt lenfoma"}, {"letter": "B", "text": "Mantle lenfoma"}, {"letter": "C", "text": "Foliküler lenfoma"}, {"letter": "D", "text": "Anaplastik büyük hücreli lenfoma"}, {"letter": "E", "text": "Burkitt lenfoma"}], "answer": "C", "note": null, "id": "2024-2025_Q56", "explanation": "Verilen şıklar arasında erişkinlerde en sık görülen (indolent) Non-Hodgkin lenfoma tipi **Foliküler lenfoma**dır (tüm NHL'lerin en sık tipi DBBHL, ikinci en sık tipi Foliküler lenfomadır).", "repeats": [{"kurul": "1", "year": "2025-2026", "q_num": 69, "id": "2025-2026_Q69"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 57, "question": "Ağır kombine immün yetmezlik için yanlış olan hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Bebeklerde pamukçuk, ağır bebekbezi döküntüsü vardır."}, {"letter": "B", "text": "Yerli amerikalı toplumlarında daha sıktır."}, {"letter": "C", "text": "Timus büyüktür."}, {"letter": "D", "text": "Kök hücre transplantasyonu ve viral gen terapisi başarılı olur."}, {"letter": "E", "text": "X'e bağlı ve otozomal resessif tipleri vardır."}], "answer": "C", "note": null, "id": "2024-2025_Q57", "explanation": "Ağır Kombine İmmün Yetmezlikte (SCID) T lenfosit gelişimi bozuk olduğu için **timus bezinde büyüme değil, ağır hipoplazi/atrofi (küçük timus)** görülür ('Timus büyüktür' ifadesi yanlıştır)."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 58, "question": "HIV enfeksiyonunda (AIDS) sekonder görülmeyen tümör hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kaposi sarkomu"}, {"letter": "B", "text": "Lenfomalar"}, {"letter": "C", "text": "Uterin serviks karsinomu"}, {"letter": "D", "text": "Anal karsinomlar"}, {"letter": "E", "text": "Gliomlar"}], "answer": "E", "note": null, "id": "2024-2025_Q58", "explanation": "HIV/AIDS hastalarında Kaposi sarkomu (HHV-8), B hücreli Non-Hodgkin ve Hodgkin lenfomalar (EBV) ile serviks ve anal skuamöz karsinomlar (HPV) sıklığı belirgin artarken; **beyin gliomları** AIDS ile ilişkili sekonder tümörlerden değildir."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 59, "question": "miRNA(mikroRNA) için yanlış olan hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Karsinogenezde sadece onkojen ekspresyonunu artırarak rol oynarlar."}, {"letter": "B", "text": "Tek şeritli, kodlama yapmayan RNAlardır."}, {"letter": "C", "text": "Çekirdekte pre-miRNA olarak bulunurlar."}, {"letter": "D", "text": "Bazem mRNAyı inhibe ederler."}, {"letter": "E", "text": "22 nukleotid uzunluğundadırlar."}], "answer": "A", "note": null, "id": "2024-2025_Q59", "explanation": "MikroRNA'lar (miRNA) hedef mRNA'nın 3'-UTR bölgesine bağlanarak **translasyonu inhibe eder veya mRNA yıkımını sağlar**; karsinogenezde tümör süpresör genleri baskılayarak (onkomiR) veya onkogenleri baskılayan miRNA'ların kaybıyla rol oynarlar ('sadece onkojen ekspresyonunu artırarak rol oynarlar' ifadesi yanlıştır)."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 60, "question": "Hangisi homolog rekombinasyon ile DNA onarımı kusurlarının mevcut olduğu\nhastalıklardan değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Herediter nonpolipöz kolon kanseri sendromu"}, {"letter": "B", "text": "Bloom sendromu"}, {"letter": "C", "text": "Fanconi anemisi"}, {"letter": "D", "text": "Ataksi-telanjiektazi"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": null, "id": "2024-2025_Q60", "explanation": "**Herediter nonpolipöz kolon kanseri (Lynch sendromu)** homolog rekombinasyon değil, **DNA yanlış eşleşme onarımı (Mismatch Repair - MMR)** kusuru sonucu gelişir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 59, "id": "2019-2020_Q59"}, {"kurul": "1", "year": "2021-2022", "q_num": 56, "id": "2021-2022_Q56"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 61, "question": "Senil amiloidozda görülen prekürsör protein hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "SAA"}, {"letter": "B", "text": "Beta2-mikroglobülin."}, {"letter": "C", "text": "İmmünglobülin hafif zincirleri"}, {"letter": "D", "text": "Transtiretin"}, {"letter": "E", "text": "Kalsitonin"}], "answer": "D", "note": null, "id": "2024-2025_Q61", "explanation": "Yaşlı bireylerde özellikle kalpte biriken **Senil sistemik amiloidozda (ATTRwt)** prekürsör protein normal (wild-type) **Transtiretin (TTR)**'dir."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 62, "question": "NET oluşumunda rolü oynayan iltihabi hüce hangisidir*", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Nötrofil lökosit"}, {"letter": "B", "text": "Eozinofil lökosit"}, {"letter": "C", "text": "Makrofaj"}, {"letter": "D", "text": "T lenfosit"}, {"letter": "E", "text": "B lenfosit"}], "answer": "A", "note": null, "id": "2024-2025_Q62", "explanation": "Mikroorganizmaları hücre dışında hapseden kromatin/histon ve granül enzimlerinden oluşan **NET (Neutrophil Extracellular Traps - Nötrofil Hücre Dışı Tuzakları)** yapısını oluşturan hücre **Nötrofil lökosittir**."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 63, "question": "Şok için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Myokardda etkilenme yoktur."}, {"letter": "B", "text": "Soğuk ve soluk deri vardır."}, {"letter": "C", "text": "Dokularda pH düşüşü vardır."}, {"letter": "D", "text": "Hipoperfüzyon vardır."}, {"letter": "E", "text": "Mikrovasküler tromboz izlenir."}], "answer": "A", "note": null, "id": "2024-2025_Q63", "explanation": "Şok tablosunda sistemik hipoperfüzyon, laktik asidoz (pH düşüşü), mikrovasküler tromboz ve **miyokardiyal kontraktilite bozukluğu (miyokard depresyonu / iskemi)** gelişir; 'Miyokardda etkilenme yoktur' ifadesi yanlıştır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 64, "question": "Tip IV hipersensitivite reaksiyonlarında rol oynamayan hücre hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Antijen sunan hücreler"}, {"letter": "B", "text": "CD4 + lenfositler"}, {"letter": "C", "text": "CD8+ lenfositler"}, {"letter": "D", "text": "Nötrofil lökositler"}, {"letter": "E", "text": "NK hücreleri"}], "answer": "E", "note": null, "id": "2024-2025_Q64", "explanation": "Tip IV (hücre aracılı) aşırı duyarlılık reaksiyonlarında antijen sunan hücreler, CD4+ (Th1, Th17) T lenfositler, CD8+ sitotoksik T lenfositler, makrofajlar ve Th17 aracılı nötrofiller rol oynar; **NK (Doğal Öldürücü) hücreleri** ise doğal immünite ve Tip II ADCC'de görev alır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 65, "question": "Arthus reaksiyonu nedir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Deneysel görülen kütanöz vaskülitdir."}, {"letter": "B", "text": "Hepatit B’de görülen sistemik vaskülitdir"}, {"letter": "C", "text": "Sle'de görülen sistemik vaskülitdir."}, {"letter": "D", "text": "Poststreptokoksik glomerülonefritdir,"}, {"letter": "E", "text": "Hiçbiri"}], "answer": "A", "note": null, "id": "2024-2025_Q65", "explanation": "**Arthus reaksiyonu**, bağışıklanmış bireye intradermal antijen verilmesiyle oluşan lokalize immün kompleks (Tip III) aracılı **deneysel akut kütanöz nekrotizan vaskülittir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 55, "id": "2019-2020_Q55"}, {"kurul": "1", "year": "2021-2022", "q_num": 59, "id": "2021-2022_Q59"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 66, "question": "GVHD (graft versus host disease) için yanlış olan hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "İmmünkompetan hücre transplantasyonundan sonra görülür."}, {"letter": "B", "text": "Akut, subakut ve kronik formları vardır."}, {"letter": "C", "text": "Karaciğerde küçük safra kanallarının harabiyetine yol açar."}, {"letter": "D", "text": "EBV ile ilişkili B hücreli lenfoma insidansını artırı."}, {"letter": "E", "text": "Bireylerde yüksek HLA uyumluluğu aranır."}], "answer": "B", "note": null, "id": "2024-2025_Q66", "explanation": "Graft-Versus-Host Hastalığının (GVHD) **akut** (<100 gün) ve **kronik** (>100 gün) olmak üzere iki formu vardır; **'subakut' formu şeklinde bir sınıflaması yoktur** (Bülent Mızrak ders notu bilgisi)."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 67, "question": "Knudson'un çift-darbe hipotezi ilkin hangi tümörde öne sürülmüştür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Meme karsinomu"}, {"letter": "B", "text": "Akciğer karsinomu"}, {"letter": "C", "text": "Osteosarkom"}, {"letter": "D", "text": "Nöroblastom"}, {"letter": "E", "text": "Retinoblastom"}], "answer": "E", "note": null, "id": "2024-2025_Q67", "explanation": "Knudson'un çift-darbe (two-hit) karsinogenez hipotezi ilk kez **Retinoblastom (RB1 geni)** için öne sürülmüştür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 57, "id": "2019-2020_Q57"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 68, "question": "\".....heterotopik hücre kalıntılarından oluşan bir anormalliktir\" cümlesinde özne\nhangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Koristoma"}, {"letter": "B", "text": "Teratoma"}, {"letter": "C", "text": "Fibroadenoma"}, {"letter": "D", "text": "Myoma"}, {"letter": "E", "text": "Fibroma"}], "answer": "A", "note": null, "id": "2024-2025_Q68", "explanation": "Mikroskopik olarak tamamen normal bir dokunun normalde bulunmadığı yabancı (ektopik/heterotopik) bir anatomik bölgede bulunmasına (ör. Meckel divertikülünde mide veya pankreas dokusu) **Koristoma (heterotopi)** denir."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 69, "question": "Doğal (natural) immünitede hangisi rol oynamaz?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "NK hücresi"}, {"letter": "B", "text": "Plazma hücresi"}, {"letter": "C", "text": "CD 4 + hücreler"}, {"letter": "D", "text": "CD 8+ hücreler"}, {"letter": "E", "text": "Makrofajlar"}], "answer": "B", "note": null, "id": "2024-2025_Q69", "explanation": "**Plazma hücresi** B lenfositlerden gelişen ve spesifik antikor salgılayan **edinsel (adaptif)** immün sistem hücresidir; doğal immünitede yer almaz.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 42, "id": "2020-2021_Q42"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 70, "question": "Aşağıdakilerden hangisi effektör immün hücre değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "CD8+ T lenfositler"}, {"letter": "B", "text": "CD4+ T lenfositler"}, {"letter": "C", "text": "NK hücreleri"}, {"letter": "D", "text": "Dendritik hücreler"}, {"letter": "E", "text": "Plazma hücreleri"}], "answer": "D", "note": null, "id": "2024-2025_Q70", "explanation": "**Dendritik hücreler** efektör hücre değil, antijeni yakalayıp lenf düğümünde naif T hücrelerine sunan profesyonel **Antijen Sunan Hücrelerdir (APC)**."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 71, "question": "Philadelphia kromozomu için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kronik myeloid lösemide görülür"}, {"letter": "B", "text": "t(9,22) ile gösterilir"}, {"letter": "C", "text": "Tirozin kinaz aktivitesini yok eder"}, {"letter": "D", "text": "BCR-ABL rearrangement (yeniden düzenlenmesi) söz konusudur"}, {"letter": "E", "text": "Kimerik (chimeric) gen olarak da bilinir"}], "answer": "C", "note": null, "id": "2024-2025_Q71", "explanation": "KML'de görülen **Philadelphia kromozomu [t(9;22) / BCR-ABL]** tirozin kinaz aktivitesini yok etmez, aksine **konstitütif (sürekli aktif) tirozin kinaz aktivitesi kazandırarak** hücre çoğalmasını uyarır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 72, "question": "Di George sendromu için hangisi doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "22q11.2 delesyonu vardır"}, {"letter": "B", "text": "Timik hipoplazi vardır"}, {"letter": "C", "text": "Hipokalsemi vardır"}, {"letter": "D", "text": "Yele boyun vardır"}, {"letter": "E", "text": "T hücre immün yetmezliği vardır"}], "answer": "D", "note": null, "id": "2024-2025_Q72", "explanation": "**Yele boyun (webbed neck)** DiGeorge sendromunda değil, **Turner sendromunda (45,X0)** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 62, "id": "2019-2020_Q62"}, {"kurul": "1", "year": "2021-2022", "q_num": 54, "id": "2021-2022_Q54"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 73, "question": "Non-immün hidropsta önem kazanan virüs hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Hepatitis B"}, {"letter": "B", "text": "Hepatitis C"}, {"letter": "C", "text": "Rubella"}, {"letter": "D", "text": "Varicella"}, {"letter": "E", "text": "Parvovirus B19"}], "answer": "E", "note": null, "id": "2024-2025_Q73", "explanation": "Gebelikte eritroid öncülleri enfekte ederek ağır fetal anemi ve **non-immün hidrops fetalis** yapan virüs **Parvovirus B19**'dur.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 63, "id": "2019-2020_Q63"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 74, "question": "Otosplenektomi hangi hastalıkta görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Herediter sferositoz"}, {"letter": "C", "text": "Alfa talasemi"}, {"letter": "D", "text": "Beta talasemi"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği"}], "answer": "A", "note": null, "id": "2024-2025_Q74", "explanation": "Tekrarlayan dalak enfarktlarına bağlı **otosplenektomi** karakteristik olarak **Orak Hücreli Anemide** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 64, "id": "2019-2020_Q64"}, {"kurul": "1", "year": "2021-2022", "q_num": 49, "id": "2021-2022_Q49"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 75, "question": "Herediter sferositoz için hangi ifade doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Eritrosit membranındaki kalıtsal defektlerden kaynaklanır"}, {"letter": "B", "text": "X-linked geçişlidir"}, {"letter": "C", "text": "Splenektominin yararlı etkisi vardır."}, {"letter": "D", "text": "Eritrositlerde Howell-Jolly cisimcikleri görülebilir"}, {"letter": "E", "text": "Anizositoz ve sferositler görülür."}], "answer": "B", "note": null, "id": "2024-2025_Q75", "explanation": "**Herediter sferositoz** X'e bağlı (X-linked) değil, olguların %75'inde **otozomal dominant** (kalanında otozomal resesif) kalıtılır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 76, "question": "Auer isimcikleri hangi kemik iliği hastalığında görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "AML (Akut myeloblastik lösemi)"}, {"letter": "B", "text": "Myelodisplastik sendorm"}, {"letter": "C", "text": "Kronik myelositer lösemi"}, {"letter": "D", "text": "Polistemia vera"}, {"letter": "E", "text": "Primer myelofibrozis"}], "answer": "A", "note": null, "id": "2024-2025_Q76", "explanation": "**Auer cisimcikleri** neoplastik miyeloblastlarda görülen azurofilik çubuklardır ve **Akut Miyeloblastik Lösemi (AML)** için tanısaldır.", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 54, "id": "2020-2021_Q54"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 77, "question": "Raynaud fenomeni hangi anemi türünde görülür?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Orak hücreli anemi"}, {"letter": "B", "text": "Beta talasemi"}, {"letter": "C", "text": "Sıcak antikorlu immünhemolitik anemiler"}, {"letter": "D", "text": "Soğuk antikorlu immünhemolitik anemiler"}, {"letter": "E", "text": "Glukoz 6 fosfat dehidrogenaz eksikliği."}], "answer": "D", "note": null, "id": "2024-2025_Q77", "explanation": "Uç kapillerlerde soğukta eritrosit aglütinasyonu ve **Raynaud fenomeni**, **soğuk antikorlu (IgM) otoimmün hemolitik anemilerde** görülür.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 66, "id": "2019-2020_Q66"}, {"kurul": "1", "year": "2021-2022", "q_num": 51, "id": "2021-2022_Q51"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 78, "question": "Bir deneyde bakteriler belirli miktarlarda eklenir antikoagülan ile muamele edilmiş\nnormal insan kanına. Bakterilerin, nötrofiller tarafından fagosite edildiği gözlendi veya lizize\nuğradığı saptandı. Aşağıdaki plazma bileşenlerinin hangisi bu etkileri kolaylaştırmıştır?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kompleman"}, {"letter": "B", "text": "Fibrin"}, {"letter": "C", "text": "Kallikrein"}, {"letter": "D", "text": "Plasmin"}, {"letter": "E", "text": "Trombin"}], "answer": "A", "note": null, "id": "2024-2025_Q78", "explanation": "Kanda bakterilerin opsonize edilerek nötrofillerce fagositozunu ve MAC ile doğrudan lizisini kolaylaştıran plazma protein sistemi **Kompleman** sistemidir.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 51, "id": "2023-2024_Q51"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 79, "question": "Sjögren sendromu için hangisi doğru değildir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Keratoconjunctivitis sicca vardır,"}, {"letter": "B", "text": "CD8 hücreleri ile ilişkilidir"}, {"letter": "C", "text": "Xerostomia vardır,"}, {"letter": "D", "text": "SS-A (Ro) ve SS-B (La)’ya karşı otoantikorlara sahiptir"}, {"letter": "E", "text": "SLE’de görülebilir"}], "answer": "B", "note": null, "id": "2024-2025_Q79", "explanation": "Sjögren sendromunda ekzokrin bez yıkımında başrol oynayan hücreler CD8+ değil, **CD4+ yardımcı T hücreleri ve B lenfositlerdir**.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 56, "id": "2019-2020_Q56"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 80, "question": "Sistemik lupus eritematozus için spesifik otoantikor tipi hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Anti düzkas antikoru"}, {"letter": "B", "text": "ANA (antinükleer antikor)"}, {"letter": "C", "text": "Antimitokondrial antikor"}, {"letter": "D", "text": "Anti Sm (Smith) antikor"}, {"letter": "E", "text": "Antifosfolipid antikor"}], "answer": "D", "note": null, "id": "2024-2025_Q80", "explanation": "SLE için özgüllüğü (spesifisitesi) yüksek olan karakteristik otoantikor **Anti-Sm (Smith)** antikorudur (ve Anti-dsDNA).", "repeats": [{"kurul": "1", "year": "2020-2021", "q_num": 44, "id": "2020-2021_Q44"}, {"kurul": "1", "year": "2021-2022", "q_num": 58, "id": "2021-2022_Q58"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 81, "question": "40 yaşında bir erkeğe perfore sigmoid kolon divertikülü nedeniyle laparotomi\nyapıldı. Bir yara enfeksiyonu ameliyat sonrası süreci zorlaştırdı ve ameliyat yarası ayrılma\nmeydana geldi. Birincil kapatma artık mümkün değildi,ve yara \"granüle olmuş\"tu. Altı hafta\nsonra, yara orijinal boyutunun sadece %10'u kadardır. Aşağıdakilerden hangisi son 6\nhaftadaki yara büyüklüğünde gözlenen azalmayı en iyi şekilde açıklayan süreçtir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Adheziv glikoproteinlerin üretimi"}, {"letter": "B", "text": "Kollajen sentezinde artış"}, {"letter": "C", "text": "Metalloproteinazlrın inhibisyonu"}, {"letter": "D", "text": "Myofibroblast kontraksiyonu"}, {"letter": "E", "text": "Subkütan ödeömin çözülmesi"}], "answer": "D", "note": null, "id": "2024-2025_Q81", "explanation": "Sekonder iyileşen geniş bir yaranın 6 hafta içinde boyutunun %90 oranında küçülmesini sağlayan temel süreç **miyofibroblast kontraksiyonudur (yara kontraksiyonu)**.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 47, "id": "2023-2024_Q47"}]}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 82, "question": "Mast hücreleri için doğru olan hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Lökosit kemotaksisi"}, {"letter": "B", "text": "Düz kas kontraksiyonu"}, {"letter": "C", "text": "Ağrı"}, {"letter": "D", "text": "Vasküler permeabilite artışı"}, {"letter": "E", "text": "Direkt hedefin öldürülmesi"}], "answer": "D", "note": null, "id": "2024-2025_Q82", "explanation": "Mast hücrelerinden salınan histaminin temel vasküler etkisi venüllerde endotel kontraksiyonu yaparak **vasküler permeabilite artışı** ve ödem oluşturmaktır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 83, "question": "Kronik inflamasyonda gamma interferonun etkisi hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Nötrofil ve monositlerin toplanması"}, {"letter": "B", "text": "Sistemik etkiler"}, {"letter": "C", "text": "Endotelyal adhezyon moleküllerinin ekspresyonu"}, {"letter": "D", "text": "Lökosit kemotaksisi"}, {"letter": "E", "text": "Makrofajların aktivasyonu"}], "answer": "E", "note": null, "id": "2024-2025_Q83", "explanation": "Kronik inflamasyonda Th1 ve NK hücrelerinden salgılanan **IFN-γ (gama interferon)**'nın temel görevi **makrofajların klasik yoldan aktivasyonu** ve epiteloid/dev hücrelere dönüşümüdür."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 84, "question": "Antifossfolpid antikor sendromu için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Tekrarlayan düşükler görülür"}, {"letter": "B", "text": "Kardiak kapak vejetasyonları görülür"}, {"letter": "C", "text": "Sadece otoimmün hastalıklarda görülür"}, {"letter": "D", "text": "Sistemik lupus eritematozusda görülebilir"}, {"letter": "E", "text": "Renal mikroanjiopatiye yol açabilir"}], "answer": "C", "note": null, "id": "2024-2025_Q84", "explanation": "Antifosfolipid antikor sendromu SLE gibi otoimmün hastalıklara eşlik edebildiği (**sekonder**) gibi, altta yatan hiçbir otoimmün hastalık olmadan tek başına da (**primer antifosfolipid sendromu**) görülebilir; 'sadece otoimmün hastalıklarda görülür' ifadesi yanlıştır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 85, "question": "Dissemine İntravasküler Koagülasyon için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Sürrenal bezlerin tutulumu Sheehan sendromuna yol açar"}, {"letter": "B", "text": "Masif doku hasarı ve sepsis başlatıcı faktörlerdendir"}, {"letter": "C", "text": "Yaygın mikrovasküler tromboz görülür"}, {"letter": "D", "text": "Pıhtılaşma faktörleri ve trombositler tüketilir"}, {"letter": "E", "text": "Bir aşamada plazmin aktivasyonu oluşur"}], "answer": "A", "note": null, "id": "2024-2025_Q85", "explanation": "DİK (Dissemine İntravasküler Koagülasyon) sırasında sürrenal (adrenal) bezlerin hemorajik nekrozu Sheehan sendromuna değil, **Waterhouse-Friderichsen sendromuna** yol açar (Sheehan sendromu postpartum hipofiz nekrozudur)."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 86, "question": "Sistemik ödem için yanlış olan ifade hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Kalp yetmezliği, kapiller hidrostatik basıncın azalmasına yolaçar"}, {"letter": "B", "text": "Böbrek kan akımı azalır"}, {"letter": "C", "text": "Renin-anjiotensin-aldosteron sistemi aktive olur"}, {"letter": "D", "text": "Plazma osmotik basıncı azalır"}, {"letter": "E", "text": "Kan hacmi artar"}], "answer": "A", "note": null, "id": "2024-2025_Q86", "explanation": "Konjestif kalp yetmezliğinde venöz staza bağlı olarak kapiller hidrostatik basınç azalmaz, aksine **kapiller hidrostatik basınç artar** ve bu artış ödeme yol açar."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 87, "question": "Kronik iltihapta TH17 hücrelerinin rolü hangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Makrofajları uyarır"}, {"letter": "B", "text": "Eozinofil lökositleri toplar"}, {"letter": "C", "text": "Nötrofillerin toplanmasından sorumlu kemokinler salgılar"}, {"letter": "D", "text": "CD4+ lenfositleri uyarır"}, {"letter": "E", "text": "CD8+ lenfositleri uyarır."}], "answer": "C", "note": null, "id": "2024-2025_Q87", "explanation": "Kronik iltihapta **Th17 hücreleri** IL-17 ve IL-22 salgılayarak inflamasyon bölgesine **nötrofillerin (ve monositlerin) toplanmasından sorumlu kemokinleri** uyarır."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 88, "question": "Tümörlerin immün gözetimi ve öldürülmesinde en kilit öneme saahip olan sistem\nhangisidir?", "professor": "Bülent Mızrak", "options": [{"letter": "A", "text": "Dendritik hücreler tarafından tanınma"}, {"letter": "B", "text": "CTL'ler tarafından yok edilme"}, {"letter": "C", "text": "B lenfositlerinin uyarılması ve antikor üretilmesi"}, {"letter": "D", "text": "makrrofajların aktivasyonu"}, {"letter": "E", "text": "CD4+ hücrelerin aktivasyonu"}], "answer": "B", "note": null, "id": "2024-2025_Q88", "explanation": "Tümörlerin immün gözetimi ve doğrudan öldürülmesinde en kilit öneme sahip edinsel immün mekanizma, MHC Sınıf I üzerindeki tümör antijenlerini tanıyan **CD8+ Sitotoksik T Lenfositler (CTL) tarafından tümör hücrelerinin yok edilmesidir**."}, {"year": "2024-2025", "subject": "Patoloji", "q_num": 89, "question": "[PDF Notu] 89. Soru: Demir eksikliği ile ilgili bir soru varmış ama bulunamadı.", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Tamam (Notu okudum, geç)"}, {"letter": "B", "text": "Seçenek B"}, {"letter": "C", "text": "Seçenek C"}, {"letter": "D", "text": "Seçenek D"}, {"letter": "E", "text": "Seçenek E"}], "answer": "A", "note": "24-25 çıkmış sorular PDF'inde 89. soru metni hatırlanamadığı için bu not düşülmüştür.", "id": "2024-2025_Q89", "explanation": "2024-2025 çıkmış sorular PDF'inde 89. soru metni hatırlanamadığı için bu bilgi notu eklenmiştir."}, {"year": "2024-2025", "subject": "Biyokimya", "q_num": 90, "question": "Aşağıdaki durumlardan hangisi izole olarak yalnızca aktive parsiyel tromboplastin\nzamanı (aPTT) yüksekliğine neden olur?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Hemofili B"}, {"letter": "B", "text": "Vitamin K eksikliği"}, {"letter": "C", "text": "Karaciğer hastalığı"}, {"letter": "D", "text": "DIC (Dissemine İntravasküler Koagülopati)"}, {"letter": "E", "text": "Trombositopeni"}], "answer": "A", "note": null, "id": "2024-2025_Q90", "explanation": "**Hemofili B (Faktör IX eksikliği)** sadece intrensek koagülasyon yolağını etkilediği için **izole aPTT uzamasına** neden olur (PT, trombosit sayısı ve kanama zamanı normaldir). K vitamini eksikliği, karaciğer hastalığı ve DİK hem PT hem aPTT'yi uzatır."}, {"year": "2024-2025", "subject": "Biyokimya", "q_num": 91, "question": "Kanser hücrelerinde karbonhidrat metabolizmasında sıklıkla görülen\ndeğişikliklerden biri olan Warburg etkisi neyi ifade eder?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Kanser hücrelerinin oksijen varlığında bile glikolizi tercih etmesi"}, {"letter": "B", "text": "Kanser hücrelerinin artan oksidatif fosforilasyon kapasitesi"}, {"letter": "C", "text": "Kanser hücrelerinin sadece laktik asit üretmesi"}, {"letter": "D", "text": "Kanser hücrelerinin oksijen tüketimini artırması"}, {"letter": "E", "text": "Kanser hücrelerinin glikoz yerine yağ asitlerini enerji kaynağı olarak kullanması"}], "answer": "A", "note": null, "id": "2024-2025_Q91", "explanation": "**Warburg etkisi**, kanser hücrelerinin bol **oksijen varlığında bile** enerji ve biyosentetik ara ürün elde etmek için mitokondriyal oksidatif fosforilasyon yerine **glikolizi (ve laktat üretimini) tercih etmesidir (aerobik glikoliz)**."}, {"year": "2024-2025", "subject": "Biyokimya", "q_num": 92, "question": "Aşağıdaki tümör belirteçlerinden hangisi bir germ hücre tümörü ile en yakından\nilişkilidir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "CA-125"}, {"letter": "B", "text": "Prostat spesifik antijen (PSA)"}, {"letter": "C", "text": "Alfa-fetoprotein (AFP)"}, {"letter": "D", "text": "CA 19-9"}, {"letter": "E", "text": "Karsinoembriyonik antijen (CEA)"}], "answer": "C", "note": null, "id": "2024-2025_Q92", "explanation": "Non-seminomatöz **germ hücreli tümörler** (özellikle yolk kesesi / endodermal sinüs tümörü ve embriyonal karsinom) ile en yakından ilişkili onkofetal tümör belirteci **Alfa-fetoprotein (AFP)**'dir (ve hCG)."}, {"year": "2024-2025", "subject": "Biyokimya", "q_num": 93, "question": "55 yaşındaki bir kadın, son 6 aydır yorgunluk, baş dönmesi, el ve ayaklarında\nuyuşma hissi ve dengesizlik şikayetleri ile başvuruyor. Ayrıca, zaman zaman unutkanlık ve\ndilde yanma şikayeti olduğunu belirtiyor. Fizik muayenede dilde atrofik değişiklikler,\nbacaklarda vibrasyon duyusu kaybı saptanan hastanın aşağıdakilerden hangisi laboratuvar\nbulgusu olarak saptanmaz?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Serum Kobalamin düzeyi düşer"}, {"letter": "B", "text": "İdrar metilmalonik asit azalır"}, {"letter": "C", "text": "Kan homosistein düzeyi artar"}, {"letter": "D", "text": "Kan LDH düzeyi artar"}, {"letter": "E", "text": "Ortalama eritrosit hacmi artar"}], "answer": "B", "note": null, "id": "2024-2025_Q93", "explanation": "Atrofik glossit ve posterolateral kord demiyelinizasyonuna bağlı vibrasyon/pozisyon duyusu kaybı ile başvuran **Vitamin B12 (kobalamin) eksikliği** hastasında metilmalonil-KoA mutaz çalışamadığı için **idrar ve kan metilmalonik asit düzeyi azalmaz, belirgin olarak artar**."}, {"year": "2024-2025", "subject": "Biyokimya", "q_num": 94, "question": "Aşağıdakilerden hangisi apoptozisi inhibe ederek düzenleyen bir gendir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Bax"}, {"letter": "B", "text": "P53"}, {"letter": "C", "text": "Bcl-2"}, {"letter": "D", "text": "Bıd"}, {"letter": "E", "text": "Bad"}], "answer": "C", "note": null, "id": "2024-2025_Q94", "explanation": "BAX, BAD, BID ve p53 pro-apoptotik (apoptozu uyaran) genler iken; **Bcl-2** mitokondri dış membran geçirgenliğini koruyarak **apoptozisi inhibe eden (anti-apoptotik)** gendir."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 95, "question": "45 yaşında böbrek transplant hastası öksürük, ateş, nefes darlığı şikayetleri ile\nbaşvuruyor. Hastaneye yatırılan hastada intravenöz meropenem tedavisine rağmen ateşi\ndüşmüyor ve kliniğinde herhangi bir düzelme olmuyor. Hastanın akciğer tomografisinde çok\nsayıda nodül saptanırken alınan biyopsi örneğinde hif oluşturmayan, etrafında kapsül\nyapıları boyanmış ovoid hücreler görülüyor. Bu hastadaki pnömoni tablosundan sorumlu en\nolası etken aşağıdakilerden hangisidir?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Cryptococcus neoformans"}, {"letter": "B", "text": "Rhizopus spp."}, {"letter": "C", "text": "Malassezia furfur"}, {"letter": "D", "text": "Candida krusei"}, {"letter": "E", "text": "Aspergillus fumigatus"}], "answer": "A", "note": null, "id": "2024-2025_Q95", "explanation": "Böbrek nakli hastasında antibiyotiğe yanıtsız nodüler pnömoni ve biyopside **hif oluşturmayan, etrafında geniş kapsül bulunan ovoid maya hücreleri** görülmesi **Cryptococcus neoformans** enfeksiyonu için tanısaldır."}, {"year": "2024-2025", "subject": "Mikrobiyoloji", "q_num": 96, "question": "18 yaşında kadın hastanın, kulak ağrısı şikayetiyle başvurduğu klinikte verilen\namoksisilin-klavulonat etken maddeli antibiyotiğe rağmen şikayetleri düzelmemiştir. Kulak\nağrısı daha da şiddetlenerek yeniden başvurduğunda dış kulak yolunda siyah renkli, pamuksu\nyapılar gözlenmiştir. Aşağıdaki etkenlerden hangisini öncelikle düşünürsünüz?", "professor": "Hüseyin Haydar Kutlu", "options": [{"letter": "A", "text": "Aspergillus niger"}, {"letter": "B", "text": "Aspergillus flavus"}, {"letter": "C", "text": "Candida albicans"}, {"letter": "D", "text": "Cryptococcus neoformans"}, {"letter": "E", "text": "Histoplasma capsulatum"}], "answer": "A", "note": null, "id": "2024-2025_Q96", "explanation": "Antibiyotiğe yanıtsız dış kulak yolu enfeksiyonunda (otomikoz) siyah renkli, pamuksu küf yapıları **Aspergillus niger** için karakteristiktir.", "repeats": [{"kurul": "1", "year": "2019-2020", "q_num": 93, "id": "2019-2020_Q93"}]}, {"year": "2024-2025", "subject": "Radyoloji", "q_num": 97, "question": "Radyolojik görüntüleme modaliteleri ile ilgili aşağıdaki ifadelerden hangisi\nyanlıştır?", "professor": "Tuğberk Baştürk", "options": [{"letter": "A", "text": "Kemik yapıların değerlendirilmesinde öncelikle direk grafi tercih edilir."}, {"letter": "B", "text": "İntraartiküler yapıların değerlendirilmesinde en faydalı tetkik MR’dır."}, {"letter": "C", "text": "Malignite şüphesi bulunan akciğer lezyonlarında BT sık kullanılan kılavuz yöntemdir."}, {"letter": "D", "text": "Göğüs duvarı invazyonu bulunan akciğer kitlelerinde ultrason kılavuz yöntem olarak kullanılabilir."}, {"letter": "E", "text": "Ultrasonografi ile saptanan jinekolojik patolojilerde ileri tetkik olarak kullanılan en faydalı yöntem BT’dir."}], "answer": "E", "note": null, "id": "2024-2025_Q97", "explanation": "Ultrasonografi ile saptanan **jinekolojik (uterus, over, serviks) patolojilerde** yumuşak doku kontrast çözünürlüğü çok yüksek olduğu ve iyonizan radyasyon içermediği için ileri tetkik olarak en faydalı yöntem BT değil, **Pelvik MRG (Manyetik Rezonans Görüntüleme)**'dir."}, {"year": "2024-2025", "subject": "Radyoloji", "q_num": 98, "question": "Neoplazilerin radyolojik görüntülemesi ile ilgili aşağdaki ifadelerden hangisi\nyanlıştır?", "professor": "Tuğberk Baştürk", "options": [{"letter": "A", "text": "Ülkemizde meme kanseri taraması mammografi ile iki yılda bir yapılmaktadır."}, {"letter": "B", "text": "Uzun süre sigara kullanımı olan bireylerde akciğer grafisi ve düşük doz BT taraması önerilmektedir."}, {"letter": "C", "text": "Tiroid, testis gibi yüzeyel yapılarda kitle şüphesinde ilk yapılması gereken tetkik ultrasonografidir."}, {"letter": "D", "text": "İnce iğne aspirasyon biyopsisi ile histopatolojik, kalın iğne biyopsiler ile sitopatolojik inceleme yapılabilmektedir."}, {"letter": "E", "text": "Metastaz taraması için yapılan BT ve MR tetkikler"}], "answer": "D", "note": null, "id": "2024-2025_Q98", "explanation": "**İnce iğne aspirasyon biyopsisi (İİAB)** ile hücre yayması elde edilerek **sitopatolojik** inceleme yapılır; **kalın iğne (tru-cut / kor) biyopsi** ile ise doku silindiri alınarak **histopatolojik** inceleme yapılır (D şıkkında tam tersi yazıldığı için yanlıştır)."}, {"year": "2024-2025", "subject": "İmmünoloji", "q_num": 99, "question": "Yüksek IL-2 varlığında ortaya çıkan ve tümör hücrelerini öldürme yeteneği olan\nhücreler aşağıdakileden hangisidir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "T yardımcı hücreler"}, {"letter": "B", "text": "Sittotoksik T hücreleri"}, {"letter": "C", "text": "NK hücreleri"}, {"letter": "D", "text": "NKT hücreleri"}, {"letter": "E", "text": "LAK hücreleri (Lenfokin ile etkinleşen öldürücü hücreler)"}], "answer": "E", "note": null, "id": "2024-2025_Q99", "explanation": "Periferik kan lenfositlerinin (başlıca NK ve T hücrelerinin) in vitro veya in vivo **yüksek doz İnterlökin-2 (IL-2)** ile uyarılması sonucu oluşan ve MHC kısıtlaması olmaksızın tümör hücrelerini öldüren hücrelere **LAK hücreleri (Lenfokin ile Etkinleşen Öldürücü Hücreler)** denir."}, {"year": "2024-2025", "subject": "İmmünoloji", "q_num": 100, "question": "İmmünolojik olarak oluşturulmuş tümörün kontrolsüz olarak hızla yayılması\nolarak tanımlanan klinikte kanseri gördüğümüz evre aşağıdakilerden hangisidir?", "professor": "Rahşan Ilıkçı Sağkan", "options": [{"letter": "A", "text": "İmmüngözetim evresi"}, {"letter": "B", "text": "Eliminasyon evresi"}, {"letter": "C", "text": "Equilibrium (denge) evresi"}, {"letter": "D", "text": "Escape (kaçış) evresi"}, {"letter": "E", "text": "Uyku evresi"}], "answer": "D", "note": null, "id": "2024-2025_Q100", "explanation": "Kanserin immün şekillendirilmesi (Immunoediting - 3E) sürecinde immün sistemden kaçabilen varyantların kontrolsüz çoğalarak **klinikte görünür kanser oluşturduğu son evre Escape (Kaçış) evresidir**."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 1, "question": "47 yaşında, daha önce sağlıklı olan bir erkek, 2 haftadır ateş ve halsizlik şikayetiyle başvurmuştur. Muayenede hassas lenfadenopati ve hafif farenjit saptanmıştır. Laboratuvar tetkiklerinde HIV serolojik pozitifliği saptanmıştır. Bu hastanın lenf düğümlerinde aşağıdaki mikroskobik bulgulardan hangisi en olasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Germinal merkez genişlemesi"}, {"letter": "B", "text": "Lenfositten yoksunluk"}, {"letter": "C", "text": "Nekrotizan granülomalar"}, {"letter": "D", "text": "Reed-Sternberg hücreleri"}, {"letter": "E", "text": "Sinüs histiositozisi"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q1", "explanation": "Akut/erken HIV enfeksiyonunda lenf düğümlerinde B hücre aktivasyonuna bağlı olarak **belirgin folliküler hiperplazi ve germinal merkez genişlemesi** görülür (ileri AIDS evresinde ise folliküler involüsyon ve lenfositten yoksunluk gelişir)."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 2, "question": "Vitamin B12 veya folik asit eksikliği sonucu makrositik anemi gören hastaların sonuçlarını değerlendirmek için bir klinik çalışma yapılmıştır. Laboratuvar test stratejilerinin karşılaştırılması, en iyi stratejinin serum homosistein, metilmalonik asit, vitamin B12 (kobalamin) ve folik asit testlerini içermesi gerektiğini göstermektedir. Bu testlerin aynı anda istenmesinin en önemli nedeni nedir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aplastik anemi her iki besin maddesinin eksiklğinden kaynaklanabilir"}, {"letter": "B", "text": "Her iki besin maddesi benzer şekilde emilebilir"}, {"letter": "C", "text": "Nörolojik hasar önlenmelidir"}, {"letter": "D", "text": "Her ikisinde de yaşamı tehdit eden trombositope gelişebilir"}, {"letter": "E", "text": "Bir yetmezliğin tedavisi diğerini de iyileştirir"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q2", "explanation": "Makrositer anemide B12 eksikliği tek başına folik asit ile tedavi edilirse hematolojik tablo düzelir ancak B12 eksikliğine bağlı **geri dönüşümsüz nörolojik hasar (subakut kombine dejenerasyon) ilerlemeye devam eder**; bu nedenle **nörolojik hasarı önlemek için** her iki vitamin ve metabolitleri aynı anda değerlendirilmelidir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 3, "question": "17 yaşındaki bir kız çocuğu, hayatı boyunca yorgunluk ve halsizlik şikayeti ile başvurmuştur. Ergenlik dönemine girmemiştir. Fizik muayenede, ikincil cinsel özellikler iyi gelişmemiştir. Hepatosplenomegali vardır. Tam kan sayımı hemoglobin 9,1 g/dL, hematokrit %26,7, MCV 66 µm3, trombosit sayısı 89.000/mm3 ve WBC sayısı 3670/mm3. Periferik kan yaymasında RBC hipokromi, mikrositoz ve anizositoz ile ara sıra hedef hücreler görülmektedir. Ek laboratuvar bulguları arasında serum glikoz 144 mg/dL, tiroid uyarıcı hormon (TSH) 6,2 mU/mL ve ferritin 679 ng/mL bulunmaktadır. Bu kızda aşağıdakilerden hangisini kodlayan gende bir mutasyon mevcut olma olasılığı en yüksektir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ankirin"}, {"letter": "B", "text": "Beta globin"}, {"letter": "C", "text": "G6PD"}, {"letter": "D", "text": "HFE"}, {"letter": "E", "text": "NADPH oksidaz"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q3", "explanation": "17 yaşında primer amenore/gecikmiş puberte, hepatosplenomegali, ağır mikrositer hipokrom anemi (MCV: 66), hedef hücreler ve transfüzyonel **hemokromatozise (ferritin: 679) bağlı diyabet ve hipotiroidi** tablosu **Beta-talasemi intermedia/majör** olup **Beta-globin** gen mutasyonu sonucu gelişir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 4, "question": "Sicilya'dan 3 yaşındaki bir erkek çocuk iştahsız ve yaşı ve boyuna göre zayıf. Fizik muayenede hepatosplenomegali saptanıyor. Hemoglobin konsantrasyonu 6 g/dL ve periferik kan yaymasında ciddi hipokromik ve mikrositik kırmızı kan hücreleri görülüyor. Toplam serum demir düzeyi normal ve retikülosit sayısı %10. Kafatası röntgeni maksillofasiyal deformiteler ve genişlemiş kemik iliği boşlukları göstermektedir. Aşağıdakilerden hangisi bu çocuğun hastalığının en olası nedenidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Alfa ve beta globin zinciri üretiminde dengesizlik"}, {"letter": "B", "text": "Eritrosit membranlarının frajijitesinde artma"}, {"letter": "C", "text": "Hemoglobin F sentezinde azalma"}, {"letter": "D", "text": "Vitamin B12nin göreceli azlığı"}, {"letter": "E", "text": "Demirin retiküloendotelyal hücrelerde sekestrasyonu"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q4", "explanation": "Akdeniz (Sicilya) kökenli çocukta ağır hipokrom mikrositer anemi, hepatosplenomegali ve kafatasında ekstramedüller hematopoeze bağlı kemik iliği genişlemesi/maksillofasiyal deformite (**Beta-talasemi majör / Cooley anemisi**), **alfa ve beta globin zinciri üretimindeki dengesizlik** (beta zincir yokluğu ve serbest alfa zincirlerinin çökmesi) sonucu gelişir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 5, "question": "30 yaşındaki bir erkekte sol adrenal bezde feokromositoma vardır; kardeşinde serebellar hemanjiyoblastom vardır. Adrenalektomi ameliyatı geçiren hastanın mikroskobik incelemesinde neoplazmda yaygın vaskülarite görülmüştür. Neoplastik hücrelerin mutasyon analizi, bir genin her iki alel kopyasının da kaybolduğunu ve bunun sonucunda vasküler endotelyal büyüme faktörü (VEGF) transkripsiyonunun aktivasyonunu göstermiştir. Aşağıdaki genlerden hangisinin bu erkekte mutasyona uğramış olma olasılığı en yüksektir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "APC"}, {"letter": "B", "text": "BCL2"}, {"letter": "C", "text": "HER2"}, {"letter": "D", "text": "MYC"}, {"letter": "E", "text": "von Hippel-Lindau (VHL)"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q5", "explanation": "Serebellar hemanjiyoblastom, feokromositoma ve renal hücreli karsinom ile seyreden **von Hippel-Lindau (VHL) sendromunda** **VHL** tümör süpresör geninin her iki alleli kaybolur; HIF-1α yıkılamadığı için **VEGF** transkripsiyonu aşırı artar ve yoğun vaskülarite gelişir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 6, "question": "54 yaşındaki bir kadın sağ göğsünde bir kitle fark eder. Fizik muayenede, meme başı çevresindeki dokulara sabitlenmiş 2 cm'lik bir kitle ve sağ koltuk altında üç adet sert, ağrısız, elle hissedilebilen lenf bezi saptanır. Ailesinde kanser öyküsü yoktur. Eksizyonel meme biyopsisi yapılır ve mikroskobik inceleme, şekildeki bulguları gösterir. Sonraki 6 ay içinde, ek lenf düğümleri büyür ve BT taramaları akciğer, karaciğer ve beyinde nodüllerin ortaya çıktığını gösterir. Aşağıdaki moleküler anormalliklerden hangisi, kadının karsinom hücrelerinde en çok görülme olasılığı yüksektir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "ERBB2 (HER2) gen amplifikasyonu"}, {"letter": "B", "text": "Bir RB gen delesyonu"}, {"letter": "C", "text": "BCR ve ABL gen füzyonu"}, {"letter": "D", "text": "Bir BRCA1 gen kopyasının inaktivasyonu"}, {"letter": "E", "text": "Bir TP53 gen kopyasının mutasyonu"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q6", "image": "data:image/jpeg;base64,", "explanation": "Aile öyküsü olmayan (sporadik) agresif invaziv meme karsinomunda tümör hücrelerinde görülme olasılığı en yüksek somatik genetik anomali **ERBB2 (HER2) gen amplifikasyonudur**."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 7, "question": "66 yaşında bir erkek, 100 paket-yıl sigara içme geçmişi olan, son bir aydır idrarının koyulaştığını fark etmiştir. İdrar tahlili kan olduğunu göstermektedir. Sistoskopi yapılmış ve idrar kesesinin kubbesinde 5 cm'lik düzensiz bir kitle saptanmıştır. Biyopsi alınmış ve mikroskobik incelemede büyük nükleer-sitoplazmik oranına sahip çok pleomorfik hücreler görülmüştür. Hücrelerin yönelimi veya kitlenin yüzeyine doğru belirgin bir olgunlaşma olmadığından polarite eksikliği vardır. Atipik mitozlar mevcuttur. İmmünohistokimyasal boyama, ürotelyal kökenli özellikler göstermektedir. Bu lezyon aşağıdaki terimlerden hangisiyle en iyi şekilde tanımlanabilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "İlerlemiş evre"}, {"letter": "B", "text": "Lokal evre (limited stage)"}, {"letter": "C", "text": "Yüksek gradeli"}, {"letter": "D", "text": "Düşük gradeli"}, {"letter": "E", "text": "Hematojen metastaz"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q7", "explanation": "Biyopside hücrelerin normal dokuya benzerliğini kaybetmesi (polarite kaybı, belirgin pleomorfizm, yüksek nükleer/sitoplazmik oran ve atipik mitozlar) tümörün diferansiasyon derecesini yani **Yüksek gradeli (High-grade)** olduğunu tanımlar."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 8, "question": "73 yaşındaki bir kadının mamogramında, sol göğsünün üst dış kadranında düzensiz, sivri uçlu 3 cm'lik bir kitle görülmektedir. Radyoizotop Kitlenin yakınına bir radyoaktif izleyici enjekte edildi. Kitlenin cerrahi eksizyonu, taramada radyoaktif izleyici içeren aksiller lenf düğümü ile birlikte gerçekleştirildi. Eksize edilen düğümün immünohistokimyasal boyama ile mikroskobik incelemesi, sitokeratin için pozitif subkapsüler hücreler ortaya çıkardı. Aşağıdakilerden hangisi, bu sitokeratin pozitif hücrelerin en olası yorumudur?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Atipi"}, {"letter": "B", "text": "Enflamasyon"}, {"letter": "C", "text": "İnvazyon"}, {"letter": "D", "text": "Metaplazi"}, {"letter": "E", "text": "Metastaz"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q8", "explanation": "Normalde mezenşimal/lenfoid kökenli olan aksiller sentinel lenf düğümünün subkapsüler sinüsünde epitelyal belirteç olan **sitokeratin pozitif** hücrelerin görülmesi, meme karsinomunun lenf düğümüne **Metastaz (mikrometastaz)** yaptığını kanıtlar."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 9, "question": "Arı sokmasından 5 dakika sonra, 15 yaşındaki bir kız çocuğu aniden nefes almada güçlük çekmeye başlar ve gırtlak ödemi nedeniyle belirgin inspiratuar stridor görülür. Belirgin ürtiker görülür ve sokulan elinde şişlik fark edilir. Aşağıdakilerden hangisi, bu kızın belirti ve semptomlarını tedavi etmek için en uygun farmakolojik ajandır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Sikolosporin"}, {"letter": "B", "text": "Epinefrin"}, {"letter": "C", "text": "Glükokortikoid"}, {"letter": "D", "text": "Metotraksat"}, {"letter": "E", "text": "Penisilin"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q9", "explanation": "Arı sokması sonrası dakikalar içinde gelişen laringeal ödem (stridor) ve yaygın ürtiker **Anafilaksi (Tip I hipersensitivite)** tablosudur; hayat kurtarıcı ilk tercih acil tedavi **intramüsküler Epinefrin (Adrenalin)** uygulamasıdır."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 10, "question": "33 yaşındaki bir erkek, mide bulantısı ve kusma şikayeti ile başvurmuş ve son bir hafta içinde hafif sarılık gelişmiştir. Fizik muayenede ateşi 37,4°C'dir. Laboratuvar tetkiklerinde serum aspartat transaminaz (AST) 208 U/L ve alanin transaminaz (ALT) 274 U/L olarak saptanmıştır. Hepatit B yüzey antijeni (HBsAg) ve hepatit B çekirdek antikoru (HBcAb) için serolojik bulgular olumludur. Mikroskopla incelenen karaciğer biyopsi örneğinde portal inflamatuar hücre infiltrasyonu ile birlikte hepatositlerin fokal ölümü görülmektedir. Aşağıdakilerden hangisi bu koşullar altında karaciğer hücresi hasarının meydana gelmesinin en olası mekanizmasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aktive makrofajların sitokin salımı"}, {"letter": "B", "text": "HbSag sunan hepatositlerin antikorla yokedilmesi"}, {"letter": "C", "text": "Dolaşan HBSagnin CD4+ lenfositlerce tanınmas"}, {"letter": "D", "text": "Viral peptidin, MHC l molekülleri yardımıyla CD8+ lenfositlerce tanınması-"}, {"letter": "E", "text": "MHC class II moleküller ile sunulan viral partiküllerin NK (natrual killer) hücrelerce tanınmas"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q10", "explanation": "Akut Hepatit B enfeksiyonunda hepatosit hasarı, enfekte hepatositlerde **MHC Sınıf I molekülleriyle sunulan viral peptidlerin CD8+ sitotoksik T lenfositlerce tanınarak** hücrenin apoptoza uğratılması sonucu oluşur."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 11, "question": "80 yaşındaki bir kadın, 1 haftadır dizüri şikayetiyle başvurdu ve şimdi ateşi var. Muayenede, ateşi 37,9°C (100,2°F), nabzı 103/dk ve kan basıncı 80/40 mm Hg. Sağ yan ağrısı var. İdrar tahlili çok sayıda WBC(lökosit) göstermektedir. Plazma laktatı yükselmiştir. İdrar kültürü ve kan kültüründe Escherichia coli üremektedir. Aşağıdakilerden hangisi Toll-like hücre reseptörlerini tetikleyerek kardiyovasküler kolapsına en çok katkıda bulunur?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kompleman C3b"}, {"letter": "B", "text": "Lipopolisakkarid"}, {"letter": "C", "text": "Nitrik oksit"}, {"letter": "D", "text": "Platelet activating factor (PAF)"}, {"letter": "E", "text": "Toksik şok sendrom toksin-1"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q11", "explanation": "*Escherichia coli* ürosepsisi (Gram-negatif septik şok) tablosunda makrofaj ve endotel hücrelerindeki **Toll-like reseptör 4 (TLR4)**'ü uyararak aşırı TNF/IL-1/NO salınımına ve kardiyovasküler kollapsa yol açan bakteriyel endotoksin **Lipopolisakkarid (LPS)**'dir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 12, "question": "48 yaşındaki bir kadının parmakları sivrilmiş ve pençe gibidir, küçük eklemlerde hareket kabiliyeti azalmıştır. Yüzünde kırışıklık çizgileri yoktur. Cildin mikroskobik görünümü şekilde gösterilmiştir. Hastada ayrica pulmoner hipertansiyon ve kor pulmonale ile birlikte yaygın interstisyel fibrozis vardır. Aşağıdaki deri iltihap hücrelerinden hangisi, cilt hastalığının nedeni olan sürecin başlatıcısı olma olasılığı en yüksektir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "CD4+ lenfositler"}, {"letter": "B", "text": "Makrofaj"}, {"letter": "C", "text": "Mast hücresi"}, {"letter": "D", "text": "Nötrofil"}, {"letter": "E", "text": "NK (natural killer)"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q12", "image": "data:image/jpeg;base64,", "explanation": "Pençe el (sklerodaktili), maske yüz, yaygın dermal ve pulmoner interstisyel fibrozis **Sistemik Skleroz (Skleroderma)** tablosudur; patogenezde süreci başlatan ve TGF-β/IL-13 gibi sitokinlerle fibroblastları uyaran temel hücre **CD4+ T lenfositlerdir**."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 13, "question": "22 yaşındaki bir kadın, komplikasyonsuz bir hamilelik geçirirken normal bir bebek için rutin vajinal doğum sırasında aniden siyanoz ve hipotansiyon ile birlikte nefes darlığı başlar. Genel bir nöbet geçirir ve komaya girer. Durumu sonraki 2 gün boyunca düzelmez. Aşağıdaki bulgulardan hangisi periferik pulmoner arterlerinde en olasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Trombositlerin aggregasyonu"}, {"letter": "B", "text": "Amniotik sıvı"}, {"letter": "C", "text": "Yağ globülleri"}, {"letter": "D", "text": "Gaz kabarcıkları"}, {"letter": "E", "text": "Tromboemboli"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q13", "explanation": "Normal vajinal doğum sırasında veya hemen sonrasında ani gelişen dispne, siyanoz, hipotansiyon, nöbet/koma ve DİK tablosu **Amniyon Sıvısı Embolisi**dir; pulmoner arteriyollerde fetal skuamöz epitel hücreleri, lanugo ve müsin içeren **amniyotik sıvı** elemanları görülür."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 14, "question": "Büyük bir karın ameliyatı geçiren 55 yaşındaki bir kadın, son bir haftadır sol bacağında rahatsızlık ve şişlik hissediyor. Fizik muayenede baldırda derin hassasiyet gözleniyor. Doppler ultrasonografide sol bacağın derin damarlarında tromboz görüntüleniyor. Aşağıdaki mekanizmalardan hangisi kadının durumuna en çok katkıda bulunmuş olabilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hiperkalsemi"}, {"letter": "B", "text": "İmmobilizasyon"}, {"letter": "C", "text": "Aspirin injesyonu"}, {"letter": "D", "text": "Nitrik oksit salınımı"}, {"letter": "E", "text": "Türbülan kan akımı"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q14", "explanation": "Büyük batın cerrahisi sonrasında bacak derin venlerinde tromboz (DVT) gelişimine en çok katkıda bulunan Virchow triadı bileşeni, yatak istirahatine bağlı venöz staz yani **İmmobilizasyon (hareketsizlik)**'dur."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 15, "question": "26 yaşındaki bir kadın, son 12 yıldır sık sık burun kanaması ve adet kanamasında artış öyküsü vardır. Fizik muayenede, ekstremitelerinin derisinde peteşi ve purpura gözlenir. Laboratuvar tetkiklerinde parsiyel tromboplastin zamanı (PTT), protrombin zamanı (PT) ve trombosit sayısı normal, ancak von Willebrand faktörü aktivitesi azalmıştır. Bu hastada en olası olarak hemostazın aşağıdaki aşamalarından hangisinde bir bozukluk vardır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Fibrin polimerizasyonu"}, {"letter": "B", "text": "Trombosit adezyonu"}, {"letter": "C", "text": "Trombosit aggregasyonu"}, {"letter": "D", "text": "Protrombin oluşumu"}, {"letter": "E", "text": "Protrombin inhibisyonu"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q15", "explanation": "**von Willebrand faktörü (vWF)**, endotel hasarı bölgesinde subendotelyal kollajen ile trombosit yüzeyindeki GpIb-IX reseptörü arasında köprü kurar; bu nedenle vWF eksikliğinde (von Willebrand hastalığında) temel bozukluk **Trombosit adezyonu** aşamasındadır."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 16, "question": "7 yaşındaki bir erkek çocuk bir haftadır giderek artan halsizlik şikayetiyle başvurmuştur. Fizik muayenede, periorbital ödem ve ayak bileklerinde çukurlaşan ödem saptanmış, ancak kan basıncı normal ve ateşi yoktur. Laboratuvar tetkiklerinde belirgin albüminüri saptanmıştır. Tiyazid diüretik verilmiş ve idrar çıkışı artmış, ödemi giderilmiştir. Aşağıdaki değişikliklerden hangisi ödemini en olası şekilde güçlendirmiştir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Azalmış aldosteron"}, {"letter": "B", "text": "Azalmış renin"}, {"letter": "C", "text": "Armıs kortizol"}, {"letter": "D", "text": "Artmış tuz tutulumu"}, {"letter": "E", "text": "Azalmış antiiüretik hormon"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q16", "explanation": "Nefrotik sendromlu (ağır albüminürili) çocukta plazma onkotik basıncının düşmesiyle sıvı interstisyuma kaçar ve efektif arteriyel kan hacmi azalır; buna yanıt olarak **Renin-Anjiyotensin-Aldosteron (RAAS) sistemi aktive olur ve böbrekten artmış tuz (sodyum) ve su tutulumu** ödemi daha da şiddetlendirir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 17, "question": "Uzun süre ayakta çalışarak mesleğini icra eden 45 yaşındaki bir kadın, 8 saatlik vardiyasının sonunda, günün başında herhangi bir şişlik olmamasına rağmen, bacaklarının alt kısmının ve ayaklarının şiştiğini fark eder. Bu şişlikle ilişkili herhangi bir ağrı veya kızarıklık yoktur. Kadın, bunun dışında sağlıklıdır ve herhangi bir ilaç kullanmamaktadır; laboratuvar testleri karaciğer ve böbrek fonksiyonlarının normal olduğunu göstermektedir. Aşağıdaki mekanizmalardan hangisi bu durumu en iyi şekilde açıklamaktadır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aşırı su içilmesi"}, {"letter": "B", "text": "Hipoalbüminemi"}, {"letter": "C", "text": "Artmış hidrostatik basınç"}, {"letter": "D", "text": "Lenfatik obstrüksiyon"}, {"letter": "E", "text": "Sekonder aldosteronizm"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q17", "explanation": "Sağlıklı bir bireyde uzun süre ayakta hareketsiz kalma sonucunda yerçekimi etkisiyle alt ekstremite venlerinde oluşan göllenme ve ödem, **artmış kapiller hidrostatik basınç** mekanizmasıyla açıklanır."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 18, "question": "11 yaşındaki bir erkek çocuk bisikletinden düştükten sonra dizinde sıyrık oluşur. Sonraki 3 gün içinde 2 x 4 cm'lik yara, kabarık, pürüzlü, kırmızı, granül bir alan oluşarak iyileşir. İyileşme sürecini hızlandırmak için makrofajlardan hangisi salınır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Fibroblast growth faktör"}, {"letter": "B", "text": "GTP-binding protein"}, {"letter": "C", "text": "myc protein"}, {"letter": "D", "text": "p53 protein"}, {"letter": "E", "text": "Tirozin kinaz"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q18", "explanation": "Yara iyileşmesi ve granülasyon dokusu oluşumu sırasında M2 makrofajlardan salınarak fibroblast çoğalmasını ve anjiyogenezi hızlandıran büyüme faktörü **Fibroblast Büyüme Faktörü (FGF)**'dür (TGF-β, PDGF ve VEGF ile birlikte)."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 19, "question": "Doku kültüründeki hücrelerin yüksek düzeyde ultraviyole radyant enerjiye maruz bırakıldığı bir deney yapılır. Elektron mikroskobu, denatüre proteinlerin sitozolik agregatlarının artması şeklinde hücresel hasar olduğunu göstermektedir. In situ hibridizasyon, bu agregatlardaki protein bileşenlerinin proteazomlarda da bulunduğunu ortaya koymaktadır. Aşağıdaki maddelerden hangisi, denatüre proteinlere bağlanarak, sitozolik proteazomlar tarafından katabolizma için hedef alınmalarını sağlar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kalsiyum"}, {"letter": "B", "text": "Caspase"}, {"letter": "C", "text": "Granzyme B"}, {"letter": "D", "text": "Ubiquitin"}, {"letter": "E", "text": "Superoxide"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q19", "explanation": "Hücre içinde hasarlanmış veya yanlış katlanmış denatüre proteinlere kovalent olarak bağlanarak onları sitozolik **proteazomlarda yıkım için etiketleyen** 76 aminoasitlik küçük düzenleyici protein **Ubiquitin (Ubikuitin)**'dir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 20, "question": "5 yaşındaki bir çocuk, besin yağlarının emilim bozukluğu nedeniyle büyüme geriliği ile birlikte tekrarlayan akciğer enfeksiyonları yaşamaktadır. Tüm ekzom dizilemesi, CFTR proteinini kodlayan bir gende mutasyon olduğunu ortaya koymaktadır. Bu protein yanlış katlanmıştır ve hücreler içinde tutulmaktadır. Aşağıdaki hücre organellerinden hangisi, uygun konformasyona sahip olmayan bu yanlış katlanmış proteinleri tutan şaperon moleküllerine sahiptir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Golgi aparatı"}, {"letter": "B", "text": "Lizozom"}, {"letter": "C", "text": "Proteazom"}, {"letter": "D", "text": "Ribozom"}, {"letter": "E", "text": "RER( rough endoplazmik retikulum)"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q20", "explanation": "Kistik fibroziste (ΔF508 mutasyonu) sentezlenen membran proteinlerinin (CFTR) katlanmasını denetleyen ve yanlış katlanmış proteinleri Golgiden hücre yüzeyine göndermeyip ER ilişkili yıkıma (ERAD) yönlendiren şaperon molekülleri **Granüllü Endoplazmik Retikulum (RER)** içinde yer alır."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 21, "question": "Cerrahi kesi yerinde, endotel hücreleri vasküler endotel büyüme faktörünü üretir. Endotel hücrelerinin yaraya göçü ile yeni kılcal damarların oluşması için filizlenme meydana gelir. Aşağıdaki hücre içi proteinlerden hangisi endotel hücrelerinin hareketini kolaylaştırmada en önemli olanıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aktin"}, {"letter": "B", "text": "Sitokeratin"}, {"letter": "C", "text": "Desmin"}, {"letter": "D", "text": "Laminin"}, {"letter": "E", "text": "Myosin"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q21", "explanation": "Anjiyogenez sırasında endotel hücrelerinin ekstrasellüler matriks içinde lamellipodia/filopodia uzatarak **aktif göç (migrasyon) ve hareket** etmesini sağlayan temel hücre iskeleti mikrofilamenti **Aktin**dir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 22, "question": "48 yaşındaki bir kadına meme kanseri teşhisi konur ve tümör hücrelerinin moleküler analizi, nükleer kromozomal genin aktif olarak haberci RNA'yı (mRNA) transkribe ettiğini ve bunun hücre sitoplazmasına taşınarak hücre çoğalmasını tetiklediğini gösterir. Hasta, ekspresyonu değiştiren bir ajanla tedavi edilir, böylece bu mRNA'nın translasyonundan protein ürünü gözlemlenmez. Bu aktif genin mRNA'sının sessizleştirilmesi en olası şekilde nasıl gerçekleşir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Tranfer RNAnın yokluğu"}, {"letter": "B", "text": "miRNAya bağlanma"}, {"letter": "C", "text": "DNAnın metilasyonu"}, {"letter": "D", "text": "mRNAnın mutasyonu"}, {"letter": "E", "text": "Mitokondrial RNAnın upregülasyonu"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q22", "explanation": "Çekirdekten transkribe edilip sitoplazmaya geçen aktif bir mRNA'nın protein ürününe çevrilmesinin (translasyonunun) post-transkripsiyonel olarak susturulması/sessizleştirilmesi, **miRNA (mikroRNA) veya siRNA'ya bağlanma (RNA interferansı)** yoluyla gerçekleşir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 23, "question": "28 yaşındaki bir kadın çocukluğundan beri sürekli halsizlik hissi yaşamaktadır. Fizik muayenede ateşi yoktur, nabzı 80/dk, solunum sayısı 15/dk ve kan basıncı 110/70 mm Hg'dir. Dalak ucu palpe edilebilir, ancak karın ağrısı veya hassasiyeti yoktur. Laboratuvar tetkiklerinde hemoglobin 11,7 g/dL, trombosit sayısı 159.000/mm3 ve WBC sayısı 5390/mm3 olarak saptanmıştır. Periferik kan smearinde, merkezinde solukluk bölgesi olmayan küçük yuvarlak eritrositler görülmektedir. Bu bulguları en iyi açıklayan kalıtsal anormallik aşağıdaki RBC bileşenlerinden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Alfa globin zinciri"}, {"letter": "B", "text": "Beta globin zinciri"}, {"letter": "C", "text": "Karbonik anhidraz"}, {"letter": "D", "text": "Glükoz 6 fosfat dehidrojenaz"}, {"letter": "E", "text": "Spektrin sitoskeletal proteini"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q23", "explanation": "Splenomegali ve periferik yaymada merkezi solukluğu olmayan küçük yuvarlak eritrositler (**sferositler**) ile karakterize **Herediter Sferositoz**, eritrosit membran hücre iskeleti proteinlerinden **Spektrin** (veya ankirin, band 3, protein 4.2) defekti sonucu gelişir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 24, "question": "19 yaşındaki sağlıklı bir kadın motorlu araç kazasında künt abdominal travma geçirdi. Hastaneye yatırıldığında başlangıç hematokriti %33 idi, ancak bir saat içinde %28'e düştü. Paracentezde serozangiöz sıvı çıkmıştır. Ameliyata alınan hastanın karaciğer yırtığı onarılmış ve periton boşluğundan 1 litre kanlı sıvı alınmıştır. Hastanın durumu stabil kalmıştır. 3gün sonra yapılan tam kan sayımı, periferik kanda aşağıdaki morfolojik bulgulardan hangisini gösterecektir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Eritrositlerin bazofilik stipplingi"}, {"letter": "B", "text": "Hipokromik eritrositler"}, {"letter": "C", "text": "Lökoeritroblastozis"}, {"letter": "D", "text": "Retikülositozis"}, {"letter": "E", "text": "Schistositozis"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q24", "explanation": "Akut travmatik iç kanama (karaciğer laserasyonu) sonrasında kemik iliği sağlam olan genç hastada hipoksi ve eritropoetin artışına yanıt olarak **3-5. günlerde periferik kanda belirgin Retikülositozis (polikromazi)** görülür."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 25, "question": "12 yaşındaki bir kız çocuğu, son 3 gündür boğaz ağrısı şikayetiyle başvurmuştur. Fizik muayenede, ateşi 38,4°C ve faringeal eritem ile minimal eksüda mevcuttur. Boğaz kültüründe A grubu ẞ- hemolitik Streptococcus üremektedir. Farenjit düzelir, ancak 3 hafta sonra kızda ateş ve göğüs ağrısı gelişir. Anti-streptolizin O titresi 1:512'dir. Aşağıdaki immünolojik mekanizmalardan hangisi göğüs ağrısına en olası neden olmuştur?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "T hücre anerjisinin yıkımı"}, {"letter": "B", "text": "T hücre ile oluşan supresyonun yetersizliği"}, {"letter": "C", "text": "Moleküler mimikri (taklit)"}, {"letter": "D", "text": "Poliklonal lenfosit aktivasyonu"}, {"letter": "E", "text": "Sekestre antijenlerin salımı"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q25", "explanation": "A grubu β-hemolitik streptokok (*S. pyogenes*) farenjitinden 3 hafta sonra ateş ve göğüs ağrısı (perikardit/miyokardit) ile gelişen **Akut Romatizmal Ateş**, streptokok M proteini ile miyokard antijenleri arasındaki **Moleküler mimikri (moleküler taklit / çapraz reaksiyon)** sonucu oluşur."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 26, "question": "Yeni bir viral solunum yolu patojeninin neden olduğu bir pandeminin epidemiyolojik çalışması, enfekte kişiler arasında hastalığın şiddetinde farklılıklar olduğunu ortaya koymaktadır. Viral antijen testi pozitif çıkan bazı kişilerde sadece hafif ateş, kuru öksürük ve burun akıntısı görülürken, diğer kişilerde şiddetli alt solunum yolu pnömonisi gelişir. Aşağıdaki moleküllerden hangisinin polimorfizmleri, bu virüse karşı konakçı CD8 T hücresi yanıtındaki biyolojik değişkenliği açıklamaya en uygun olasılıktır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "NK hücre reseptörleri"}, {"letter": "B", "text": "Kompleman C3"}, {"letter": "C", "text": "MHC Class I molekülleri"}, {"letter": "D", "text": "Myeloperoksidaz"}, {"letter": "E", "text": "C-reaktif protein"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q26", "explanation": "Hücre içi viral patojenlere karşı **CD8+ sitotoksik T lenfosit** yanıtı, viral peptidlerin **MHC Sınıf I (HLA-A, HLA-B, HLA-C)** molekülleri tarafından sunulmasına bağlıdır; bu nedenle bireyler arasındaki CD8+ T hücre yanıt farklılıklarını **MHC Class I polimorfizmleri** açıklar."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 27, "question": "35 yaşındaki bir erkek, son 5 aydır artan kas güçsüzlüğü yaşamaktadır. Bu güçsüzlük, en çok göz kapaklarının levator palpebrae gibi yoğun olarak kullanılan kaslarda belirgindir ve günün sonunda görme zorluğu yaşamasına neden olmaktadır. Bir gece uykudan sonra, semptomları azalmıştır. Fizik muayenede ateşi yoktur. Ciltte kızarıklık görülmemektedir. Kas gücü başlangıçta 5/5 ancak tekrarlayan hareketlerle azalmaktadır. Göğüs BT taramasında timus büyümesi görülmektedir. Aşağıdakilerden hangisi bu hastada kas güçsüzlüğünün en olası mekanizmasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Nöromusküler bileşkenin antikorla oluşturulan disfonksiyonu"}, {"letter": "B", "text": "Kas antijenlerine karşı gecikmiş hipersensitivite"}, {"letter": "C", "text": "Kas kapillerlerinde immün kompleks birikimi"}, {"letter": "D", "text": "Kas hücrelerinin CD8+ lenfositlerce yıkımı"}, {"letter": "E", "text": "Aktive makrofajlardan sitokin salınımı"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q27", "explanation": "Gün içinde tekrarlayan hareketlerle artan kas güçsüzlüğü, pitozis/diplopi ve timus hiperplazisi/timoma ile karakterize **Myastenia Gravis**, postsinaptik nikotinik asetilkolin reseptörlerine karşı gelişen otoantikorlarla **nöromusküler bileşkenin antikor aracılı (Tip II) disfonksiyonu** sonucu gelişir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 28, "question": "59 yaşındaki diyabet öyküsü olan bir kadın 3 ay önce miyokard enfarktüsü geçirdi. BMI'si 35 kg/ m2'dir. Tekrarlayan arteriyel tromboz riskini azaltmak için şu anda düşük doz asetilsalisilik asit (aspirin) alıyor. Hemostazda aşağıdaki adımlardan hangisinde aspirin dozu en büyük etkiye sahiptir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Trombositlerin kollajene adezyonu"}, {"letter": "B", "text": "Trpmbositlerin aggregasyonu"}, {"letter": "C", "text": "Doku faktörünün üretimi"}, {"letter": "D", "text": "von Willebrand faktör sentezi"}, {"letter": "E", "text": "Antitrombin III sentezi"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q28", "explanation": "Düşük doz **aspirin (asetilsalisilik asit)**, trombositlerdeki COX-1 enzimini irreversibl inhibe ederek Tromboksan A2 (TxA2) sentezini durdurur ve hemostazda **trombositlerin agregasyonu (kümeleşmesi)** basamağını bloke eder."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 29, "question": "53 yaşındaki bir erkek, konjestif kalp yetmezliği varlığıyla birlikte COVID-19 geçirdikten sonra pulmoner Streptococcus pneumoniae enfeksiyonu geliştirir. 2 hafta iyileştikten sonra, plevral göğüs ağrısı hisseder. Muayenede sol bacağı şişmiş ve hassastır. Ağrı, şekilde gösterilen lezyonun gelişmesinden kaynaklanmaktadır. Bu erkekte aşağıdaki olaylardan hangisi en olasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Akut pulmoner konjesyon"}, {"letter": "B", "text": "Kronik pulmoner konjesyon"}, {"letter": "C", "text": "Pulmoner ödem"}, {"letter": "D", "text": "Pulmoner enfarkt"}, {"letter": "E", "text": "Pulmoner nenöz tromboz"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q29", "image": "data:image/jpeg;base64,", "explanation": "Konjestif kalp yetmezliği ve bacakta derin ven trombozu (şiş ve hassas bacak) olan hastada plevral göğüs ağrısı ve akciğer periferinde tabanı plevraya, tepesi hilusa bakan **kama (üçgen) şeklinde kırmızı/hemorajik nekroz alanı** gelişmesi **Pulmoner enfarkt** için tipiktir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 30, "question": "85 yaşındaki bir erkek banyoda düşerek başının arkasını çarpar. Sonraki 24 saat içinde uyku hali giderek artar. Kafa BT taramasında dura altında sıvı birikimi ve sol beyin yarıküresinde bası olduğu görülür. Aşağıdaki terimlerden hangisi bu sıvı birikimini en iyi şekilde tanımlar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Konjesyon"}, {"letter": "B", "text": "Ekimoz"}, {"letter": "C", "text": "Hematom"}, {"letter": "D", "text": "Peteşi"}, {"letter": "E", "text": "Purpura"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q30", "explanation": "Kafa travması sonrası dura mater altında (subdural aralıkta) beyin parankimine bası yapacak şekilde pıhtılaşmış kan kitlesi birikmesine **Hematom (Subdural hematom)** denir."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 31, "question": "6 yaşındaki bir erkek çocuk, son bir haftadır kasıklarının sağ tarafında ağrının şiddetlendiğinden şikayetçi. Fizik muayenede sağ kasık bölgesinde ağrılı, şişmiş lenf düğümleri görüldü. Kasık lenf düğümü biyopsisi yapıldı ve mikroskobik incelemede düğümde çok sayıda mitotik figür içeren, büyüklükleri değişken, geniş germinal merkezler görüldü. Çok sayıda parafoliküler ve sinüzoidal nötrofil vardı. Bu histolojik değişikliklerin en olası nedeni nedir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Akut lenfadenitis"}, {"letter": "B", "text": "Akut lenfoblastik lösemi"}, {"letter": "C", "text": "Folliküler lenfoma"}, {"letter": "D", "text": "Sarkoidozis"}, {"letter": "E", "text": "Toksoplazmozis"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q31", "explanation": "Ağrılı inguinal lenfadenopati, biyopside çok sayıda mitotik figür içeren genişlemiş germinal merkezler ve yoğun parafoliküler/sinüzoidal nötrofil infiltrasyonu drenaj alanındaki enfeksiyona ikincil **Akut nonspesifik lenfadenit** tablosudur."}, {"year": "2025-2026", "subject": "Patoloji", "q_num": 32, "question": "51 yaşındaki sağlıklı bir erkeğe tarama kolonoskopisi yapılır. Tek lezyon, sigmoid bölgede bulunan 0,6 cm çapında sessil bir kitledir. Bu kitle, çevreleyen mukoza seviyesinin 0,2 cm üzerine uzanır, pürüzsüz kahverengi bir yüzeye sahiptir ve iyi tanımlanmış sınırları vardır. Aşağıdaki terimlerden hangisi bu kitlenin mikroskobik görünümünü en iyi şekilde tanımlar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Adenoma"}, {"letter": "B", "text": "Papilloma"}, {"letter": "C", "text": "Fibroma"}, {"letter": "D", "text": "Karsinoma"}, {"letter": "E", "text": "Sarkoma"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q32", "explanation": "Tarama kolonoskopisinde sigmoid kolonda saptanan iyi sınırlı, sesil, benign glandüler mukoza neoplazisi **Adenoma** olarak tanımlanır."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 33, "question": "Aşağıdakilerden hangisi antianemik ilaçlarla ilgili yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Üst üste yüksek doz demir ilacı alımı yapılırsa mukozal blok gelişir ve emilim kısıtlanır."}, {"letter": "B", "text": "Fe+3 mukoza epitelindeki DMT1 reseptörüyle emilir."}, {"letter": "C", "text": "Ferröz form biyoyararlanımı yüksek olduğu için oral tedavide tercih edilir."}, {"letter": "D", "text": "Askorbik asitle demir ilacı alımı emilimi artırır"}, {"letter": "E", "text": "Demir tedavisinde etkinliğin anlaşılması için 3-4 hafta kullanım gereklidir."}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q33", "explanation": "Duodenum mukoza epitelindeki **DMT1 (Divalan Metal Taşıyıcı-1)** reseptörüyle Fe+3 (ferrik) demir değil, ferrik redüktaz ile indirgenmiş **Fe+2 (ferröz) demir** emilir."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 34, "question": "Aşağıdakilerden hangisi Fe+2 ilaç değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "demir sülfat"}, {"letter": "B", "text": "Demir Süksinat"}, {"letter": "C", "text": "Demir Fumarat"}, {"letter": "D", "text": "Demir Bisglisinat"}, {"letter": "E", "text": "Demir glisin Sülfat"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q34", "explanation": "Demir sülfat, demir fumarat, demir bisglisinat ve demir glisin sülfat Fe+2 (ferröz) preparatlardır; bu soruda cevap anahtarında **B (Demir Süksinat / Ferrik süksinat)** işaretlenmiştir."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 35, "question": "Aşağıdaki dokulardan hangisinde parasempatik sistem daha baskındır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Ventrikül kası dokusu"}, {"letter": "B", "text": "Arter düz kas dokusu"}, {"letter": "C", "text": "Gözde radyal kas"}, {"letter": "D", "text": "Apokrin ter bezleri"}, {"letter": "E", "text": "Gastrointestinal doku"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q35", "explanation": "Ventrikül kası, arteriyoler düz kaslar, gözdeki radyal kas (dilatatör pupilla) ve apokrin ter bezlerinde sempatik sistem baskınken; **Gastrointestinal kanal düz kasları ve salgı bezlerinde parasempatik (vagal/pelvik kolinerjik) sistem daha baskındır**."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 36, "question": "Otonom sinir sitemindeki reseptörleri ile ilgili hangisi yanlıştır?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Vasküler düz kaslarda a1 uyarılınca kasılma olur"}, {"letter": "B", "text": "Kalpte SA ve AV nod M2 uyarılınca kalp hızlanır"}, {"letter": "C", "text": "Mesane kasında ẞ3 uyarılması gevşeme olur"}, {"letter": "D", "text": "Bronş düz kaslarında M3 uyarılması kasılma olur"}, {"letter": "E", "text": "Beyindeki a2 uyarılması sonrası tansiyon düşmes sağlanır"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q36", "prof_inferred": true, "explanation": "Kalpte SA ve AV düğümde bulunan **M2 muskarinik reseptörler** (Gi kenetli) uyarıldığında K+ kanalları açılır, cAMP azalır ve **kalp hızı yavaşlar (negatif kronotrop ve negatif dromotrop etki)**; 'kalp hızlanır' ifadesi yanlıştır."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 37, "question": "Ameliyat sonrası hastada nöromüsküler kavşak blokör ilaçların etkisini ortadan kaldırmak için hangisini verirsin?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Neostigmin"}, {"letter": "B", "text": "Betanekol"}, {"letter": "C", "text": "Atropin"}, {"letter": "D", "text": "Süksinil kolin"}, {"letter": "E", "text": "Donepezil"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q37", "explanation": "Ameliyat sonrasında non-depolarizan nöromüsküler kavşak blokörlerinin etkisini geri çevirmek (ortadan kaldırmak) için asetilkolinesteraz inhibitörü olan **Neostigmin** (atropin ile birlikte) verilir."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 38, "question": "Parasempatomimetik ilaçların endikasyonlarından biri değildir?", "professor": "Bilge Özcan", "options": [{"letter": "A", "text": "Nöromusküler bloke edicilerin etkisini sonlandırmak"}, {"letter": "B", "text": "Paralitik ileus"}, {"letter": "C", "text": "Alzheimer hastalığı"}, {"letter": "D", "text": "Antikolinerjik ilaç zehirlenmesinde"}, {"letter": "E", "text": "Hipersalivasyon tedavisinde"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q38", "prof_inferred": true, "explanation": "Parasempatomimetik ilaçlar tükürük salgısını artırarak ağız kuruluğu (kserostomi) tedavisinde kullanılır; **hipersalivasyon (aşırı tükürük salgısı) tedavisinde ise parasempatomimetikler değil antimuskarinikler kullanılır**."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 39, "question": "M3 reseptörlerini yüksek selektiviteyle bloke etmesi sebebiyle mesane ve üretra üzerine daha etkili olan üriner sistem antispazmolitiği olan ilaç hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Flavoksat"}, {"letter": "B", "text": "Tropikamid"}, {"letter": "C", "text": "Atropin"}, {"letter": "D", "text": "Siklopentolat"}, {"letter": "E", "text": "Hyosin-N-Butil bromür"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q39", "explanation": "Mesane ve üretra düz kasları üzerinde antispazmodik etki gösteren üriner sistem ilacı olarak bu sorunun cevap anahtarında **A (Flavoksat)** işaretlenmiştir."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 40, "question": "Antimuskarinik ilaçlardan hangisi antispazmodik olarak gastrointestinal sistem spazmları ve renal kolikte kullanılır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hyosin n-butil bromür"}, {"letter": "B", "text": "Pirenzepin"}, {"letter": "C", "text": "Darifenasin"}, {"letter": "D", "text": "Asetilkolin"}, {"letter": "E", "text": "Solifenasin"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q40", "explanation": "Gastrointestinal sistem spazmları, biliyer kolik ve renal kolikte antispazmodik olarak yaygın kullanılan kuaterner amin yapılı antimuskarinik **Hyosin-N-butil bromür**'dür."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 41, "question": "Hodgkin lenfoması tanısı alan bir hasta MOPP rejimi ile tedavi edilmektedir. Bu rejimde kullanılan alkilleyici ajan aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Prokarbazin"}, {"letter": "B", "text": "Vinkristin"}, {"letter": "C", "text": "Prednizon"}, {"letter": "D", "text": "Mekloretamin"}, {"letter": "E", "text": "Doksorubisin"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q41", "explanation": "Hodgkin lenfomada kullanılan **MOPP** (Mekloretamin, Onkovin/Vinkristin, Prokarbazin, Prednizon) rejimindeki klasik nitrojen mustard grubu **alkilleyici ajan Mekloretamin**dir."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 42, "question": "35 yaşında bir hasta, akut lenfoblastik lösemi (ALL) tanısıyla kemoterapiye başlanıyor. Kullanılan ilaç, dihidrofolat redüktaz (DHFR) enzimini inhibe ederek DNA sentezini bozar. Bu ilacın antidotu olarak folinik asit (lökovorin) verilebilir. Bu ilaç aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Metotreksat"}, {"letter": "B", "text": "Sitarabin"}, {"letter": "C", "text": "6-Merkaptopürin"}, {"letter": "D", "text": "5-Fluorourasil"}, {"letter": "E", "text": "Hidroksiüre"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q42", "explanation": "**Dihidrofolat redüktaz (DHFR)** enzimini inhibe ederek DNA sentezini bozan ve toksisitesinde antidot olarak **folinik asit (lökovorin)** kullanılan folat antimetaboliti **Metotreksat**tır."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 43, "question": "52 yaşında kadın hasta, meme kanseri nedeniyle kemoterapi almaktadır. Tedavi sırasında en önemli sınırlayıcı yan etkinin gelişmemesi için sık aralıklarla tam kan sayımı istenmektedir. Aşağıdakilerden hangisi antineoplastik ilaçların en sık ve en önemli sınırlayıcı toksisitesidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kardiyotoksisite"}, {"letter": "B", "text": "Kemik iliği süpresyonu"}, {"letter": "C", "text": "Hepatotoksisite"}, {"letter": "D", "text": "Periferik nöropati"}, {"letter": "E", "text": "Ototoksisite"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q43", "explanation": "Sitotoksik antineoplastik ilaçların en sık görülen ve doz artırımını en çok sınırlayan yan etkisi **Kemik iliği süpresyonudur (miyelosüpresyon)**."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 44, "question": "Topoizomeraz-I enzim inhibisyonu yapan antikanser ilaç aşağıdakilerden habgisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "İrinotekan"}, {"letter": "B", "text": "Tioguanin"}, {"letter": "C", "text": "Klorambusil"}, {"letter": "D", "text": "Tenipozit"}, {"letter": "E", "text": "Bleomisin"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q44", "prof_inferred": true, "explanation": "**İrinotekan** (ve topotekan) **Topoizomeraz-I** enzimini inhibe eden antineoplastik ilaçtır.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 14, "id": "2022-2023_Q14"}]}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 45, "question": "İmmünsüpresif ilaçların etkinliğinin en düşük olduğu durum hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Geç gelişen kronik red reaksiyonu üzerindeki"}, {"letter": "B", "text": "Organ naklindenki (böbrek, karaciğer, kemik iliği) etkinliği"}, {"letter": "C", "text": "Psöriyazis ve atopik dermatitin tedavisindeki etkinliği"}, {"letter": "D", "text": "Otoimmün hastalıklar (RA, SLE gibi) üzerindeki etkinliği"}, {"letter": "E", "text": "CD4 + tipi T lenfositlerin aracılığı ile oluşturulan red (rejeksiyon) reaksiyonunundaki etkinliği"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q45", "explanation": "Mevcut immünsüpresif ilaçlar akut hücresel reddi önlemede ve otoimmün hastalıkları baskılamada oldukça etkiliyken, damar duvarında intimal fibrozis ve iskemiyle ilerleyen **geç gelişen kronik red (rejeksiyon) reaksiyonu üzerindeki etkinlikleri en düşüktür**."}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 46, "question": "Hangisi İmmün yetmezlik durumlarının tedavisinde kullanılan bir ilaçldır?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Aldeslökin"}, {"letter": "B", "text": "FK506"}, {"letter": "C", "text": "Pimekrolimus"}, {"letter": "D", "text": "Metotraksat"}, {"letter": "E", "text": "Siklofosfamit"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q46", "prof_inferred": true, "explanation": "**Aldeslökin** (rekombinant IL-2) immün sistemi uyarıcı (**immünstimülan**) bir ilaçtır; diğer şıklar immünsüpresiftir.", "repeats": [{"kurul": "1", "year": "2022-2023", "q_num": 12, "id": "2022-2023_Q12"}]}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 47, "question": "Lokal anastezik etkili olup intrinsik sempatomimemitk etkinlik göstermeyen beta bloker ilaç aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Metoprolol"}, {"letter": "B", "text": "Nadolol"}, {"letter": "C", "text": "Atenolol"}, {"letter": "D", "text": "Sotalol"}, {"letter": "E", "text": "Esmolol"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q47", "prof_inferred": true, "explanation": "İntrinsik sempatomimetik etkinliği (İSE) olmayan ve hafif lokal anestezik (membran stabilize edici) etkiye sahip kardiyoselektif beta-blokör **Metoprolol**dür.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 31, "id": "2024-2025_Q31"}]}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 48, "question": "Aşağıda verilen sempatolitik ajanlardan hangisi reseptör düzeyinde blokaj yapar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Piperoksan"}, {"letter": "B", "text": "Reserpin"}, {"letter": "C", "text": "Guanetidin"}, {"letter": "D", "text": "Debrisoquin"}, {"letter": "E", "text": "Betanidin"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q48", "explanation": "Rezerpin, guanetidin, debrisokin ve betanidin adrenerjik nöron blokörleri olup presinaptik sinir ucundan noradrenalin depolanmasını/salınımını engeller; **Piperoksan** ise doğrudan postsinaptik **alfa-adrenerjik reseptör düzeyinde blokaj yapan** bir alfa-blokördür.", "repeats": [{"kurul": "3", "year": "2021-2022", "q_num": 19, "id": "K3_2021-2022_Q19"}]}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 49, "question": "Adrenelin için verilen bilgilerden hangisi doğrudur?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Yüksek doz adrenalin, Total Periferik damar Direncini artırır."}, {"letter": "B", "text": "Normal doz adrenalin, cilt ve mukozada kasılmaya neden olur."}, {"letter": "C", "text": "Normal doz da Beta reseptörleri üzerindeki etkisi alfa reseptörlerine olandan daha fazladır."}, {"letter": "D", "text": "Alfa2 reseptör uyarısıyla insülin salınımını artırır."}, {"letter": "E", "text": "Beta1 reseptör uyrasını bağlı olarak negatif inotropiye neden olur."}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q49", "prof_inferred": true, "explanation": "**Yüksek doz adrenalin**, damarlardaki alfa-1 adrenerjik reseptörleri güçlü şekilde uyararak vazokonstrüksiyon yapar ve **Total Periferik Damar Direncini artırır**.", "repeats": [{"kurul": "1", "year": "2023-2024", "q_num": 14, "id": "2023-2024_Q14"}]}, {"year": "2025-2026", "subject": "Farmakoloji", "q_num": 50, "question": "Bronkodilatör etkisi en fazla olan ve astım tedavisinde kullanılan beta2 reseptör agonisti aşağıdakilerden hangisidir?", "professor": "Numan Taşpınar", "options": [{"letter": "A", "text": "Salbutamol"}, {"letter": "B", "text": "Prazosin"}, {"letter": "C", "text": "Metoksamin"}, {"letter": "D", "text": "Oksedrin"}, {"letter": "E", "text": "Dekstroamfetamin"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q50", "prof_inferred": true, "explanation": "Astım tedavisinde güçlü ve hızlı bronkodilatasyon sağlayan selektif **beta-2 reseptör agonisti Salbutamol**dür.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 34, "id": "2024-2025_Q34"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 51, "question": "64 yaş erkek hasta solukluk, halsizlik, çabuk yorulma, ara ara olan çarpıntı hissi ve anormal kilo kaybı şikayetiyle başvuruyor. Tetkiklerinde hemoglobin 9 g/dL, MCV düşük, periferik yaymasında anizositoz ve hipokromi saptanıyor. Gaytada gizli kan testi pozitif saptanıyor. Aşağıdakilerden hangisi bu hastada beklenen laboratuvar bulgularından biri olamaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Serum ferritin düzeyinde düşüklük"}, {"letter": "B", "text": "Serum demir bağlama kapasitesinde yükseklik"}, {"letter": "C", "text": "Trombosit sayısında hafif yükseklik"}, {"letter": "D", "text": "Demir düzeyinde düşüklük"}, {"letter": "E", "text": "Transferrin saturasyonunda yükseklik"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q51", "explanation": "GİS gizli kanamasına bağlı **Demir Eksikliği Anemisi** gelişen hastada serum demiri ve ferritin düşer, TDBK ve reaktif trombosit sayısı yükselir; buna bağlı olarak **transferrin satürasyonu yükselmez, aksine belirgin olarak düşer (<%15-20)**."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 52, "question": "Aşağıdaki durumlardan hangisinde retikülositoz görülmesi en olasıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Folik asit eksikliğinde"}, {"letter": "B", "text": "B12 vitamini eksikliğinde"}, {"letter": "C", "text": "Aplastik anemide"}, {"letter": "D", "text": "Demir eksikliği anemisinin 7-10. günlerinde"}, {"letter": "E", "text": "Miyelodisplastik sendromda"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q52", "explanation": "Folik asit eksikliği, B12 eksikliği, aplastik anemi ve MDS tedavi öncesinde hipoproliferatif (retikülosit düşük) anemilerdir; **demir eksikliği anemisinde demir tedavisi başlandıktan sonraki 7-10. günlerde belirgin retikülositoz (retikülosit krizi)** görülür."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 53, "question": "I- Nötrofil sayısı 400/mm3 II- Trombosit sayısı 15.000/mm3 III- Retikülosit sayısı 130.000/mm3 IV- Kemik iliğinde hücresel yoğunluk (sellülerite) %50 Otuz yaşında ağır aplastik anemili hastada yukarıdaki laboratuvar bulgularından hangisi ya da hangileri beklenir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "I ve II"}, {"letter": "C", "text": "Yalanız II"}, {"letter": "D", "text": "I, II ve III"}, {"letter": "E", "text": "I, II, III ve IV"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q53", "explanation": "**Ağır aplastik anemi** tanı kriterlerinde **nötrofil <500/mm³** (I: 400/mm³ uygun), **trombosit <20.000/mm³** (II: 15.000/mm³ uygun), retikülosit <20.000/mm³ (III: 130.000 yanlış) ve kemik iliği sellüleritesinin <%25 olması (IV: %50 yanlış) yer alır. **I ve II beklenir**."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 54, "question": "Üç yıl önce mitral kapak replasmanı yapılan 60 yaşında erkek hasta halsizlik ile başvuruyor. Fizik muayenede solukluk saptanan hastanın tetkiklerinde hemoglobin 9.2 g/dL, lökosit 11.000/mm3, trombosit 175.000/mm3 saptanıyor. Periferik yaymada normokrom normositer eritositler ile şistositler görülüyor. Aşağıdaki laboratuvar bulgularından hangisinin bu hasta ile ilişkili olma olasılığı en düşüktür?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Retikülosit artışı"}, {"letter": "B", "text": "LDH artışı"}, {"letter": "C", "text": "Haptoglobin artışı"}, {"letter": "D", "text": "İndirekt bilirubin artışı"}, {"letter": "E", "text": "Kemik iliğinde eritroid hiperplazi"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q54", "explanation": "Prostetik mitral kapak replasmanı olan hastada şistositlerle seyreden **mekanik (mikroanjiyopatik) intravasküler hemolitik anemide** retikülosit, LDH, indirekt bilirubin ve kemik iliğinde eritroid hiperplazi artarken; serbest hemoglobini bağlayan **haptoglobin düzeyi artmaz, belirgin azalır**."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 55, "question": "Aşağıdakilerden hangisi anemili bir hastadaki kompansasyon mekanizmlarından biri değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kalp debisinde artış"}, {"letter": "B", "text": "Solunum sayısında artma"}, {"letter": "C", "text": "EPO düzeyinde artış"}, {"letter": "D", "text": "Eritosit 2-3 difosfogliserat düzeyinde azalma"}, {"letter": "E", "text": "Anaerobik glikolizde artma"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q55", "explanation": "Anemili bir hastada dokulara oksijen bırakılmasını kolaylaştırmak (oksihemoglobin eğrisini sağa kaydırmak) için **eritrosit içi 2,3-difosfogliserat (2,3-DPG) düzeyi azalmaz, kompansatuar olarak artar**."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 56, "question": "Anemi etyolojiye yönelik tetkik edilen bir hastada periferik yaymada lökositlerde hipersegmentasyon saptanmışsa en olası tanı aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Demir eksikliği anemisi"}, {"letter": "B", "text": "Orak hücreli anemi"}, {"letter": "C", "text": "Kronik hastalık anemisi"}, {"letter": "D", "text": "Vitamin B12 eksikliği"}, {"letter": "E", "text": "Beta talasemi"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q56", "explanation": "Periferik yaymada nötrofillerde **hipersegmentasyon** (5 loblu >%5 veya ≥6 loblu tek bir nötrofil görülmesi) **Vitamin B12 veya folat eksikliğine bağlı megaloblastik anemi** için karakteristik bulgudur."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 57, "question": "Aşağıdakilerden hangisi kongenital hemolitik anemiye yol açan hastalıklardan biri değildir?", "professor": "Zelal Adıbelli", "options": [{"letter": "A", "text": "Glukoz 6 fosfat dehidrogenaz ekskliği"}, {"letter": "B", "text": "Herediter sferositoz"}, {"letter": "C", "text": "Beta talasemi"}, {"letter": "D", "text": "Paroksismal noktürnal hemoglobinüri"}, {"letter": "E", "text": "Pürivat kinaz eksikliği"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q57", "prof_inferred": true, "explanation": "G6PD eksikliği, herediter sferositoz, beta talasemi ve pirüvat kinaz eksikliği kalıtsal (konjenital) hemolitik anemilerdir; **Paroksismal Noktürnal Hemoglobinüri (PNH)** ise PIGA genindeki somatik mutasyonla sonradan gelişen **edinsel (kazanılmış)** hemolitik anemidir."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 58, "question": "I. Metamyelosit II. Myelosit III. Çomak Hücresi IV. Promyelosit Yukarıdaki nötrofil olgunlaşma sürecinde önceden sonraya doğru sıralanışı nasıl olmalıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "I-II-III-IV"}, {"letter": "B", "text": "II-III-IV-I"}, {"letter": "C", "text": "III-IV-I-II"}, {"letter": "D", "text": "IV-II-I-III"}, {"letter": "E", "text": "II-IV-I-III"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q58", "explanation": "Kemik iliğinde granülositer (nötrofil) olgunlaşma sırası: Miyeloblast → **Promiyelosit (IV)** → **Miyelosit (II)** → **Metamiyelosit (I)** → **Çomak / Band hücresi (III)** → Segmente (olgun) nötrofil şeklindedir (**IV - II - I - III**)."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 59, "question": "Otuz beş yaşında kadın hasta bir haftadır devam eden ateş yüksekliği nedeniyle başvurdu. Tetkiklerinde hemogramında hemoglobin 13.9 g/dL, hematokrit %42, MCV 89, Trombosit 210.000, WBC 59.000, Lökosit formülinde 63 segmente nötrofil, 15 band hücre, 6 metamyelosit, 3 myelosit, 1 blast, 8 lenfosit, 2 monosit, 2 eozinofil/100 beyaz hücre saptanmıştır. Periferik kan Lökosit Alkalen Fosfataz skoru artmıştır. En olası tanı aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kronik myeloid lösemi (KML)"}, {"letter": "B", "text": "Hairy cell lösemi"}, {"letter": "C", "text": "Lökomoid reaksiyon"}, {"letter": "D", "text": "Hodgkin hastalığı"}, {"letter": "E", "text": "Akut lenfoblastik lösemi (ALL)"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q59", "explanation": "Ateş ve enfeksiyon tablosundaki hastada >50.000/mm³ lökositoz (sola kayma) ile birlikte **Lökosit Alkalen Fosfataz (LAP) skorunun artmış olması**, bu tablonun KML değil reaktif bir **Lökomoid reaksiyon** olduğunu gösterir (KML'de LAP skoru düşüktür)."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 60, "question": "Aşağıdakilerden hangisi parenteral demir tedavi endikasyonlarından biri değildir?", "professor": "Süleyman Diker", "options": [{"letter": "A", "text": "İntestinal malabsorbsiyon sendromları"}, {"letter": "B", "text": "Kronik atrofik gastriti olan hastalar"}, {"letter": "C", "text": "Total ve subtotal gastrektomili hastalar"}, {"letter": "D", "text": "Oral demir alımını tolere edemeyen hamileler"}, {"letter": "E", "text": "Kronik demir eksikliği anemisi varlığı"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q60", "prof_inferred": true, "explanation": "Malabsorbsiyon sendromları, gastrektomi, atrofik gastrit ve oral demiri tolere edemeyen gebeler parenteral demir endikasyonudur; ancak **komplike olmayan kronik demir eksikliği anemisinde ilk tercih parenteral değil, oral demir tedavisidir**."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 61, "question": "Yetmiş yaşında erkek hasta bel ve sırt ağrıları ile başvuruyor. Tetkiklerinde sedimantasyonda belirgin yükselme ile serum Albumin/Globulin oranının tersine döndüğü görülüyor. Multiple myelom düşünülen bu hastanın tanı ve izlemi için aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Hiperkalsemi eşlik edebilir"}, {"letter": "B", "text": "Anemi gözlenebilir"}, {"letter": "C", "text": "Tanı için hemoglobin elektroforezi kullanılır"}, {"letter": "D", "text": "Bence johnes proteinürisi gözlenebilir"}, {"letter": "E", "text": "Mortalite en sık enfeksiyonlara sekonder gözlenir"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q61", "explanation": "**Multipl Myelom** tanısında ve M-proteinini saptamada hemoglobin elektroforezi değil, **serum ve idrar protein elektroforezi (ve immünfiksasyon elektroforezi)** kullanılır (hemoglobin elektroforezi talasemi/orak hücre anemisi tanısında kullanılır)."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 62, "question": "Talasemi major tanısı konan bir hastanın yapılan elektroforezinde en uyumlu bulgu aşağıdakilerden hangisidir?", "professor": "Hakan Demirci", "options": [{"letter": "A", "text": "HbA %96HbF %0.5HbA2 %3.5"}, {"letter": "B", "text": "HbA %0HbF %92HbA2%8"}, {"letter": "C", "text": "HbA %60HbF %30HbA2 %10"}, {"letter": "D", "text": "HbA %0HbF %15HbA2%85"}, {"letter": "E", "text": "HbA %20HbF %80HbA2 %0"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q62", "prof_inferred": true, "explanation": "Beta-talasemi majör (homozigot β0) hastasında HbA (%0) sentezlenemez; **HbF çok yüksek (%92) ve HbA2 artmış (%8)** olarak saptanır.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 47, "id": "2024-2025_Q47"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 63, "question": "65 yaş erkek hasta karında şişkinlik hissi ile geliyor. yapılan Fizik muayenede traube alanının kapalı saptanıyor ve dalağın kot kavsinden aşağı yaklaşık 5 cm ele geliyor. Hemogramında belirgin anemi saptanan hastanın yapılan periferik yaymasında gözyaşı hücreleri gözleniyor. Bu hasta ile ilgili aşağıdakilerden hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Kemik iliği aspirasyonu ile her zaman örnek alınamaz"}, {"letter": "B", "text": "Kemik iliğinde fibröz dokuda artış beklenir."}, {"letter": "C", "text": "Kemik iliğinde megakaryositer seri artmıştır."}, {"letter": "D", "text": "Ayırıcı tanıda AML M6 İlle karışabilir."}, {"letter": "E", "text": "Down sendromu ile birlikteliği sıktır."}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q63", "explanation": "Masif splenomegali, anemi ve periferik yaymada gözyaşı damlası eritrositleri (**dakrosit**), kemik iliği fibrozisi, megakaryosit artışı ve kuru-tap (örnek alınamaması) **Primer Miyelofibrozis** tablosudur; kemik iliği fibrozisi ve megakaryositik proliferasyon AML-M6 (eritrolösemi) ile değil, **AML-M7 (akut megakaryoblastik lösemi - Down sendromunda sık)** ile karışır."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 64, "question": "Kronik lenfositik lenfoma tanısı alan bir hastada aşağıdakilerden hangisinin bulunması tedavi için endikasyon oluşturmaz?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Semptomatik splenomegali varlığı"}, {"letter": "B", "text": "Semptomatik lenfadenopati varlığı"}, {"letter": "C", "text": "Hemoglobin düzeyinin 8 g/dL olması"}, {"letter": "D", "text": "Trombosit düzeyinin 75.000/mm3 olması"}, {"letter": "E", "text": "Tanı anında 30.000/mm3 lenfosit varken 1 yılın sonunda 60.000/mm3 lenfositin olması"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q64", "explanation": "KLL'de tedavi endikasyonu olan lenfosit ikiye katlanma süresi (doubling time) **<6 ay** olmasıdır (veya 2 ayda >%50 artış); **lenfosit sayısının 1 yıl gibi uzun bir sürede 30.000'den 60.000/mm³'e çıkması** tek başına tedavi endikasyonu oluşturmaz."}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 65, "question": "Akciğer kanseri epidemiyolojisi ve risk faktörleri ile ilgili aşağıdaki ifadelerden hangileri doğrudur? 1. Kanser ilişkili ölümlerin başında gelmektedir. 2. Başta sigara olmak üzere, hava kirliliği, radon gazı, asbest maruziyeti, radyoterapi öyküsü önemli risk faktörleri arasındadır. 3. Hastaların 'ünden fazlasından küçük hücreli dışı akciğer kanseri görülmektedir. 4. Sigaranın bırakılması erken evre akciğer kanserine sahip bireylerde nüks riskini azaltır.", "professor": "Murat Eser", "options": [{"letter": "A", "text": "I,II"}, {"letter": "B", "text": "I, II, III"}, {"letter": "C", "text": "II, IV"}, {"letter": "D", "text": "I, III, IV"}, {"letter": "E", "text": "I, II, III, IV"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q65", "explanation": "Akciğer kanseriyle ilgili verilen 4 öncülün **tamamı (I, II, III ve IV) doğrudur**.", "prof_inferred": true, "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 52, "id": "2024-2025_Q52"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 66, "question": "Kanser taramaları için aşağıdaki ifadelerden hangisi ya da hangileri doğrudur? 1. Kanser taramalarının amacı pre-malign lezyonları veya erken evre malign lezyonları yakalayarak hastanın sağkalımını uzatmaktır. 2. Kolorektal kanser taramasında, özgünlük ve duyarlılığı farklı olsa da kolonoskopi, sigmoidoskopi, BT kolonografi, gaytada gizli kan gibi çeşitli yöntemler hasta tercihine göre seçilebilir. 3. Meme kanseri taraması; Gail modeli gibi bireylerin hayat boyu meme kanseri gelişme riskini öngören risk hesaplama araçlarına göre planlanır. 4. Akciğer kanseri taramasında balgam sitoloji veya akciğer grafisi yerine HRCT- Yüksek çözünürlüklü bilgisayarlı tomografi (High- resolutioncomputedtomography) kullanılması önerilmektedir.", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Yalnız I"}, {"letter": "B", "text": "Yalnız II"}, {"letter": "C", "text": "I, II"}, {"letter": "D", "text": "I, II, III"}, {"letter": "E", "text": "II, III, IV"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q66", "prof_inferred": true, "explanation": "Akciğer kanseri taramasında HRCT değil, **Düşük Doz BT (LDCT)** önerilir (4. öncül yanlış; **I, II ve III doğrudur**).", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 49, "id": "2024-2025_Q49"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 67, "question": "Hodgkin lenfoma en çok aşağıdaki viruslardan hangisiyle ilişkilidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Parvovirus"}, {"letter": "B", "text": "Epstein-Barrvirusu"}, {"letter": "C", "text": "Hepatit B virusu"}, {"letter": "D", "text": "Rotavirus"}, {"letter": "E", "text": "İnsan papilloma virusu tip 16"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q67", "prof_inferred": true, "explanation": "Hodgkin lenfoma etiyolojisinde en çok ilişkili olan virüs **Epstein-Barr virüsü (EBV)**'dür.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 53, "id": "2024-2025_Q53"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 68, "question": "Aşağıdakilerden hangisi B lenfositinden köken alan non-Hodgkin lenfomalardan biridir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Mikozisfungoides"}, {"letter": "B", "text": "Enteropati ile ilişkili lenfoma"}, {"letter": "C", "text": "Foliküler lenfoma"}, {"letter": "D", "text": "Periferik nazal tip lenfoma"}, {"letter": "E", "text": "HTLV-1 virüsü ile ilişkili lenfoma"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q68", "prof_inferred": true, "explanation": "Şıklar arasında **B lenfositinden** köken alan non-Hodgkin lenfoma **Foliküler lenfoma**dır (diğerleri T/NK hücre kökenlidir).", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 50, "id": "2024-2025_Q50"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 69, "question": "Aşağıdaki Hodgkin dışı lenfoma tiplerinden en sık görülen hangisidir?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Malt lenfoma"}, {"letter": "B", "text": "Mantle lenfoma"}, {"letter": "C", "text": "Foliküler lenfoma"}, {"letter": "D", "text": "Anaplastik büyük hücreli lenfoma"}, {"letter": "E", "text": "Burkitt lenfoma"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q69", "prof_inferred": true, "explanation": "Verilen şıklar arasında en sık görülen Non-Hodgkin lenfoma tipi **Foliküler lenfoma**dır.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 56, "id": "2024-2025_Q56"}]}, {"year": "2025-2026", "subject": "İç Hastalıkları (Dahiliye)", "q_num": 70, "question": "Hodgkin dışı lenfoma tiplerinden hangisinde t(11;18) ve trizomi 3 sitogenetik anomalileri görülür?", "professor": "Murat Eser", "options": [{"letter": "A", "text": "Foliküler lenfoma"}, {"letter": "B", "text": "Mantle hücreli lenfoma"}, {"letter": "C", "text": "Burkitt lenfoma"}, {"letter": "D", "text": "Malt lenfoma"}, {"letter": "E", "text": "Anaplastik LCL"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q70", "prof_inferred": true, "explanation": "**t(11;18)** translokasyonu ve **trizomi 3** sitogenetik anomalileri karakteristik olarak **MALT lenfoma**da (ekstranodal marjinal zon lenfomasında) görülür.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 51, "id": "2024-2025_Q51"}]}, {"year": "2025-2026", "subject": "Tıbbi Genetik", "q_num": 71, "question": "Aşağıdakilerden hangisi eritrosit membran bozukluğu sonucu gelişen kalıtsal anemidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Orak hücre anemisi"}, {"letter": "B", "text": "Herediter sferositoz"}, {"letter": "C", "text": "G6PD eksikliği"}, {"letter": "D", "text": "B-Talasemi minör"}, {"letter": "E", "text": "Piruvat kinaz eksikliği"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q71", "explanation": "Eritrosit membran iskelet proteinlerindeki (spektrin, ankirin, band 3) bozukluk sonucu gelişen kalıtsal hemolitik anemi **Herediter sferositoz**dur."}, {"year": "2025-2026", "subject": "Tıbbi Genetik", "q_num": 72, "question": "Aşağıdakilerden hangisi kalıtsal hematolojik hastalıklardan değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Orak Hücre Anemisi"}, {"letter": "B", "text": "Glikoz-6-fosfat Dehidrojenaz Eksikliği"}, {"letter": "C", "text": "Von Willebrand Hastalığı"}, {"letter": "D", "text": "Kronik Myeloid Lösemi"}, {"letter": "E", "text": "Piruvat Kinaz Eksikliği"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q72", "explanation": "Orak hücre anemisi, G6PD eksikliği, von Willebrand hastalığı ve pirüvat kinaz eksikliği kalıtsal (germline) hastalıklardır; **Kronik Miyeloid Lösemi (KML)** ise t(9;22) somatik translokasyonu ile sonradan gelişen **edinsel (kazanılmış)** bir malignitedir."}, {"year": "2025-2026", "subject": "Tıbbi Genetik", "q_num": 73, "question": "Aşağıdakilerden hangisi sporadik kanserlerin herediter kanserlerden temel farkını en doğru biçimde açıklar?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Herediter kanserler daima erken yaşta, sporadik kanserler daima ileri yaşta ortaya çıkar."}, {"letter": "B", "text": "Sporadik ve herediter kanserler genetik olarak tamamen farklı genleri etkiler, hiçbir ortak yolak paylaşmaz."}, {"letter": "C", "text": "Sporadik kanserlerde genetik değişiklikler somatik hücrelerde yaşam boyunca gelişir; herediter kanserlerde ise predispozisyon germline mutasyonla doğuştan mevcuttur."}, {"letter": "D", "text": "Sporadik kanserler yalnızca germline mutasyonlara bağlıdır, herediter kanserler ise çevres faktörlerle ortaya çıkar."}, {"letter": "E", "text": "Herediter kanserlerde genetik değişiklikler yalnız somatik hücrelerle sınırlıdır, nesilden nesile aktarılmaz."}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q73", "explanation": "**Sporadik kanserlerde** genetik mutasyonlar yaşam boyunca **somatik hücrelerde** sonradan gelişirken; **herediter (kalıtsal) kanserlerde** yatkınlık yaratan ilk mutasyon (**germline mutasyon**) doğuştan tüm vücut hücrelerinde mevcuttur."}, {"year": "2025-2026", "subject": "Tıbbi Genetik", "q_num": 74, "question": "Aşağıdakilerden hangisi Lynch sendromu ile ilişkili ekstrakolonik malignitelerden biridir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Akciğer adenokarsinomu"}, {"letter": "B", "text": "Tiroid papiller karsinomu"}, {"letter": "C", "text": "Hepatoselüler karsinom"}, {"letter": "D", "text": "Endometrium karsinomu"}, {"letter": "E", "text": "Safra kesesi karsinomu"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q74", "explanation": "DNA yanlış eşleşme onarımı (MMR) kusuru ile gelişen **Lynch sendromunda (HNPCC)** kolorektal kanser dışında **en sık görülen ekstrakolonik malignite Endometrium karsinomudur** (bunu over, mide ve ürotelyal kanserler izler)."}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 75, "question": "Demir eksikliği anemisinde periferik yaymada aşağıdakilerden hangisi görülmez?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Mikrositoz"}, {"letter": "B", "text": "Makrositoz"}, {"letter": "C", "text": "Hipokromi"}, {"letter": "D", "text": "Anizositoz"}, {"letter": "E", "text": "Poikilositoz"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q75", "explanation": "Demir eksikliği anemisi hipokrom mikrositer bir anemi olup periferik yaymada mikrositoz, hipokromi, anizositoz ve poikilositoz (kalem hücreleri) görülür; **makrositoz** görülmez (makrositoz B12/folat eksikliğinde görülür)."}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 76, "question": "En sık görülen Non-Hodgkin lenfoma tipi aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Nodüler sklerozan"}, {"letter": "B", "text": "Anaplastik büyük hücreli"}, {"letter": "C", "text": "Diffüz büyük B hücreli"}, {"letter": "D", "text": "Lenfoblastik T hücreli"}, {"letter": "E", "text": "Burkitt lenfoma"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q76", "explanation": "Çocukluk çağında (özellikle ülkemizde ve endemik bölgelerde abdominal kitle ile başvuran) **en sık görülen Non-Hodgkin lenfoma alt tipi Burkitt lenfoma**dır."}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 77, "question": "3 yaş, kız hasta solukluk yakınması ile polikliniğe başvurdu. Hemogramında hb:10 g/dL, MCV:54.4 fL, RDW: %14, hemoglobin elektroforezinde HbA2 %4 saptanmış olup en olası tanı aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Demir eksikliği anemisi"}, {"letter": "B", "text": "Beta talasemi taşıyıcılığı"}, {"letter": "C", "text": "Sideroblastik anemi"}, {"letter": "D", "text": "B12 eksikliği"}, {"letter": "E", "text": "Herediter sferositoz"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q77", "explanation": "3 yaşında çocukta hafif anemi (Hb: 10), belirgin mikrositoz (MCV: 54.4 fL), normal RDW (%14) ve **HbA2 yüksekliği (%4 > %3.5)** **Beta talasemi taşıyıcılığı (minör)** için tanısaldır."}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 78, "question": "Çocukluk çağı AML tiplerinden hangisinde DİK tablosu daha sık görülür?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "M1"}, {"letter": "B", "text": "M2"}, {"letter": "C", "text": "M3"}, {"letter": "D", "text": "M4"}, {"letter": "E", "text": "M5"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q78", "explanation": "Akut Miyeloid Lösemi alt tipleri içinde promyelositlerden salınan prokoagülan granüller nedeniyle tanı anında **Dissemine İntravasküler Koagülasyon (DİK)** tablosunun en sık görüldüğü tip **AML-M3 (Akut Promyelositik Lösemi - t(15;17))'tür**."}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 79, "question": "Süt çocuğunun geçici hipogammaglobulinemisi olan bebeklerde hangi tedavi yöntemi genellikle uygulanmaz?", "professor": "Aysel Burcu İbili", "options": [{"letter": "A", "text": "Antibiyotik tedavisi"}, {"letter": "B", "text": "Aşılama"}, {"letter": "C", "text": "Düzenli takip"}, {"letter": "D", "text": "IVIG tedavisi"}, {"letter": "E", "text": "Semptomatik tedavi"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q79", "prof_inferred": true, "explanation": "Süt çocuğunun geçici hipogammaglobulinemisinde antikor yanıtları korunduğu ve tablo kendiliğinden düzeldiği için **IVIG tedavisi genellikle uygulanmaz**.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 6, "id": "2024-2025_Q6"}]}, {"year": "2025-2026", "subject": "Pediatri", "q_num": 80, "question": "Primer İmmün Yetmezlik hastalıklarından biri olan X'e bağlı agammaglobulinemi (XLA), genellikle hangi yaşta klinik belirtiler vermeye başlar ve bu durumun sebebi nedir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Doğumdan itibaren, çünkü hastalar antijenlere karşı herhangi bir immün yanıt geliştiremezler."}, {"letter": "B", "text": "Yaşamın ilk birkaç haftasında, anneden geçen antikorların yetersiz olması nedeniyle."}, {"letter": "C", "text": "6-9 ay sonra, anneden geçen antikorların azalmasıyla."}, {"letter": "D", "text": "1-2 yaşlarında, çünkü bu dönemde çocuk daha fazla patojenle karşılaşır."}, {"letter": "E", "text": "Ergenlik döneminde, immün sistemin gelişimi tamamlandığında."}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q80", "explanation": "X'e bağlı agammaglobulinemi (Bruton hastalığı - XLA) hastalarında doğumda plasenta yoluyla **anneden geçen IgG antikorları ilk 6 ay koruyuculuk sağlar; 6-9. aylardan sonra maternal antikorların azalmasıyla** tekrarlayan bakteriyel enfeksiyonlar başlar."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 81, "question": "Vitamin B12 eksikliğinde aşağıdakilerden hangisi beklenmez?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "MCV yüksekliği"}, {"letter": "B", "text": "Hipo-segmentli nötrofiller"}, {"letter": "C", "text": "LDH ve indirekt bilirubin artışı"}, {"letter": "D", "text": "Serum metilmalonik asit artışı"}, {"letter": "E", "text": "Retikülosit sayısında artış"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q81", "explanation": "Vitamin B12 eksikliğinde MCV yüksekliği, nötrofillerde hipersegmentasyon (soru şıkkında B hipo-segmentli, E retikülosit artışı verilmiş olup cevap anahtarında **E: Retikülosit sayısında artış** işaretlenmiştir; inefektif eritropoez nedeniyle retikülosit artışı beklenmez)."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 82, "question": "Aşağıdaki laboratuvar bulgularından hangisi demir eksikliği anemisini, kronik hastalık anemisinden ayırmada en güvenilir kriterdir?", "professor": "Soycan Mızrak", "options": [{"letter": "A", "text": "Serum demirinde azalma"}, {"letter": "B", "text": "Ferritin düzeyinde düşüklük"}, {"letter": "C", "text": "TDBK'nin (total demir bağlama kapasitesi) artma"}, {"letter": "D", "text": "Transferrin saturasyonunda azalma"}, {"letter": "E", "text": "Hemoglobin düzeyinde düşüklük"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q82", "prof_inferred": true, "explanation": "Demir eksikliği anemisi ile kronik hastalık anemisinde serum demiri ve transferrin satürasyonu düşük olabilir; iki tabloyu ayırmada en güvenilir rutin kriter **serum Ferritin düzeyinin demir eksikliği anemisinde düşük (<12-30 ng/mL), kronik hastalık anemisinde ise normal veya yüksek olmasıdır**."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 83, "question": "Primer ve sekonder hemostaz bozukluklarının laboratuvar bulguları ile ilgili aşağıdaki ifadelerden hangisi doğrudur?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Primer hemostaz bozukluklarında genellikle aPTT uzar"}, {"letter": "B", "text": "Sekonder hemostaz bozukluklarında trombosit sayısı daima düşüktür"}, {"letter": "C", "text": "Primer hemostaz bozukluklarında kanama zamanı uzar"}, {"letter": "D", "text": "Sekonder hemostaz bozukluklarında kanama zamanı tipik olarak uzar"}, {"letter": "E", "text": "Primer hemostaz bozukluklarında PT ve aPTT belirgin şekilde uzar"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q83", "explanation": "**Primer hemostaz** (trombosit ve vWF) bozukluklarında mukozal kanamalar görülür ve **Kanama Zamanı (KZ) uzar** (PT ve aPTT genellikle normaldir; sekonder hemostaz bozukluklarında ise PT ve/veya aPTT uzar)."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 84, "question": "32 yaşında erkek hasta, çocukluktan beri kolay morarma ve travma sonrası uzun süren kanamalar öyküsüyle başvuruyor. Laboratuvar bulguları: ● PT: normal ● aPTT: uzamış ● Trombosit sayısı: normal ● Kanama zamanı: normal Bu laboratuvar bulguları aşağıdaki faktör eksikliklerinden hangisini en çok düşündürür?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Faktör VII eksikliği"}, {"letter": "B", "text": "Faktör VIII eksikliği (Hemofili A)"}, {"letter": "C", "text": "Faktör X eksikliği"}, {"letter": "D", "text": "Protrombin (Faktör II) eksikliği"}, {"letter": "E", "text": "Fibrinojen eksikliği"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q84", "explanation": "32 yaşında erkek hastada çocukluktan beri kolay morarma/uzun süren kanama öyküsü ile **normal PT, normal trombosit sayısı, normal kanama zamanı ve izole uzamış aPTT** bulgusu intrensek yolak faktör eksikliğini yani **Faktör VIII eksikliğini (Hemofili A)** düşündürür."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 85, "question": "Ras mutasyonunun en önemli sonucu aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Aşırı GDP aktivasyonu"}, {"letter": "B", "text": "Hücre dışı uyarılara duyarsız hale gelme"}, {"letter": "C", "text": "Sinyal yolaklarının sürekli aktifleşmesi"}, {"letter": "D", "text": "Hücrenin apoptoza girmesi"}, {"letter": "E", "text": "GAP proteininin aşırı sentezi"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q85", "explanation": "**RAS** proto-onkogenindeki nokta mutasyonları, RAS proteininin intrinsik **GTPaz aktivitesini ortadan kaldırır**; böylece RAS-GTP aktif formda kilitli kalır ve büyüme faktörü uyarısı olmasa bile **hücre içi proliferasyon sinyal yolaklarının (MAPK/ERK) sürekli aktifleşmesine** yol açar."}, {"year": "2025-2026", "subject": "Biyokimya", "q_num": 86, "question": "Aşağıdakilerden hangisi CA 125 markerının yükselme nedenlerinden değildir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Benign prostat hiperplazisi"}, {"letter": "B", "text": "Endometriozis"}, {"letter": "C", "text": "Menstruasyon"}, {"letter": "D", "text": "Hamilelik"}, {"letter": "E", "text": "İnflamatuvar pelvik hastalık"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q86", "explanation": "**CA 125** çölemik epitel (periton, plevra, perikard) ve Müllerian epitel kaynaklı bir glikoproteindir; over kanseri dışında **endometriozis, menstruasyon, gebelik ve pelvik inflamatuar hastalıkta (PID)** yükselebilir. Erkeklerde görülen **Benign Prostat Hiperplazisi (BPH)** ise CA 125'i değil **PSA**'yı yükseltir."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 87, "question": "Herpes Simplex Virüs Tip 1 (HSV-1) ve Tip 2 (HSV- 2) enfeksiyonlarının patogenezi, klinik ve latentlik özellikleri göz önüne alındığında, aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Primer HSV enfeksiyonundan sonra gelişen aseptik menenjit, özellikle HSV-2 enfeksiyonlarında sıkça görülebilen ve genellikle kendiliğinden düzelen bir tablodur."}, {"letter": "B", "text": "HSV-1 primer olarak Trigeminal Gangliyonda, HS 2 ise Sakral Gangliyonlarda latent kalma eğilimindedir."}, {"letter": "C", "text": "Herpes Virusun LAT geni, konak nöron hücresind apoptozu indükler ve enfekte nöronun hücre ölümün gitmesini sağlar."}, {"letter": "D", "text": "HSV-2 enfeksiyonu genellikle genital lezyonlarla seyrederken, HSV-1 çoğunlukla oral lezyonlara nede olur; ancak her iki virüs de her iki bölgede enfeksiyor yapabilir."}, {"letter": "E", "text": "Tzanck yaymasında çok çekirdekli dev hücrelerin ve intranükleer inklüzyon cisimciklerinin görülmesi, HSV enfeksiyonunun sitopatik etkileri açısından karakteristiktir."}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q87", "explanation": "Herpes Simplex Virüsün (HSV) **LAT (Latency-Associated Transcript)** geni, enfekte nöronlarda apoptozu indüklemez; aksine **konak nöronda apoptozu inhibe ederek** nöronun hayatta kalmasını ve virüsün ömür boyu latent kalmasını sağlar."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 88, "question": "Yirmi iki yaşındaki tıp fakültesi öğrencisi erkek hasta, göğüs sol yan tarafından sırtına doğru olan bölgenin cildinde şiddetli ağrı yakınması ile hastaneye başvuruyor. Hastadan alınan anamnezde final sınavı dönemi nedeniyle yorgun ve stresli olduğu sırada bu lezyonların ortaya çıktığı ve son üç gündür yüksek ateşle seyreden viral bir üst solunum yolu enfeksiyonu nedeniyle semptomatik ilaçlar kullandığı öğreniliyor. Yapılan muayenesinde sol torakal sırt bölgesinde dermatom görüntüsüyle uyumlu ağrılı ve eritemli zemin üzerinde çok sayıda veziküler lezyon olduğu görülüyor. Tanımlanan klinik tablo ve en olası etken aşağıdakilerden hangisidir?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Uçuk - Herpes Simpleks Virus tip 1"}, {"letter": "B", "text": "Su çiçeği - Herpes Simpleks Virus tip 2"}, {"letter": "C", "text": "Zona - Varicella Zoster Virus"}, {"letter": "D", "text": "Enfeksiyöz mononükleozis - Epistein Barr Virus"}, {"letter": "E", "text": "Kondiloma - Human Papilloma Virus"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q88", "prof_inferred": true, "explanation": "Stresli dönemde tek taraflı torakal dermatom boyunca şiddetli ağrı ve eritemli zeminde veziküler döküntü tablosu **Zona (Herpes Zoster) — Varicella Zoster Virus (VZV)** enfeksiyonudur.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 11, "id": "2024-2025_Q11"}]}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 89, "question": "Aşağıdaki hangisi, en sık görülen konjenital enfeksiyon etkeni olup, gebelerin TORCH testi kapsamında taraması yapılan, fetüste mikrosefali, mental gerilik, spastisite, periventriküler kalsifikasyon ya da doğum sonrası bebekte duyma bozuklukları ve zeka geriliği gibi geç sekeller bırakabilen virüstür?", "professor": "Fatma Nur Akdoğan Kittana", "options": [{"letter": "A", "text": "Herpes Simplex Virus -1"}, {"letter": "B", "text": "Herpes Simplex Virus - 2"}, {"letter": "C", "text": "Cytomegalovirus"}, {"letter": "D", "text": "Epstein-Barr Virus"}, {"letter": "E", "text": "Human Herpes Virus – 6"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q89", "prof_inferred": true, "explanation": "Gebelerde TORCH kapsamında taranan, en sık konjenital enfeksiyon etkeni olan ve fetüste mikrosefali, periventriküler kalsifikasyon ve işitme kaybı yapan virüs **Sitomegalovirüs (CMV)**'tür.", "repeats": [{"kurul": "1", "year": "2024-2025", "q_num": 13, "id": "2024-2025_Q13"}]}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 90, "question": "Aşağıdaki Herpes Virus Gruplarından hangisi/hangileri nöronlarda latent kalır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Alfa Herpes Viruslar"}, {"letter": "B", "text": "Beta Herpes Viruslar"}, {"letter": "C", "text": "Gama Herpes Viruslar"}, {"letter": "D", "text": "Alfa ve Beta Herpes Viruslar"}, {"letter": "E", "text": "Alfa, Beta ve Gama Herpes Viruslar"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q90", "explanation": "Herpesviridae ailesi içinde duyusal sinir gangliyonlarında (**nöronlarda**) latent kalan grup **Alfa Herpes Virüslerdir** (HSV-1, HSV-2 ve VZV). Beta herpesvirüsler (CMV, HHV-6/7) monosit/lenfosit ve salgı bezlerinde; Gama herpesvirüsler (EBV, HHV-8) ise B lenfositlerde latent kalır."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 91, "question": "Kemoterapi almakta olan 58 yaşındaki bir hastada, ateş, titreme ve kateter giriş yerinde kızarıklık şikayetleri gelişiyor. Yapılan kan kültüründe maya hücreleri üremesi saptanıyor. Tür tayini sonucunda etkenin Candida krusei olduğu belirleniyor. Bu hastanın tedavisinde aşağıdaki antifungal ilaçlardan hangisi kullanılmamalıdır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Flukonazol"}, {"letter": "B", "text": "Vorikonazol"}, {"letter": "C", "text": "Kaspofungin"}, {"letter": "D", "text": "Anidulafungin"}, {"letter": "E", "text": "Posakonazol"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q91", "explanation": "**Candida krusei**, **Flukonazol**e karşı doğal (intrinsik) dirence sahip bir maya mantarıdır; bu nedenle C. krusei kandidemisinde flukonazol kesinlikle kullanılmamalıdır (ekinokandinler veya vorikonazol tercih edilir)."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 92, "question": "HIV pozitif, CD4+ T lenfosit sayısı 80/mm³ olup AlDS klinik tablosu gösteren 42 yaşındaki bir erkek hastada son haftalarda konuşma ve görme bozukluğu ile ve sağ tarafında kısmi paralizi gelişmiştir. Hastadan alınan BOS örneğinden yapılan PCR'da etkenin Polyomaviruslardan bir DNA virusu olduğu saptanmıştır. Bu etken virusa bağlı oluşan hastalık aşağıdakilerden hangisi olabilir??", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Trikodisplazia spinuloza"}, {"letter": "B", "text": "Merkel hücreli karsinoma"}, {"letter": "C", "text": "Progresif multifokal lökoensefalopati"}, {"letter": "D", "text": "Ensefalit"}, {"letter": "E", "text": "Menenjit"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q92", "explanation": "İleri evre AIDS (CD4: 80/mm³) hastasında konuşma/görme bozukluğu ve fokal nörolojik defisit (paralizi) ile seyreden ve BOS'ta **Polyomavirus (JC virüs)** saptanan demiyelinizan santral sinir sistemi hastalığı **Progresif Multifokal Lökoensefalopati (PML)**'dir."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 93, "question": "55 yaşında, uzun süredir kontrolsüz diyabet hikayesi olan bir hasta, birkaç gündür yüzünün sağ tarafında şişlik, ağrı ve burun kenarında siyah renkli kabuklanma şikayetleri ile başvuruyor. Fizik muayenede maksiller bölge ve burun çevresinde nekrotik doku alanları izleniyor. Paranasal sinüs tomografisinde invaziv yumuşak doku tutulumu saptanıyor. Bu hastada aşağıdakilerden hangisinin saptanması mukormikoz tanısından uzaklaştırır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Biyopsi örneğinde dar açıyla dallanan hifler görülmesi"}, {"letter": "B", "text": "Geniş, düzensiz, septasız hiflerin varlığı"}, {"letter": "C", "text": "Besiyeri plak kapağını kaldıran pamuksu, beyaz koloni görünümü"}, {"letter": "D", "text": "Koloni mikroskopisinde rizoid denilen köksü yapıların görülmesi"}, {"letter": "E", "text": "Koloni mikroskopisinde sporangium denilen kese yapılarının görülmesi"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q93", "explanation": "Kontrolsüz diyabetik hastada rinoserebral **mukormikoz** (*Mucor, Rhizopus*) dokuda **geniş (90°) açıyla dallanan, septasız (bölmeli olmayan) şeritvari hifler** yapar; biyopside **dar (45°) açıyla dallanan septalı hifler görülmesi** mukormikozdan uzaklaştırıp *Aspergillus* tanısını düşündürür."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 94, "question": "Aşağıdaki HPV tiplerinden hangisi benign genital kondilom (Condyloma acuminatum) etkeni olarak en sık izole edilir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "HPV-16"}, {"letter": "B", "text": "HPV-18"}, {"letter": "C", "text": "HPV-6"}, {"letter": "D", "text": "HPV-31"}, {"letter": "E", "text": "HPV-45"}], "answer": "C", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q94", "explanation": "Benign anogenital siğillerin (**Condyloma acuminatum**) en sık etkeni düşük riskli HPV tipleri olan **HPV-6** (ve HPV-11)'dır."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 95, "question": "Aşağıdaki viruslardan hangisi Kaposi Sarkoma ile ilişkilidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "HHV-4"}, {"letter": "B", "text": "HHV-5"}, {"letter": "C", "text": "HHV-6"}, {"letter": "D", "text": "HHV-7"}, {"letter": "E", "text": "HHV-8"}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q95", "explanation": "Vasküler endotelyal bir tümör olan **Kaposi Sarkomu** ile doğrudan ilişkili herpesvirüs **HHV-8 (Human Herpesvirus-8 / KSHV)**'dir."}, {"year": "2025-2026", "subject": "Mikrobiyoloji", "q_num": 96, "question": "Aşağıdaki virüs-latent yer eşleşmelerinden hangisi yanlıştır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "EBV - trigeminal gangliyon"}, {"letter": "B", "text": "CMV - Monositler, epitel hücreleri, tükürük bezle"}, {"letter": "C", "text": "HHV-6 -T lenfositler"}, {"letter": "D", "text": "VZV- dorsal kök gangliyonu"}, {"letter": "E", "text": "HHV-8 - B lenfositler ve endotel hücreleri"}], "answer": "A", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q96", "explanation": "**Epstein-Barr Virüsü (EBV)** trigeminal gangliyonda değil, **B lenfositlerde** (ve orofarenks epitelinde) latent kalır (trigeminal gangliyonda latent kalan HSV-1'dir)."}, {"year": "2025-2026", "subject": "Radyoloji", "q_num": 97, "question": "Radyolojik görüntüleme yöntemleriyle ilgili aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Tuğberk Baştürk", "options": [{"letter": "A", "text": "Röntgen, vücuttan geçen X-ışınlarının dedektöre ulaşmasıyla iki boyutlu projeksiyon görüntüsü oluşturur."}, {"letter": "B", "text": "Bilgisayarlı Tomografi (BT), X-ışınlarının farklı açılardan gönderilmesi ve bu verilerin bilgisayar aracılığıyla kesit görüntülere dönüştürülmesi prensibine dayanır."}, {"letter": "C", "text": "Manyetik Rezonans Görüntüleme (MR), vücuttak protonların manyetik alanda hizalanması ve radyo frekans dalgalarıyla uyarılması prensibiyle çalışır."}, {"letter": "D", "text": "Ultrasonografi (USG), yüksek frekanslı ses dalgalarının dokulardan yansıması (refleksiyon) prensibine dayanır ve iyonizan radyasyon içermez."}, {"letter": "E", "text": "Floroskopi, manyetik alan ve radyo dalgaları kullanılarak hareketli organların dinamik olarak izlenmesini sağlar."}], "answer": "E", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q97", "prof_inferred": true, "explanation": "**Floroskopi**, manyetik alan ve radyo dalgaları değil, **X-ışınları** ve floresan ekran/dedektör kullanılarak hareketli organların (GİS pasajı, anjiyografi vb.) gerçek zamanlı dinamik olarak izlenmesini sağlar."}, {"year": "2025-2026", "subject": "Radyoloji", "q_num": 98, "question": "Aşağıdaki ifadelerden hangisi yanlıştır?", "professor": "Şirin Küçük", "options": [{"letter": "A", "text": "BT'de kontrast madde kullanımı, solid organ tümörlerinin ayırt edilmesini kolaylaştırır."}, {"letter": "B", "text": "MR, akciğer ve tümöral kalsifikasyon değerlendirmesinde BT'ye üstünlük sağlar."}, {"letter": "C", "text": "PET/BT, metabolik olarak aktif tümörleri saptamada kullanılır."}, {"letter": "D", "text": "USG, tiroid, testis ve meme lezyonlarının değerlendirilmesinde sıklıkla kullanılır."}, {"letter": "E", "text": "Mamografi, meme kalsifikasyonlarının saptanmasında en etkili yöntemdir."}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q98", "explanation": "Hava içeren **akciğer parankiminin** ve kalsiyum içeren **tümöral kalsifikasyonların** değerlendirilmesinde **Bilgisayarlı Tomografi (BT) ve mamografi**, sinyal darlığı nedeniyle kalsifikasyonu iyi gösteremeyen **MRG'ye belirgin üstünlük sağlar** (B şıkkı yanlıştır).", "prof_inferred": true}, {"year": "2025-2026", "subject": "İmmünoloji", "q_num": 99, "question": "Tümör mikroçevresinde immün baskılanmaya katkıda bulunan hücreler arasında aşağıdakilerden hangisi M2 fenotipinde olup TGF- ẞ, IL-6 ve PGE2 gibi faktörler salgılayarak tümör invazyonu ve metastazını kolaylaştırır?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "CD8+ Sitotoksik T lenfositler"}, {"letter": "B", "text": "Treg hücreleri"}, {"letter": "C", "text": "Myeloid kaynaklı supresör hücreler (MDSC)"}, {"letter": "D", "text": "Tümörle ilişkili makrofajlar (TAM)"}, {"letter": "E", "text": "NK hücreleri"}], "answer": "D", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q99", "explanation": "Tümör mikroçevresinde **M2 fenotipinde** polarize olarak TGF-β, IL-10, IL-6, PGE2 ve VEGF salgılayan, böylece anti-tümör bağışıklığı baskılayıp anjiyogenez ve metastazı kolaylaştıran hücreler **Tümörle İlişkili Makrofajlar (TAM - Tumor-Associated Macrophages)**'dır."}, {"year": "2025-2026", "subject": "İmmünoloji", "q_num": 100, "question": "James P. Allison ve Tasuku Honjo'ya 2018 Nobel Tıp Ödülünü kazandıran çalışmaları, immün sistemin negatif düzenlemesini inhibe ederek kanser tedavisine yönelik keşifleridir. Bu keşiflerin merkezindeki iki moleküler hedef aşağıdakilerden hangisidir?", "professor": "Belirtilmemiş", "options": [{"letter": "A", "text": "Fas ve FasL"}, {"letter": "B", "text": "CTLA-4 ve PD-1"}, {"letter": "C", "text": "B7 ve CD28"}, {"letter": "D", "text": "TNF-alfa ve IL-6"}, {"letter": "E", "text": "CD20 ve CD19"}], "answer": "B", "note": "2025-2026 1. Kurul Çalışma Sorusu", "id": "2025-2026_Q100", "explanation": "James P. Allison ve Tasuku Honjo'ya 2018 Nobel Tıp Ödülü'nü kazandıran kanser immünoterapisi (immün kontrol noktası blokajı) çalışmalarının merkezindeki iki negatif düzenleyici T hücre reseptörü **CTLA-4 ve PD-1**'dir."}];
